@app.cell(hide_code=True)
def _(html, mo, np, plt):
    def section(num, title, anchor, level=2, kicker=None, lead=None):
        """Заголовок раздела с номером и якорем: на него ведут оглавление и cat_mark_table."""
        tag = f"h{level}"
        k = f'<div class="sec-kicker">{kicker}</div>' if kicker else ""
        l = f'<p class="sec-lead">{lead}</p>' if lead else ""
        n = f'<span class="sec-num">{num}</span>' if num else ""
        return mo.Html(
            f'<header class="sec sec-l{level}" id="{anchor}">{k}'
            f'<{tag}>{n}<span class="sec-title">{title}</span>'
            f'<a class="sec-link" href="#{anchor}" aria-label="ссылка на раздел">#</a></{tag}>{l}</header>'
        )


    def prose(md):
        """Связный текст без отдельной рамки вокруг каждого абзаца."""
        return mo.Html(f'<div class="report-prose">{mo.as_html(md).text}</div>')


    def code_panel(title, source):
        """Один и тот же треугольник раскрывает и закрывает исходный код."""
        return mo.Html(
            '<details class="code-panel"><summary>' + html.escape(title) +
            '</summary><div class="code-body"><pre><code class="language-python">' +
            html.escape(source) + '</code></pre></div></details>'
        )


    def kpis(items):
        """Ряд карточек-чисел: [(подпись, значение, подсказка), ...]."""
        cards = "".join(
            f'<div class="kpi"><div class="kpi-l">{l}</div>'
            f'<div class="kpi-v">{v}</div><div class="kpi-h">{h}</div></div>'
            for l, v, h in items
        )
        return mo.Html(f'<div class="kpis">{cards}</div>')


    def chip(text, kind="neutral"):
        return f'<span class="chip chip-{kind}">{text}</span>'


    def fmt_p(p):
        """p-value в читаемом виде: 6.5·10⁻²⁰."""
        if p == 0:
            return "&lt; 10<sup>−300</sup>"
        if p >= 1e-3:
            return f"{p:.3f}"
        m, e = f"{p:.1e}".split("e")
        e = int(e)
        return f"{m}·10<sup>{'−' if e < 0 else ''}{abs(e)}</sup>"


    def num(x, d=3):
        s = f"{x:.{d}f}"
        return s.replace("-", "−")


    def verdict(title, h0, h1, test, rows, p, alpha=0.05, note=None):
        """Карточка-вердикт по гипотезе: крупно «отвергаем / не отвергаем»."""
        reject = p < alpha
        cls = "reject" if reject else "keep"
        word = "H₀ отвергаем" if reject else "Нет оснований отвергнуть H₀"
        body = "".join(f'<div class="v-row"><span>{k}</span><b>{v}</b></div>' for k, v in rows)
        nt = f'<p class="v-note">{note}</p>' if note else ""
        return mo.Html(
            f'<div class="verdict verdict-{cls}">'
            f'<div class="v-head"><div class="v-title">{title}</div><div class="v-word">{word}</div></div>'
            f'<div class="v-hyp"><span>H₀: {h0}</span><span>H₁: {h1}</span><span>{test}, α = {alpha}</span></div>'
            f'<div class="v-body">{body}<div class="v-row v-p"><span>p-value</span><b>{fmt_p(p)}</b></div></div>{nt}</div>'
        )


    def html_table(table, best=None, fmt=None, cls="tbl"):
        """Таблица в стиле сайта; best — множество (строка, столбец) для подсветки."""
        fmt = fmt or {}
        best = best or set()
        head = "".join(f"<th>{c}</th>" for c in [table.index.name or ""] + list(table.columns))
        body = ""
        for idx, row in table.iterrows():
            tds = f'<th scope="row">{idx}</th>'
            for c in table.columns:
                v = row[c]
                s = fmt[c](v) if c in fmt else (num(v, 4) if isinstance(v, (float, np.floating)) else v)
                mark = ' class="best"' if (idx, c) in best else ""
                tds += f"<td{mark}>{s}</td>"
            body += f"<tr>{tds}</tr>"
        return mo.Html(f'<div class="tbl-wrap"><table class="{cls}"><thead><tr>{head}</tr></thead><tbody>{body}</tbody></table></div>')


    def figure(fig):
        """Единая рамка для графиков."""
        import io as _io
        import base64 as _base64
        _width,_height=fig.get_size_inches()
        _ratio=_width/_height
        _kind='plot-wide' if _ratio>=1.6 else 'plot-portrait' if _ratio<.85 else 'plot-square'
        _target=9 if _ratio>=1.6 else 4.6 if _ratio<.85 else 6.3
        fig.set_size_inches(_target,_target/_ratio)
        _buffer = _io.BytesIO()
        fig.savefig(_buffer, format="png", bbox_inches="tight")
        _title = next((ax.get_title() for ax in fig.axes if ax.get_title()), "Статистический график")
        plt.close(fig)
        import struct as _struct
        _width, _height = _struct.unpack(">II", _buffer.getvalue()[16:24])
        _image = _base64.b64encode(_buffer.getvalue()).decode("ascii")
        return mo.Html(f'<figure class="plot {_kind}"><img width="{_width}" height="{_height}" src="data:image/png;base64,{_image}" alt="{html.escape(_title, quote=True)}" /></figure>')
    return (chip, code_panel, figure, fmt_p, html_table, kpis, num, prose, section, verdict,)


@app.cell(hide_code=True)
async def _(mo, pd):
    UCI_URL = ("https://archive.ics.uci.edu/ml/machine-learning-databases/"
               "wine-quality/winequality-white.csv")

    async def read_public_csv(filename, sep=";"):
        """Read bundled CSV locally or fetch it from the notebook URL in WASM."""
        import sys as _sys
        from io import StringIO as _StringIO
        if _sys.platform == "emscripten":
            from pyodide.http import pyfetch as _pyfetch
            _url = str(mo.notebook_location() / "public" / filename)
            _response = await _pyfetch(_url)
            if not _response.ok:
                raise RuntimeError(f"Не удалось загрузить {filename}: HTTP {_response.status}")
            _text = await _response.string()
            if _text.lstrip().lower().startswith(("<!doctype html", "<html")):
                raise RuntimeError(f"Вместо CSV {filename} сервер вернул HTML")
            return pd.read_csv(_StringIO(_text), sep=sep)
        return pd.read_csv(mo.notebook_location() / "public" / filename, sep=sep)

    try:
        df = await read_public_csv("winequality-white.csv")
    except Exception as _data_error:
        mo.output.append(mo.callout(
            mo.md(f"**Не удалось загрузить данные.** {_data_error}. "
                  "Обновите страницу; если ошибка сохраняется, проверьте папку public в публикации."),
            kind="danger"))
        mo.stop(True)
    return (UCI_URL, df, read_public_csv,)


@app.cell(hide_code=True)
def _(df, stats):
    VARS = {
        "ph": dict(
            num=1, col="pH", name="pH", unit="", unit_std="",
            axis="pH (безразмерная)", mu0=3.2, mu0_step=0.01,
            models=[("Нормальное", stats.norm, {}), ("Лог-нормальное", stats.lognorm, {})],
            generator="лог-нормальное со сдвигом (через нормальные числа)",
            kind="непрерывная величина",
        ),
        "sugar": dict(
            num=2, col="residual sugar", name="Остаточный сахар", unit="г/л", unit_std="г/л",
            axis="Остаточный сахар, г/л", mu0=6.4, mu0_step=0.1,
            models=[("Лог-нормальное", stats.lognorm, {"floc": 0}),
                    ("Гамма", stats.gamma, {"floc": 0}),
                    ("Вейбулла", stats.weibull_min, {"floc": 0}),
                    ("Экспоненциальное", stats.expon, {"floc": 0})],
            generator="эмпирическое квантильное преобразование",
            kind="непрерывная, неотрицательная",
        ),
        "alc": dict(
            num=3, col="alcohol", name="Спирт", unit="% об.", unit_std="п.п.",
            axis="Алкоголь, % об.", mu0=10.5, mu0_step=0.05,
            models=[("Нормальное", stats.norm, {}),
                    ("Скошенное нормальное", stats.skewnorm, {}),
                    ("Гамма со сдвигом", stats.gamma, {})],
            generator="скошенное нормальное распределение",
            kind="непрерывная, записана с округлением",
        ),
    }
    X = {k: df[v["col"]].dropna().to_numpy(dtype=float) for k, v in VARS.items()}
    SIZES = [10, 30, 100, 300, 1000, 3000]
    return (SIZES, VARS, X,)


@app.cell(hide_code=True)
def _(SEED, SIZES, VARS, X, df, functools, np, pd, stats):
    def describe(x):
        s = pd.Series(x)
        return {
            "n": len(s), "среднее": s.mean(), "медиана": s.median(), "мода": s.mode().iloc[0],
            "std": s.std(ddof=1), "min": s.min(), "max": s.max(),
            "Q1": s.quantile(.25), "Q3": s.quantile(.75),
            "асимметрия": s.skew(), "эксцесс": s.kurt(),
        }


    @functools.lru_cache(maxsize=None)
    def fit_models(key):
        x = X[key]
        rows, params = [], {}
        for name, model, kw in VARS[key]["models"]:
            pars = model.fit(x, **kw)
            params[name] = pars
            ll = np.sum(model.logpdf(x, *pars))
            k = len(pars) - len(kw)          # фиксированные параметры не считаем
            aic = 2 * k - 2 * ll
            ks = stats.kstest(x, model.cdf, args=pars).statistic
            rows.append([name, k, aic, ks])
        table = pd.DataFrame(rows, columns=["Модель", "k", "AIC", "KS D"]).set_index("Модель")
        return table.sort_values("AIC"), params


    @functools.lru_cache(maxsize=None)
    def consistency(key, reps=200):
        x = X[key]
        rng = np.random.default_rng(SEED)
        means, stds = [], []
        for n in SIZES:
            smp = rng.choice(x, size=(reps, n), replace=True)
            means.append(smp.mean(axis=1))
            stds.append(smp.std(axis=1, ddof=1))
        return means, stds


    @functools.lru_cache(maxsize=None)
    def sampling(key, n, reps=1000):
        x = X[key]
        rng = np.random.default_rng(SEED)
        m_no = np.array([rng.choice(x, n, replace=False).mean() for _ in range(reps)])
        m_yes = np.array([rng.choice(x, n, replace=True).mean() for _ in range(reps)])
        N = len(x)
        se_yes = x.std(ddof=0) / np.sqrt(n)
        se_no = se_yes * np.sqrt((N - n) / (N - 1))
        return m_no, m_yes, se_no, se_yes


    @functools.lru_cache(maxsize=None)
    def quality_test(key):
        col = VARS[key]["col"]
        high = df.loc[df["quality"] >= 7, col]
        low = df.loc[df["quality"] <= 5, col]
        u, p = stats.mannwhitneyu(high, low, alternative="two-sided")
        rbc = 2 * u / (len(high) * len(low)) - 1
        return dict(high=high, low=low, u=u, p=p, rbc=rbc)
    return (consistency, describe, fit_models, quality_test, sampling,)


@app.cell(hide_code=True)
def _(C, DIVERGING, SIZES, VARS, X, consistency, df, fit_models, model_style, np, num, plt, sampling, stats):
    def plot_box(x, axis):
        fig, ax = plt.subplots(figsize=(7.6, 1.9))
        ax.boxplot(x, vert=False, widths=0.55, patch_artist=True,
                   boxprops=dict(facecolor=C["data_soft"], edgecolor=C["data"]),
                   whiskerprops=dict(color=C["data"]), capprops=dict(color=C["data"]),
                   medianprops=dict(color=C["ink"], linewidth=2),
                   flierprops=dict(marker="o", markersize=3, markerfacecolor=C["data"],
                                   markeredgecolor="none", alpha=.45))
        ax.set_yticks([])
        ax.grid(axis="y", visible=False)
        ax.set_xlabel(axis)
        ax.set_title("Ящик с усами: медиана, IQR, выбросы по правилу 1.5·IQR")
        return fig


    def plot_shape(x, axis):
        fig, (a1, a2) = plt.subplots(1, 2, figsize=(10, 3.6))
        a1.hist(x, bins=40, density=True, color=C["data"], alpha=.85)
        a1.set(xlabel=axis, ylabel="Плотность", title="Гистограмма (40 столбиков)")
        osm, osr = stats.probplot(x, dist="norm", fit=False)
        slope, icpt = np.polyfit(osm, osr, 1)
        a2.scatter(osm, osr, s=5, color=C["data"], alpha=.5, label="Данные", edgecolor="none")
        a2.plot(osm, slope * osm + icpt, **model_style("Нормальное"), label="Нормальное")
        a2.set(xlabel="Теоретические квантили N(0, 1)", ylabel=f"Квантили выборки, {axis}",
               title="Q-Q график против нормального")
        a2.legend(loc="upper left")
        fig.tight_layout()
        return fig


    def plot_fit(key, names, bins):
        x = X[key]
        _, params = fit_models(key)
        fig, ax = plt.subplots(figsize=(8.4, 3.8))
        ax.hist(x, bins=bins, density=True, color=C["data_soft"], label="Данные")
        grid = np.linspace(max(x.min() - .05 * np.ptp(x), 0 if key == "sugar" else -np.inf), x.max(), 600)
        for name, model, _kw in VARS[key]["models"]:
            if name in names:
                ax.plot(grid, model.pdf(grid, *params[name]), label=name, **model_style(name))
        ax.set(xlabel=VARS[key]["axis"], ylabel="Плотность", title="Данные и подобранные плотности (ММП)")
        ax.legend()
        return fig


    def plot_norm(x, axis):
        z = (x - x.mean()) / x.std(ddof=1)
        fig, (a1, a2) = plt.subplots(1, 2, figsize=(10, 3.4))
        a1.hist(x, bins=40, density=True, color=C["data"], alpha=.85)
        a1.set(xlabel=axis, ylabel="Плотность", title="До: исходная шкала")
        a2.hist(z, bins=40, density=True, color=C["data"], alpha=.85, label="z-значения")
        g = np.linspace(z.min(), z.max(), 400)
        a2.plot(g, stats.norm.pdf(g), **model_style("Нормальное"), label="N(0, 1)")
        a2.set(xlabel="z = (x − x̄) / s, безразмерная", ylabel="Плотность", title="После: стандартизация")
        a2.legend()
        fig.tight_layout()
        return fig, z


    def plot_pairs(key):
        others = [k for k in VARS if k != key]
        fig, axs = plt.subplots(1, 2, figsize=(10, 3.6))
        for ax, o in zip(axs, others):
            ax.scatter(X[o], X[key], s=5, alpha=.25, color=C["data"], edgecolor="none")
            r = stats.pearsonr(X[o], X[key])[0]
            ax.set(xlabel=VARS[o]["axis"], ylabel=VARS[key]["axis"],
                   title=f"{VARS[key]['name']} и {VARS[o]['name'].lower() if o != 'ph' else 'pH'}:  r = {num(r, 2)}")
        fig.tight_layout()
        return fig


    def plot_consistency(key, n_sel):
        means, stds = consistency(key)
        x = X[key]
        v = VARS[key]
        fig, axs = plt.subplots(1, 2, figsize=(10, 3.6))
        for ax, data, truth, lab in [(axs[0], means, x.mean(), f"Выборочное среднее, {v['unit']}" if v["unit"] else "Выборочное среднее pH"),
                                     (axs[1], stds, x.std(ddof=1), f"Выборочное std, {v['unit_std']}" if v["unit_std"] else "Выборочное std pH")]:
            bp = ax.boxplot(data, positions=range(len(SIZES)), widths=.55, patch_artist=True, showfliers=False,
                            medianprops=dict(color=C["ink"]), whiskerprops=dict(color=C["muted"]),
                            capprops=dict(color=C["muted"]))
            for i, b in enumerate(bp["boxes"]):
                sel = SIZES[i] == n_sel
                b.set(facecolor=C["data"] if sel else C["data_soft"], edgecolor=C["data"])
            ax.axhline(truth, color=C["ref"], lw=1.6, label="По всей таблице")
            ax.set_xticks(range(len(SIZES)))
            ax.set_xticklabels([str(s) for s in SIZES])
            ax.set(xlabel="Размер выборки n (200 повторов)", ylabel=lab)
            ax.legend(loc="upper right")
        axs[0].set_title("Среднее сходится к значению таблицы")
        axs[1].set_title("Стандартное отклонение тоже")
        fig.tight_layout()
        return fig


    def plot_sampling(key, n):
        m_no, m_yes, se_no, se_yes = sampling(key, n)
        v = VARS[key]
        fig, ax = plt.subplots(figsize=(8.4, 3.6))
        bins = np.histogram_bin_edges(np.r_[m_no, m_yes], bins=40)
        ax.hist(m_yes, bins=bins, histtype="step", lw=2, color=C["data_alt"], label="С возвращением")
        ax.hist(m_no, bins=bins, color=C["data"], alpha=.55, label="Без возвращения")
        ax.axvline(X[key].mean(), color=C["ref"], lw=1.6, label="Среднее по таблице")
        ax.set(xlabel=f"Выборочное среднее при n = {n}" + (f", {v['unit']}" if v["unit"] else " (pH)"), ylabel="Число повторов из 1000",
               title="Разброс выборочных средних: 1000 выборок каждым способом")
        ax.legend()
        return fig


    def plot_corr(method):
        cols = [v["col"] for v in VARS.values()]
        labels = [v["name"] for v in VARS.values()]
        corr = df[cols].corr(method=method).to_numpy()
        fig, ax = plt.subplots(figsize=(5.2, 4.2))
        im = ax.imshow(corr, vmin=-1, vmax=1, cmap=DIVERGING)
        ax.set_xticks(range(3))
        ax.set_xticklabels(labels)
        ax.set_yticks(range(3))
        ax.set_yticklabels(labels)
        ax.grid(False)
        for i in range(3):
            for j in range(3):
                ax.text(j, i, num(corr[i, j], 2), ha="center", va="center", fontsize=12,
                        fontweight="bold", color=C["ink"])
        ax.set_title(f"Корреляция {'Пирсона r' if method == 'pearson' else 'Спирмена ρ'}")
        fig.colorbar(im, ax=ax, shrink=.8, label="коэффициент, от −1 до 1")
        return fig
    return (plot_box, plot_consistency, plot_corr, plot_fit, plot_norm, plot_pairs, plot_sampling, plot_shape,)


@app.cell(hide_code=True)
def _():
    REPORTS = {'sprint1': [{'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><h1 id="sprint1-heading-0-1">Lab01 - sprint 1</h1></span>', 'source': '# Lab01 - sprint 1\n'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><h2 id="sprint1-heading-1-1">Общее описание данных</h2>\n<span class="paragraph"><strong>Источник:</strong> Wine Quality (белые вина), UCI Machine Learning Repository; Cortez P., Cerdeira A., Almeida F., Matos T., Reis J. Modeling wine preferences by data mining from physicochemical properties. Decision Support Systems, 2009.</span>\n<span class="paragraph"><strong>Что это за данные:</strong> таблица из 4898 белых вин «Vinho Verde» (север Португалии), 12 столбцов. Одиннадцать столбцов — физико-химические показатели, измеренные в лаборатории: fixed acidity, volatile acidity, citric acid, residual sugar, chlorides, free sulfur dioxide, total sulfur dioxide, density, pH, sulphates, alcohol. Двенадцатый столбец, quality, — оценка качества от 0 до 10, которую выставляют дегустаторы (это медиана нескольких экспертных оценок). Пропусков нет, все показатели числовые, одна строка — один образец вина. Значения получены измерением образцов в лаборатории, а не вычислены по формулам, поэтому для каждой бутылки они заранее неизвестны.</span>\n<span class="paragraph"><strong>Три выбранные величины:</strong> pH, residual sugar (г/л), alcohol (% об.). Почему выбрала именно их: у них три разных «характера» распределения, и это интересно сравнивать. pH почти колоколообразный, с небольшим правым хвостом. Residual sugar сильно скошен вправо с длинным хвостом (асимметрия 1.08, эксцесс 3.47). Alcohol дискретизован (всего 103 значения) и имеет несколько пиков. Кроме того, у них разная связь друг с другом: pH и alcohol почти независимы (r = 0.12), а alcohol и residual sugar связаны заметно (r = −0.45), и этому есть химическое объяснение (брожение превращает сахар в спирт). Это удобно для заданий про независимость и подбор распределений.</span></span>', 'source': '## Общее описание данных\n**Источник:** Wine Quality (белые вина), UCI Machine Learning Repository; Cortez P., Cerdeira A., Almeida F., Matos T., Reis J. Modeling wine preferences by data mining from physicochemical properties. Decision Support Systems, 2009.\n\n**Что это за данные:** таблица из 4898 белых вин «Vinho Verde» (север Португалии), 12 столбцов. Одиннадцать столбцов — физико-химические показатели, измеренные в лаборатории: fixed acidity, volatile acidity, citric acid, residual sugar, chlorides, free sulfur dioxide, total sulfur dioxide, density, pH, sulphates, alcohol. Двенадцатый столбец, quality, — оценка качества от 0 до 10, которую выставляют дегустаторы (это медиана нескольких экспертных оценок). Пропусков нет, все показатели числовые, одна строка — один образец вина. Значения получены измерением образцов в лаборатории, а не вычислены по формулам, поэтому для каждой бутылки они заранее неизвестны.\n\n**Три выбранные величины:** pH, residual sugar (г/л), alcohol (% об.). Почему выбрала именно их: у них три разных «характера» распределения, и это интересно сравнивать. pH почти колоколообразный, с небольшим правым хвостом. Residual sugar сильно скошен вправо с длинным хвостом (асимметрия 1.08, эксцесс 3.47). Alcohol дискретизован (всего 103 значения) и имеет несколько пиков. Кроме того, у них разная связь друг с другом: pH и alcohol почти независимы (r = 0.12), а alcohol и residual sugar связаны заметно (r = −0.45), и этому есть химическое объяснение (брожение превращает сахар в спирт). Это удобно для заданий про независимость и подбор распределений.'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><h3 id="sprint1-heading-2-1"><span class="notebook-index">0.1</span>Почему я выбрала эту тему</h3>\n<span class="paragraph">Я выбрала тему исследования физико-химических характеристик белого вина, потому что мне было интересно увидеть, как химические показатели связаны между собой и с оценкой качества продукта. Вино оказалось удобным примером для статистического анализа: у него можно измерить pH, содержание остаточного сахара и долю алкоголя, но значения этих показателей различаются от образца к образцу. Мне хотелось понять, какие закономерности можно обнаружить в таких данных и насколько они устойчивы.</span>\n<span class="paragraph">Особенно меня заинтересовало сравнение трёх величин с разными распределениями. Я предполагала, что сахар и алкоголь могут быть связаны, а распределение pH будет ближе к симметричному. Кроме того, мне хотелось проверить, можно ли по измеряемым характеристикам обнаружить различия между винами с более высокой и более низкой оценкой качества. Для меня эта тема объединяет химию с практическим применением статистики: можно не только построить графики, но и проверить первоначальные предположения с помощью численных методов.</span></span>', 'source': '### Почему я выбрала эту тему\n\nЯ выбрала тему исследования физико-химических характеристик белого вина, потому что мне было интересно увидеть, как химические показатели связаны между собой и с оценкой качества продукта. Вино оказалось удобным примером для статистического анализа: у него можно измерить pH, содержание остаточного сахара и долю алкоголя, но значения этих показателей различаются от образца к образцу. Мне хотелось понять, какие закономерности можно обнаружить в таких данных и насколько они устойчивы.\n\nОсобенно меня заинтересовало сравнение трёх величин с разными распределениями. Я предполагала, что сахар и алкоголь могут быть связаны, а распределение pH будет ближе к симметричному. Кроме того, мне хотелось проверить, можно ли по измеряемым характеристикам обнаружить различия между винами с более высокой и более низкой оценкой качества. Для меня эта тема объединяет химию с практическим применением статистики: можно не только построить графики, но и проверить первоначальные предположения с помощью численных методов.'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><h3 id="sprint1-heading-3-1"><span class="notebook-index">0.2</span>Загрузка и первый взгляд</h3></span>', 'source': '### Загрузка и первый взгляд'}, {'kind': 'code', 'html': '', 'source': 'import numpy as np\nimport pandas as pd\nimport matplotlib.pyplot as plt\nfrom scipy import stats\n\n# Общие параметры для всей работы\nSEED = 42          # один seed для всех разделов\nN_SAMPLE = 500     # размер выборки для сравнений и гипотез\nCOLOR = "#6389B8"  # основной цвет графиков\n\n# Единый стиль графиков\nplt.rcParams["axes.prop_cycle"] = plt.cycler(color=[COLOR, "#E4572E", "#76B391", "#F3A712"])\nplt.rcParams["axes.grid"] = True\nplt.rcParams["grid.alpha"] = 0.3\nplt.rcParams["figure.dpi"] = 100\n\n\ndef hist_kde(x, xlabel, bins="auto", bw=None, ax=None):\n    """Гистограмма плотности + KDE (сглаженная оценка плотности)."""\n    ax = ax or plt.gca()\n    ax.hist(x, bins=bins, density=True, alpha=0.5, color=COLOR, label="Гистограмма")\n    grid = np.linspace(x.min(), x.max(), 400)\n    ax.plot(grid, stats.gaussian_kde(x, bw_method=bw)(grid), color="#E4572E", label="KDE")\n    ax.set_xlabel(xlabel)\n    ax.set_ylabel("Плотность")\n    ax.legend()\n'}, {'kind': 'code', 'html': '<div class="tbl-wrap"><div>\n<style scoped>\n    .dataframe tbody tr th:only-of-type {\n        vertical-align: middle;\n    }\n\n    .dataframe tbody tr th {\n        vertical-align: top;\n    }\n\n    .dataframe thead th {\n        text-align: right;\n    }\n</style>\n<table border="1" class="dataframe">\n  <thead>\n    <tr style="text-align: right;">\n      <th></th>\n      <th>fixed acidity</th>\n      <th>volatile acidity</th>\n      <th>citric acid</th>\n      <th>residual sugar</th>\n      <th>chlorides</th>\n      <th>free sulfur dioxide</th>\n      <th>total sulfur dioxide</th>\n      <th>density</th>\n      <th>pH</th>\n      <th>sulphates</th>\n      <th>alcohol</th>\n      <th>quality</th>\n    </tr>\n  </thead>\n  <tbody>\n    <tr>\n      <th>0</th>\n      <td>7.0</td>\n      <td>0.27</td>\n      <td>0.36</td>\n      <td>20.7</td>\n      <td>0.045</td>\n      <td>45.0</td>\n      <td>170.0</td>\n      <td>1.0010</td>\n      <td>3.00</td>\n      <td>0.45</td>\n      <td>8.8</td>\n      <td>6</td>\n    </tr>\n    <tr>\n      <th>1</th>\n      <td>6.3</td>\n      <td>0.30</td>\n      <td>0.34</td>\n      <td>1.6</td>\n      <td>0.049</td>\n      <td>14.0</td>\n      <td>132.0</td>\n      <td>0.9940</td>\n      <td>3.30</td>\n      <td>0.49</td>\n      <td>9.5</td>\n      <td>6</td>\n    </tr>\n    <tr>\n      <th>2</th>\n      <td>8.1</td>\n      <td>0.28</td>\n      <td>0.40</td>\n      <td>6.9</td>\n      <td>0.050</td>\n      <td>30.0</td>\n      <td>97.0</td>\n      <td>0.9951</td>\n      <td>3.26</td>\n      <td>0.44</td>\n      <td>10.1</td>\n      <td>6</td>\n    </tr>\n    <tr>\n      <th>3</th>\n      <td>7.2</td>\n      <td>0.23</td>\n      <td>0.32</td>\n      <td>8.5</td>\n      <td>0.058</td>\n      <td>47.0</td>\n      <td>186.0</td>\n      <td>0.9956</td>\n      <td>3.19</td>\n      <td>0.40</td>\n      <td>9.9</td>\n      <td>6</td>\n    </tr>\n    <tr>\n      <th>4</th>\n      <td>7.2</td>\n      <td>0.23</td>\n      <td>0.32</td>\n      <td>8.5</td>\n      <td>0.058</td>\n      <td>47.0</td>\n      <td>186.0</td>\n      <td>0.9956</td>\n      <td>3.19</td>\n      <td>0.40</td>\n      <td>9.9</td>\n      <td>6</td>\n    </tr>\n  </tbody>\n</table>\n</div></div><pre class="numeric-result">Размер таблицы (строк, столбцов): (4898, 12)\n</pre>', 'source': 'url = "https://archive.ics.uci.edu/ml/machine-learning-databases/wine-quality/winequality-white.csv"\ndf = pd.read_csv(url, sep=";")\n\nprint("Размер таблицы (строк, столбцов):", df.shape)\ndf.head()'}, {'kind': 'code', 'html': '<pre class="numeric-result">&lt;class &#x27;pandas.core.frame.DataFrame&#x27;&gt;\nRangeIndex: 4898 entries, 0 to 4897\nData columns (total 12 columns):\n #   Column                Non-Null Count  Dtype  \n---  ------                --------------  -----  \n 0   fixed acidity         4898 non-null   float64\n 1   volatile acidity      4898 non-null   float64\n 2   citric acid           4898 non-null   float64\n 3   residual sugar        4898 non-null   float64\n 4   chlorides             4898 non-null   float64\n 5   free sulfur dioxide   4898 non-null   float64\n 6   total sulfur dioxide  4898 non-null   float64\n 7   density               4898 non-null   float64\n 8   pH                    4898 non-null   float64\n 9   sulphates             4898 non-null   float64\n 10  alcohol               4898 non-null   float64\n 11  quality               4898 non-null   int64  \ndtypes: float64(11), int64(1)\nmemory usage: 459.3 KB\n</pre>', 'source': 'df.info()'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><h3 id="sprint1-heading-7-1"><span class="notebook-index">0.3</span>Пропуски и дубликаты</h3></span>', 'source': '### Пропуски и дубликаты'}, {'kind': 'code', 'html': '<pre class="numeric-result">Дубликатов: 937\n</pre>', 'source': 'print("Дубликатов:", df.duplicated().sum())'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><span class="paragraph"><strong>Дубликаты.</strong> В таблице 937 одинаковых строк (около 19%). Что я с ними делаю: оставляю. Почему: в таблице нет идентификатора вина, а значения округлены, поэтому две разные бутылки (например, из одной партии) могут дать одинаковые измерения всех 11 показателей и одну и ту же оценку качества. Доказать, что это ошибка записи, а не реальные вина, нельзя, а удаление 19% наблюдений изменило бы выборку.\nВсе дальнейшие расчёты сделаны с дубликатами (4898 строк).</span></span>', 'source': '**Дубликаты.** В таблице 937 одинаковых строк (около 19%). Что я с ними делаю: оставляю. Почему: в таблице нет идентификатора вина, а значения округлены, поэтому две разные бутылки (например, из одной партии) могут дать одинаковые измерения всех 11 показателей и одну и ту же оценку качества. Доказать, что это ошибка записи, а не реальные вина, нельзя, а удаление 19% наблюдений изменило бы выборку.\nВсе дальнейшие расчёты сделаны с дубликатами (4898 строк).'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><h3 id="sprint1-heading-10-1"><span class="notebook-index">0.4</span>Три величины: общий EDA</h3></span>', 'source': '### Три величины: общий EDA'}, {'kind': 'code', 'html': '<div class="tbl-wrap"><div>\n<style scoped>\n    .dataframe tbody tr th:only-of-type {\n        vertical-align: middle;\n    }\n\n    .dataframe tbody tr th {\n        vertical-align: top;\n    }\n\n    .dataframe thead th {\n        text-align: right;\n    }\n</style>\n<table border="1" class="dataframe">\n  <thead>\n    <tr style="text-align: right;">\n      <th></th>\n      <th>pH</th>\n      <th>residual sugar</th>\n      <th>alcohol</th>\n    </tr>\n  </thead>\n  <tbody>\n    <tr>\n      <th>count</th>\n      <td>4898.000000</td>\n      <td>4898.000000</td>\n      <td>4898.000000</td>\n    </tr>\n    <tr>\n      <th>mean</th>\n      <td>3.188267</td>\n      <td>6.391415</td>\n      <td>10.514267</td>\n    </tr>\n    <tr>\n      <th>std</th>\n      <td>0.151001</td>\n      <td>5.072058</td>\n      <td>1.230621</td>\n    </tr>\n    <tr>\n      <th>min</th>\n      <td>2.720000</td>\n      <td>0.600000</td>\n      <td>8.000000</td>\n    </tr>\n    <tr>\n      <th>25%</th>\n      <td>3.090000</td>\n      <td>1.700000</td>\n      <td>9.500000</td>\n    </tr>\n    <tr>\n      <th>50%</th>\n      <td>3.180000</td>\n      <td>5.200000</td>\n      <td>10.400000</td>\n    </tr>\n    <tr>\n      <th>75%</th>\n      <td>3.280000</td>\n      <td>9.900000</td>\n      <td>11.400000</td>\n    </tr>\n    <tr>\n      <th>max</th>\n      <td>3.820000</td>\n      <td>65.800000</td>\n      <td>14.200000</td>\n    </tr>\n  </tbody>\n</table>\n</div></div>', 'source': 'df[["pH", "residual sugar", "alcohol"]].describe()'}, {'kind': 'code', 'html': '<figure class="plot plot-wide"><img width="1638" height="426" decoding="async" data-report-asset="./public/reports/sprint1/12-0.png" src="data:image/png;base64," alt="График исследования" /></figure>', 'source': 'fig, axes = plt.subplots(1, 3, figsize=(15, 4))\nfor ax, col in zip(axes, ["pH", "residual sugar", "alcohol"]):\n    ax.hist(df[col], bins=40)\n    ax.set_title(col)\n    ax.set_xlabel(col)\n    ax.set_ylabel("Количество вин")\nplt.tight_layout()\nplt.show()'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><span class="paragraph"><strong>Что видно на гистограммах</strong></span>\n<ul>\n<li><strong>pH:</strong> похож на колокол с пиком около 3.2, справа небольшой хвост.</li>\n<li><strong>residual sugar:</strong> около 1600 вин имеют сахар меньше 2, дальше значения плавно спадают до 20, и есть редкие вина до 65. Длинный правый хвост.</li>\n<li><strong>alcohol:</strong> график неровный, с зубцами и несколькими пиками (около 9.5, 10.5, 11, 12). Зубцы появились потому, что в данных всего 103 разных значения спирта на 4898 вин, и при 40 столбиках одни столбики захватывают лишнее «круглое» значение, а другие нет.</li>\n</ul></span>', 'source': '**Что видно на гистограммах**\n\n- **pH:** похож на колокол с пиком около 3.2, справа небольшой хвост.\n- **residual sugar:** около 1600 вин имеют сахар меньше 2, дальше значения плавно спадают до 20, и есть редкие вина до 65. Длинный правый хвост.\n- **alcohol:** график неровный, с зубцами и несколькими пиками (около 9.5, 10.5, 11, 12). Зубцы появились потому, что в данных всего 103 разных значения спирта на 4898 вин, и при 40 столбиках одни столбики захватывают лишнее «круглое» значение, а другие нет.'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><h4 id="sprint1-heading-14-1"><span class="notebook-index">0.4.1</span>Те же гистограммы с KDE</h4></span>', 'source': '#### Те же гистограммы с KDE'}, {'kind': 'code', 'html': '<figure class="plot plot-wide"><img width="1638" height="426" decoding="async" data-report-asset="./public/reports/sprint1/15-0.png" src="data:image/png;base64," alt="График исследования" /></figure>', 'source': 'fig, axes = plt.subplots(1, 3, figsize=(15, 4))\nfor ax, (col, label, b) in zip(axes, [("pH", "pH", 25),\n                                      ("residual sugar", "residual sugar, г/л", 40),\n                                      ("alcohol", "alcohol, % об.", 15)]):\n    hist_kde(df[col], label, bins=b, ax=ax)\n    ax.set_title(col)\nplt.tight_layout()\nplt.show()'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><span class="paragraph"><strong>KDE и число столбиков.</strong> При 25 столбиках для pH и 15 для alcohol отдельные скачки частот из-за округления становятся менее заметны. KDE позволяет увидеть общую форму распределения независимо от выбранных границ столбиков: у pH один основной максимум с небольшим правым хвостом, у сахара выраженный правый хвост, а у алкоголя более сложная форма с локальными максимумами. Сглаживание улучшает читаемость, но не устраняет особенности исходных измерений.</span></span>', 'source': '**KDE и число столбиков.** При 25 столбиках для pH и 15 для alcohol отдельные скачки частот из-за округления становятся менее заметны. KDE позволяет увидеть общую форму распределения независимо от выбранных границ столбиков: у pH один основной максимум с небольшим правым хвостом, у сахара выраженный правый хвост, а у алкоголя более сложная форма с локальными максимумами. Сглаживание улучшает читаемость, но не устраняет особенности исходных измерений.\n'}, {'kind': 'code', 'html': '<pre class="numeric-result">Уникальных значений alcohol: 103\nalcohol\n9.4     229\n9.5     228\n9.2     199\n9.0     185\n10.0    162\n10.5    160\n11.0    158\n10.4    153\n9.1     144\n9.8     136\nName: count, dtype: int64\n</pre>', 'source': 'print("Уникальных значений alcohol:", df["alcohol"].nunique())\nprint(df["alcohol"].value_counts().head(10))'}, {'kind': 'code', 'html': '<pre class="numeric-result">pH                0.457783\nresidual sugar    1.077094\nalcohol           0.487342\ndtype: float64\npH                0.530775\nresidual sugar    3.469820\nalcohol          -0.698425\ndtype: float64\n</pre>', 'source': 'cols = ["pH", "residual sugar", "alcohol"]\nprint(df[cols].skew())\nprint(df[cols].kurt())'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><h2 id="sprint1-heading-19-1">Random Variable 01 (pH)</h2></span>', 'source': '## Random Variable 01 (pH)\n'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><h3 id="sprint1-heading-20-1"><span class="notebook-index">1.1</span>Description</h3></span>', 'source': '### Description\n'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><span class="paragraph"><strong>Величина:</strong> pH белого вина (датасет Wine Quality, 4898 измерений).</span>\n<table>\n<thead>\n<tr>\n<th>Параметр</th>\n<th>Значение</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Единицы измерения</td>\n<td>безразмерная величина (pH = −lg[H⁺])</td>\n</tr>\n<tr>\n<td>Тип</td>\n<td>непрерывная</td>\n</tr>\n<tr>\n<td>Диапазон в данных</td>\n<td>от 2.72 до 3.82</td>\n</tr>\n<tr>\n<td>Среднее</td>\n<td>3.19</td>\n</tr>\n</tbody>\n</table>\n<span class="paragraph"><strong>Почему pH случайная величина</strong></span>\n<ol>\n<li><strong>Значение зависит от многих факторов, которые заранее неизвестны:</strong>\n   сорт винограда, погода в год урожая, зрелость ягод, условия брожения.</li>\n<li><strong>Нет формулы, по которой его можно вычислить.</strong>\n   Формула <marimo-tex class="arithmatex">||(pH = -\\lg[H^+]||)</marimo-tex> работает для раствора одной кислоты известной\n   концентрации. Вино является сложной смесью нескольких кислот и солей,\n   поэтому pH вина измеряют, а не вычисляют.</li>\n<li><strong>Измерение даёт шум.</strong>\n   Даже у бутылок из одной партии значения немного отличаются из-за\n   погрешности pH-метра и температуры при замере.</li>\n</ol>\n<span class="paragraph"><strong>Вывод:</strong> pH бутылки нельзя предсказать детерминированно, поэтому его\nможно рассматривать как случайную величину.</span></span>', 'source': '**Величина:** pH белого вина (датасет Wine Quality, 4898 измерений).\n\n| Параметр | Значение |\n|---|---|\n| Единицы измерения | безразмерная величина (pH = −lg[H⁺]) |\n| Тип | непрерывная |\n| Диапазон в данных | от 2.72 до 3.82 |\n| Среднее | 3.19 |\n\n**Почему pH случайная величина**\n\n1. **Значение зависит от многих факторов, которые заранее неизвестны:**\n   сорт винограда, погода в год урожая, зрелость ягод, условия брожения.\n2. **Нет формулы, по которой его можно вычислить.**\n   Формула $pH = -\\lg[H^+]$ работает для раствора одной кислоты известной\n   концентрации. Вино является сложной смесью нескольких кислот и солей,\n   поэтому pH вина измеряют, а не вычисляют.\n3. **Измерение даёт шум.**\n   Даже у бутылок из одной партии значения немного отличаются из-за\n   погрешности pH-метра и температуры при замере.\n\n**Вывод:** pH бутылки нельзя предсказать детерминированно, поэтому его\nможно рассматривать как случайную величину.'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><h3 id="sprint1-heading-22-1"><span class="notebook-index">1.2</span>EDA &amp; Distribution</h3></span>', 'source': '\n### EDA & Distribution\n'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><h4 id="sprint1-heading-23-1"><span class="notebook-index">1.2.1</span>Описательные статистики</h4></span>', 'source': '#### Описательные статистики'}, {'kind': 'code', 'html': '<figure class="plot plot-wide"><img width="724" height="303" decoding="async" data-report-asset="./public/reports/sprint1/24-0.png" src="data:image/png;base64," alt="График исследования" /></figure><pre class="numeric-result">                   pH\nn           4898.0000\nсреднее        3.1883\nмедиана        3.1800\nмода           3.1400\nstd            0.1510\nmin            2.7200\nmax            3.8200\nQ1             3.0900\nQ3             3.2800\nасимметрия     0.4578\nэксцесс        0.5308\n</pre>', 'source': 'ph = df["pH"]\ndesc = pd.DataFrame({"pH": {\n    "n": ph.count(), "среднее": ph.mean(), "медиана": ph.median(),\n    "мода": ph.mode()[0], "std": ph.std(), "min": ph.min(), "max": ph.max(),\n    "Q1": ph.quantile(0.25), "Q3": ph.quantile(0.75),\n    "асимметрия": ph.skew(), "эксцесс": ph.kurt()}})\nprint(desc.round(4))\n\nplt.figure(figsize=(8, 2.5))\nplt.boxplot(ph, vert=False)\nplt.xlabel("pH")\nplt.title("pH: ящик с усами (выбросы)")\nplt.show()'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><span class="paragraph"><strong>Выводы по описательным статистикам:</strong> среднее (3.188) и медиана (3.18) почти совпадают, асимметрия 0.46 (небольшая положительная, правый хвост чуть длиннее левого), эксцесс 0.53 (немного больше нуля: пик чуть острее и хвосты чуть тяжелее, чем у нормального). На ящике видно, что выбросы есть с обеих сторон: границы усов по правилу 1.5·IQR равны 2.805 и 3.565 (Q1 = 3.09, Q3 = 3.28, IQR = 0.19), а min = 2.72 и max = 3.82 лежат за ними, при этом справа хвост длиннее. Их немного на фоне 4898 вин, точное число выводится в ячейке ниже. Выбросы я оставляю, потому что значения 2.7–3.8 лежат в реальном диапазоне pH вина и не похожи на ошибки измерения, а если их убрать, то обрежется хвост, который мы как раз моделируем (лог-нормальное лучше нормального именно из-за хвоста).</span></span>', 'source': '**Выводы по описательным статистикам:** среднее (3.188) и медиана (3.18) почти совпадают, асимметрия 0.46 (небольшая положительная, правый хвост чуть длиннее левого), эксцесс 0.53 (немного больше нуля: пик чуть острее и хвосты чуть тяжелее, чем у нормального). На ящике видно, что выбросы есть с обеих сторон: границы усов по правилу 1.5·IQR равны 2.805 и 3.565 (Q1 = 3.09, Q3 = 3.28, IQR = 0.19), а min = 2.72 и max = 3.82 лежат за ними, при этом справа хвост длиннее. Их немного на фоне 4898 вин, точное число выводится в ячейке ниже. Выбросы я оставляю, потому что значения 2.7–3.8 лежат в реальном диапазоне pH вина и не похожи на ошибки измерения, а если их убрать, то обрежется хвост, который мы как раз моделируем (лог-нормальное лучше нормального именно из-за хвоста).'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><h4 id="sprint1-heading-26-1"><span class="notebook-index">1.2.2</span>Форма распределения: гистограмма, Q-Q график, Шапиро-Уилк</h4></span>', 'source': '#### Форма распределения: гистограмма, Q-Q график, Шапиро-Уилк'}, {'kind': 'code', 'html': '<figure class="plot plot-wide"><img width="1308" height="426" decoding="async" data-report-asset="./public/reports/sprint1/27-0.png" src="data:image/png;base64," alt="График исследования" /></figure>', 'source': 'fig, axes = plt.subplots(1, 2, figsize=(12, 4))\n\naxes[0].hist(df["pH"], bins=40, density=True)\naxes[0].set_title("pH: гистограмма")\naxes[0].set_xlabel("pH")\naxes[0].set_ylabel("Плотность")\n\nstats.probplot(df["pH"], dist="norm", plot=axes[1])\naxes[1].set_title("pH: Q-Q график против нормального")\n\nplt.tight_layout()\nplt.show()'}, {'kind': 'code', 'html': '<pre class="numeric-result">Статистика Шапиро-Уилка: 0.9880964981563648\np-value: 6.505518567470481e-20\n</pre>', 'source': 'stat, p = stats.shapiro(df["pH"])\nprint("Статистика Шапиро-Уилка:", stat)\nprint("p-value:", p)'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><span class="paragraph"><strong>Q-Q график:</strong> в центре точки лежат на прямой, на правом конце уходят вверх, то есть правый хвост у pH тяжелее, чем у нормального распределения: высокие значения pH встречаются чаще, чем предсказывает нормальный закон. Это согласуется с положительной асимметрией 0.46 и с отвергнутой нормальностью по Шапиро-Уилку.</span></span>', 'source': '**Q-Q график:** в центре точки лежат на прямой, на правом конце уходят вверх, то есть правый хвост у pH тяжелее, чем у нормального распределения: высокие значения pH встречаются чаще, чем предсказывает нормальный закон. Это согласуется с положительной асимметрией 0.46 и с отвергнутой нормальностью по Шапиро-Уилку.'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><h4 id="sprint1-heading-30-1"><span class="notebook-index">1.2.3</span>Сглаживание гистограммы: KDE и ширина столбиков</h4></span>', 'source': '#### Сглаживание гистограммы: KDE и ширина столбиков'}, {'kind': 'code', 'html': '<figure class="plot plot-wide"><img width="1637" height="426" decoding="async" data-report-asset="./public/reports/sprint1/31-0.png" src="data:image/png;base64," alt="График исследования" /></figure>', 'source': 'fig, axes = plt.subplots(1, 3, figsize=(15, 4))\nhist_kde(df["pH"], "pH", bins=15, ax=axes[0]);  axes[0].set_title("15 столбиков")\nhist_kde(df["pH"], "pH", bins=25, ax=axes[1]);  axes[1].set_title("25 столбиков")\nhist_kde(df["pH"].round(1), "pH (округлено до 0.1)", bins=np.arange(2.65, 3.95, 0.1), ax=axes[2])\naxes[2].set_title("Округлено до 0.1")\nplt.tight_layout()\nplt.show()'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><span class="paragraph"><strong>Вывод.</strong> Гистограмма pH с 25 столбиками сохраняет больше деталей, а вариант с 15 столбиками показывает общий колоколообразный профиль нагляднее. После округления до 0.1 детали теряются, поэтому такой рисунок полезен только для демонстрации влияния точности записи. KDE показывает основную форму без зависимости от числа столбиков. Для подбора моделей и тестов использованы исходные данные.</span></span>', 'source': '**Вывод.** Гистограмма pH с 25 столбиками сохраняет больше деталей, а вариант с 15 столбиками показывает общий колоколообразный профиль нагляднее. После округления до 0.1 детали теряются, поэтому такой рисунок полезен только для демонстрации влияния точности записи. KDE показывает основную форму без зависимости от числа столбиков. Для подбора моделей и тестов использованы исходные данные.\n'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><h4 id="sprint1-heading-33-1"><span class="notebook-index">1.2.4</span>Подбор распределения: нормальное и лог-нормальное</h4></span>', 'source': '#### Подбор распределения: нормальное и лог-нормальное'}, {'kind': 'code', 'html': '<figure class="plot plot-wide"><img width="760" height="407" decoding="async" data-report-asset="./public/reports/sprint1/34-0.png" src="data:image/png;base64," alt="График исследования" /></figure><pre class="numeric-result">Нормальное: mu = 3.1882666394446715 , sigma = 0.15098518431212068\nЛог-нормальное: shape = 0.13634791317753076 , loc = 2.0877008414301246 , scale = 1.090376581705438\n</pre>', 'source': 'x = np.linspace(df["pH"].min(), df["pH"].max(), 300)\n\nmu, sigma = stats.norm.fit(df["pH"])\nshape, loc, scale = stats.lognorm.fit(df["pH"])\n\nplt.figure(figsize=(8, 4))\nplt.hist(df["pH"], bins=40, density=True, alpha=0.5, label="Данные")\nplt.plot(x, stats.norm.pdf(x, mu, sigma), label="Нормальное")\nplt.plot(x, stats.lognorm.pdf(x, shape, loc, scale), label="Лог-нормальное")\nplt.xlabel("pH")\nplt.ylabel("Плотность")\nplt.legend()\nplt.show()\n\nprint("Нормальное: mu =", mu, ", sigma =", sigma)\nprint("Лог-нормальное: shape =", shape, ", loc =", loc, ", scale =", scale)'}, {'kind': 'code', 'html': '<pre class="numeric-result">AIC нормальное: -4616.136762839567\nAIC лог-нормальное: -4765.473072519413\nKstestResult(statistic=np.float64(0.049265405769459814), pvalue=np.float64(9.036547927625019e-11), statistic_location=np.float64(3.2), statistic_sign=np.int8(1))\nKstestResult(statistic=np.float64(0.02463079670197671), pvalue=np.float64(0.005160058220836768), statistic_location=np.float64(3.1), statistic_sign=np.int8(-1))\n</pre>', 'source': 'll_norm = np.sum(stats.norm.logpdf(df["pH"], mu, sigma))\nll_logn = np.sum(stats.lognorm.logpdf(df["pH"], shape, loc, scale))\n\naic_norm = 2 * 2 - 2 * ll_norm\naic_logn = 2 * 3 - 2 * ll_logn\n\nprint("AIC нормальное:", aic_norm)\nprint("AIC лог-нормальное:", aic_logn)\n\nprint(stats.kstest(df["pH"], "norm", args=(mu, sigma)))\nprint(stats.kstest(df["pH"], "lognorm", args=(shape, loc, scale)))'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><span class="paragraph"><strong>Выводы по распределению pH</strong></span>\n<span class="paragraph">Тест Шапиро-Уилка дал p = 6.5·10⁻²⁰, значит, нормальность отвергаем.\nПри этом W = 0.988, то есть очень близко к 1.\nРасстояние KS у нормального 0.049, у лог-нормального 0.025, а AIC\nу лог-нормального ниже (−4765 против −4616), поэтому лог-нормальное\nописывает данные лучше. Скорее всего, из-за правого хвоста.\nНа графике разница между кривыми небольшая, и ни одно распределение\nне подходит идеально.</span></span>', 'source': '**Выводы по распределению pH**\n\nТест Шапиро-Уилка дал p = 6.5·10⁻²⁰, значит, нормальность отвергаем.\nПри этом W = 0.988, то есть очень близко к 1.\nРасстояние KS у нормального 0.049, у лог-нормального 0.025, а AIC\nу лог-нормального ниже (−4765 против −4616), поэтому лог-нормальное\nописывает данные лучше. Скорее всего, из-за правого хвоста.\nНа графике разница между кривыми небольшая, и ни одно распределение\nне подходит идеально.\n'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><span class="paragraph"><strong>Оговорки к тесту KS и к параметрам:</strong></span>\n<ul>\n<li>Параметры распределений я подбирала по тем же данным, на которых потом считала KS, поэтому p-value получается завышенным. Сравниваю распределения друг с другом (AIC и расстояние KS), а не смотрю на p по отдельности.</li>\n<li>У лог-нормального параметр loc = 2.09: это сдвинутое лог-нормальное с тремя параметрами, поэтому для сравнения использован AIC (он штрафует за число параметров).</li>\n<li>Итоговый выбор распределения для pH: лог-нормальное со сдвигом (loc = 2.09), потому что у него ниже AIC (−4765 против −4616) и меньше расстояние KS (0.025 против 0.049), но это лишь лучшее из двух кандидатов: p-value KS малы у обоих, и идеально pH не описывает ни одно. Для генератора во втором спринте беру: лог-нормальное с параметрами shape = 0.136, loc = 2.088, scale = 1.090 (нормальное N(3.188; 0.151) оставляю как запасной вариант для сравнения).</li>\n</ul></span>', 'source': '**Оговорки к тесту KS и к параметрам:**\n- Параметры распределений я подбирала по тем же данным, на которых потом считала KS, поэтому p-value получается завышенным. Сравниваю распределения друг с другом (AIC и расстояние KS), а не смотрю на p по отдельности.\n- У лог-нормального параметр loc = 2.09: это сдвинутое лог-нормальное с тремя параметрами, поэтому для сравнения использован AIC (он штрафует за число параметров).\n- Итоговый выбор распределения для pH: лог-нормальное со сдвигом (loc = 2.09), потому что у него ниже AIC (−4765 против −4616) и меньше расстояние KS (0.025 против 0.049), но это лишь лучшее из двух кандидатов: p-value KS малы у обоих, и идеально pH не описывает ни одно. Для генератора во втором спринте беру: лог-нормальное с параметрами shape = 0.136, loc = 2.088, scale = 1.090 (нормальное N(3.188; 0.151) оставляю как запасной вариант для сравнения).'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><h4 id="sprint1-heading-38-1"><span class="notebook-index">1.2.5</span>Математическое описание распределения</h4></span>', 'source': '#### Математическое описание распределения'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><span class="paragraph"><strong>1. Нормальное распределение.</strong> Плотность</span>\n<marimo-tex class="arithmatex">||[\nf(x)=\\frac{1}{\\sigma\\sqrt{2\\pi}}\\exp\\left(-\\frac{(x-\\mu)^2}{2\\sigma^2}\\right),\\quad x\\in\\mathbb{R}.\n||]</marimo-tex><span class="paragraph">Параметр <marimo-tex class="arithmatex">||(\\mu||)</marimo-tex> — центр распределения, он же среднее, медиана и мода. Параметр <marimo-tex class="arithmatex">||(\\sigma||)</marimo-tex> — стандартное отклонение, оно задаёт ширину колокола: в пределах <marimo-tex class="arithmatex">||(\\mu\\pm\\sigma||)</marimo-tex> лежит около 68% значений. Для pH получилось <marimo-tex class="arithmatex">||(\\mu = 3.188||)</marimo-tex>, <marimo-tex class="arithmatex">||(\\sigma = 0.151||)</marimo-tex>.</span>\n<span class="paragraph"><strong>2. Лог-нормальное распределение со сдвигом.</strong> Величина <marimo-tex class="arithmatex">||(X||)</marimo-tex> имеет такое распределение, если <marimo-tex class="arithmatex">||(\\ln(X-\\theta)||)</marimo-tex> нормальна. Плотность</span>\n<marimo-tex class="arithmatex">||[\nf(x)=\\frac{1}{(x-\\theta)\\,s\\sqrt{2\\pi}}\\exp\\left(-\\frac{\\left(\\ln(x-\\theta)-m\\right)^2}{2s^2}\\right),\\quad x&gt;\\theta.\n||]</marimo-tex><span class="paragraph">Здесь <marimo-tex class="arithmatex">||(\\theta||)</marimo-tex> (в <code>scipy</code> это <code>loc</code>) — сдвиг: левая граница, левее которой значений нет. <marimo-tex class="arithmatex">||(m=\\ln(\\text{scale})||)</marimo-tex> — среднее, а <marimo-tex class="arithmatex">||(s||)</marimo-tex> (<code>shape</code>) — стандартное отклонение величины <marimo-tex class="arithmatex">||(\\ln(X-\\theta)||)</marimo-tex>. Для pH: <marimo-tex class="arithmatex">||(s = 0.136||)</marimo-tex>, <marimo-tex class="arithmatex">||(\\theta = 2.088||)</marimo-tex>, <marimo-tex class="arithmatex">||(\\text{scale} = 1.090||)</marimo-tex>, то есть <marimo-tex class="arithmatex">||(m=\\ln 1.090\\approx 0.087||)</marimo-tex>.</span>\n<span class="paragraph"><strong>3. Откуда берутся эти распределения.</strong> Нормальное возникает по центральной предельной теореме: если величина — сумма многих небольших независимых воздействий, то она близка к нормальной. Лог-нормальное возникает из того же рассуждения для произведения: если величина — произведение многих небольших положительных множителей, то её логарифм (сумма логарифмов) близок к нормальному, а сама величина лог-нормальна.</span>\n<span class="paragraph"><strong>4. Особенности.</strong> Нормальное симметрично, определено на всей прямой, асимметрия равна 0, эксцесс (избыточный) равен 0. Лог-нормальное определено только при <marimo-tex class="arithmatex">||(x&gt;\\theta||)</marimo-tex> и скошено вправо, у него длинный правый хвост. Моменты (для <marimo-tex class="arithmatex">||(X-\\theta||)</marimo-tex>): <marimo-tex class="arithmatex">||(\\mathbb{E}[X]=\\theta+e^{m+s^2/2}||)</marimo-tex>, асимметрия <marimo-tex class="arithmatex">||((e^{s^2}+2)\\sqrt{e^{s^2}-1}||)</marimo-tex>. Подставив мои параметры, получаю среднее <marimo-tex class="arithmatex">||(\\approx 3.188||)</marimo-tex> (в данных 3.188) и асимметрию <marimo-tex class="arithmatex">||(\\approx 0.41||)</marimo-tex> (в данных 0.46), так что подобранное распределение воспроизводит и центр, и скошенность.</span>\n<span class="paragraph"><strong>5. Почему это подходит для pH.</strong> pH — это <marimo-tex class="arithmatex">||(-\\lg[\\mathrm{H}^+]||)</marimo-tex>, то есть уже логарифм концентрации, а на кислотность вина влияет много факторов (сорт, зрелость, брожение, соли и кислоты), действующих вместе. Поэтому разумно ожидать, что pH близок к нормальному (если pH нормален, то сама концентрация <marimo-tex class="arithmatex">||([\\mathrm{H}^+]=10^{-\\mathrm{pH}}||)</marimo-tex> лог-нормальна). Реальный pH слегка скошен вправо (асимметрия 0.46), и сдвинутое лог-нормальное описывает этот хвост лучше нормального (AIC −4765 против −4616). При этом химического смысла у параметра <marimo-tex class="arithmatex">||(\\theta = 2.09||)</marimo-tex> я не вижу, это просто подгонка формы, и ни одно из распределений не подходит идеально (KS отвергает оба).</span>\n<span class="paragraph"><strong>6. Как оценила параметры.</strong> Методом максимального правдоподобия: нахожу параметры, которые максимизируют <marimo-tex class="arithmatex">||(\\sum_i \\ln f(x_i;\\,\\text{параметры})||)</marimo-tex>. Для нормального ответ в явном виде: <marimo-tex class="arithmatex">||(\\hat\\mu=\\bar x||)</marimo-tex>, <marimo-tex class="arithmatex">||(\\hat\\sigma^2=\\frac1n\\sum(x_i-\\bar x)^2||)</marimo-tex>. Для лог-нормального с тремя параметрами формулы нет, <code>stats.lognorm.fit</code> ищет максимум численно. Модели сравнивала по <marimo-tex class="arithmatex">||(AIC=2k-2\\ln L||)</marimo-tex>, где <marimo-tex class="arithmatex">||(k||)</marimo-tex> — число параметров (2 и 3), потому что он штрафует за усложнение.</span>\n<span class="paragraph"><strong>7. Литература.</strong></span>\n<ul>\n<li>Cortez P., Cerdeira A., Almeida F., Matos T., Reis J. Modeling wine preferences by data mining from physicochemical properties. Decision Support Systems, 2009 (источник данных).</li>\n<li>Limpert E., Stahel W.A., Abbt M. Log-normal distributions across the sciences: keys and clues. BioScience, 2001.</li>\n<li>Гмурман В.Е. Теория вероятностей и математическая статистика.</li>\n<li>Akaike H. A new look at the statistical model identification. IEEE Trans. Automatic Control, 1974.</li>\n<li>Документация SciPy: <code>scipy.stats.norm</code>, <code>scipy.stats.lognorm</code>.</li>\n</ul></span>', 'source': '**1. Нормальное распределение.** Плотность\n\n$$f(x)=\\frac{1}{\\sigma\\sqrt{2\\pi}}\\exp\\left(-\\frac{(x-\\mu)^2}{2\\sigma^2}\\right),\\quad x\\in\\mathbb{R}.$$\n\nПараметр $\\mu$ — центр распределения, он же среднее, медиана и мода. Параметр $\\sigma$ — стандартное отклонение, оно задаёт ширину колокола: в пределах $\\mu\\pm\\sigma$ лежит около 68% значений. Для pH получилось $\\mu = 3.188$, $\\sigma = 0.151$.\n\n**2. Лог-нормальное распределение со сдвигом.** Величина $X$ имеет такое распределение, если $\\ln(X-\\theta)$ нормальна. Плотность\n\n$$f(x)=\\frac{1}{(x-\\theta)\\,s\\sqrt{2\\pi}}\\exp\\left(-\\frac{\\left(\\ln(x-\\theta)-m\\right)^2}{2s^2}\\right),\\quad x>\\theta.$$\n\nЗдесь $\\theta$ (в `scipy` это `loc`) — сдвиг: левая граница, левее которой значений нет. $m=\\ln(\\text{scale})$ — среднее, а $s$ (`shape`) — стандартное отклонение величины $\\ln(X-\\theta)$. Для pH: $s = 0.136$, $\\theta = 2.088$, $\\text{scale} = 1.090$, то есть $m=\\ln 1.090\\approx 0.087$.\n\n**3. Откуда берутся эти распределения.** Нормальное возникает по центральной предельной теореме: если величина — сумма многих небольших независимых воздействий, то она близка к нормальной. Лог-нормальное возникает из того же рассуждения для произведения: если величина — произведение многих небольших положительных множителей, то её логарифм (сумма логарифмов) близок к нормальному, а сама величина лог-нормальна.\n\n**4. Особенности.** Нормальное симметрично, определено на всей прямой, асимметрия равна 0, эксцесс (избыточный) равен 0. Лог-нормальное определено только при $x>\\theta$ и скошено вправо, у него длинный правый хвост. Моменты (для $X-\\theta$): $\\mathbb{E}[X]=\\theta+e^{m+s^2/2}$, асимметрия $(e^{s^2}+2)\\sqrt{e^{s^2}-1}$. Подставив мои параметры, получаю среднее $\\approx 3.188$ (в данных 3.188) и асимметрию $\\approx 0.41$ (в данных 0.46), так что подобранное распределение воспроизводит и центр, и скошенность.\n\n**5. Почему это подходит для pH.** pH — это $-\\lg[\\mathrm{H}^+]$, то есть уже логарифм концентрации, а на кислотность вина влияет много факторов (сорт, зрелость, брожение, соли и кислоты), действующих вместе. Поэтому разумно ожидать, что pH близок к нормальному (если pH нормален, то сама концентрация $[\\mathrm{H}^+]=10^{-\\mathrm{pH}}$ лог-нормальна). Реальный pH слегка скошен вправо (асимметрия 0.46), и сдвинутое лог-нормальное описывает этот хвост лучше нормального (AIC −4765 против −4616). При этом химического смысла у параметра $\\theta = 2.09$ я не вижу, это просто подгонка формы, и ни одно из распределений не подходит идеально (KS отвергает оба).\n\n**6. Как оценила параметры.** Методом максимального правдоподобия: нахожу параметры, которые максимизируют $\\sum_i \\ln f(x_i;\\,\\text{параметры})$. Для нормального ответ в явном виде: $\\hat\\mu=\\bar x$, $\\hat\\sigma^2=\\frac1n\\sum(x_i-\\bar x)^2$. Для лог-нормального с тремя параметрами формулы нет, `stats.lognorm.fit` ищет максимум численно. Модели сравнивала по $AIC=2k-2\\ln L$, где $k$ — число параметров (2 и 3), потому что он штрафует за усложнение.\n\n**7. Литература.**\n- Cortez P., Cerdeira A., Almeida F., Matos T., Reis J. Modeling wine preferences by data mining from physicochemical properties. Decision Support Systems, 2009 (источник данных).\n- Limpert E., Stahel W.A., Abbt M. Log-normal distributions across the sciences: keys and clues. BioScience, 2001.\n- Гмурман В.Е. Теория вероятностей и математическая статистика.\n- Akaike H. A new look at the statistical model identification. IEEE Trans. Automatic Control, 1974.\n- Документация SciPy: `scipy.stats.norm`, `scipy.stats.lognorm`.\n'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><h4 id="sprint1-heading-40-1"><span class="notebook-index">1.2.6</span>Нормализация (пункт 2.4)</h4></span>', 'source': '#### Нормализация (пункт 2.4)'}, {'kind': 'code', 'html': '<figure class="plot plot-wide"><img width="1308" height="426" decoding="async" data-report-asset="./public/reports/sprint1/41-0.png" src="data:image/png;base64," alt="График исследования" /></figure><pre class="numeric-result">Среднее после стандартизации: -1.195359767795677e-15\nStd после стандартизации: 1.0\nАсимметрия до и после: 0.4577825459180807 0.45778254591808415\n</pre>', 'source': 'ph = df["pH"]\nph_z = (ph - ph.mean()) / ph.std()\n\nprint("Среднее после стандартизации:", ph_z.mean())\nprint("Std после стандартизации:", ph_z.std())\nprint("Асимметрия до и после:", ph.skew(), ph_z.skew())\n\nfig, axes = plt.subplots(1, 2, figsize=(12, 4))\naxes[0].hist(ph, bins=40, density=True)\naxes[0].set_xlabel("pH")\naxes[0].set_ylabel("Плотность")\naxes[0].set_title("До")\n\naxes[1].hist(ph_z, bins=40, density=True)\nxs = np.linspace(-4, 5, 300)\naxes[1].plot(xs, stats.norm.pdf(xs), color="red", label="N(0, 1)")\naxes[1].set_xlabel("z = (pH − среднее) / std")\naxes[1].set_ylabel("Плотность")\naxes[1].set_title("После")\naxes[1].legend()\n\nplt.tight_layout()\nplt.show()'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><span class="paragraph"><strong>Вывод по нормализации:</strong>\nПосле стандартизации <marimo-tex class="arithmatex">||(z = (x - \\bar{x})/s||)</marimo-tex> среднее равно 0 (порядка 10⁻¹⁵, это ошибка округления), std равно 1. Асимметрия до и после одинаковая (0.4578): стандартизация меняет только шкалу, но не форму. Поэтому pH после неё не становится нормальным, это видно по правому хвосту и более высокому пику относительно <marimo-tex class="arithmatex">||(N(0,1)||)</marimo-tex>. Мотивация: pH, residual sugar и alcohol измерены в разных единицах (безразмерная величина, г/л, % об.), и после стандартизации их можно сравнивать в одной шкале. Кроме того, z-значения удобно сопоставлять со стандартным <marimo-tex class="arithmatex">||(N(0,1)||)</marimo-tex>, а для генератора обратное преобразование <marimo-tex class="arithmatex">||(x = s \\cdot z + \\bar{x}||)</marimo-tex> возвращает значения в исходные единицы.</span></span>', 'source': '**Вывод по нормализации:**\nПосле стандартизации $z = (x - \\bar{x})/s$ среднее равно 0 (порядка 10⁻¹⁵, это ошибка округления), std равно 1. Асимметрия до и после одинаковая (0.4578): стандартизация меняет только шкалу, но не форму. Поэтому pH после неё не становится нормальным, это видно по правому хвосту и более высокому пику относительно $N(0,1)$. Мотивация: pH, residual sugar и alcohol измерены в разных единицах (безразмерная величина, г/л, % об.), и после стандартизации их можно сравнивать в одной шкале. Кроме того, z-значения удобно сопоставлять со стандартным $N(0,1)$, а для генератора обратное преобразование $x = s \\cdot z + \\bar{x}$ возвращает значения в исходные единицы.'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><h3 id="sprint1-heading-43-1"><span class="notebook-index">1.3</span>Independence &amp; Estimations</h3></span>', 'source': '\n### Independence & Estimations\n'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><h4 id="sprint1-heading-44-1"><span class="notebook-index">1.3.1</span>Независимость (пункт 2.2)</h4></span>', 'source': '#### Независимость (пункт 2.2)'}, {'kind': 'code', 'html': '<figure class="plot plot-wide"><img width="1638" height="428" decoding="async" data-report-asset="./public/reports/sprint1/45-0.png" src="data:image/png;base64," alt="График исследования" /></figure><pre class="numeric-result">pH и alcohol: Пирсон r = 0.121 (p = 1.5e-17), Спирмен rho = 0.149 (p = 1.1e-25)\npH и residual sugar: Пирсон r = -0.194 (p = 8.4e-43), Спирмен rho = -0.180 (p = 5.9e-37)\nalcohol и residual sugar: Пирсон r = -0.451 (p = 1.2e-243), Спирмен rho = -0.445 (p = 3.1e-237)\n</pre>', 'source': 'pairs = [("pH", "alcohol"), ("pH", "residual sugar"), ("alcohol", "residual sugar")]\n\nfor a, b in pairs:\n    r, p_r = stats.pearsonr(df[a], df[b])\n    rho, p_s = stats.spearmanr(df[a], df[b])\n    print(f"{a} и {b}: Пирсон r = {r:.3f} (p = {p_r:.2g}), Спирмен rho = {rho:.3f} (p = {p_s:.2g})")\n\nfig, axes = plt.subplots(1, 3, figsize=(15, 4))\nfor ax, (a, b) in zip(axes, pairs):\n    ax.scatter(df[a], df[b], s=5, alpha=0.3)\n    ax.set_xlabel(a)\n    ax.set_ylabel(b)\nplt.tight_layout()\nplt.show()'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><span class="paragraph"><strong>Независимость величин</strong></span>\n<span class="paragraph">Я проверила три пары величин, измеренных на одном и том же вине.\nСамая независимая пара: pH и alcohol (r = 0.12), на графике это\nбесформенное облако без наклона.\nСамая связанная пара: alcohol и residual sugar (r = −0.45), на графике\nоблако идёт вниз: чем больше спирта, тем меньше сахара.\nПара pH и residual sugar дала r = −0.19, связь слабая.\nВсе p-value очень маленькие (от 10⁻¹⁷ до 10⁻²⁴³), но это потому, что\nнаблюдений 4898, и тест замечает даже очень слабую связь. Поэтому я\nсмотрю на размер коэффициента, а не только на p.\nПирсон и Спирмен получились почти одинаковыми, значит, хвост сахара и\nвыбросы корреляцию не искажают.\nВывод: величины нельзя считать полностью независимыми, но зависимость\nмежду pH и спиртом пренебрежимо слабая, а между спиртом и сахаром\nумеренная.\nХимическая причина: при брожении дрожжи превращают сахар в спирт, и\nчем полнее брожение, тем больше спирта и меньше остаточного сахара.</span></span>', 'source': '**Независимость величин**\n\nЯ проверила три пары величин, измеренных на одном и том же вине.\nСамая независимая пара: pH и alcohol (r = 0.12), на графике это\nбесформенное облако без наклона.\nСамая связанная пара: alcohol и residual sugar (r = −0.45), на графике\nоблако идёт вниз: чем больше спирта, тем меньше сахара.\nПара pH и residual sugar дала r = −0.19, связь слабая.\nВсе p-value очень маленькие (от 10⁻¹⁷ до 10⁻²⁴³), но это потому, что\nнаблюдений 4898, и тест замечает даже очень слабую связь. Поэтому я\nсмотрю на размер коэффициента, а не только на p.\nПирсон и Спирмен получились почти одинаковыми, значит, хвост сахара и\nвыбросы корреляцию не искажают.\nВывод: величины нельзя считать полностью независимыми, но зависимость\nмежду pH и спиртом пренебрежимо слабая, а между спиртом и сахаром\nумеренная.\nХимическая причина: при брожении дрожжи превращают сахар в спирт, и\nчем полнее брожение, тем больше спирта и меньше остаточного сахара.'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><span class="paragraph">Критерий χ² для пары alcohol и residual sugar приведён один раз в разделе «Независимость трёх величин» (перед Lab resume).</span></span>', 'source': 'Критерий χ² для пары alcohol и residual sugar приведён один раз в разделе «Независимость трёх величин» (перед Lab resume).'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><h4 id="sprint1-heading-48-1"><span class="notebook-index">1.3.2</span>Состоятельность оценок (пункт 2.3)</h4></span>', 'source': '#### Состоятельность оценок (пункт 2.3)'}, {'kind': 'code', 'html': '<figure class="plot plot-wide"><img width="1309" height="429" decoding="async" data-report-asset="./public/reports/sprint1/49-0.png" src="data:image/png;base64," alt="График исследования" /></figure><pre class="numeric-result">Диапазон средних при n=10: 3.0420–3.3290\nДиапазон средних при n=3000: 3.1804–3.1964\n</pre>', 'source': 'rng = np.random.default_rng(SEED)\n\ntrue_mean = df["pH"].mean()\ntrue_std = df["pH"].std()\n\nsizes = [10, 30, 100, 300, 1000, 3000]\nn_repeats = 200\n\nmeans = []\nstds = []\nfor n in sizes:\n    m_list = []\n    s_list = []\n    for _ in range(n_repeats):\n        sample = rng.choice(df["pH"], size=n, replace=True)\n        m_list.append(sample.mean())\n        s_list.append(sample.std(ddof=1))\n    means.append(m_list)\n    stds.append(s_list)\n\nfig, axes = plt.subplots(1, 2, figsize=(12, 4))\naxes[0].boxplot(means, tick_labels=sizes)\naxes[0].axhline(true_mean, color="red", label="Среднее по всей таблице")\naxes[0].set_xlabel("Размер выборки n")\naxes[0].set_ylabel("Выборочное среднее pH")\naxes[0].legend()\n\naxes[1].boxplot(stds, tick_labels=sizes)\naxes[1].axhline(true_std, color="red", label="Std по всей таблице")\naxes[1].set_xlabel("Размер выборки n")\naxes[1].set_ylabel("Выборочное std pH")\naxes[1].legend()\n\nplt.tight_layout()\nplt.show()\nprint(f"Диапазон средних при n=10: {min(means[0]):.4f}–{max(means[0]):.4f}")\nprint(f"Диапазон средних при n=3000: {min(means[-1]):.4f}–{max(means[-1]):.4f}")\n'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><span class="paragraph"><strong>Состоятельность.</strong> При увеличении размера выборки разброс оценок среднего и стандартного отклонения pH сокращается, а значения концентрируются вокруг характеристик всей таблицы. Ниже приведены рассчитанные диапазоны выборочных средних по 200 повторениям для двух крайних размеров выборки. Выборки сделаны с возвращением, поэтому эффект не связан с почти полным совпадением выборки и таблицы. «Истинные» значения в эксперименте — характеристики 4898 строк, а не всех белых вин.</span></span>', 'source': '**Состоятельность.** При увеличении размера выборки разброс оценок среднего и стандартного отклонения pH сокращается, а значения концентрируются вокруг характеристик всей таблицы. Ниже приведены рассчитанные диапазоны выборочных средних по 200 повторениям для двух крайних размеров выборки. Выборки сделаны с возвращением, поэтому эффект не связан с почти полным совпадением выборки и таблицы. «Истинные» значения в эксперименте — характеристики 4898 строк, а не всех белых вин.\n'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><span class="paragraph"><strong>Дополнение к выводу:</strong> (проверьте по новому графику) выборочное std при малых n в среднем чуть ниже красной линии, то есть оценка немного смещена вниз, но с ростом n это проходит. Среднее смещения не показывает.</span></span>', 'source': '**Дополнение к выводу:** (проверьте по новому графику) выборочное std при малых n в среднем чуть ниже красной линии, то есть оценка немного смещена вниз, но с ростом n это проходит. Среднее смещения не показывает.'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><h4 id="sprint1-heading-52-1"><span class="notebook-index">1.3.3</span>Выборки с возвращением и без (пункт 2.5)</h4></span>', 'source': '#### Выборки с возвращением и без (пункт 2.5)'}, {'kind': 'code', 'html': '<pre class="numeric-result">            Вся таблица  Без возвращения  С возвращением\nСреднее          3.1883           3.1909          3.2007\nStd              0.1510           0.1544          0.1475\nМедиана          3.1800           3.1800          3.1800\nАсимметрия       0.4578           0.5170          0.5695\n</pre>', 'source': 'rng = np.random.default_rng(SEED)\nn = N_SAMPLE\n\nsample_no_repl = rng.choice(df["pH"], size=n, replace=False)\nsample_repl = rng.choice(df["pH"], size=n, replace=True)\n\nresult = pd.DataFrame({\n    "Вся таблица": [df["pH"].mean(), df["pH"].std(), df["pH"].median(), df["pH"].skew()],\n    "Без возвращения": [sample_no_repl.mean(), sample_no_repl.std(ddof=1), np.median(sample_no_repl), stats.skew(sample_no_repl)],\n    "С возвращением": [sample_repl.mean(), sample_repl.std(ddof=1), np.median(sample_repl), stats.skew(sample_repl)],\n}, index=["Среднее", "Std", "Медиана", "Асимметрия"])\n\nprint(result.round(4))'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><span class="paragraph"><strong>По одной выборке из 500:</strong> среднее, std и медиана обеих выборок близки к значениям по всей таблице. Асимметрия в выборках выше (0.52 и 0.57 против 0.46). Разницу между способами по одной выборке делать нельзя, она зависит от seed, поэтому ниже повторяю 1000 раз.</span></span>', 'source': '**По одной выборке из 500:** среднее, std и медиана обеих выборок близки к значениям по всей таблице. Асимметрия в выборках выше (0.52 и 0.57 против 0.46). Разницу между способами по одной выборке делать нельзя, она зависит от seed, поэтому ниже повторяю 1000 раз.'}, {'kind': 'code', 'html': '<pre class="numeric-result">Среднее по таблице: 3.1882666394446715\nБез возвращения: среднее средних = 3.18830516 , std средних = 0.006215137625999139\nС возвращением:  среднее средних = 3.1885384999999995 , std средних = 0.006774398705998024\nТеория с возвращением: 0.006752262714344733\nТеория без возвращения: 0.006398996782587607\n</pre>', 'source': 'rng = np.random.default_rng(SEED)\nn = N_SAMPLE\nreps = 1000\n\nm_no = [rng.choice(df["pH"], size=n, replace=False).mean() for _ in range(reps)]\nm_yes = [rng.choice(df["pH"], size=n, replace=True).mean() for _ in range(reps)]\n\nprint("Среднее по таблице:", df["pH"].mean())\nprint("Без возвращения: среднее средних =", np.mean(m_no), ", std средних =", np.std(m_no, ddof=1))\nprint("С возвращением:  среднее средних =", np.mean(m_yes), ", std средних =", np.std(m_yes, ddof=1))\n\nN = len(df)\nsigma_pop = df["pH"].std(ddof=0)\nprint("Теория с возвращением:", sigma_pop / np.sqrt(n))\nprint("Теория без возвращения:", sigma_pop / np.sqrt(n) * np.sqrt((N - n) / (N - 1)))'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><span class="paragraph"><strong>С возвращением и без</strong></span>\n<span class="paragraph">С возвращением: вытащили элемент, записали результат и положили обратно.\nСостав совокупности не меняется, поэтому испытания независимы, а один\nи тот же элемент может попасть в выборку несколько раз.\nБез возвращения: вытащенный элемент назад не кладётся, совокупность\n«уменьшается», испытания зависимы, повторов быть не может.</span>\n<span class="paragraph">В моём эксперименте на 1000 повторов разброс средних был 0.0062\n(без возвращения) и 0.0068 (с возвращением). Без возвращения он меньше,\nпотому что одно и то же вино не может попасть в выборку дважды, и\nвыборки меньше отличаются друг от друга. Теория дала 0.0064 и 0.0068,\nто есть сходится с экспериментом.</span></span>', 'source': '**С возвращением и без**\n\nС возвращением: вытащили элемент, записали результат и положили обратно.\nСостав совокупности не меняется, поэтому испытания независимы, а один\nи тот же элемент может попасть в выборку несколько раз.\nБез возвращения: вытащенный элемент назад не кладётся, совокупность\n«уменьшается», испытания зависимы, повторов быть не может.\n\nВ моём эксперименте на 1000 повторов разброс средних был 0.0062\n(без возвращения) и 0.0068 (с возвращением). Без возвращения он меньше,\nпотому что одно и то же вино не может попасть в выборку дважды, и\nвыборки меньше отличаются друг от друга. Теория дала 0.0064 и 0.0068,\nто есть сходится с экспериментом.'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><span class="paragraph">Стратифицированная выборка (по оценке качества <code>quality</code>) и ответ на вопрос «можно ли по выборке судить о генеральной совокупности» приведены в разделе «Выборка и генеральная совокупность» (перед литературой).</span></span>', 'source': 'Стратифицированная выборка (по оценке качества `quality`) и ответ на вопрос «можно ли по выборке судить о генеральной совокупности» приведены в разделе «Выборка и генеральная совокупность» (перед литературой).'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><h4 id="sprint1-heading-58-1"><span class="notebook-index">1.3.4</span>Проверка гипотезы (пункт 2.7)</h4></span>', 'source': '#### Проверка гипотезы (пункт 2.7)'}, {'kind': 'code', 'html': '<pre class="numeric-result">Среднее выборки: 3.1908999999999996\nt = -1.3176099190086636 , p = 0.18823888374447473\nНа всей таблице: t = -5.438174447136783 , p = 5.644454762998372e-08\n</pre>', 'source': 'rng = np.random.default_rng(SEED)\nsample = rng.choice(df["pH"], size=N_SAMPLE, replace=False)\n\nt, p = stats.ttest_1samp(sample, popmean=3.2)\nprint("Среднее выборки:", sample.mean())\nprint("t =", t, ", p =", p)\n\n# Тот же тест на всей таблице\nt_all, p_all = stats.ttest_1samp(df["pH"], popmean=3.2)\nprint("На всей таблице: t =", t_all, ", p =", p_all)'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><span class="paragraph"><strong>Проверка гипотезы</strong></span>\n<span class="paragraph"><marimo-tex class="arithmatex">||(H_0||)</marimo-tex>: среднее pH равно 3.2, <marimo-tex class="arithmatex">||(H_1||)</marimo-tex>: среднее pH не равно 3.2, <marimo-tex class="arithmatex">||(\\alpha = 0.05||)</marimo-tex>.\nНа выборке из 500 вин: среднее = 3.1909, t = −1.32, p = 0.188 &gt; 0.05, значит <marimo-tex class="arithmatex">||(H_0||)</marimo-tex> отвергнуть нельзя. Это не доказывает, что среднее равно 3.2, просто данных недостаточно против него.\nНа всей таблице (n = 4898): t = −5.44, p = 5.6·10⁻⁸, <marimo-tex class="arithmatex">||(H_0||)</marimo-tex> отвергаем.\nРезультаты разные, потому что <marimo-tex class="arithmatex">||(t = (\\bar{x} - \\mu_0)\\sqrt{n}/s||)</marimo-tex> растёт с n: при n = 500 разница в 0.01 теряется в шуме, при n = 4898 уже заметна.\nПрактически разница между 3.188 и 3.2 мала (меньше типичной погрешности pH-метра), значимость статистическая, а не практическая.\nУсловие применимости: pH формально не нормальный, но при n = 500 среднее близко к нормальному по ЦПТ.\nУстойчивость: разница между средним по таблице и 3.2 равна около 0.012, а стандартная ошибка среднего при n = 500 около 0.0064, то есть ожидаемое t порядка −1.8, прямо рядом с порогом 0.05. Поэтому p на выборке из 500 вин от seed к seed колеблется около 0.05 и решение (отвергать <marimo-tex class="arithmatex">||(H_0||)</marimo-tex> или нет) на одной выборке неустойчиво; значения p для seed = 1, 2, 3 выводятся в ячейке ниже.</span></span>', 'source': '**Проверка гипотезы**\n\n$H_0$: среднее pH равно 3.2, $H_1$: среднее pH не равно 3.2, $\\alpha = 0.05$.\nНа выборке из 500 вин: среднее = 3.1909, t = −1.32, p = 0.188 > 0.05, значит $H_0$ отвергнуть нельзя. Это не доказывает, что среднее равно 3.2, просто данных недостаточно против него.\nНа всей таблице (n = 4898): t = −5.44, p = 5.6·10⁻⁸, $H_0$ отвергаем.\nРезультаты разные, потому что $t = (\\bar{x} - \\mu_0)\\sqrt{n}/s$ растёт с n: при n = 500 разница в 0.01 теряется в шуме, при n = 4898 уже заметна.\nПрактически разница между 3.188 и 3.2 мала (меньше типичной погрешности pH-метра), значимость статистическая, а не практическая.\nУсловие применимости: pH формально не нормальный, но при n = 500 среднее близко к нормальному по ЦПТ.\nУстойчивость: разница между средним по таблице и 3.2 равна около 0.012, а стандартная ошибка среднего при n = 500 около 0.0064, то есть ожидаемое t порядка −1.8, прямо рядом с порогом 0.05. Поэтому p на выборке из 500 вин от seed к seed колеблется около 0.05 и решение (отвергать $H_0$ или нет) на одной выборке неустойчиво; значения p для seed = 1, 2, 3 выводятся в ячейке ниже.'}, {'kind': 'code', 'html': '<pre class="numeric-result">Вин с quality &gt;= 7: 1060 , с quality &lt;= 5: 1640\nМедиана pH: высокое качество = 3.2 , низкое = 3.16\nU = 1022099.0 , p = 1.0627230508442323e-14 , размер эффекта (r_rb) = 0.176\nРешение при alpha=0.05: отвергаем H0; p=1.0627e-14; медианы=3.2 и 3.16; r_rb=0.1759\n</pre>', 'source': '# Гипотеза: pH у вин с высокой и низкой оценкой качества различается\nhigh = df.loc[df["quality"] >= 7, "pH"]\nlow = df.loc[df["quality"] <= 5, "pH"]\nu, p_u = stats.mannwhitneyu(high, low, alternative="two-sided")\nrbc = 2 * u / (len(high) * len(low)) - 1   # ранговая бисериальная корреляция (размер эффекта)\nprint("Вин с quality >= 7:", len(high), ", с quality <= 5:", len(low))\nprint("Медиана pH: высокое качество =", high.median(), ", низкое =", low.median())\nprint("U =", u, ", p =", p_u, ", размер эффекта (r_rb) =", round(rbc, 3))\nprint(f"Решение при alpha=0.05: {\'отвергаем H0\' if p_u < 0.05 else \'нет оснований отвергнуть H0\'}; p={p_u:.5g}; медианы={high.median():.4g} и {low.median():.4g}; r_rb={rbc:.4f}")\n'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><span class="paragraph"><strong>Гипотеза о связи pH с качеством.</strong> Проверяется <marimo-tex class="arithmatex">||(H_0||)</marimo-tex>: распределения показателя у вин с оценками не ниже 7 и не выше 5 совпадают; <marimo-tex class="arithmatex">||(H_1||)</marimo-tex>: распределения различаются (<marimo-tex class="arithmatex">||(\\alpha=0.05||)</marimo-tex>). Для двух независимых групп использован двусторонний критерий Манна—Уитни, который не требует нормальности данных. Точные p-value, медианы и ранговая бисериальная корреляция вычисляются в ячейке выше. При p &lt; 0.05 нулевая гипотеза отвергается; величина эффекта помогает оценить практическую значимость различия. Наблюдаемая связь не доказывает, что именно pH определяет качество: на оценку могут влиять и другие характеристики вина.</span></span>', 'source': '**Гипотеза о связи pH с качеством.** Проверяется $H_0$: распределения показателя у вин с оценками не ниже 7 и не выше 5 совпадают; $H_1$: распределения различаются ($\\alpha=0.05$). Для двух независимых групп использован двусторонний критерий Манна—Уитни, который не требует нормальности данных. Точные p-value, медианы и ранговая бисериальная корреляция вычисляются в ячейке выше. При p < 0.05 нулевая гипотеза отвергается; величина эффекта помогает оценить практическую значимость различия. Наблюдаемая связь не доказывает, что именно pH определяет качество: на оценку могут влиять и другие характеристики вина.\n'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><h3 id="sprint1-heading-63-1"><span class="notebook-index">1.4</span>Итоговый вывод по pH</h3>\n<span class="paragraph">pH белого вина можно считать случайной величиной: он зависит от множества заранее неизвестных факторов (сорт, урожай, брожение), его нельзя вычислить по формуле и он измеряется с шумом. Нормальным его считать нельзя (Шапиро-Уилк: p = 6.5·10⁻²⁰, хотя W = 0.988 близко к 1), потому что правый хвост тяжелее нормального. Из двух кандидатов лучше лог-нормальное со сдвигом (AIC −4765 против −4616, KS 0.025 против 0.049), его я и беру для генератора, помня, что идеально не подходит ни одно. Оценки среднего и std состоятельны: с ростом размера выборки ящики сужаются вокруг значений по всей таблице (std при малых n немного занижен). pH слабо связан со спиртом (r = 0.12) и сахаром (r = −0.19), в отличие от пары спирт–сахар (r = −0.45), поэтому с точки зрения генератора pH можно моделировать почти отдельно. Проверка гипотезы <marimo-tex class="arithmatex">||(H_0||)</marimo-tex>: среднее = 3.2 на выборке из 500 вин не отвергла её (p = 0.188), а на всей таблице отвергла (p = 5.6·10⁻⁸), но разница в 0.012 практически ничтожна, и вывод на одной выборке неустойчив. В целом белые вина в датасете имеют узкий диапазон кислотности (pH 2.72–3.82, std 0.15), то есть довольно однородны по этому показателю.</span></span>', 'source': '### Итоговый вывод по pH\npH белого вина можно считать случайной величиной: он зависит от множества заранее неизвестных факторов (сорт, урожай, брожение), его нельзя вычислить по формуле и он измеряется с шумом. Нормальным его считать нельзя (Шапиро-Уилк: p = 6.5·10⁻²⁰, хотя W = 0.988 близко к 1), потому что правый хвост тяжелее нормального. Из двух кандидатов лучше лог-нормальное со сдвигом (AIC −4765 против −4616, KS 0.025 против 0.049), его я и беру для генератора, помня, что идеально не подходит ни одно. Оценки среднего и std состоятельны: с ростом размера выборки ящики сужаются вокруг значений по всей таблице (std при малых n немного занижен). pH слабо связан со спиртом (r = 0.12) и сахаром (r = −0.19), в отличие от пары спирт–сахар (r = −0.45), поэтому с точки зрения генератора pH можно моделировать почти отдельно. Проверка гипотезы $H_0$: среднее = 3.2 на выборке из 500 вин не отвергла её (p = 0.188), а на всей таблице отвергла (p = 5.6·10⁻⁸), но разница в 0.012 практически ничтожна, и вывод на одной выборке неустойчив. В целом белые вина в датасете имеют узкий диапазон кислотности (pH 2.72–3.82, std 0.15), то есть довольно однородны по этому показателю.\n'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><h2 id="sprint1-heading-64-1">Random Variable 02 (residual sugar)</h2></span>', 'source': '\n## Random Variable 02 (residual sugar)\n'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><h3 id="sprint1-heading-65-1"><span class="notebook-index">2.1</span>Description</h3>\n<span class="paragraph"><strong>Случайная величина:</strong> массовая концентрация остаточного сахара в белом вине (residual sugar). Используем те же 4898 наблюдений из Wine Quality (белые вина), что и для pH и alcohol.</span>\n<table>\n<thead>\n<tr>\n<th>Характеристика</th>\n<th>Значение</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Единицы измерения</td>\n<td>г/л</td>\n</tr>\n<tr>\n<td>Физический тип</td>\n<td>непрерывная, неотрицательная</td>\n</tr>\n<tr>\n<td>Диапазон в данных</td>\n<td>0.6–65.8 г/л</td>\n</tr>\n<tr>\n<td>Среднее</td>\n<td>6.3914 г/л</td>\n</tr>\n<tr>\n<td>Медиана</td>\n<td>5.2 г/л</td>\n</tr>\n</tbody>\n</table>\n<span class="paragraph"><strong>Почему это случайная величина.</strong> Для случайно выбранного вина концентрация сахара зависит от исходного состава винограда, степени зрелости, активности дрожжей, режима и момента остановки брожения. Не зная условий производства и измерений, точное значение заранее предсказать нельзя. Измерение имеет конечную точность, поэтому в таблице возможны повторения округлённых значений, хотя исходная физическая величина непрерывна.\n<strong>Вывод:</strong> остаточный сахар можно анализировать как случайную величину.</span></span>', 'source': '### Description\n**Случайная величина:** массовая концентрация остаточного сахара в белом вине (residual sugar). Используем те же 4898 наблюдений из Wine Quality (белые вина), что и для pH и alcohol.\n| Характеристика | Значение |\n|---|---|\n| Единицы измерения | г/л |\n| Физический тип | непрерывная, неотрицательная |\n| Диапазон в данных | 0.6–65.8 г/л |\n| Среднее | 6.3914 г/л |\n| Медиана | 5.2 г/л |\n\n**Почему это случайная величина.** Для случайно выбранного вина концентрация сахара зависит от исходного состава винограда, степени зрелости, активности дрожжей, режима и момента остановки брожения. Не зная условий производства и измерений, точное значение заранее предсказать нельзя. Измерение имеет конечную точность, поэтому в таблице возможны повторения округлённых значений, хотя исходная физическая величина непрерывна.\n**Вывод:** остаточный сахар можно анализировать как случайную величину.'}, {'kind': 'code', 'html': '<pre class="numeric-result">Число наблюдений: 4898\nУникальные записанные значения: 310\nНаиболее частые значения (г/л):\nresidual sugar\n1.2    187\n1.4    184\n1.6    165\n1.3    147\n1.1    146\n1.5    142\n1.8     99\n1.7     99\n1.0     93\n2.0     79\n</pre>', 'source': 'residual_sugar = df["residual sugar"].dropna()\nsugar_values = residual_sugar.to_numpy()\nprint("Число наблюдений:", len(sugar_values))\nprint("Уникальные записанные значения:", residual_sugar.nunique())\nprint("Наиболее частые значения (г/л):")\nprint(residual_sugar.value_counts().head(10).to_string())'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><h3 id="sprint1-heading-67-1"><span class="notebook-index">2.2</span>EDA &amp; Distribution</h3></span>', 'source': '\n### EDA & Distribution\n'}, {'kind': 'code', 'html': '<figure class="plot plot-wide"><img width="868" height="261" decoding="async" data-report-asset="./public/reports/sprint1/68-0.png" src="data:image/png;base64," alt="График исследования" /></figure><pre class="numeric-result">n             4898.0000\nсреднее          6.3914\nмедиана          5.2000\nмода             1.2000\nstd              5.0721\nmin              0.6000\nmax             65.8000\nQ1               1.7000\nQ3               9.9000\nасимметрия       1.0771\nэксцесс          3.4698\nГраницы по правилу 1.5 IQR: -10.60 ... 22.20 г/л\nЧисло формальных выбросов: 7\n</pre>', 'source': 'sugar_description = pd.Series({\n    "n": residual_sugar.count(),\n    "среднее": residual_sugar.mean(),\n    "медиана": residual_sugar.median(),\n    "мода": residual_sugar.mode().iloc[0],\n    "std": residual_sugar.std(ddof=1),\n    "min": residual_sugar.min(),\n    "max": residual_sugar.max(),\n    "Q1": residual_sugar.quantile(.25),\n    "Q3": residual_sugar.quantile(.75),\n    "асимметрия": residual_sugar.skew(),\n    "эксцесс": residual_sugar.kurt()\n})\nprint(sugar_description.round(4).to_string())\nsugar_q1, sugar_q3 = residual_sugar.quantile([.25, .75])\nsugar_iqr = sugar_q3 - sugar_q1\nsugar_lower = sugar_q1 - 1.5 * sugar_iqr\nsugar_upper = sugar_q3 + 1.5 * sugar_iqr\nsugar_outliers = ((residual_sugar < sugar_lower) | (residual_sugar > sugar_upper)).sum()\nprint(f"Границы по правилу 1.5 IQR: {sugar_lower:.2f} ... {sugar_upper:.2f} г/л")\nprint("Число формальных выбросов:", int(sugar_outliers))\n\nplt.figure(figsize=(8, 2.5))\nplt.boxplot(sugar_values, vert=False)\nplt.xlabel("Остаточный сахар, г/л")\nplt.title("Residual sugar: ящик с усами")\nplt.grid(axis="x", alpha=.2)\nplt.tight_layout()\nplt.show()'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><span class="paragraph"><strong>Интерпретация.</strong> Среднее <strong>6.3914 г/л</strong> выше медианы <strong>5.2 г/л.</strong> Стандартное отклонение <strong>5.0721 г/л</strong>, асимметрия <strong>1.0771</strong> (длинный правый хвост), эксцесс 3.4698 (более тяжёлые хвосты относительно нормального распределения). Q1 = <strong>1.7</strong> г/л, Q3 = <strong>9.9</strong> г/л, поэтому IQR = 8.2 г/л и верхняя граница по правилу 1.5·IQR составляет <strong>22.2 г/л.</strong> Значения выше неё являются формальными выбросами, но не обязательно ошибками: сладкие вина могут содержать намного больше остаточного сахара. Такие наблюдения сохраняем, поскольку они важны для формы хвоста.</span></span>', 'source': '**Интерпретация.** Среднее **6.3914 г/л** выше медианы **5.2 г/л.** Стандартное отклонение **5.0721 г/л**, асимметрия **1.0771** (длинный правый хвост), эксцесс 3.4698 (более тяжёлые хвосты относительно нормального распределения). Q1 = **1.7** г/л, Q3 = **9.9** г/л, поэтому IQR = 8.2 г/л и верхняя граница по правилу 1.5·IQR составляет **22.2 г/л.** Значения выше неё являются формальными выбросами, но не обязательно ошибками: сладкие вина могут содержать намного больше остаточного сахара. Такие наблюдения сохраняем, поскольку они важны для формы хвоста.'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><h4 id="sprint1-heading-70-1"><span class="notebook-index">2.2.1</span>Форма распределения, Q–Q график и тест Шапиро–Уилка</h4></span>', 'source': '#### Форма распределения, Q–Q график и тест Шапиро–Уилка'}, {'kind': 'code', 'html': '<figure class="plot plot-wide"><img width="1638" height="426" decoding="async" data-report-asset="./public/reports/sprint1/71-0.png" src="data:image/png;base64," alt="График исследования" /></figure><pre class="numeric-result">Шапиро–Уилк: W=0.884569; p=2.821e-51\n</pre>', 'source': 'fig, axs = plt.subplots(1, 3, figsize=(15, 4))\naxs[0].hist(sugar_values, bins=40, color="#6389B8", alpha=.85)\naxs[0].set(xlabel="Остаточный сахар, г/л", ylabel="Число вин", title="Гистограмма")\n\nsugar_freq = residual_sugar.value_counts().sort_index()\naxs[1].plot(sugar_freq.index, sugar_freq.values, ".", markersize=5)\naxs[1].set(xlabel="Остаточный сахар, г/л", ylabel="Частота", title="Частоты записанных значений")\n\nstats.probplot(sugar_values, dist="norm", plot=axs[2])\naxs[2].set_title("Q–Q против нормального")\nplt.tight_layout()\nplt.show()\n\nsugar_w, sugar_p_shapiro = stats.shapiro(sugar_values)\nprint(f"Шапиро–Уилк: W={sugar_w:.6f}; p={sugar_p_shapiro:.3e}")'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><span class="paragraph">Гистограмма показывает концентрацию наблюдений при относительно небольшом содержании сахара и длинный хвост вправо до <strong>65.8 г/л.</strong> График частот позволяет увидеть повторения значений, записанных с ограниченной точностью. На Q–Q графике выраженное отклонение точек от прямой (особенно справа) показывает, что нормальное распределение плохо описывает хвост. По тесту Шапиро–Уилка при <strong>p &lt; 0.05</strong> отвергаем гипотезу о точной нормальности (точное значение p выводится кодом). Важно, что при n = <strong>4898</strong> тест чувствителен даже к сравнительно небольшим отклонениям; форму дополнительно оцениваем визуально и сравнением моделей.</span></span>', 'source': 'Гистограмма показывает концентрацию наблюдений при относительно небольшом содержании сахара и длинный хвост вправо до **65.8 г/л.** График частот позволяет увидеть повторения значений, записанных с ограниченной точностью. На Q–Q графике выраженное отклонение точек от прямой (особенно справа) показывает, что нормальное распределение плохо описывает хвост. По тесту Шапиро–Уилка при **p < 0.05** отвергаем гипотезу о точной нормальности (точное значение p выводится кодом). Важно, что при n = **4898** тест чувствителен даже к сравнительно небольшим отклонениям; форму дополнительно оцениваем визуально и сравнением моделей.'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><h4 id="sprint1-heading-73-1"><span class="notebook-index">2.2.2</span>Подбор распределения: лог-нормальное, гамма, Вейбулла и экспоненциальное</h4></span>', 'source': '#### Подбор распределения: лог-нормальное, гамма, Вейбулла и экспоненциальное'}, {'kind': 'code', 'html': '<figure class="plot plot-wide"><img width="978" height="426" decoding="async" data-report-asset="./public/reports/sprint1/74-0.png" src="data:image/png;base64," alt="График исследования" /></figure><pre class="numeric-result">          Модель  k        AIC   KS D\n           Гамма  2 27559.5859 0.1198\n        Вейбулла  2 27584.8272 0.1180\n  Лог-нормальное  2 27611.8500 0.1108\nЭкспоненциальное  1 27969.1457 0.1291\nЛучшая модель по AIC: Гамма\nПараметры (в порядке SciPy): (1.4814063452349577, 0, np.float64(4.314423847155702))\n</pre>', 'source': '# Все четыре кандидата поддерживают x > 0; loc=0 фиксируем,\n# чтобы модель не приписывала отрицательные значения концентрации.\nsugar_models = {\n    "Лог-нормальное": stats.lognorm,\n    "Гамма": stats.gamma,\n    "Вейбулла": stats.weibull_min,\n    "Экспоненциальное": stats.expon,\n}\nsugar_fitted = {}\nsugar_results = []\nsugar_x = np.linspace(0, sugar_values.max() + 2, 550)\n\nplt.figure(figsize=(9, 4))\nplt.hist(sugar_values, bins=40, density=True, color="#6389B8", alpha=.40, label="Данные")\nfor name, model in sugar_models.items():\n    params = model.fit(sugar_values, floc=0)\n    sugar_fitted[name] = params\n    ll = np.sum(model.logpdf(sugar_values, *params))\n    # Параметр loc=0 задан заранее, не оценивается по данным.\n    k = len(params) - 1\n    aic = 2 * k - 2 * ll\n    ks_d = stats.kstest(sugar_values, model.cdf, args=params).statistic\n    sugar_results.append([name, k, aic, ks_d])\n    plt.plot(sugar_x, model.pdf(sugar_x, *params), linewidth=2, label=name)\n\nplt.xlabel("Остаточный сахар, г/л")\nplt.ylabel("Плотность")\nplt.title("Residual sugar: сравнение моделей")\nplt.legend()\nplt.tight_layout()\nplt.show()\n\nsugar_fit_table = pd.DataFrame(sugar_results, columns=["Модель", "k", "AIC", "KS D"]).sort_values("AIC")\nprint(sugar_fit_table.round(4).to_string(index=False))\nsugar_best_model = sugar_fit_table.iloc[0]["Модель"]\nprint("Лучшая модель по AIC:", sugar_best_model)\nprint("Параметры (в порядке SciPy):", sugar_fitted[sugar_best_model])'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><h4 id="sprint1-heading-75-1"><span class="notebook-index">2.2.3</span>Сравнение распределений</h4>\n<span class="paragraph">Для сравнения моделей используются критерии <strong>AIC</strong> и <strong>KS D</strong>: чем меньше их значения, тем лучше модель описывает данные. Наиболее подходящее распределение выбирается по минимальному AIC.</span>\n<span class="paragraph">Для всех моделей принято <code>loc=0</code>. При этом логнормальное, гамма-распределение и распределение Вейбулла имеют по два оцениваемых параметра, экспоненциальное — один.</span>\n<span class="paragraph">Поскольку данные могут содержать несколько пиков и выбросы, выбранная модель является приближением. Для более точного воспроизведения исходного распределения можно использовать эмпирический метод.</span>\n<span class="paragraph"><strong>Сопоставление подобранных моделей.</strong></span>\n<table>\n<thead>\n<tr>\n<th>Распределение</th>\n<th style="text-align: right;">k</th>\n<th style="text-align: right;">AIC</th>\n<th style="text-align: right;">KS D</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Гамма</td>\n<td style="text-align: right;">2</td>\n<td style="text-align: right;"><strong>27559.6</strong></td>\n<td style="text-align: right;">0.1198</td>\n</tr>\n<tr>\n<td>Вейбулла</td>\n<td style="text-align: right;">2</td>\n<td style="text-align: right;">27584.8</td>\n<td style="text-align: right;">0.1180</td>\n</tr>\n<tr>\n<td>Лог-нормальное</td>\n<td style="text-align: right;">2</td>\n<td style="text-align: right;">27611.9</td>\n<td style="text-align: right;"><strong>0.1108</strong></td>\n</tr>\n<tr>\n<td>Экспоненциальное</td>\n<td style="text-align: right;">1</td>\n<td style="text-align: right;">27969.1</td>\n<td style="text-align: right;">0.1291</td>\n</tr>\n</tbody>\n</table>\n<span class="paragraph">По AIC лучшая модель — гамма (параметры формы 1.48 и масштаба 4.31 при loc = 0). По расстоянию KS лучшее — лог-нормальное. Критерии расходятся, потому что AIC оценивает правдоподобие всей выборки, а KS — максимальное расхождение функций распределения. При этом все значения KS больше 0.11: ни одна простая гладкая модель сахар не описывает хорошо (у данных пик около 1.2 г/л и «полка» до 20 г/л). Для генератора поэтому разумно рассмотреть эмпирическое квантильное преобразование.</span></span>', 'source': '#### Сравнение распределений\n\nДля сравнения моделей используются критерии **AIC** и **KS D**: чем меньше их значения, тем лучше модель описывает данные. Наиболее подходящее распределение выбирается по минимальному AIC.\n\nДля всех моделей принято `loc=0`. При этом логнормальное, гамма-распределение и распределение Вейбулла имеют по два оцениваемых параметра, экспоненциальное — один.\n\nПоскольку данные могут содержать несколько пиков и выбросы, выбранная модель является приближением. Для более точного воспроизведения исходного распределения можно использовать эмпирический метод.\n\n**Сопоставление подобранных моделей.**\n\n| Распределение | k | AIC | KS D |\n|---|---:|---:|---:|\n| Гамма | 2 | **27559.6** | 0.1198 |\n| Вейбулла | 2 | 27584.8 | 0.1180 |\n| Лог-нормальное | 2 | 27611.9 | **0.1108** |\n| Экспоненциальное | 1 | 27969.1 | 0.1291 |\n\nПо AIC лучшая модель — гамма (параметры формы 1.48 и масштаба 4.31 при loc = 0). По расстоянию KS лучшее — лог-нормальное. Критерии расходятся, потому что AIC оценивает правдоподобие всей выборки, а KS — максимальное расхождение функций распределения. При этом все значения KS больше 0.11: ни одна простая гладкая модель сахар не описывает хорошо (у данных пик около 1.2 г/л и «полка» до 20 г/л). Для генератора поэтому разумно рассмотреть эмпирическое квантильное преобразование.'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><h4 id="sprint1-heading-76-1"><span class="notebook-index">2.2.4</span>Логарифмическое преобразование</h4></span>', 'source': '#### Логарифмическое преобразование'}, {'kind': 'code', 'html': '<figure class="plot plot-square"><img width="642" height="498" decoding="async" data-report-asset="./public/reports/sprint1/77-0.png" src="data:image/png;base64," alt="График исследования" /></figure>', 'source': 'hist_kde(df["residual sugar"], "residual sugar, г/л", bins=40)\nplt.title("residual sugar: гистограмма и KDE")\nplt.show()'}, {'kind': 'code', 'html': '<figure class="plot plot-wide"><img width="1308" height="426" decoding="async" data-report-asset="./public/reports/sprint1/78-0.png" src="data:image/png;base64," alt="График исследования" /></figure><pre class="numeric-result">Асимметрия: до 1.077 , после -0.161\nЭксцесс:    до 3.47 , после -1.352\nШапиро-Уилк для ln(сахар): ShapiroResult(statistic=np.float64(0.9305950187852422), pvalue=np.float64(6.368238728030208e-43))\nAIC (лог-нормальное, пересчитано на исходную шкалу): 27611.85003815327\nИТОГ ln(сахар): skew=1.0771 -&gt; -0.1612; kurt=3.4698 -&gt; -1.3523; Shapiro p=6.3682e-43\n</pre>', 'source': 's = df["residual sugar"]\ns_log = np.log(s)\n\nprint("Асимметрия: до", round(s.skew(), 3), ", после", round(s_log.skew(), 3))\nprint("Эксцесс:    до", round(s.kurt(), 3), ", после", round(s_log.kurt(), 3))\nprint("Шапиро-Уилк для ln(сахар):", stats.shapiro(s_log))\n\nfig, axes = plt.subplots(1, 2, figsize=(12, 4))\nhist_kde(s_log, "ln(residual sugar)", bins=30, ax=axes[0])\nstats.probplot(s_log, dist="norm", plot=axes[1])\naxes[1].set_title("Q-Q график для ln(сахар)")\nplt.tight_layout()\nplt.show()\n\n# Нормальное на логарифмах = лог-нормальное на исходных данных\nmu_l, sd_l = stats.norm.fit(s_log)\nll_log = np.sum(stats.norm.logpdf(s_log, mu_l, sd_l)) - np.sum(s_log)  # поправка на замену переменной\nprint("AIC (лог-нормальное, пересчитано на исходную шкалу):", 2 * 2 - 2 * ll_log)\nprint(f"ИТОГ ln(сахар): skew={s.skew():.4f} -> {s_log.skew():.4f}; kurt={s.kurt():.4f} -> {s_log.kurt():.4f}; Shapiro p={stats.shapiro(s_log).pvalue:.5g}")\n'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><span class="paragraph"><strong>Вывод по логарифмированию остаточного сахара.</strong> Логарифмирование уменьшает влияние больших значений и меняет асимметрию и эксцесс, но не гарантирует нормального распределения: окончательный вывод делается по Q-Q графику и критерию Шапиро—Уилка. Численные значения до и после преобразования, p-value и AIC выводятся непосредственно в ячейке выше. AIC логнормальной модели, вычисленный на исходной шкале с учётом якобиана преобразования, должен совпасть с AIC двухпараметрического логнормального распределения из таблицы (с учётом округления). Сравнивать AIC на разных шкалах без поправки нельзя.</span></span>', 'source': '**Вывод по логарифмированию остаточного сахара.** Логарифмирование уменьшает влияние больших значений и меняет асимметрию и эксцесс, но не гарантирует нормального распределения: окончательный вывод делается по Q-Q графику и критерию Шапиро—Уилка. Численные значения до и после преобразования, p-value и AIC выводятся непосредственно в ячейке выше. AIC логнормальной модели, вычисленный на исходной шкале с учётом якобиана преобразования, должен совпасть с AIC двухпараметрического логнормального распределения из таблицы (с учётом округления). Сравнивать AIC на разных шкалах без поправки нельзя.\n'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><h4 id="sprint1-heading-80-1"><span class="notebook-index">2.2.5</span>Математическая база распределения</h4>\n<span class="paragraph"><strong>1. Логнормальное распределение</strong></span>\n<span class="paragraph">Если <marimo-tex class="arithmatex">||(Y=\\ln X||)</marimo-tex> имеет нормальное распределение, то плотность <marimo-tex class="arithmatex">||(X||)</marimo-tex>:</span>\n<marimo-tex class="arithmatex">||[\nf_{LN}(x)=\\frac{1}{xs\\sqrt{2\\pi}}\\exp\\left(-\\frac{(\\ln x-m)^2}{2s^2}\\right), \\quad x&gt;0\n||]</marimo-tex><span class="paragraph">В <code>scipy.stats.lognorm</code> параметр <code>shape</code> равен <marimo-tex class="arithmatex">||(s||)</marimo-tex>, <code>scale</code> равен <marimo-tex class="arithmatex">||(e^m||)</marimo-tex>, <code>loc=0</code>. Распределение имеет правостороннюю асимметрию.</span>\n<marimo-tex class="arithmatex">||[\nE[X]=e^{m+s^2/2}\n||]</marimo-tex><span class="paragraph"><strong>2. Гамма-распределение</strong></span>\n<span class="paragraph">Плотность распределения:</span>\n<marimo-tex class="arithmatex">||[\nf_G(x)=\\frac{x^{k-1}e^{-x/\\theta}}{\\Gamma(k)\\theta^k}, \\quad x&gt;0\n||]</marimo-tex><span class="paragraph">где <marimo-tex class="arithmatex">||(k&gt;0||)</marimo-tex> — параметр формы (<code>a</code> в SciPy), <marimo-tex class="arithmatex">||(\\theta&gt;0||)</marimo-tex> — масштаб (<code>scale</code>).</span>\n<marimo-tex class="arithmatex">||[\nE[X]=k\\theta, \\qquad Var(X)=k\\theta^2\n||]</marimo-tex><span class="paragraph">Гамма-распределение используется для описания положительных асимметричных величин.</span>\n<span class="paragraph"><strong>3. Распределение Вейбулла</strong></span>\n<span class="paragraph">Плотность распределения:</span>\n<marimo-tex class="arithmatex">||[\nf_W(x)=\\frac{k}{\\lambda}\\left(\\frac{x}{\\lambda}\\right)^{k-1}\\exp\\left[-\\left(\\frac{x}{\\lambda}\\right)^k\\right], \\quad x&gt;0\n||]</marimo-tex><span class="paragraph">где <marimo-tex class="arithmatex">||(k&gt;0||)</marimo-tex> — параметр формы (<code>c</code> в SciPy), <marimo-tex class="arithmatex">||(\\lambda&gt;0||)</marimo-tex> — масштаб (<code>scale</code>).</span>\n<span class="paragraph">При <marimo-tex class="arithmatex">||(k=1||)</marimo-tex> распределение становится экспоненциальным. Изменение параметра формы влияет на асимметрию и хвост распределения.</span>\n<span class="paragraph"><strong>4. Экспоненциальное распределение</strong></span>\n<span class="paragraph">Плотность распределения:</span>\n<marimo-tex class="arithmatex">||[\nf_E(x)=\\lambda e^{-\\lambda x}, \\quad x\\geq 0\n||]</marimo-tex><span class="paragraph">где <marimo-tex class="arithmatex">||(\\lambda&gt;0||)</marimo-tex> — параметр интенсивности.</span>\n<marimo-tex class="arithmatex">||[\nE[X]=\\frac{1}{\\lambda}\n||]</marimo-tex><span class="paragraph">В SciPy <code>scale=1/λ</code>. Это однопараметрическая модель с убывающей плотностью.</span>\n<span class="paragraph"><strong>Выбор распределений</strong></span>\n<span class="paragraph">Концентрация остаточного сахара неотрицательна, а её распределение имеет правостороннюю асимметрию и может содержать экстремальные значения. Рассмотренные модели позволяют описывать такие данные с разной точностью.</span>\n<span class="paragraph">Параметры оцениваются методом максимального правдоподобия, а сравнение моделей проводится по критериям <strong>AIC</strong> и <strong>KS D</strong>.</span></span>', 'source': '\n#### Математическая база распределения\n\n**1. Логнормальное распределение**\n\nЕсли $Y=\\ln X$ имеет нормальное распределение, то плотность $X$:\n\n$$\nf_{LN}(x)=\\frac{1}{xs\\sqrt{2\\pi}}\\exp\\left(-\\frac{(\\ln x-m)^2}{2s^2}\\right), \\quad x>0\n$$\n\nВ `scipy.stats.lognorm` параметр `shape` равен $s$, `scale` равен $e^m$, `loc=0`. Распределение имеет правостороннюю асимметрию.\n\n$$\nE[X]=e^{m+s^2/2}\n$$\n\n**2. Гамма-распределение**\n\nПлотность распределения:\n\n$$\nf_G(x)=\\frac{x^{k-1}e^{-x/\\theta}}{\\Gamma(k)\\theta^k}, \\quad x>0\n$$\n\nгде $k>0$ — параметр формы (`a` в SciPy), $\\theta>0$ — масштаб (`scale`).\n\n$$\nE[X]=k\\theta, \\qquad Var(X)=k\\theta^2\n$$\n\nГамма-распределение используется для описания положительных асимметричных величин.\n\n**3. Распределение Вейбулла**\n\nПлотность распределения:\n\n$$\nf_W(x)=\\frac{k}{\\lambda}\\left(\\frac{x}{\\lambda}\\right)^{k-1}\\exp\\left[-\\left(\\frac{x}{\\lambda}\\right)^k\\right], \\quad x>0\n$$\n\nгде $k>0$ — параметр формы (`c` в SciPy), $\\lambda>0$ — масштаб (`scale`).\n\nПри $k=1$ распределение становится экспоненциальным. Изменение параметра формы влияет на асимметрию и хвост распределения.\n\n**4. Экспоненциальное распределение**\n\nПлотность распределения:\n\n$$\nf_E(x)=\\lambda e^{-\\lambda x}, \\quad x\\geq 0\n$$\n\nгде $\\lambda>0$ — параметр интенсивности.\n\n$$\nE[X]=\\frac{1}{\\lambda}\n$$\n\nВ SciPy `scale=1/λ`. Это однопараметрическая модель с убывающей плотностью.\n\n**Выбор распределений**\n\nКонцентрация остаточного сахара неотрицательна, а её распределение имеет правостороннюю асимметрию и может содержать экстремальные значения. Рассмотренные модели позволяют описывать такие данные с разной точностью.\n\nПараметры оцениваются методом максимального правдоподобия, а сравнение моделей проводится по критериям **AIC** и **KS D**.\n'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><h4 id="sprint1-heading-81-1"><span class="notebook-index">2.2.6</span>Нормализация</h4></span>', 'source': '#### Нормализация'}, {'kind': 'code', 'html': '<figure class="plot plot-wide"><img width="1308" height="427" decoding="async" data-report-asset="./public/reports/sprint1/82-0.png" src="data:image/png;base64," alt="График исследования" /></figure><pre class="numeric-result">Среднее после стандартизации: -1.1097696873345787e-16\nStd после стандартизации: 1.0\nАсимметрия до и после: 1.0770937564240868 1.077093756424087\n</pre>', 'source': 'sugar_z = (residual_sugar - residual_sugar.mean()) / residual_sugar.std(ddof=1)\nprint("Среднее после стандартизации:", sugar_z.mean())\nprint("Std после стандартизации:", sugar_z.std(ddof=1))\nprint("Асимметрия до и после:", residual_sugar.skew(), sugar_z.skew())\n\nfig, axs = plt.subplots(1, 2, figsize=(12, 4))\naxs[0].hist(sugar_values, bins=40, density=True, color="#6389B8")\naxs[0].set(xlabel="Остаточный сахар, г/л", ylabel="Плотность", title="До")\naxs[1].hist(sugar_z, bins=40, density=True, color="#76B391", alpha=.7)\nsugar_z_grid = np.linspace(sugar_z.min(), sugar_z.max(), 350)\naxs[1].plot(sugar_z_grid, stats.norm.pdf(sugar_z_grid), color="red", label="N(0, 1)")\naxs[1].set(xlabel="z (безразмерное)", ylabel="Плотность", title="После")\naxs[1].legend()\nplt.tight_layout()\nplt.show()'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><span class="paragraph">Стандартизация выполняется по формуле:</span>\n<marimo-tex class="arithmatex">||[\nz_i = \\frac{x_i - \\bar{x}}{s}\n||]</marimo-tex><span class="paragraph">После стандартизации среднее значение становится равным <strong>0</strong>, а выборочное стандартное отклонение — <strong>1</strong>.</span>\n<span class="paragraph">Асимметрия остаётся <strong>1.0771</strong>, поэтому распределение сохраняет правостороннюю асимметрию и не становится нормальным.</span>\n<span class="paragraph">Стандартизация позволяет сравнивать остаточный сахар, pH и содержание алкоголя на единой безразмерной шкале.</span></span>', 'source': 'Стандартизация выполняется по формуле:\n\n$$\nz_i = \\frac{x_i - \\bar{x}}{s}\n$$\n\nПосле стандартизации среднее значение становится равным **0**, а выборочное стандартное отклонение — **1**.\n\nАсимметрия остаётся **1.0771**, поэтому распределение сохраняет правостороннюю асимметрию и не становится нормальным.\n\nСтандартизация позволяет сравнивать остаточный сахар, pH и содержание алкоголя на единой безразмерной шкале.\n'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><h3 id="sprint1-heading-84-1"><span class="notebook-index">2.3</span>Independence &amp; Estimations</h3></span>', 'source': '\n### Independence & Estimations\n'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><h4 id="sprint1-heading-85-1"><span class="notebook-index">2.3.1</span>Зависимость от pH и содержания алкоголя</h4></span>', 'source': '#### Зависимость от pH и содержания алкоголя'}, {'kind': 'code', 'html': '<figure class="plot plot-wide"><img width="1308" height="426" decoding="async" data-report-asset="./public/reports/sprint1/86-0.png" src="data:image/png;base64," alt="График исследования" /></figure><pre class="numeric-result">residual sugar / pH: Пирсон r=-0.1941 (p=8.40e-43); Спирмен rho=-0.1800 (p=5.91e-37)\nresidual sugar / alcohol: Пирсон r=-0.4506 (p=1.21e-243); Спирмен rho=-0.4453 (p=3.09e-237)\n</pre>', 'source': 'for sugar_other_col in ["pH", "alcohol"]:\n    r, p = stats.pearsonr(df["residual sugar"], df[sugar_other_col])\n    rho, p_s = stats.spearmanr(df["residual sugar"], df[sugar_other_col])\n    print(f"residual sugar / {sugar_other_col}: Пирсон r={r:.4f} (p={p:.2e}); "\n          f"Спирмен rho={rho:.4f} (p={p_s:.2e})")\n\nfig, axs = plt.subplots(1, 2, figsize=(12, 4))\nfor ax, sugar_other_col in zip(axs, ["pH", "alcohol"]):\n    ax.scatter(df[sugar_other_col], df["residual sugar"], s=6, alpha=.25)\n    ax.set(xlabel=sugar_other_col, ylabel="Остаточный сахар, г/л",\n           title=f"Residual sugar и {sugar_other_col}")\nplt.tight_layout()\nplt.show()'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><h4 id="sprint1-heading-87-1"><span class="notebook-index">2.3.2</span>Анализ корреляций</h4>\n<span class="paragraph">Остаточный сахар имеет <strong>слабую отрицательную корреляцию с pH</strong> (Пирсон <marimo-tex class="arithmatex">||(r=-0.194||)</marimo-tex>, Спирмен <marimo-tex class="arithmatex">||(\\rho=-0.180||)</marimo-tex>) и <strong>умеренную отрицательную корреляцию с алкоголем</strong> (<marimo-tex class="arithmatex">||(r=-0.451||)</marimo-tex>, <marimo-tex class="arithmatex">||(\\rho=-0.445||)</marimo-tex>).</span>\n<span class="paragraph">Малые значения p-value указывают на статистическую значимость связей. Следовательно, показатели не являются независимыми.</span>\n<span class="paragraph">Наиболее выражена обратная связь сахара и алкоголя, что согласуется с процессом брожения, при котором сахар превращается в этанол. Однако корреляция не доказывает причинно-следственную связь.</span></span>', 'source': '#### Анализ корреляций\n\nОстаточный сахар имеет **слабую отрицательную корреляцию с pH** (Пирсон $r=-0.194$, Спирмен $\\rho=-0.180$) и **умеренную отрицательную корреляцию с алкоголем** ($r=-0.451$, $\\rho=-0.445$).\n\nМалые значения p-value указывают на статистическую значимость связей. Следовательно, показатели не являются независимыми.\n\nНаиболее выражена обратная связь сахара и алкоголя, что согласуется с процессом брожения, при котором сахар превращается в этанол. Однако корреляция не доказывает причинно-следственную связь.\n'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><span class="paragraph">Критерий χ² для пары alcohol и residual sugar приведён один раз в разделе «Независимость трёх величин» (перед Lab resume).</span></span>', 'source': 'Критерий χ² для пары alcohol и residual sugar приведён один раз в разделе «Независимость трёх величин» (перед Lab resume).'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><h4 id="sprint1-heading-89-1"><span class="notebook-index">2.3.3</span>Состоятельность оценок</h4></span>', 'source': '#### Состоятельность оценок'}, {'kind': 'code', 'html': '<figure class="plot plot-wide"><img width="1308" height="426" decoding="async" data-report-asset="./public/reports/sprint1/90-0.png" src="data:image/png;base64," alt="График исследования" /></figure><pre class="numeric-result">   n  RMSE среднего, г/л\n  10             1.63642\n  30             0.92322\n 100             0.51789\n 300             0.27272\n1000             0.13966\n3000             0.08352\n</pre>', 'source': 'sugar_rng = np.random.default_rng(SEED)\nsugar_sizes = [10, 30, 100, 300, 1000, 3000]\nsugar_means = []\nsugar_stds = []\nsugar_rmses = []\nfor sample_size in sugar_sizes:\n    ms, ss = [], []\n    for _ in range(200):\n        sampled_sugar = sugar_rng.choice(sugar_values, size=sample_size, replace=True)\n        ms.append(sampled_sugar.mean())\n        ss.append(sampled_sugar.std(ddof=1))\n    sugar_means.append(ms)\n    sugar_stds.append(ss)\n    sugar_rmses.append(np.sqrt(np.mean((np.array(ms) - sugar_values.mean()) ** 2)))\n\nprint(pd.DataFrame({"n": sugar_sizes, "RMSE среднего, г/л": sugar_rmses}).round(5).to_string(index=False))\nfig, axs = plt.subplots(1, 2, figsize=(12, 4))\naxs[0].boxplot(sugar_means, tick_labels=sugar_sizes)\naxs[0].axhline(sugar_values.mean(), color="red")\naxs[0].set(xlabel="n", ylabel="Среднее сахара, г/л", title="Средние")\naxs[1].boxplot(sugar_stds, tick_labels=sugar_sizes)\naxs[1].axhline(sugar_values.std(ddof=1), color="red")\naxs[1].set(xlabel="n", ylabel="Std сахара, г/л", title="Стандартные отклонения")\nplt.tight_layout()\nplt.show()'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><span class="paragraph">По мере увеличения <marimo-tex class="arithmatex">||(n||)</marimo-tex> оценки среднего и стандартного отклонения концентрируются вокруг значений для всей таблицы (красные линии), а RMSE среднего уменьшается. Это иллюстрирует состоятельность оценок: при больших выборках случайная ошибка становится меньше. Из-за тяжёлого правого хвоста редкие большие значения сахара могут заметно менять стандартное отклонение в маленьких выборках. В эксперименте выборка берётся <strong>с возвращением</strong>, а «истинные» параметры условно равны статистикам 4898 записей, не всех белых вин в мире.</span></span>', 'source': 'По мере увеличения $n$ оценки среднего и стандартного отклонения концентрируются вокруг значений для всей таблицы (красные линии), а RMSE среднего уменьшается. Это иллюстрирует состоятельность оценок: при больших выборках случайная ошибка становится меньше. Из-за тяжёлого правого хвоста редкие большие значения сахара могут заметно менять стандартное отклонение в маленьких выборках. В эксперименте выборка берётся **с возвращением**, а «истинные» параметры условно равны статистикам 4898 записей, не всех белых вин в мире.'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><h4 id="sprint1-heading-92-1"><span class="notebook-index">2.3.4</span>Выборки с возвращением и без</h4></span>', 'source': '#### Выборки с возвращением и без'}, {'kind': 'code', 'html': '<pre class="numeric-result">            Вся таблица  Без возвращения  С возвращением\nСреднее          6.3914           6.4448          6.5832\nStd              5.0721           5.0270          5.1802\nМедиана          5.2000           5.4000          5.3500\nАсимметрия       1.0771           0.7351          0.7534\nБез возвращения: разброс средних 0.21220, теория 0.21494\nС возвращением: разброс средних 0.22722, теория 0.22681\n</pre>', 'source': 'sugar_rng = np.random.default_rng(SEED)\nsugar_n = N_SAMPLE\nsugar_without = sugar_rng.choice(sugar_values, sugar_n, replace=False)\nsugar_with = sugar_rng.choice(sugar_values, sugar_n, replace=True)\nprint(pd.DataFrame({\n    "Вся таблица": [sugar_values.mean(), sugar_values.std(ddof=1), np.median(sugar_values),\n                    stats.skew(sugar_values, bias=False)],\n    "Без возвращения": [sugar_without.mean(), sugar_without.std(ddof=1), np.median(sugar_without),\n                         stats.skew(sugar_without, bias=False)],\n    "С возвращением": [sugar_with.mean(), sugar_with.std(ddof=1), np.median(sugar_with),\n                        stats.skew(sugar_with, bias=False)]\n}, index=["Среднее", "Std", "Медиана", "Асимметрия"]).round(4).to_string())\n\nsugar_rng = np.random.default_rng(SEED)\nsugar_rep = 1000\nsugar_m_no = np.array([sugar_rng.choice(sugar_values, sugar_n, replace=False).mean()\n                       for _ in range(sugar_rep)])\nsugar_m_yes = np.array([sugar_rng.choice(sugar_values, sugar_n, replace=True).mean()\n                        for _ in range(sugar_rep)])\nsugar_N = len(sugar_values)\nsugar_sigma_N = sugar_values.std(ddof=0)\nsugar_se_yes = sugar_sigma_N / np.sqrt(sugar_n)\nsugar_se_no = sugar_se_yes * np.sqrt((sugar_N - sugar_n) / (sugar_N - 1))\nprint(f"Без возвращения: разброс средних {sugar_m_no.std(ddof=1):.5f}, теория {sugar_se_no:.5f}")\nprint(f"С возвращением: разброс средних {sugar_m_yes.std(ddof=1):.5f}, теория {sugar_se_yes:.5f}")'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><span class="paragraph">При выборке <strong>с возвращением</strong> одно наблюдение может выбираться несколько раз, а <strong>без возвращения</strong> — только один раз.</span>\n<span class="paragraph">Теоретическая стандартная ошибка среднего:</span>\n<span class="paragraph"><strong>С возвращением:</strong></span>\n<marimo-tex class="arithmatex">||[\nSE = \\frac{\\sigma_N}{\\sqrt{n}}\n||]</marimo-tex><span class="paragraph"><strong>Без возвращения:</strong></span>\n<marimo-tex class="arithmatex">||[\nSE = \\frac{\\sigma_N}{\\sqrt{n}}\\sqrt{\\frac{N-n}{N-1}}\n||]</marimo-tex><span class="paragraph">При <marimo-tex class="arithmatex">||(N=4898||)</marimo-tex> и <marimo-tex class="arithmatex">||(n=500||)</marimo-tex> стандартные ошибки составляют <strong>0.2268 г/л</strong> и <strong>0.2149 г/л</strong> соответственно.</span>\n<span class="paragraph">Таким образом, <strong>выборка без возвращения имеет меньший разброс среднего</strong> благодаря поправке на конечную совокупность. Для проверки результата проводится <strong>1000 повторных выборок</strong>, после чего экспериментальные значения сравниваются с теоретическими.</span>\n<span class="paragraph"><strong>Результаты повторных выборок.</strong> На 1000 повторов разброс средних: без возвращения 0.2122 г/л (теория 0.2149), с возвращением 0.2272 г/л (теория 0.2268). Без возвращения разброс меньше, как и предсказывает поправка на конечную совокупность. В единичных выборках по 500 асимметрия (0.74 и 0.75) заметно ниже, чем во всей таблице (1.08): редкие вина с очень большим сахаром в выборку почти не попадают, а они и дают хвост.</span></span>', 'source': 'При выборке **с возвращением** одно наблюдение может выбираться несколько раз, а **без возвращения** — только один раз.\n\nТеоретическая стандартная ошибка среднего:\n\n**С возвращением:**\n\n$$\nSE = \\frac{\\sigma_N}{\\sqrt{n}}\n$$\n\n**Без возвращения:**\n\n$$\nSE = \\frac{\\sigma_N}{\\sqrt{n}}\\sqrt{\\frac{N-n}{N-1}}\n$$\n\nПри $N=4898$ и $n=500$ стандартные ошибки составляют **0.2268 г/л** и **0.2149 г/л** соответственно.\n\nТаким образом, **выборка без возвращения имеет меньший разброс среднего** благодаря поправке на конечную совокупность. Для проверки результата проводится **1000 повторных выборок**, после чего экспериментальные значения сравниваются с теоретическими.\n\n**Результаты повторных выборок.** На 1000 повторов разброс средних: без возвращения 0.2122 г/л (теория 0.2149), с возвращением 0.2272 г/л (теория 0.2268). Без возвращения разброс меньше, как и предсказывает поправка на конечную совокупность. В единичных выборках по 500 асимметрия (0.74 и 0.75) заметно ниже, чем во всей таблице (1.08): редкие вина с очень большим сахаром в выборку почти не попадают, а они и дают хвост.'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><span class="paragraph">Стратифицированная выборка (по оценке качества <code>quality</code>) и ответ на вопрос «можно ли по выборке судить о генеральной совокупности» приведены в разделе «Выборка и генеральная совокупность» (перед литературой).</span></span>', 'source': 'Стратифицированная выборка (по оценке качества `quality`) и ответ на вопрос «можно ли по выборке судить о генеральной совокупности» приведены в разделе «Выборка и генеральная совокупность» (перед литературой).'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><h4 id="sprint1-heading-96-1"><span class="notebook-index">2.3.5</span>Проверка гипотезы</h4></span>', 'source': '#### Проверка гипотезы'}, {'kind': 'code', 'html': '<pre class="numeric-result">Выборка n=N_SAMPLE: mean=6.444800 г/л, t=0.1993, p=0.842130\n95%-й ДИ для среднего: [6.0031; 6.8865] г/л\nВся таблица: t=-0.1185, p=0.905708\nРешение при α=0.05: нет оснований отвергнуть H0\n</pre>', 'source': 'sugar_rng = np.random.default_rng(SEED)\nsugar_sample = sugar_rng.choice(sugar_values, size=N_SAMPLE, replace=False)\nsugar_mu0 = 6.4  # г/л; условное проверяемое значение, а не отраслевой норматив\nsugar_test = stats.ttest_1samp(sugar_sample, sugar_mu0)\nsugar_ci = stats.t.interval(.95, df=len(sugar_sample)-1,\n                            loc=sugar_sample.mean(), scale=stats.sem(sugar_sample))\nsugar_full_test = stats.ttest_1samp(sugar_values, sugar_mu0)\nprint(f"Выборка n=N_SAMPLE: mean={sugar_sample.mean():.6f} г/л, "\n      f"t={sugar_test.statistic:.4f}, p={sugar_test.pvalue:.6f}")\nprint(f"95%-й ДИ для среднего: [{sugar_ci[0]:.4f}; {sugar_ci[1]:.4f}] г/л")\nprint(f"Вся таблица: t={sugar_full_test.statistic:.4f}, p={sugar_full_test.pvalue:.6f}")\nprint("Решение при α=0.05:",\n      "отвергаем H0" if sugar_test.pvalue < .05 else "нет оснований отвергнуть H0")'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><span class="paragraph">Проверяем гипотезы о среднем содержании остаточного сахара:</span>\n<marimo-tex class="arithmatex">||[\nH_0: \\mu = 6.4 \\text{ г/л}\n||]</marimo-tex><marimo-tex class="arithmatex">||[\nH_1: \\mu \\neq 6.4 \\text{ г/л}\n||]</marimo-tex><span class="paragraph">Уровень значимости: <marimo-tex class="arithmatex">||(\\alpha = 0.05||)</marimo-tex>. Значение 6.4 г/л выбрано условно, как близкое к среднему по данным.</span>\n<span class="paragraph">Для выборки из <strong>500 наблюдений</strong> рассчитываются t-статистика, p-value и 95%-й доверительный интервал. Аналогичный тест проводится для всей таблицы.</span>\n<span class="paragraph">Если <marimo-tex class="arithmatex">||(p &lt; 0.05||)</marimo-tex>, <strong>нулевая гипотеза отвергается</strong>, иначе оснований для её отклонения недостаточно.</span>\n<span class="paragraph">При большом объёме выборки применение t-теста обосновано центральной предельной теоремой. Однако асимметрия данных, выбросы и возможная зависимость наблюдений могут влиять на точность результатов.</span>\n<span class="paragraph"><strong>Результат (результат).</strong> На выборке из 500: среднее 6.4448 г/л, t = 0.199, p = 0.842, 95%-й ДИ [6.00; 6.89], поэтому <marimo-tex class="arithmatex">||(H_0||)</marimo-tex> не отвергаем. На всей таблице t = −0.119, p = 0.906, вывод тот же. Гипотеза взята рядом со средним, поэтому «не отвергнута» ожидаемо; отдельная проверка со сравнением групп по качеству приведена ниже.</span></span>', 'source': 'Проверяем гипотезы о среднем содержании остаточного сахара:\n\n$$\nH_0: \\mu = 6.4 \\text{ г/л}\n$$\n\n$$\nH_1: \\mu \\neq 6.4 \\text{ г/л}\n$$\n\nУровень значимости: $\\alpha = 0.05$. Значение 6.4 г/л выбрано условно, как близкое к среднему по данным.\n\nДля выборки из **500 наблюдений** рассчитываются t-статистика, p-value и 95%-й доверительный интервал. Аналогичный тест проводится для всей таблицы.\n\nЕсли $p < 0.05$, **нулевая гипотеза отвергается**, иначе оснований для её отклонения недостаточно.\n\nПри большом объёме выборки применение t-теста обосновано центральной предельной теоремой. Однако асимметрия данных, выбросы и возможная зависимость наблюдений могут влиять на точность результатов.\n\n**Результат (результат).** На выборке из 500: среднее 6.4448 г/л, t = 0.199, p = 0.842, 95%-й ДИ [6.00; 6.89], поэтому $H_0$ не отвергаем. На всей таблице t = −0.119, p = 0.906, вывод тот же. Гипотеза взята рядом со средним, поэтому «не отвергнута» ожидаемо; отдельная проверка со сравнением групп по качеству приведена ниже.'}, {'kind': 'code', 'html': '<pre class="numeric-result">Вин с quality &gt;= 7: 1060 , с quality &lt;= 5: 1640\nМедиана residual sugar: высокое качество = 3.875 , низкое = 6.625\nU = 734322.5 , p = 9.136645717794553e-12 , размер эффекта (r_rb) = -0.155\nРешение при alpha=0.05: отвергаем H0; p=9.1366e-12; медианы=3.875 и 6.625; r_rb=-0.1552\n</pre>', 'source': '# Гипотеза: остаточный сахар у вин с высокой и низкой оценкой качества различается\nhigh = df.loc[df["quality"] >= 7, "residual sugar"]\nlow = df.loc[df["quality"] <= 5, "residual sugar"]\nu, p_u = stats.mannwhitneyu(high, low, alternative="two-sided")\nrbc = 2 * u / (len(high) * len(low)) - 1   # ранговая бисериальная корреляция (размер эффекта)\nprint("Вин с quality >= 7:", len(high), ", с quality <= 5:", len(low))\nprint("Медиана residual sugar: высокое качество =", high.median(), ", низкое =", low.median())\nprint("U =", u, ", p =", p_u, ", размер эффекта (r_rb) =", round(rbc, 3))\nprint(f"Решение при alpha=0.05: {\'отвергаем H0\' if p_u < 0.05 else \'нет оснований отвергнуть H0\'}; p={p_u:.5g}; медианы={high.median():.4g} и {low.median():.4g}; r_rb={rbc:.4f}")\n'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><span class="paragraph"><strong>Гипотеза о связи остаточного сахара с качеством.</strong> Проверяется <marimo-tex class="arithmatex">||(H_0||)</marimo-tex>: распределения показателя у вин с оценками не ниже 7 и не выше 5 совпадают; <marimo-tex class="arithmatex">||(H_1||)</marimo-tex>: распределения различаются (<marimo-tex class="arithmatex">||(\\alpha=0.05||)</marimo-tex>). Для двух независимых групп использован двусторонний критерий Манна—Уитни, который не требует нормальности данных. Точные p-value, медианы и ранговая бисериальная корреляция вычисляются в ячейке выше. При p &lt; 0.05 нулевая гипотеза отвергается; величина эффекта помогает оценить практическую значимость различия. Наблюдаемая связь не доказывает, что именно остаточного сахара определяет качество: на оценку могут влиять и другие характеристики вина.</span></span>', 'source': '**Гипотеза о связи остаточного сахара с качеством.** Проверяется $H_0$: распределения показателя у вин с оценками не ниже 7 и не выше 5 совпадают; $H_1$: распределения различаются ($\\alpha=0.05$). Для двух независимых групп использован двусторонний критерий Манна—Уитни, который не требует нормальности данных. Точные p-value, медианы и ранговая бисериальная корреляция вычисляются в ячейке выше. При p < 0.05 нулевая гипотеза отвергается; величина эффекта помогает оценить практическую значимость различия. Наблюдаемая связь не доказывает, что именно остаточного сахара определяет качество: на оценку могут влиять и другие характеристики вина.\n'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><h3 id="sprint1-heading-101-1"><span class="notebook-index">2.4</span>Итоговый вывод по residual sugar</h3>\n<span class="paragraph"><strong>Остаточный сахар</strong> — неотрицательная непрерывная случайная величина: для случайно выбранного вина точную концентрацию нельзя определить заранее без знания условий производства и измерения. В 4898 строках среднее <strong>6.3914</strong> <strong>г/л</strong>, медиана <strong>5.2</strong> <strong>г/л</strong> , стандартное отклонение <strong>5.0721 г/л</strong>. Асимметрия <strong>1.0771</strong>, эксцесс <strong>3.4698</strong> и максимум <strong>65.8</strong> г/л показывают длинный правый хвост. Гипотезу нормальности проверяли Шапиро–Уилком и Q–Q графиком; для описания распределения сопоставляем <strong>лог-нормальное, гамма, Вейбулла и экспоненциальное</strong> по AIC и KS D (по AIC лучшая гамма, по KS лучшее лог-нормальное, но все KS &gt; 0.11). Ни одна простая гладкая модель не обязана воспроизводить все локальные пики и крайние значения.</span>\n<span class="paragraph">Стандартизация приводит среднее значение к <strong>0</strong>, а стандартное отклонение — к <strong>1</strong>, сохраняя исходную асимметрию распределения.</span>\n<span class="paragraph">Обнаружена <strong>слабая отрицательная корреляция</strong> сахара с pH (<marimo-tex class="arithmatex">||(r \\approx -0.19||)</marimo-tex>) и <strong>умеренная отрицательная корреляция</strong> с алкоголем (<marimo-tex class="arithmatex">||(r \\approx -0.45||)</marimo-tex>), что указывает на наличие статистической связи.</span>\n<span class="paragraph">С увеличением объёма выборки <strong>точность оценок возрастает</strong>, а стандартная ошибка среднего при выборке без возвращения оказывается немного меньше.</span>\n<span class="paragraph">Проверка гипотезы о среднем содержании сахара <strong>6.4 г/л</strong> проводится для 500 наблюдений и всей таблицы, что позволяет оценить влияние объёма выборки на результаты теста.</span>\n<span class="paragraph">Для генератора во втором спринте разумно рассмотреть модель с минимальным AIC, но если важно точно сохранить хвост и фактическую частотную структуру, использовать эмпирическую обратную CDF.</span>\n<span class="paragraph">Литература:</span>\n<ol>\n<li>Cortez P. et al. Wine Quality [dataset]. UCI Machine Learning Repository (2009). <a href="https://doi.org/10.24432/C56S3T" rel="noopener" target="_blank">https://doi.org/10.24432/C56S3T</a></li>\n<li>SciPy Documentation, Continuous distributions: <a href="https://docs.scipy.org/doc/scipy/reference/stats.html" rel="noopener" target="_blank">https://docs.scipy.org/doc/scipy/reference/stats.html</a></li>\n</ol></span>', 'source': '### Итоговый вывод по residual sugar\n\n**Остаточный сахар** — неотрицательная непрерывная случайная величина: для случайно выбранного вина точную концентрацию нельзя определить заранее без знания условий производства и измерения. В 4898 строках среднее **6.3914** **г/л**, медиана **5.2** **г/л** , стандартное отклонение **5.0721 г/л**. Асимметрия **1.0771**, эксцесс **3.4698** и максимум **65.8** г/л показывают длинный правый хвост. Гипотезу нормальности проверяли Шапиро–Уилком и Q–Q графиком; для описания распределения сопоставляем **лог-нормальное, гамма, Вейбулла и экспоненциальное** по AIC и KS D (по AIC лучшая гамма, по KS лучшее лог-нормальное, но все KS > 0.11). Ни одна простая гладкая модель не обязана воспроизводить все локальные пики и крайние значения.\n\n\n\n\nСтандартизация приводит среднее значение к **0**, а стандартное отклонение — к **1**, сохраняя исходную асимметрию распределения.\n\nОбнаружена **слабая отрицательная корреляция** сахара с pH ($r \\approx -0.19$) и **умеренная отрицательная корреляция** с алкоголем ($r \\approx -0.45$), что указывает на наличие статистической связи.\n\nС увеличением объёма выборки **точность оценок возрастает**, а стандартная ошибка среднего при выборке без возвращения оказывается немного меньше.\n\nПроверка гипотезы о среднем содержании сахара **6.4 г/л** проводится для 500 наблюдений и всей таблицы, что позволяет оценить влияние объёма выборки на результаты теста.\n\n\nДля генератора во втором спринте разумно рассмотреть модель с минимальным AIC, но если важно точно сохранить хвост и фактическую частотную структуру, использовать эмпирическую обратную CDF.\n\nЛитература:\n1. Cortez P. et al. Wine Quality [dataset]. UCI Machine Learning Repository (2009). https://doi.org/10.24432/C56S3T\n2. SciPy Documentation, Continuous distributions: https://docs.scipy.org/doc/scipy/reference/stats.html'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><h2 id="sprint1-heading-102-1">Random Variable 03 (alcohol)</h2></span>', 'source': '## Random Variable 03 (alcohol)'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><h3 id="sprint1-heading-103-1"><span class="notebook-index">3.1</span>Description</h3>\n<span class="paragraph"><strong>Случайная величина:</strong> объёмная доля этилового спирта в белом вине (alcohol). Данные — 4898 строк таблицы Wine Quality (белые вина).</span>\n<table>\n<thead>\n<tr>\n<th>Характеристика</th>\n<th>Значение</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Единицы измерения</td>\n<td>% об.</td>\n</tr>\n<tr>\n<td>Физический тип</td>\n<td>непрерывная</td>\n</tr>\n<tr>\n<td>В таблице</td>\n<td>103 уникальных записанных значения</td>\n</tr>\n<tr>\n<td>Диапазон</td>\n<td>8.0–14.2 % об.</td>\n</tr>\n<tr>\n<td>Среднее</td>\n<td>10.5143 % об.</td>\n</tr>\n</tbody>\n</table>\n<span class="paragraph"><strong>Обоснование случайности.</strong> Алкоголь конкретного вина зависит от исходной сахаристости винограда, температуры и длительности брожения, активности дрожжей и технологических условий. Эти факторы заранее неизвестны для случайно выбранного образца. Процесс подчиняется физико-химическим закономерностям, но содержание алкоголя без информации об условиях и измерений нельзя однозначно вычислить по одной универсальной формуле. Погрешность измерения также вносит разброс.</span>\n<span class="paragraph">Физическая величина непрерывна, но в датасете измерения округлены и записаны с конечной точностью. Поэтому 103 различных значения — следствие формы записи, а не доказательство физической дискретности. В таблице есть одинаковые строки; сохраняем их, как в анализе pH: без идентификаторов неизвестно, дубликаты ли это наблюдений или разные образцы с совпавшими результатами.</span>\n<span class="paragraph"><strong>Вывод:</strong> содержание алкоголя можно рассматривать как случайную величину при случайном выборе вина из представленной совокупности.</span></span>', 'source': '### Description\n\n**Случайная величина:** объёмная доля этилового спирта в белом вине (alcohol). Данные — 4898 строк таблицы Wine Quality (белые вина).\n\n| Характеристика | Значение |\n|---|---|\n| Единицы измерения | % об. |\n| Физический тип | непрерывная |\n| В таблице | 103 уникальных записанных значения |\n| Диапазон | 8.0–14.2 % об. |\n| Среднее | 10.5143 % об. |\n\n**Обоснование случайности.** Алкоголь конкретного вина зависит от исходной сахаристости винограда, температуры и длительности брожения, активности дрожжей и технологических условий. Эти факторы заранее неизвестны для случайно выбранного образца. Процесс подчиняется физико-химическим закономерностям, но содержание алкоголя без информации об условиях и измерений нельзя однозначно вычислить по одной универсальной формуле. Погрешность измерения также вносит разброс.\n\nФизическая величина непрерывна, но в датасете измерения округлены и записаны с конечной точностью. Поэтому 103 различных значения — следствие формы записи, а не доказательство физической дискретности. В таблице есть одинаковые строки; сохраняем их, как в анализе pH: без идентификаторов неизвестно, дубликаты ли это наблюдений или разные образцы с совпавшими результатами.\n\n**Вывод:** содержание алкоголя можно рассматривать как случайную величину при случайном выборе вина из представленной совокупности.'}, {'kind': 'code', 'html': '<pre class="numeric-result">Число наблюдений: 4898\nУникальные записанные значения: 103\nНаиболее частые значения (% об.):\nalcohol\n9.4     229\n9.5     228\n9.2     199\n9.0     185\n10.0    162\n10.5    160\n11.0    158\n10.4    153\n9.1     144\n9.8     136\n</pre>', 'source': 'alcohol = df["alcohol"].dropna()\na = alcohol.to_numpy()\nprint("Число наблюдений:", len(a))\nprint("Уникальные записанные значения:", alcohol.nunique())\nprint("Наиболее частые значения (% об.):")\nprint(alcohol.value_counts().head(10).to_string())'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><h3 id="sprint1-heading-105-1"><span class="notebook-index">3.2</span>EDA &amp; Distribution</h3>\n<h4 id="sprint1-heading-105-2"><span class="notebook-index">3.2.1</span>Описательная статистика и выбросы</h4></span>', 'source': '### EDA & Distribution\n\n#### Описательная статистика и выбросы'}, {'kind': 'code', 'html': '<figure class="plot plot-wide"><img width="724" height="303" decoding="async" data-report-asset="./public/reports/sprint1/106-0.png" src="data:image/png;base64," alt="График исследования" /></figure><pre class="numeric-result">n             4898.0000\nсреднее         10.5143\nмедиана         10.4000\nмода             9.4000\nstd              1.2306\nmin              8.0000\nmax             14.2000\nQ1               9.5000\nQ3              11.4000\nасимметрия       0.4873\nэксцесс         -0.6984\nГраницы по правилу 1.5 IQR: 6.65 ... 14.25\nЧисло формальных выбросов: 0\n</pre>', 'source': 'alcohol_description = pd.Series({\n    "n": alcohol.count(),\n    "среднее": alcohol.mean(),\n    "медиана": alcohol.median(),\n    "мода": alcohol.mode().iloc[0],\n    "std": alcohol.std(ddof=1),\n    "min": alcohol.min(),\n    "max": alcohol.max(),\n    "Q1": alcohol.quantile(.25),\n    "Q3": alcohol.quantile(.75),\n    "асимметрия": alcohol.skew(),\n    "эксцесс": alcohol.kurt()\n})\nprint(alcohol_description.round(4).to_string())\nq1, q3 = alcohol.quantile([.25,.75])\nlower, upper = q1-1.5*(q3-q1), q3+1.5*(q3-q1)\nprint(f"Границы по правилу 1.5 IQR: {lower:.2f} ... {upper:.2f}")\nprint("Число формальных выбросов:", int(((alcohol<lower)|(alcohol>upper)).sum()))\nplt.figure(figsize=(8,2.5))\nplt.boxplot(a,vert=False)\nplt.xlabel("Алкоголь, % об.")\nplt.title("Alcohol: ящик с усами")\nplt.grid(axis="x",alpha=.2)\nplt.show()'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><span class="paragraph"><strong>Интерпретация.</strong> Среднее <strong>10.5143 % об.</strong>, медиана <strong>10.4 % об.</strong>, стандартное отклонение <strong>1.2306 процентного пункта</strong>. Асимметрия <strong>0.4873</strong> указывает на умеренный правый хвост; отрицательный эксцесс <strong>−0.6984</strong> — на более плоское распределение по сравнению с нормальным. Q1 = 9.5, Q3 = 11.4. По правилу 1.5 IQR выбросов нет, поэтому наблюдения не удаляем.</span></span>', 'source': '**Интерпретация.** Среднее **10.5143 % об.**, медиана **10.4 % об.**, стандартное отклонение **1.2306 процентного пункта**. Асимметрия **0.4873** указывает на умеренный правый хвост; отрицательный эксцесс **−0.6984** — на более плоское распределение по сравнению с нормальным. Q1 = 9.5, Q3 = 11.4. По правилу 1.5 IQR выбросов нет, поэтому наблюдения не удаляем.'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><h4 id="sprint1-heading-108-1"><span class="notebook-index">3.2.2</span>Форма распределения, Q–Q график и тест Шапиро–Уилка</h4></span>', 'source': '#### Форма распределения, Q–Q график и тест Шапиро–Уилка'}, {'kind': 'code', 'html': '<figure class="plot plot-wide"><img width="1638" height="426" decoding="async" data-report-asset="./public/reports/sprint1/109-0.png" src="data:image/png;base64," alt="График исследования" /></figure><pre class="numeric-result">Шапиро–Уилк: W=0.955302; p=2.569e-36\n</pre>', 'source': 'fig,axs=plt.subplots(1,3,figsize=(15,4))\naxs[0].hist(a,bins=40,color="#6389B8",alpha=.85)\naxs[0].set(xlabel="Алкоголь, % об.",ylabel="Число вин",title="Гистограмма")\nfreq=alcohol.value_counts().sort_index()\naxs[1].plot(freq.index,freq.values,".",markersize=5)\naxs[1].set(xlabel="Алкоголь, % об.",ylabel="Частота",title="Частоты записанных значений")\nstats.probplot(a,dist="norm",plot=axs[2])\naxs[2].set_title("Q–Q против нормального")\nplt.tight_layout()\nplt.show()\nw,p_shapiro=stats.shapiro(a)\nprint(f"Шапиро–Уилк: W={w:.6f}; p={p_shapiro:.3e}")'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><span class="paragraph">Гистограмма имеет несколько пиков и «зубцы» вследствие повторяющихся округлённых измерений. Точки на Q–Q графике отклоняются от линии нормального распределения, особенно в хвостах. <strong>Шапиро–Уилк:</strong> <marimo-tex class="arithmatex">||(W=0.9553||)</marimo-tex>, <marimo-tex class="arithmatex">||(p=2.57\\cdot10^{-36}||)</marimo-tex>; при <marimo-tex class="arithmatex">||(\\alpha=0.05||)</marimo-tex> гипотезу точной нормальности отвергаем. Из-за большого <marimo-tex class="arithmatex">||(n||)</marimo-tex> тест чувствителен к небольшим нарушениям формы, поэтому дополнительно сравним несколько моделей.</span></span>', 'source': 'Гистограмма имеет несколько пиков и «зубцы» вследствие повторяющихся округлённых измерений. Точки на Q–Q графике отклоняются от линии нормального распределения, особенно в хвостах. **Шапиро–Уилк:** $W=0.9553$, $p=2.57\\cdot10^{-36}$; при $\\alpha=0.05$ гипотезу точной нормальности отвергаем. Из-за большого $n$ тест чувствителен к небольшим нарушениям формы, поэтому дополнительно сравним несколько моделей.'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><h4 id="sprint1-heading-111-1"><span class="notebook-index">3.2.3</span>Сглаживание гистограммы: KDE и ширина столбиков</h4></span>', 'source': '#### Сглаживание гистограммы: KDE и ширина столбиков'}, {'kind': 'code', 'html': '<figure class="plot plot-wide"><img width="1638" height="426" decoding="async" data-report-asset="./public/reports/sprint1/112-0.png" src="data:image/png;base64," alt="График исследования" /></figure>', 'source': 'fig, axes = plt.subplots(1, 3, figsize=(15, 4))\nhist_kde(df["alcohol"], "alcohol, % об.", bins=15, ax=axes[0])\naxes[0].set_title("15 столбиков")\nhist_kde(df["alcohol"], "alcohol, % об.", bins=np.arange(8, 14.5, 0.5), ax=axes[1])\naxes[1].set_title("Ширина столбика 0.5")\nhist_kde((df["alcohol"] * 2).round() / 2, "alcohol (округлено до 0.5)", bins=np.arange(7.75, 14.5, 0.5), ax=axes[2])\naxes[2].set_title("Округлено до 0.5")\nplt.tight_layout()\nplt.show()'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><span class="paragraph"><strong>Вывод.</strong> При 15 столбиках и при ширине 0.5 % об. зубчатость гистограммы уменьшается. KDE показывает общую неоднородную форму распределения с несколькими локальными максимумами, а не строго симметричный нормальный колокол. Округление до 0.5 применяется только для визуализации; все статистические расчёты выполнены на исходных значениях.</span></span>', 'source': '**Вывод.** При 15 столбиках и при ширине 0.5 % об. зубчатость гистограммы уменьшается. KDE показывает общую неоднородную форму распределения с несколькими локальными максимумами, а не строго симметричный нормальный колокол. Округление до 0.5 применяется только для визуализации; все статистические расчёты выполнены на исходных значениях.\n'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><h4 id="sprint1-heading-114-1"><span class="notebook-index">3.2.4</span>Подбор распределения: нормальное, скошенное нормальное, гамма</h4></span>', 'source': '#### Подбор распределения: нормальное, скошенное нормальное, гамма'}, {'kind': 'code', 'html': '<figure class="plot plot-wide"><img width="978" height="426" decoding="async" data-report-asset="./public/reports/sprint1/115-0.png" src="data:image/png;base64," alt="График исследования" /></figure><pre class="numeric-result">              Модель  k        AIC   KS D\nСкошенное нормальное  3 15125.2840 0.0569\n    Гамма со сдвигом  3 15358.8376 0.0729\n          Нормальное  2 15935.7737 0.0916\nПараметры skew-normal: shape, loc, scale = (np.float64(9.981325379517678), np.float64(8.806782475860167), np.float64(2.1046650921103787))\n</pre>', 'source': 'models={\n    "Нормальное":stats.norm,\n    "Скошенное нормальное":stats.skewnorm,\n    "Гамма со сдвигом":stats.gamma\n}\nresults=[]; fitted={}\nx=np.linspace(a.min()-.3,a.max()+.3,400)\nplt.figure(figsize=(9,4))\nplt.hist(a,bins=40,density=True,alpha=.4,color="#6389B8",label="Данные")\nfor name,model in models.items():\n    pars=model.fit(a)\n    fitted[name]=pars\n    ll=model.logpdf(a,*pars).sum()\n    aic=2*len(pars)-2*ll\n    ks=stats.kstest(a,model.cdf,args=pars).statistic\n    results.append([name,len(pars),aic,ks])\n    plt.plot(x,model.pdf(x,*pars),label=name,linewidth=2)\nplt.xlabel("Алкоголь, % об.")\nplt.ylabel("Плотность")\nplt.title("Сравнение моделей")\nplt.legend()\nplt.tight_layout()\nplt.show()\nprint(pd.DataFrame(results,columns=["Модель","k","AIC","KS D"]).sort_values("AIC").round(4).to_string(index=False))\nprint("Параметры skew-normal: shape, loc, scale =",fitted["Скошенное нормальное"])'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><span class="paragraph"><strong>Результаты:</strong></span>\n<table>\n<thead>\n<tr>\n<th>Распределение</th>\n<th style="text-align: right;">AIC</th>\n<th style="text-align: right;">KS D</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Нормальное</td>\n<td style="text-align: right;">15935.77</td>\n<td style="text-align: right;">0.09160</td>\n</tr>\n<tr>\n<td>Гамма со сдвигом</td>\n<td style="text-align: right;">15358.84</td>\n<td style="text-align: right;">0.07290</td>\n</tr>\n<tr>\n<td>Скошенное нормальное</td>\n<td style="text-align: right;"><strong>15125.28</strong></td>\n<td style="text-align: right;"><strong>0.05687</strong></td>\n</tr>\n</tbody>\n</table>\n<span class="paragraph">Из этих трёх моделей <strong>скошенное нормальное лучше всего согласуется с данными</strong> по AIC и расстоянию KS. Его параметры: shape ≈ 9.9813, loc ≈ 8.8068, scale ≈ 2.1047. Но идеального соответствия нет: гладкая модель не повторяет локальные пики. Значение p-value обычного теста Колмогорова–Смирнова здесь не используем, поскольку параметры подбирались по той же выборке, а данные имеют повторяющиеся округлённые значения. AIC учитывает штраф за число параметров; KS D используем лишь для относительного сравнения.</span></span>', 'source': '**Результаты:**\n\n| Распределение | AIC | KS D |\n|---|---:|---:|\n| Нормальное | 15935.77 | 0.09160 |\n| Гамма со сдвигом | 15358.84 | 0.07290 |\n| Скошенное нормальное | **15125.28** | **0.05687** |\n\nИз этих трёх моделей **скошенное нормальное лучше всего согласуется с данными** по AIC и расстоянию KS. Его параметры: shape ≈ 9.9813, loc ≈ 8.8068, scale ≈ 2.1047. Но идеального соответствия нет: гладкая модель не повторяет локальные пики. Значение p-value обычного теста Колмогорова–Смирнова здесь не используем, поскольку параметры подбирались по той же выборке, а данные имеют повторяющиеся округлённые значения. AIC учитывает штраф за число параметров; KS D используем лишь для относительного сравнения.'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><h4 id="sprint1-heading-117-1"><span class="notebook-index">3.2.5</span>Математическая база распределения</h4>\n<span class="paragraph">Плотность <strong>нормального распределения</strong>:</span>\n<marimo-tex class="arithmatex">||[\nf_N(x)=\\frac{1}{\\sigma\\sqrt{2\\pi}}\\exp\\left(-\\frac{(x-\\mu)^2}{2\\sigma^2}\\right),\n||]</marimo-tex><span class="paragraph">где <marimo-tex class="arithmatex">||(\\mu||)</marimo-tex> — среднее, <marimo-tex class="arithmatex">||(\\sigma&gt;0||)</marimo-tex> — стандартное отклонение. Нормальное распределение симметрично, его асимметрия и эксцесс равны нулю. Оно возникает как приближение результата суммы большого числа слабых независимых воздействий, но в этих данных симметрии недостаточно.</span>\n<span class="paragraph">Плотность <strong>скошенного нормального</strong>:</span>\n<marimo-tex class="arithmatex">||[\nf_{SN}(x)=\\frac{2}{\\omega}\\varphi\\left(\\frac{x-\\xi}{\\omega}\\right)\n\\Phi\\left(\\alpha\\frac{x-\\xi}{\\omega}\\right),\n||]</marimo-tex><span class="paragraph">где <marimo-tex class="arithmatex">||(\\varphi,\\Phi||)</marimo-tex> — плотность и функция распределения стандартизованной нормальной величины, <marimo-tex class="arithmatex">||(\\xi||)</marimo-tex> задаёт положение (loc), <marimo-tex class="arithmatex">||(\\omega&gt;0||)</marimo-tex> — масштаб (scale), <marimo-tex class="arithmatex">||(\\alpha||)</marimo-tex> — асимметрию (shape). При <marimo-tex class="arithmatex">||(\\alpha=0||)</marimo-tex> получаем нормальное распределение, при положительном <marimo-tex class="arithmatex">||(\\alpha||)</marimo-tex> допускается правосторонняя асимметрия. Параметр loc не равен в общем случае среднему: если <marimo-tex class="arithmatex">||(\\delta=\\alpha/\\sqrt{1+\\alpha^2}||)</marimo-tex>, то <marimo-tex class="arithmatex">||(E(X)=\\xi+\\omega\\delta\\sqrt{2/\\pi}||)</marimo-tex>.</span>\n<span class="paragraph">Параметры оцениваем методом максимального правдоподобия через scipy.stats.skewnorm.fit. Для наблюдений с повторяющимися округлёнными значениями можно также использовать <strong>эмпирическое распределение</strong>:</span>\n<marimo-tex class="arithmatex">||[\n\\widehat P(X=x_i)=\\frac{n_i}{N},\\qquad\n\\widehat F(x)=\\frac1N\\sum_{j=1}^{N}\\mathbf 1(X_j\\le x).\n||]</marimo-tex><span class="paragraph">Здесь <marimo-tex class="arithmatex">||(n_i||)</marimo-tex> — число повторений значения, <marimo-tex class="arithmatex">||(N=4898||)</marimo-tex>. Такая модель сохраняет фактические частоты и подходит для последующего генератора по обратной функции распределения <marimo-tex class="arithmatex">||(X=\\widehat F^{-1}(U)||)</marimo-tex>, где <marimo-tex class="arithmatex">||(U\\sim U(0.1)||)</marimo-tex>.</span></span>', 'source': '#### Математическая база распределения\n\nПлотность **нормального распределения**:\n$$f_N(x)=\\frac{1}{\\sigma\\sqrt{2\\pi}}\\exp\\left(-\\frac{(x-\\mu)^2}{2\\sigma^2}\\right),$$\nгде $\\mu$ — среднее, $\\sigma>0$ — стандартное отклонение. Нормальное распределение симметрично, его асимметрия и эксцесс равны нулю. Оно возникает как приближение результата суммы большого числа слабых независимых воздействий, но в этих данных симметрии недостаточно.\n\nПлотность **скошенного нормального**:\n$$f_{SN}(x)=\\frac{2}{\\omega}\\varphi\\left(\\frac{x-\\xi}{\\omega}\\right)\n\\Phi\\left(\\alpha\\frac{x-\\xi}{\\omega}\\right),$$\nгде $\\varphi,\\Phi$ — плотность и функция распределения стандартизованной нормальной величины, $\\xi$ задаёт положение (loc), $\\omega>0$ — масштаб (scale), $\\alpha$ — асимметрию (shape). При $\\alpha=0$ получаем нормальное распределение, при положительном $\\alpha$ допускается правосторонняя асимметрия. Параметр loc не равен в общем случае среднему: если $\\delta=\\alpha/\\sqrt{1+\\alpha^2}$, то $E(X)=\\xi+\\omega\\delta\\sqrt{2/\\pi}$.\n\nПараметры оцениваем методом максимального правдоподобия через scipy.stats.skewnorm.fit. Для наблюдений с повторяющимися округлёнными значениями можно также использовать **эмпирическое распределение**:\n$$\\widehat P(X=x_i)=\\frac{n_i}{N},\\qquad\n\\widehat F(x)=\\frac1N\\sum_{j=1}^{N}\\mathbf 1(X_j\\le x).$$\nЗдесь $n_i$ — число повторений значения, $N=4898$. Такая модель сохраняет фактические частоты и подходит для последующего генератора по обратной функции распределения $X=\\widehat F^{-1}(U)$, где $U\\sim U(0.1)$.'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><h4 id="sprint1-heading-118-1"><span class="notebook-index">3.2.6</span>Нормализация</h4></span>', 'source': '#### Нормализация'}, {'kind': 'code', 'html': '<figure class="plot plot-wide"><img width="1308" height="427" decoding="async" data-report-asset="./public/reports/sprint1/119-0.png" src="data:image/png;base64," alt="График исследования" /></figure><pre class="numeric-result">Среднее после стандартизации: -3.7137390844137537e-16\nStd после стандартизации: 0.9999999999999999\nАсимметрия до и после: 0.4873419932161276 0.487341993216129\n</pre>', 'source': 'z=(alcohol-alcohol.mean())/alcohol.std(ddof=1)\nprint("Среднее после стандартизации:",z.mean())\nprint("Std после стандартизации:",z.std(ddof=1))\nprint("Асимметрия до и после:",alcohol.skew(),z.skew())\nfig,axs=plt.subplots(1,2,figsize=(12,4))\naxs[0].hist(a,bins=40,density=True,color="#6389B8")\naxs[0].set(xlabel="Алкоголь, % об.",ylabel="Плотность",title="До")\naxs[1].hist(z,bins=40,density=True,color="#76B391",alpha=.7)\ngrid=np.linspace(z.min(),z.max(),300)\naxs[1].plot(grid,stats.norm.pdf(grid),color="red",label="N(0,1)")\naxs[1].set(xlabel="z (безразмерное)",ylabel="Плотность",title="После")\naxs[1].legend()\nplt.tight_layout()\nplt.show()'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><span class="paragraph">После стандартизации <marimo-tex class="arithmatex">||(z_i=(x_i-\\bar x)/s||)</marimo-tex> среднее практически равно нулю, стандартное отклонение — единице. Асимметрия остаётся <strong>0.4873</strong>. Стандартизация меняет центр и масштаб, <strong>но не делает распределение нормальным</strong>.</span></span>', 'source': 'После стандартизации $z_i=(x_i-\\bar x)/s$ среднее практически равно нулю, стандартное отклонение — единице. Асимметрия остаётся **0.4873**. Стандартизация меняет центр и масштаб, **но не делает распределение нормальным**.'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><h3 id="sprint1-heading-121-1"><span class="notebook-index">3.3</span>Independence &amp; Estimations</h3>\n<h4 id="sprint1-heading-121-2"><span class="notebook-index">3.3.1</span>Зависимость от pH и остаточного сахара</h4></span>', 'source': '### Independence & Estimations\n\n#### Зависимость от pH и остаточного сахара'}, {'kind': 'code', 'html': '<figure class="plot plot-wide"><img width="1308" height="426" decoding="async" data-report-asset="./public/reports/sprint1/122-0.png" src="data:image/png;base64," alt="График исследования" /></figure><pre class="numeric-result">alcohol / pH: Пирсон r=0.1214 (p=1.49e-17); Спирмен rho=0.1489 (p=1.14e-25)\nalcohol / residual sugar: Пирсон r=-0.4506 (p=1.21e-243); Спирмен rho=-0.4453 (p=3.09e-237)\n</pre>', 'source': 'for col in ["pH","residual sugar"]:\n    r,p=stats.pearsonr(df["alcohol"],df[col])\n    rho,p_s=stats.spearmanr(df["alcohol"],df[col])\n    print(f"alcohol / {col}: Пирсон r={r:.4f} (p={p:.2e}); Спирмен rho={rho:.4f} (p={p_s:.2e})")\nfig,axs=plt.subplots(1,2,figsize=(12,4))\nfor ax,col in zip(axs,["pH","residual sugar"]):\n    ax.scatter(df[col],df["alcohol"],s=6,alpha=.25)\n    ax.set(xlabel=col,ylabel="Алкоголь, % об.",title=f"Alcohol и {col}")\nplt.tight_layout()\nplt.show()'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><span class="paragraph">Алкоголь и pH связаны <strong>слабо положительно</strong>: <marimo-tex class="arithmatex">||(r=0.1214||)</marimo-tex>, <marimo-tex class="arithmatex">||(\\rho=0.1489||)</marimo-tex>. Связь с остаточным сахаром <strong>умеренная отрицательная</strong>: <marimo-tex class="arithmatex">||(r=-0.4506||)</marimo-tex>, <marimo-tex class="arithmatex">||(\\rho=-0.4453||)</marimo-tex>. p-value малы даже для слабой корреляции из-за большого объёма данных. Ненулевая корреляция показывает отсутствие строгой независимости, но сама по себе не доказывает причинность. Отрицательная связь алкоголя и остаточного сахара согласуется с превращением сахаров в этанол при брожении.</span></span>', 'source': 'Алкоголь и pH связаны **слабо положительно**: $r=0.1214$, $\\rho=0.1489$. Связь с остаточным сахаром **умеренная отрицательная**: $r=-0.4506$, $\\rho=-0.4453$. p-value малы даже для слабой корреляции из-за большого объёма данных. Ненулевая корреляция показывает отсутствие строгой независимости, но сама по себе не доказывает причинность. Отрицательная связь алкоголя и остаточного сахара согласуется с превращением сахаров в этанол при брожении.'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><span class="paragraph">Критерий χ² для пары alcohol и residual sugar приведён один раз в разделе «Независимость трёх величин» (перед Lab resume).</span></span>', 'source': 'Критерий χ² для пары alcohol и residual sugar приведён один раз в разделе «Независимость трёх величин» (перед Lab resume).'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><h4 id="sprint1-heading-125-1"><span class="notebook-index">3.3.2</span>Состоятельность оценок</h4></span>', 'source': '#### Состоятельность оценок'}, {'kind': 'code', 'html': '<figure class="plot plot-wide"><img width="1309" height="426" decoding="async" data-report-asset="./public/reports/sprint1/126-0.png" src="data:image/png;base64," alt="График исследования" /></figure><pre class="numeric-result">   n  RMSE среднего\n  10        0.39271\n  30        0.23468\n 100        0.12422\n 300        0.06881\n1000        0.03721\n3000        0.02338\n</pre>', 'source': 'rng=np.random.default_rng(SEED)\nsizes=[10,30,100,300,1000,3000]\nmeans=[]; stds=[]; rmses=[]\nfor n in sizes:\n    ms=[]; ss=[]\n    for _ in range(200):\n        sample=rng.choice(a,size=n,replace=True)\n        ms.append(sample.mean())\n        ss.append(sample.std(ddof=1))\n    means.append(ms); stds.append(ss)\n    rmses.append(np.sqrt(np.mean((np.array(ms)-a.mean())**2)))\nprint(pd.DataFrame({"n":sizes,"RMSE среднего":rmses}).round(5).to_string(index=False))\nfig,axs=plt.subplots(1,2,figsize=(12,4))\naxs[0].boxplot(means,tick_labels=sizes)\naxs[0].axhline(a.mean(),color="red")\naxs[0].set(xlabel="n",ylabel="Среднее алкоголя, % об.",title="Средние")\naxs[1].boxplot(stds,tick_labels=sizes)\naxs[1].axhline(a.std(ddof=1),color="red")\naxs[1].set(xlabel="n",ylabel="Std, п.п.",title="Стандартные отклонения")\nplt.tight_layout()\nplt.show()'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><span class="paragraph">С ростом <marimo-tex class="arithmatex">||(n||)</marimo-tex> разброс выборочных средних и стандартных отклонений сокращается: ящики становятся уже и располагаются около соответствующих характеристик полной таблицы. RMSE среднего также уменьшается. Это <strong>эмпирическая иллюстрация состоятельности</strong> оценок. Выборка берётся с возвращением, а «истинные» значения в этом эксперименте — статистики 4898 строк, не параметры всех белых вин в мире.</span></span>', 'source': 'С ростом $n$ разброс выборочных средних и стандартных отклонений сокращается: ящики становятся уже и располагаются около соответствующих характеристик полной таблицы. RMSE среднего также уменьшается. Это **эмпирическая иллюстрация состоятельности** оценок. Выборка берётся с возвращением, а «истинные» значения в этом эксперименте — статистики 4898 строк, не параметры всех белых вин в мире.'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><h4 id="sprint1-heading-128-1"><span class="notebook-index">3.3.3</span>Выборки с возвращением и без</h4></span>', 'source': '#### Выборки с возвращением и без'}, {'kind': 'code', 'html': '<pre class="numeric-result">         Вся таблица  Без возвращения  С возвращением\nСреднее      10.5143          10.5180         10.4805\nStd           1.2306           1.2343          1.2361\nМедиана      10.4000          10.3000         10.3000\nБез возвращения: разброс средних 0.05254, теория 0.05215\nС возвращением: разброс средних 0.05365, теория 0.05503\n</pre>', 'source': 'rng=np.random.default_rng(SEED)\nn=N_SAMPLE\nwithout=rng.choice(a,n,replace=False)\nwith_repl=rng.choice(a,n,replace=True)\nprint(pd.DataFrame({\n    "Вся таблица":[a.mean(),a.std(ddof=1),np.median(a)],\n    "Без возвращения":[without.mean(),without.std(ddof=1),np.median(without)],\n    "С возвращением":[with_repl.mean(),with_repl.std(ddof=1),np.median(with_repl)]\n},index=["Среднее","Std","Медиана"]).round(4).to_string())\n\nrng=np.random.default_rng(SEED)\nrep=1000\nm_no=np.array([rng.choice(a,n,replace=False).mean() for _ in range(rep)])\nm_yes=np.array([rng.choice(a,n,replace=True).mean() for _ in range(rep)])\nN=len(a)\nsigma_pop=a.std(ddof=0)\nse_yes=sigma_pop/np.sqrt(n)\nse_no=se_yes*np.sqrt((N-n)/(N-1))\nprint(f"Без возвращения: разброс средних {m_no.std(ddof=1):.5f}, теория {se_no:.5f}")\nprint(f"С возвращением: разброс средних {m_yes.std(ddof=1):.5f}, теория {se_yes:.5f}")'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><span class="paragraph">При выборе с возвращением повторение одного наблюдения возможно, без возвращения — нет. Для среднего теоретические ошибки:</span>\n<marimo-tex class="arithmatex">||[\nSE_{\\mathrm{с\\,возвр.}}=\\frac{\\sigma_N}{\\sqrt n},\\quad\nSE_{\\mathrm{без\\,возвр.}}=\\frac{\\sigma_N}{\\sqrt n}\\sqrt{\\frac{N-n}{N-1}}.\n||]</marimo-tex><span class="paragraph">При <marimo-tex class="arithmatex">||(N=4898||)</marimo-tex>, <marimo-tex class="arithmatex">||(n=500||)</marimo-tex> они составляют приблизительно <strong>0.0550</strong> и <strong>0.0521</strong> процентного пункта. Вторая меньше из-за поправки на конечную совокупность. Одного сравнения выборок недостаточно, поэтому методики дополнительно проверены на 1000 повторов.</span></span>', 'source': 'При выборе с возвращением повторение одного наблюдения возможно, без возвращения — нет. Для среднего теоретические ошибки:\n$$SE_{\\mathrm{с\\,возвр.}}=\\frac{\\sigma_N}{\\sqrt n},\\quad\nSE_{\\mathrm{без\\,возвр.}}=\\frac{\\sigma_N}{\\sqrt n}\\sqrt{\\frac{N-n}{N-1}}.$$\nПри $N=4898$, $n=500$ они составляют приблизительно **0.0550** и **0.0521** процентного пункта. Вторая меньше из-за поправки на конечную совокупность. Одного сравнения выборок недостаточно, поэтому методики дополнительно проверены на 1000 повторов.'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><span class="paragraph">Стратифицированная выборка (по оценке качества <code>quality</code>) и ответ на вопрос «можно ли по выборке судить о генеральной совокупности» приведены в разделе «Выборка и генеральная совокупность» (перед литературой).</span></span>', 'source': 'Стратифицированная выборка (по оценке качества `quality`) и ответ на вопрос «можно ли по выборке судить о генеральной совокупности» приведены в разделе «Выборка и генеральная совокупность» (перед литературой).'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><h4 id="sprint1-heading-132-1"><span class="notebook-index">3.3.4</span>Проверка гипотезы</h4></span>', 'source': '#### Проверка гипотезы'}, {'kind': 'code', 'html': '<pre class="numeric-result">Выборка n=N_SAMPLE: mean=10.517967, t=0.3255, p=0.744946\n95%-й ДИ для среднего: [10.4095; 10.6264] % об.\nВся таблица: t=0.8114, p=0.417192\n</pre>', 'source': 'rng=np.random.default_rng(SEED)\nsample=rng.choice(a,size=N_SAMPLE,replace=False)\nmu0=10.5\ntest=stats.ttest_1samp(sample,mu0)\nci=stats.t.interval(.95,df=N_SAMPLE-1,loc=sample.mean(),scale=stats.sem(sample))\nfull=stats.ttest_1samp(a,mu0)\nprint(f"Выборка n=N_SAMPLE: mean={sample.mean():.6f}, t={test.statistic:.4f}, p={test.pvalue:.6f}")\nprint(f"95%-й ДИ для среднего: [{ci[0]:.4f}; {ci[1]:.4f}] % об.")\nprint(f"Вся таблица: t={full.statistic:.4f}, p={full.pvalue:.6f}")'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><span class="paragraph">Проверяем <marimo-tex class="arithmatex">||(H_0:\\mu=10.5\\%||)</marimo-tex>, <marimo-tex class="arithmatex">||(H_1:\\mu\\ne10.5\\%||)</marimo-tex>, <marimo-tex class="arithmatex">||(\\alpha=0.05||)</marimo-tex>. На случайной выборке из 500 строк (seed=42) <strong>среднее = 10.5180 % об.</strong>, <marimo-tex class="arithmatex">||(t=0.3255||)</marimo-tex>, <marimo-tex class="arithmatex">||(p=0.7449&gt;0.05||)</marimo-tex>, следовательно, <strong>нет оснований отвергнуть <marimo-tex class="arithmatex">||(H_0||)</marimo-tex></strong>. 95%-й доверительный интервал <strong>[10.4095; 10.6264] % об.</strong> содержит 10.5%. На всей таблице <marimo-tex class="arithmatex">||(t=0.8114||)</marimo-tex>, <marimo-tex class="arithmatex">||(p=0.4172||)</marimo-tex> — тот же вывод.</span>\n<span class="paragraph">Неотвержение <marimo-tex class="arithmatex">||(H_0||)</marimo-tex> не доказывает точного равенства 10.5%. При <marimo-tex class="arithmatex">||(n=500||)</marimo-tex> t-тест для среднего достаточно устойчив к умеренной ненормальности благодаря центральной предельной теореме. Но результаты строго относятся к исследуемой таблице: распространение на все вина требует репрезентативного отбора и независимых наблюдений.</span></span>', 'source': 'Проверяем $H_0:\\mu=10.5\\%$, $H_1:\\mu\\ne10.5\\%$, $\\alpha=0.05$. На случайной выборке из 500 строк (seed=42) **среднее = 10.5180 % об.**, $t=0.3255$, $p=0.7449>0.05$, следовательно, **нет оснований отвергнуть $H_0$**. 95%-й доверительный интервал **[10.4095; 10.6264] % об.** содержит 10.5%. На всей таблице $t=0.8114$, $p=0.4172$ — тот же вывод.\n\nНеотвержение $H_0$ не доказывает точного равенства 10.5%. При $n=500$ t-тест для среднего достаточно устойчив к умеренной ненормальности благодаря центральной предельной теореме. Но результаты строго относятся к исследуемой таблице: распространение на все вина требует репрезентативного отбора и независимых наблюдений.'}, {'kind': 'code', 'html': '<pre class="numeric-result">Вин с quality &gt;= 7: 1060 , с quality &lt;= 5: 1640\nМедиана alcohol: высокое качество = 11.5 , низкое = 9.6\nU = 1446839.0 , p = 1.2818692810861878e-187 , размер эффекта (r_rb) = 0.665\nРешение при alpha=0.05: отвергаем H0; p=1.2819e-187; медианы=11.5 и 9.6; r_rb=0.6646\n</pre>', 'source': '# Гипотеза: спирт у вин с высокой и низкой оценкой качества различается\nhigh = df.loc[df["quality"] >= 7, "alcohol"]\nlow = df.loc[df["quality"] <= 5, "alcohol"]\nu, p_u = stats.mannwhitneyu(high, low, alternative="two-sided")\nrbc = 2 * u / (len(high) * len(low)) - 1   # ранговая бисериальная корреляция (размер эффекта)\nprint("Вин с quality >= 7:", len(high), ", с quality <= 5:", len(low))\nprint("Медиана alcohol: высокое качество =", high.median(), ", низкое =", low.median())\nprint("U =", u, ", p =", p_u, ", размер эффекта (r_rb) =", round(rbc, 3))\nprint(f"Решение при alpha=0.05: {\'отвергаем H0\' if p_u < 0.05 else \'нет оснований отвергнуть H0\'}; p={p_u:.5g}; медианы={high.median():.4g} и {low.median():.4g}; r_rb={rbc:.4f}")\n'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><span class="paragraph"><strong>Гипотеза о связи алкоголя с качеством.</strong> Проверяется <marimo-tex class="arithmatex">||(H_0||)</marimo-tex>: распределения показателя у вин с оценками не ниже 7 и не выше 5 совпадают; <marimo-tex class="arithmatex">||(H_1||)</marimo-tex>: распределения различаются (<marimo-tex class="arithmatex">||(\\alpha=0.05||)</marimo-tex>). Для двух независимых групп использован двусторонний критерий Манна—Уитни, который не требует нормальности данных. Точные p-value, медианы и ранговая бисериальная корреляция вычисляются в ячейке выше. При p &lt; 0.05 нулевая гипотеза отвергается; величина эффекта помогает оценить практическую значимость различия. Наблюдаемая связь не доказывает, что именно алкоголя определяет качество: на оценку могут влиять и другие характеристики вина.</span></span>', 'source': '**Гипотеза о связи алкоголя с качеством.** Проверяется $H_0$: распределения показателя у вин с оценками не ниже 7 и не выше 5 совпадают; $H_1$: распределения различаются ($\\alpha=0.05$). Для двух независимых групп использован двусторонний критерий Манна—Уитни, который не требует нормальности данных. Точные p-value, медианы и ранговая бисериальная корреляция вычисляются в ячейке выше. При p < 0.05 нулевая гипотеза отвергается; величина эффекта помогает оценить практическую значимость различия. Наблюдаемая связь не доказывает, что именно алкоголя определяет качество: на оценку могут влиять и другие характеристики вина.\n'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><h3 id="sprint1-heading-137-1"><span class="notebook-index">3.4</span>Итоговый вывод по alcohol</h3>\n<span class="paragraph">Объёмная доля алкоголя зависит от множества неконтролируемых условий и является случайной величиной для случайно выбранного вина. В исследуемых 4898 записях среднее <strong>10.5143 % об.</strong>, распределение умеренно асимметрично вправо и имеет пики из-за неоднородности и точности записи. Из трёх рассмотренных моделей лучше подходит <strong>скошенное нормальное распределение</strong>, но оно не идеально передаёт эмпирические частоты. Нормализация приводит среднее к нулю, а стандартное отклонение к единице, не убирая асимметрию. При увеличении размера выборки оценки становятся устойчивее; без возвращения разброс средних несколько меньше. Алкоголь умеренно отрицательно связан с остаточным сахаром и слабо положительно — с pH, то есть строгой независимости не обнаружено. Проверка гипотезы <strong><marimo-tex class="arithmatex">||(\\mu=10.5\\%||)</marimo-tex></strong> не выявила значимого отличия. Для генератора во втором спринте целесообразно рассмотреть <strong>эмпирическое квантильное преобразование</strong>, сохраняющее частоты округлённых измерений.</span>\n<span class="paragraph"><strong>Литература:</strong></span>\n<ol>\n<li>Cortez P. et al. Wine Quality [dataset]. UCI Machine Learning Repository (2009). <a href="https://doi.org/10.24432/C56S3T" rel="noopener" target="_blank">https://doi.org/10.24432/C56S3T</a></li>\n<li>SciPy Documentation, scipy.stats.skewnorm: <a href="https://docs.scipy.org/doc/scipy/reference/generated/scipy.stats.skewnorm.html" rel="noopener" target="_blank">https://docs.scipy.org/doc/scipy/reference/generated/scipy.stats.skewnorm.html</a></li>\n<li>SciPy Documentation, Statistical functions: <a href="https://docs.scipy.org/doc/scipy/reference/stats.html" rel="noopener" target="_blank">https://docs.scipy.org/doc/scipy/reference/stats.html</a></li>\n</ol></span>', 'source': '### Итоговый вывод по alcohol\n\nОбъёмная доля алкоголя зависит от множества неконтролируемых условий и является случайной величиной для случайно выбранного вина. В исследуемых 4898 записях среднее **10.5143 % об.**, распределение умеренно асимметрично вправо и имеет пики из-за неоднородности и точности записи. Из трёх рассмотренных моделей лучше подходит **скошенное нормальное распределение**, но оно не идеально передаёт эмпирические частоты. Нормализация приводит среднее к нулю, а стандартное отклонение к единице, не убирая асимметрию. При увеличении размера выборки оценки становятся устойчивее; без возвращения разброс средних несколько меньше. Алкоголь умеренно отрицательно связан с остаточным сахаром и слабо положительно — с pH, то есть строгой независимости не обнаружено. Проверка гипотезы **$\\mu=10.5\\%$** не выявила значимого отличия. Для генератора во втором спринте целесообразно рассмотреть **эмпирическое квантильное преобразование**, сохраняющее частоты округлённых измерений.\n\n**Литература:**\n1. Cortez P. et al. Wine Quality [dataset]. UCI Machine Learning Repository (2009). https://doi.org/10.24432/C56S3T\n2. SciPy Documentation, scipy.stats.skewnorm: https://docs.scipy.org/doc/scipy/reference/generated/scipy.stats.skewnorm.html\n3. SciPy Documentation, Statistical functions: https://docs.scipy.org/doc/scipy/reference/stats.html'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><h2 id="sprint1-heading-138-1">Независимость трёх величин</h2></span>', 'source': '## Независимость трёх величин'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><span class="paragraph">Величины измерены на одних и тех же винах, поэтому нужно показать, зависимы ли они. Корреляции для каждой пары показаны ниже, критерий χ² для самой связанной пары (alcohol и residual sugar) проведён один раз.</span></span>', 'source': 'Величины измерены на одних и тех же винах, поэтому нужно показать, зависимы ли они. Корреляции для каждой пары показаны ниже, критерий χ² для самой связанной пары (alcohol и residual sugar) проведён один раз.'}, {'kind': 'code', 'html': '<figure class="plot plot-wide"><img width="1007" height="462" decoding="async" data-report-asset="./public/reports/sprint1/140-0.png" src="data:image/png;base64," alt="График исследования" /></figure>', 'source': 'cols = ["pH", "residual sugar", "alcohol"]\nfig, axes = plt.subplots(1, 2, figsize=(11, 4))\nfor ax, method in zip(axes, ["pearson", "spearman"]):\n    corr = df[cols].corr(method=method)\n    im = ax.imshow(corr, vmin=-1, vmax=1, cmap="coolwarm")\n    ax.set_xticks(range(3)); ax.set_xticklabels(cols, rotation=30)\n    ax.set_yticks(range(3)); ax.set_yticklabels(cols)\n    for i in range(3):\n        for j in range(3):\n            ax.text(j, i, f"{corr.iloc[i, j]:.2f}", ha="center", va="center")\n    ax.set_title("Корреляция: " + method)\n    ax.grid(False)\nfig.colorbar(im, ax=axes, shrink=0.8)\nplt.show()'}, {'kind': 'code', 'html': '<pre class="numeric-result">residual sugar  (0.599, 1.7]  (1.7, 5.2]  (5.2, 9.9]  (9.9, 65.8]\nalcohol                                                          \n(7.999, 9.5]             168         150         348          770\n(9.5, 10.4]              317         208         359          253\n(10.4, 11.4]             467         317         289          117\n(11.4, 14.2]             305         537         222           71\nchi2 = 1355.5173030641326 , p = 3.1515287876789917e-286 , степеней свободы = 9\nМинимальная ожидаемая частота: 280.621682319314\nV Крамера = 0.3037263807731856\n</pre>', 'source': '# Разбиваем непрерывные величины на 4 группы по квантилям\nalc_q = pd.qcut(df["alcohol"], 4, duplicates="drop")\nsug_q = pd.qcut(df["residual sugar"], 4, duplicates="drop")\ntable = pd.crosstab(alc_q, sug_q)\nprint(table)\n\nchi2, p_chi, dof, expected = stats.chi2_contingency(table)\nprint("chi2 =", chi2, ", p =", p_chi, ", степеней свободы =", dof)\nprint("Минимальная ожидаемая частота:", expected.min())\n\nn_obs = table.values.sum()\nv = np.sqrt(chi2 / (n_obs * (min(table.shape) - 1)))\nprint("V Крамера =", v)'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><span class="paragraph"><strong>Независимость: критерий хи-квадрат</strong></span>\n<span class="paragraph">Я разбила спирт и сахар на 4 группы по квантилям и построила таблицу\nсопряжённости. chi2 = 1355, p = 3·10⁻²⁸⁶, число степеней свободы 9,\nV Крамера = 0.30.\nЭто значит, что спирт и сахар зависимы, а связь умеренная.\nПо таблице видно, что среди вин с малым спиртом (до 9.5) много вин с\nбольшим сахаром (770), а среди вин с большим спиртом (от 11.4) таких\nвсего 71.\nЭто совпадает с корреляцией Пирсона (r = −0.45): направление связи то\nже. Сами числа 0.30 и 0.45 напрямую сравнивать нельзя, это разные меры,\nи V Крамера зависит от того, как разбить данные на группы.\nХи-квадрат не требует линейной связи, поэтому вместе с корреляцией он\nдаёт более надёжный вывод.</span></span>', 'source': '**Независимость: критерий хи-квадрат**\n\nЯ разбила спирт и сахар на 4 группы по квантилям и построила таблицу\nсопряжённости. chi2 = 1355, p = 3·10⁻²⁸⁶, число степеней свободы 9,\nV Крамера = 0.30.\nЭто значит, что спирт и сахар зависимы, а связь умеренная.\nПо таблице видно, что среди вин с малым спиртом (до 9.5) много вин с\nбольшим сахаром (770), а среди вин с большим спиртом (от 11.4) таких\nвсего 71.\nЭто совпадает с корреляцией Пирсона (r = −0.45): направление связи то\nже. Сами числа 0.30 и 0.45 напрямую сравнивать нельзя, это разные меры,\nи V Крамера зависит от того, как разбить данные на группы.\nХи-квадрат не требует линейной связи, поэтому вместе с корреляцией он\nдаёт более надёжный вывод.'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><h2 id="sprint1-heading-143-1">Выборка и генеральная совокупность</h2></span>', 'source': '## Выборка и генеральная совокупность'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><span class="paragraph">До этого выборки брались случайно. Здесь выборка подбирается <strong>по существующей характеристике</strong>: стратифицированная выборка по оценке <code>quality</code>. Таблицу делят на группы (страты) по значению оценки и берут из каждой группы долю, пропорциональную её размеру, поэтому состав выборки по оценкам повторяет состав таблицы.</span></span>', 'source': 'До этого выборки брались случайно. Здесь выборка подбирается **по существующей характеристике**: стратифицированная выборка по оценке `quality`. Таблицу делят на группы (страты) по значению оценки и берут из каждой группы долю, пропорциональную её размеру, поэтому состав выборки по оценкам повторяет состав таблицы.'}, {'kind': 'code', 'html': '<pre class="numeric-result">Размер случайной: 500 , стратифицированной: 501\n\nДоля оценок в таблице / в случайной / в стратифицированной:\n         таблица  случайная  страт.\nquality                            \n3          0.004      0.006   0.004\n4          0.033      0.036   0.034\n5          0.297      0.298   0.297\n6          0.449      0.438   0.447\n7          0.180      0.190   0.180\n8          0.036      0.032   0.036\n9          0.001        NaN   0.002\n\n       величина            выборка  среднее    std  асимметрия\n            pH            таблица   3.1883 0.1510      0.4578\n            pH          случайная   3.1829 0.1530      0.3221\n            pH стратифицированная   3.1824 0.1588      0.5088\nresidual sugar            таблица   6.3914 5.0721      1.0771\nresidual sugar          случайная   6.1817 4.8294      0.8100\nresidual sugar стратифицированная   6.3094 5.0477      0.8466\n       alcohol            таблица  10.5143 1.2306      0.4873\n       alcohol          случайная  10.5100 1.2410      0.4746\n       alcohol стратифицированная  10.5217 1.2101      0.5905\n\npH, случайная: KS = 0.030, p = 0.782\npH, стратифицированная: KS = 0.056, p = 0.108\nresidual sugar, случайная: KS = 0.037, p = 0.554\nresidual sugar, стратифицированная: KS = 0.022, p = 0.979\nalcohol, случайная: KS = 0.018, p = 0.998\nalcohol, стратифицированная: KS = 0.028, p = 0.854\nИТОГ KS (p-value): {&#x27;pH&#x27;: {&#x27;случайная&#x27;: np.float64(0.7816), &#x27;стратифицированная&#x27;: np.float64(0.10788)}, &#x27;residual sugar&#x27;: {&#x27;случайная&#x27;: np.float64(0.5536), &#x27;стратифицированная&#x27;: np.float64(0.97853)}, &#x27;alcohol&#x27;: {&#x27;случайная&#x27;: np.float64(0.99758), &#x27;стратифицированная&#x27;: np.float64(0.85445)}}\n</pre>', 'source': 'cols = ["pH", "residual sugar", "alcohol"]\nn_s = N_SAMPLE\n\ndef stratified_sample(data, n, seed):\n    """Из каждой оценки quality берём долю, пропорциональную её размеру"""\n    parts = [g.sample(n=max(1, round(len(g) * n / len(data))), random_state=seed)\n             for _, g in data.groupby("quality")]\n    return pd.concat(parts)\n\nrand_s = df.sample(n=n_s, random_state=SEED)\nstrat_s = stratified_sample(df, n_s, SEED)\n\nprint("Размер случайной:", len(rand_s), ", стратифицированной:", len(strat_s))\nprint("\\nДоля оценок в таблице / в случайной / в стратифицированной:")\nprint(pd.concat([df["quality"].value_counts(normalize=True).rename("таблица"),\n                 rand_s["quality"].value_counts(normalize=True).rename("случайная"),\n                 strat_s["quality"].value_counts(normalize=True).rename("страт.")], axis=1).sort_index().round(3))\n\nrows = []\nfor c in cols:\n    for name, smp in [("таблица", df), ("случайная", rand_s), ("стратифицированная", strat_s)]:\n        rows.append({"величина": c, "выборка": name, "среднее": smp[c].mean(),\n                     "std": smp[c].std(), "асимметрия": smp[c].skew()})\nprint("\\n", pd.DataFrame(rows).round(4).to_string(index=False))\n\nprint()\nfor c in cols:\n    for name, smp in [("случайная", rand_s), ("стратифицированная", strat_s)]:\n        ks = stats.ks_2samp(smp[c], df[c])\n        print(f"{c}, {name}: KS = {ks.statistic:.3f}, p = {ks.pvalue:.3f}")\nprint("ИТОГ KS (p-value):", {col: {name: round(stats.ks_2samp(smp[col], df[col]).pvalue, 5) for name,smp in [("случайная",rand_s),("стратифицированная",strat_s)]} for col in cols})\n'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><span class="paragraph"><strong>Сравнение случайной и стратифицированной выборок.</strong> Для pH, остаточного сахара и алкоголя выше приведены средние, стандартные отклонения, асимметрия и результаты двухвыборочного KS для обеих выборок относительно полной таблицы. Близость отдельных характеристик не означает, что одна стратегия лучше по всем показателям: результаты нужно сопоставлять по каждой величине отдельно. При p-value KS выше 0.05 статистически значимых различий не обнаружено, но это не доказывает тождество распределений. Ниже устойчивость сравнения проверяется на 1000 повторениях.</span></span>', 'source': '**Сравнение случайной и стратифицированной выборок.** Для pH, остаточного сахара и алкоголя выше приведены средние, стандартные отклонения, асимметрия и результаты двухвыборочного KS для обеих выборок относительно полной таблицы. Близость отдельных характеристик не означает, что одна стратегия лучше по всем показателям: результаты нужно сопоставлять по каждой величине отдельно. При p-value KS выше 0.05 статистически значимых различий не обнаружено, но это не доказывает тождество распределений. Ниже устойчивость сравнения проверяется на 1000 повторениях.\n'}, {'kind': 'code', 'html': '<pre class="numeric-result">pH : std средних, случайная = 0.00641 , стратифицированная = 0.00644\nresidual sugar : std средних, случайная = 0.22624 , стратифицированная = 0.20429\nalcohol : std средних, случайная = 0.05234 , стратифицированная = 0.04352\nИТОГ разброс средних: {&#x27;pH&#x27;: {&#x27;случайная&#x27;: np.float64(0.00641), &#x27;страт.&#x27;: np.float64(0.00644)}, &#x27;residual sugar&#x27;: {&#x27;случайная&#x27;: np.float64(0.22624), &#x27;страт.&#x27;: np.float64(0.20429)}, &#x27;alcohol&#x27;: {&#x27;случайная&#x27;: np.float64(0.05234), &#x27;страт.&#x27;: np.float64(0.04352)}}\n</pre>', 'source': 'reps_s = 1000\nrng_s = np.random.default_rng(SEED)\nres_s = {c: {"случайная": [], "страт.": []} for c in cols}\nfor _ in range(reps_s):\n    rs_ = df.sample(n=n_s, random_state=int(rng_s.integers(1e9)))\n    ss_ = stratified_sample(df, n_s, int(rng_s.integers(1e9)))\n    for c in cols:\n        res_s[c]["случайная"].append(rs_[c].mean())\n        res_s[c]["страт."].append(ss_[c].mean())\n\nfor c in cols:\n    print(c, ": std средних, случайная =", round(np.std(res_s[c]["случайная"], ddof=1), 5),\n          ", стратифицированная =", round(np.std(res_s[c]["страт."], ddof=1), 5))\nprint("ИТОГ разброс средних:", {c: {k: round(np.std(v,ddof=1),5) for k,v in res_s[c].items()} for c in cols})\n'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><span class="paragraph"><strong>Можно ли по выборке судить о генеральной совокупности?</strong> Да, при корректном случайном отборе выборка позволяет оценивать характеристики той совокупности, из которой она получена, с выборочной неопределённостью. В нашем эксперименте это 4898 записей Wine Quality: оценки средних, стандартных отклонений и асимметрии для двух способов отбора сравниваются с полной таблицей в расчётах выше. KS оценивает расхождение эмпирических распределений, а 1000 повторных выборок позволяют сравнить разброс средних, не полагаясь на один удачный результат. Стратификация по <code>quality</code> обеспечивает близкие доли оценок качества, но не обязательно улучшает оценку среднего каждого химического показателя. Обобщать результаты на <strong>все</strong> белые вина нельзя без доказательства репрезентативности исходного набора: вина в нём относятся к определённому региону и способу сбора данных.</span></span>', 'source': '**Можно ли по выборке судить о генеральной совокупности?** Да, при корректном случайном отборе выборка позволяет оценивать характеристики той совокупности, из которой она получена, с выборочной неопределённостью. В нашем эксперименте это 4898 записей Wine Quality: оценки средних, стандартных отклонений и асимметрии для двух способов отбора сравниваются с полной таблицей в расчётах выше. KS оценивает расхождение эмпирических распределений, а 1000 повторных выборок позволяют сравнить разброс средних, не полагаясь на один удачный результат. Стратификация по `quality` обеспечивает близкие доли оценок качества, но не обязательно улучшает оценку среднего каждого химического показателя. Обобщать результаты на **все** белые вина нельзя без доказательства репрезентативности исходного набора: вина в нём относятся к определённому региону и способу сбора данных.\n'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><h2 id="sprint1-heading-149-1">Литература</h2>\n<ol>\n<li>Cortez P., Cerdeira A., Almeida F., Matos T., Reis J. Modeling wine preferences by data mining from physicochemical properties // Decision Support Systems. 2009. Vol. 47, № 4. P. 547–553.</li>\n<li>Cortez P. et al. Wine Quality [dataset]. UCI Machine Learning Repository, 2009. <a href="https://doi.org/10.24432/C56S3T" rel="noopener" target="_blank">https://doi.org/10.24432/C56S3T</a></li>\n<li>Гмурман В. Е. Теория вероятностей и математическая статистика.</li>\n<li>Azzalini A. A class of distributions which includes the normal ones // Scandinavian Journal of Statistics. 1985. Vol. 12, № 2. P. 171–178.</li>\n<li>Limpert E., Stahel W. A., Abbt M. Log-normal distributions across the sciences: keys and clues // BioScience. 2001. Vol. 51, № 5. P. 341–352.</li>\n<li>Devroye L. Non-Uniform Random Variate Generation. New York: Springer, 1986.</li>\n<li>SciPy documentation, scipy.stats: <a href="https://docs.scipy.org/doc/scipy/reference/stats.html" rel="noopener" target="_blank">https://docs.scipy.org/doc/scipy/reference/stats.html</a></li>\n</ol>\n<span class="paragraph"><em>Выходные данные источников 3–6 проверьте по оригиналам перед сдачей.</em></span></span>', 'source': '## Литература\n1. Cortez P., Cerdeira A., Almeida F., Matos T., Reis J. Modeling wine preferences by data mining from physicochemical properties // Decision Support Systems. 2009. Vol. 47, № 4. P. 547–553.\n2. Cortez P. et al. Wine Quality [dataset]. UCI Machine Learning Repository, 2009. https://doi.org/10.24432/C56S3T\n3. Гмурман В. Е. Теория вероятностей и математическая статистика.\n4. Azzalini A. A class of distributions which includes the normal ones // Scandinavian Journal of Statistics. 1985. Vol. 12, № 2. P. 171–178.\n5. Limpert E., Stahel W. A., Abbt M. Log-normal distributions across the sciences: keys and clues // BioScience. 2001. Vol. 51, № 5. P. 341–352.\n6. Devroye L. Non-Uniform Random Variate Generation. New York: Springer, 1986.\n7. SciPy documentation, scipy.stats: https://docs.scipy.org/doc/scipy/reference/stats.html\n\n*Выходные данные источников 3–6 проверьте по оригиналам перед сдачей.*'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><h2 id="sprint1-heading-150-1">Lab resume</h2></span>', 'source': '\n## Lab resume\n'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><h3 id="sprint1-heading-151-1"><span class="notebook-index">6.1</span>Что я получила от исследования</h3>\n<span class="paragraph">В ходе работы я научилась не ограничиваться средним значением, а рассматривать распределение показателя целиком: его разброс, асимметрию, хвосты и возможные выбросы. Я построила гистограммы, KDE и Q–Q графики, сравнила теоретические распределения и увидела, что внешнее сходство гистограммы с колоколом ещё не означает нормальности по статистическому критерию. Например, распределение pH выглядит почти симметричным, но тест Шапиро–Уилка отвергает гипотезу о его нормальности. Для остаточного сахара заметен длинный правый хвост, поэтому я отдельно рассмотрела логарифмическое преобразование.</span>\n<span class="paragraph">Больше всего меня заинтересовала отрицательная связь между содержанием остаточного сахара и алкоголя: коэффициент корреляции Пирсона составляет примерно −0,45. При этом я поняла, что корреляция сама по себе не доказывает причинно-следственную связь. Сложнее всего было разобраться, как интерпретировать статистические критерии и не путать маленькое p-value с большой силой эффекта. Проверка гипотез, сравнение моделей по AIC и анализ выборок помогли мне научиться формулировать выводы осторожнее.</span>\n<span class="paragraph">Ещё один важный результат — понимание того, что выборка не обязана точно повторять всю таблицу. Её характеристики меняются от отбора к отбору, а при увеличении объёма оценки обычно становятся устойчивее. Я также сравнила случайный и стратифицированный отбор и поняла, почему способ формирования выборки важен для обобщения результатов. В дальнейшем я хотела бы глубже изучить связь физико-химических показателей с качеством вина, учитывая несколько факторов одновременно, а не только попарные зависимости.</span></span>', 'source': '### Что я получила от исследования\n\nВ ходе работы я научилась не ограничиваться средним значением, а рассматривать распределение показателя целиком: его разброс, асимметрию, хвосты и возможные выбросы. Я построила гистограммы, KDE и Q–Q графики, сравнила теоретические распределения и увидела, что внешнее сходство гистограммы с колоколом ещё не означает нормальности по статистическому критерию. Например, распределение pH выглядит почти симметричным, но тест Шапиро–Уилка отвергает гипотезу о его нормальности. Для остаточного сахара заметен длинный правый хвост, поэтому я отдельно рассмотрела логарифмическое преобразование.\n\nБольше всего меня заинтересовала отрицательная связь между содержанием остаточного сахара и алкоголя: коэффициент корреляции Пирсона составляет примерно −0,45. При этом я поняла, что корреляция сама по себе не доказывает причинно-следственную связь. Сложнее всего было разобраться, как интерпретировать статистические критерии и не путать маленькое p-value с большой силой эффекта. Проверка гипотез, сравнение моделей по AIC и анализ выборок помогли мне научиться формулировать выводы осторожнее.\n\nЕщё один важный результат — понимание того, что выборка не обязана точно повторять всю таблицу. Её характеристики меняются от отбора к отбору, а при увеличении объёма оценки обычно становятся устойчивее. Я также сравнила случайный и стратифицированный отбор и поняла, почему способ формирования выборки важен для обобщения результатов. В дальнейшем я хотела бы глубже изучить связь физико-химических показателей с качеством вина, учитывая несколько факторов одновременно, а не только попарные зависимости.'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><h3 id="sprint1-heading-152-1"><span class="notebook-index">6.2</span>Итоговый вывод по лабораторной работе</h3>\n<span class="paragraph"><strong>Данные и величины.</strong> Я проанализировала три величины из датасета Wine Quality (4898 белых вин): pH, остаточный сахар (residual sugar) и спирт (alcohol). Все три случайные: значение у конкретной бутылки зависит от винограда, года, зрелости и хода брожения, которые заранее неизвестны, формулы для него нет, а к этому добавляется шум измерения.</span>\n<span class="paragraph"><strong>Формы распределений.</strong> Ни одна величина не оказалась нормальной. pH похож на колокол с небольшим правым хвостом (асимметрия 0.46): по Шапиро-Уилку p ≈ 10⁻²⁰, но W = 0.988, то есть отклонение от нормального небольшое. Сахар имеет сильный правый хвост (асимметрия 1.08, эксцесс 3.47): много вин с малым сахаром и редкие вина до 65.8 г/л; логарифмирование уменьшило влияние правого хвоста, но само по себе не гарантирует нормальности. Спирт ближе всего к плоскому распределению (эксцесс −0.70), а «зубцы» на гистограмме появились из-за того, что в данных только 103 разных значения.</span>\n<span class="paragraph"><strong>Выбор распределений.</strong> Для pH лучше лог-нормальное со сдвигом (AIC −4765 против −4616, KS 0.025 против 0.049). Для сахара по AIC лучшей оказалась гамма, а по KS лог-нормальное, и все значения KS больше 0.11, поэтому простая гладкая модель описывает его плохо. Для спирта лучше всех скошенное нормальное (AIC 15125, KS 0.057), но оно тоже не повторяет локальные пики. Идеально не подошло ни одно распределение, потому что значения в таблице округлены, а образцы получены из разных партий вин.</span>\n<span class="paragraph"><strong>Независимость.</strong> Самая связанная пара: спирт и сахар (r = −0.45, V Крамера = 0.30). Это согласуется с химией брожения: чем полнее дрожжи превращают сахар в спирт, тем меньше остаётся сахара. pH связан с обеими величинами слабо (r = 0.12 и −0.19). Все p-value очень малы, но это следствие большого объёма данных, поэтому я опиралась на размер коэффициентов. Значит, pH можно моделировать почти отдельно, а спирт и сахар лучше не генерировать как независимые.</span>\n<span class="paragraph"><strong>Оценки и выборки.</strong> Оценки среднего и стандартного отклонения состоятельны: с ростом размера выборки они концентрируются вокруг значений по всей таблице. Выборки без возвращения дали чуть меньший разброс средних, чем с возвращением (pH: 0.0062 и 0.0068, сахар: 0.212 и 0.227 г/л), что совпало с теоретической поправкой на конечную совокупность. Стратификация по качеству обеспечивает сохранение пропорций оценок; выигрыш в точности среднего зависит от исследуемого показателя. По корректно отобранной выборке можно оценивать характеристики исходной таблицы с учётом выборочной неопределённости.</span>\n<span class="paragraph"><strong>Гипотезы.</strong> Среднее pH = 3.2 на выборке из 500 вин не отвергается (p = 0.188), а на всей таблице отвергается (p ≈ 6·10⁻⁸), но разница в 0.012 практически ничтожна. Для сахара (6.4 г/л, p = 0.842) и спирта (10.5 %, p = 0.745) гипотезы не отвергнуты. Эти гипотезы выбирались рядом со средним, поэтому отсутствие отвержения ожидаемо. Содержательнее сравнение групп по качеству вин (критерий Манна—Уитни, оценка ≥ 7 против ≤ 5); численные результаты приведены в соответствующих разделах.</span>\n<span class="paragraph"><strong>Что это говорит о винах.</strong> Белые вина из этого датасета довольно однородны по кислотности: pH лежит в узком диапазоне 2.72–3.82 при std 0.15. А вот по сахару и спирту вина различаются сильно, причём эти две характеристики связаны через брожение: сухие вина с малым остаточным сахаром в среднем более крепкие, а вина с большим сахаром менее крепкие. Единичные вина с сахаром выше 30 г/л это редкие сладкие вина, они и формируют длинный хвост.</span>\n<span class="paragraph"><strong>Ограничения и планы.</strong> В таблице 937 повторяющихся строк, значения округлены, а «истинные» значения в экспериментах это статистики 4898 строк, а не всех белых вин. Во втором спринте я сделаю генераторы: для pH лог-нормальный через нормальные числа, для сахара и спирта метод квантильного преобразования по эмпирической функции распределения.</span></span>', 'source': '### Итоговый вывод по лабораторной работе\n\n**Данные и величины.** Я проанализировала три величины из датасета Wine Quality (4898 белых вин): pH, остаточный сахар (residual sugar) и спирт (alcohol). Все три случайные: значение у конкретной бутылки зависит от винограда, года, зрелости и хода брожения, которые заранее неизвестны, формулы для него нет, а к этому добавляется шум измерения.\n\n**Формы распределений.** Ни одна величина не оказалась нормальной. pH похож на колокол с небольшим правым хвостом (асимметрия 0.46): по Шапиро-Уилку p ≈ 10⁻²⁰, но W = 0.988, то есть отклонение от нормального небольшое. Сахар имеет сильный правый хвост (асимметрия 1.08, эксцесс 3.47): много вин с малым сахаром и редкие вина до 65.8 г/л; логарифмирование уменьшило влияние правого хвоста, но само по себе не гарантирует нормальности. Спирт ближе всего к плоскому распределению (эксцесс −0.70), а «зубцы» на гистограмме появились из-за того, что в данных только 103 разных значения.\n\n**Выбор распределений.** Для pH лучше лог-нормальное со сдвигом (AIC −4765 против −4616, KS 0.025 против 0.049). Для сахара по AIC лучшей оказалась гамма, а по KS лог-нормальное, и все значения KS больше 0.11, поэтому простая гладкая модель описывает его плохо. Для спирта лучше всех скошенное нормальное (AIC 15125, KS 0.057), но оно тоже не повторяет локальные пики. Идеально не подошло ни одно распределение, потому что значения в таблице округлены, а образцы получены из разных партий вин.\n\n**Независимость.** Самая связанная пара: спирт и сахар (r = −0.45, V Крамера = 0.30). Это согласуется с химией брожения: чем полнее дрожжи превращают сахар в спирт, тем меньше остаётся сахара. pH связан с обеими величинами слабо (r = 0.12 и −0.19). Все p-value очень малы, но это следствие большого объёма данных, поэтому я опиралась на размер коэффициентов. Значит, pH можно моделировать почти отдельно, а спирт и сахар лучше не генерировать как независимые.\n\n**Оценки и выборки.** Оценки среднего и стандартного отклонения состоятельны: с ростом размера выборки они концентрируются вокруг значений по всей таблице. Выборки без возвращения дали чуть меньший разброс средних, чем с возвращением (pH: 0.0062 и 0.0068, сахар: 0.212 и 0.227 г/л), что совпало с теоретической поправкой на конечную совокупность. Стратификация по качеству обеспечивает сохранение пропорций оценок; выигрыш в точности среднего зависит от исследуемого показателя. По корректно отобранной выборке можно оценивать характеристики исходной таблицы с учётом выборочной неопределённости.\n\n**Гипотезы.** Среднее pH = 3.2 на выборке из 500 вин не отвергается (p = 0.188), а на всей таблице отвергается (p ≈ 6·10⁻⁸), но разница в 0.012 практически ничтожна. Для сахара (6.4 г/л, p = 0.842) и спирта (10.5 %, p = 0.745) гипотезы не отвергнуты. Эти гипотезы выбирались рядом со средним, поэтому отсутствие отвержения ожидаемо. Содержательнее сравнение групп по качеству вин (критерий Манна—Уитни, оценка ≥ 7 против ≤ 5); численные результаты приведены в соответствующих разделах.\n\n**Что это говорит о винах.** Белые вина из этого датасета довольно однородны по кислотности: pH лежит в узком диапазоне 2.72–3.82 при std 0.15. А вот по сахару и спирту вина различаются сильно, причём эти две характеристики связаны через брожение: сухие вина с малым остаточным сахаром в среднем более крепкие, а вина с большим сахаром менее крепкие. Единичные вина с сахаром выше 30 г/л это редкие сладкие вина, они и формируют длинный хвост.\n\n**Ограничения и планы.** В таблице 937 повторяющихся строк, значения округлены, а «истинные» значения в экспериментах это статистики 4898 строк, а не всех белых вин. Во втором спринте я сделаю генераторы: для pH лог-нормальный через нормальные числа, для сахара и спирта метод квантильного преобразования по эмпирической функции распределения.'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><h3 id="sprint1-heading-153-1"><span class="notebook-index">7.1</span>cat_mark_table</h3></span>', 'source': '\n### cat_mark_table'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><table>\n<thead>\n<tr>\n<th>cat_id</th>\n<th>notebook_link</th>\n<th>coeff</th>\n<th>comment</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Доказательство случайности величины</td>\n<td>Random Variable 01–03 → Description</td>\n<td></td>\n<td>для каждой из трёх величин: факторы, отсутствие формулы, шум измерения; единицы измерения в таблице</td>\n</tr>\n<tr>\n<td>Независимость</td>\n<td>«Независимость трёх величин» и Independence &amp; Estimations</td>\n<td></td>\n<td>корреляции Пирсона и Спирмена для трёх пар, хи-квадрат и V Крамера для спирта и сахара</td>\n</tr>\n<tr>\n<td>Состоятельность оценок</td>\n<td>Random Variable 01–03 → Состоятельность оценок</td>\n<td></td>\n<td>ящики для n от 10 до 3000, RMSE среднего, смещение std при малых n</td>\n</tr>\n<tr>\n<td>EDA, нормализация</td>\n<td>Random Variable 01–03 → EDA &amp; Distribution, Нормализация</td>\n<td></td>\n<td>статистики, выбросы, Q-Q график, KDE, Шапиро-Уилк, стандартизация, логарифм сахара</td>\n</tr>\n<tr>\n<td>Выборка из генеральной совокупности</td>\n<td>Random Variable 01–03 → Выборки…; «Выборка и генеральная совокупность»</td>\n<td></td>\n<td>с возвращением и без (1000 повторов), стратифицированная выборка по quality</td>\n</tr>\n<tr>\n<td>Математика распределения</td>\n<td>Random Variable 01–03 → Математическая база</td>\n<td></td>\n<td>плотности, параметры, происхождение и особенности распределений</td>\n</tr>\n<tr>\n<td>Проверка гипотез</td>\n<td>Random Variable 01–03 → Проверка гипотезы</td>\n<td></td>\n<td>t-тест на выборке и всей таблице, критерий Манна-Уитни по качеству</td>\n</tr>\n<tr>\n<td>За каждое распределение</td>\n<td>EDA &amp; Distribution</td>\n<td></td>\n<td>сравнено 6 распределений: нормальное, лог-нормальное, гамма, Вейбулла, экспоненциальное, скошенное нормальное</td>\n</tr>\n<tr>\n<td>Приведение к стандартному нормальному</td>\n<td>Нормализация</td>\n<td></td>\n<td>стандартизация проведена; величины не нормальны, поэтому до N(0,1) строго не приводятся</td>\n</tr>\n</tbody>\n</table></span>', 'source': '| cat_id | notebook_link | coeff | comment |\n|--------|---------------|-------|---------|\n| Доказательство случайности величины | Random Variable 01–03 → Description | | для каждой из трёх величин: факторы, отсутствие формулы, шум измерения; единицы измерения в таблице |\n| Независимость | «Независимость трёх величин» и Independence & Estimations | | корреляции Пирсона и Спирмена для трёх пар, хи-квадрат и V Крамера для спирта и сахара |\n| Состоятельность оценок | Random Variable 01–03 → Состоятельность оценок | | ящики для n от 10 до 3000, RMSE среднего, смещение std при малых n |\n| EDA, нормализация | Random Variable 01–03 → EDA & Distribution, Нормализация | | статистики, выбросы, Q-Q график, KDE, Шапиро-Уилк, стандартизация, логарифм сахара |\n| Выборка из генеральной совокупности | Random Variable 01–03 → Выборки…; «Выборка и генеральная совокупность» | | с возвращением и без (1000 повторов), стратифицированная выборка по quality |\n| Математика распределения | Random Variable 01–03 → Математическая база | | плотности, параметры, происхождение и особенности распределений |\n| Проверка гипотез | Random Variable 01–03 → Проверка гипотезы | | t-тест на выборке и всей таблице, критерий Манна-Уитни по качеству |\n| За каждое распределение | EDA & Distribution | | сравнено 6 распределений: нормальное, лог-нормальное, гамма, Вейбулла, экспоненциальное, скошенное нормальное |\n| Приведение к стандартному нормальному | Нормализация | | стандартизация проведена; величины не нормальны, поэтому до N(0,1) строго не приводятся |'}], 'sprint2': [{'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><h1 id="sprint2-heading-0-1">Lab01 - sprint 2</h1></span>', 'source': '# Lab01 - sprint 2'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><h2 id="sprint2-heading-1-1">Random 01 (pH)</h2></span>', 'source': '## Random 01 (pH)'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><h3 id="sprint2-heading-2-1"><span class="notebook-index">1.1</span>Description</h3></span>', 'source': '### Description'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><span class="paragraph"><strong>Что генерирую.</strong> pH белого вина (датасет Wine Quality, 4898 измерений): непрерывная безразмерная величина, значения от 2.72 до 3.82.</span>\n<span class="paragraph"><strong>Распределение.</strong> В первом спринте я сравнила нормальное, лог-нормальное и другие распределения. Для pH лучше всего подошло лог-нормальное со сдвигом (AIC −4765 против −4616 у нормального, KS 0.025 против 0.049): у pH есть небольшой правый хвост, а лог-нормальное его воспроизводит. Параметры по методу максимального правдоподобия: shape = 0.1363, loc = 2.0877, scale = 1.0904.</span>\n<span class="paragraph"><strong>Зачем генератор.</strong> Он выдаёт любое число «искусственных вин» с таким же распределением pH, как у реальных (для проверки методов, моделирования, тестов), без обращения к самим данным.</span>\n<span class="paragraph"><strong>Метод.</strong> Лог-нормальное получается из стандартного нормального <marimo-tex class="arithmatex">||(Z||)</marimo-tex> преобразованием <marimo-tex class="arithmatex">||(X = \\text{loc} + \\text{scale}\\cdot e^{\\sigma Z}||)</marimo-tex>. Нормальные числа получаю методом полярных координат Марсальи из равномерных (вихрь Мерсенна), вторым методом (для сравнения) беру метод отношений.</span></span>', 'source': '**Что генерирую.** pH белого вина (датасет Wine Quality, 4898 измерений): непрерывная безразмерная величина, значения от 2.72 до 3.82.\n\n**Распределение.** В первом спринте я сравнила нормальное, лог-нормальное и другие распределения. Для pH лучше всего подошло лог-нормальное со сдвигом (AIC −4765 против −4616 у нормального, KS 0.025 против 0.049): у pH есть небольшой правый хвост, а лог-нормальное его воспроизводит. Параметры по методу максимального правдоподобия: shape = 0.1363, loc = 2.0877, scale = 1.0904.\n\n**Зачем генератор.** Он выдаёт любое число «искусственных вин» с таким же распределением pH, как у реальных (для проверки методов, моделирования, тестов), без обращения к самим данным.\n\n**Метод.** Лог-нормальное получается из стандартного нормального $Z$ преобразованием $X = \\text{loc} + \\text{scale}\\cdot e^{\\sigma Z}$. Нормальные числа получаю методом полярных координат Марсальи из равномерных (вихрь Мерсенна), вторым методом (для сравнения) беру метод отношений.\n'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><h3 id="sprint2-heading-4-1"><span class="notebook-index">1.2</span>Math desc</h3></span>', 'source': '### Math desc'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><span class="paragraph"><strong>1. Цепочка генератора.</strong> Равномерные <marimo-tex class="arithmatex">||(U(0,1)||)</marimo-tex> (вихрь Мерсенна) → стандартные нормальные <marimo-tex class="arithmatex">||(Z \\sim N(0,1)||)</marimo-tex> (полярный метод или метод отношений) → <marimo-tex class="arithmatex">||(X = \\text{loc} + \\text{scale}\\cdot e^{\\sigma Z}||)</marimo-tex>.</span>\n<span class="paragraph"><strong>2. Равномерные числа.</strong> Вихрь Мерсенна MT19937 имеет период <marimo-tex class="arithmatex">||(2^{19937}-1||)</marimo-tex>, внутреннее состояние из 624 слов и равномерное распределение до 623 измерений. В NumPy класс <code>RandomState</code> основан на нём. Не подходит для криптографии: по 624 подряд идущим выходам состояние можно восстановить.</span>\n<span class="paragraph"><strong>3. Метод полярных координат (Марсальи).</strong> Берём <marimo-tex class="arithmatex">||(u_1, u_2 \\sim U(-1,1)||)</marimo-tex> и считаем <marimo-tex class="arithmatex">||(s = u_1^2 + u_2^2||)</marimo-tex>. Точку принимаем, только если <marimo-tex class="arithmatex">||(0 &lt; s &lt; 1||)</marimo-tex>, то есть она лежит внутри единичного круга. Внутри круга точка равномерна, значит, угол <marimo-tex class="arithmatex">||(\\theta||)</marimo-tex> равномерен, а <marimo-tex class="arithmatex">||(s = r^2 \\sim U(0,1)||)</marimo-tex> и не зависит от <marimo-tex class="arithmatex">||(\\theta||)</marimo-tex>. Метод Бокса-Мюллера даёт</span>\n<marimo-tex class="arithmatex">||[\nz_1 = \\sqrt{-2\\ln s}\\cos\\theta,\\quad z_2 = \\sqrt{-2\\ln s}\\sin\\theta,\n||]</marimo-tex><span class="paragraph">а так как <marimo-tex class="arithmatex">||(\\cos\\theta = u_1/\\sqrt{s}||)</marimo-tex>, <marimo-tex class="arithmatex">||(\\sin\\theta = u_2/\\sqrt{s}||)</marimo-tex>, получаем</span>\n<marimo-tex class="arithmatex">||[\nz_1 = u_1\\sqrt{\\frac{-2\\ln s}{s}},\\quad z_2 = u_2\\sqrt{\\frac{-2\\ln s}{s}}.\n||]</marimo-tex><span class="paragraph">Это два независимых <marimo-tex class="arithmatex">||(N(0,1)||)</marimo-tex> без вычисления синуса и косинуса. Условие <marimo-tex class="arithmatex">||(s&lt;1||)</marimo-tex> нужно по двум причинам: (а) в углах квадрата направления представлены неравномерно, и угол перестал бы быть равномерным; (б) при <marimo-tex class="arithmatex">||(s&gt;1||)</marimo-tex> значение <marimo-tex class="arithmatex">||(\\ln s&gt;0||)</marimo-tex> и корень из отрицательного числа не определён; <marimo-tex class="arithmatex">||(s&gt;0||)</marimo-tex> нужно, чтобы не делить на ноль. Доля принятых точек равна отношению площадей <marimo-tex class="arithmatex">||(\\pi/4 \\approx 0.785||)</marimo-tex>, то есть отбрасывается около 21.5%.</span>\n<span class="paragraph"><strong>4. Метод отношений (Киндерман-Монахан).</strong> Для плотности <marimo-tex class="arithmatex">||(f(x) = e^{-x^2/2}||)</marimo-tex> рассмотрим область <marimo-tex class="arithmatex">||(C=\\{(u,v): 0&lt;u\\le\\sqrt{f(v/u)}\\}||)</marimo-tex>. Точка, равномерная в <marimo-tex class="arithmatex">||(C||)</marimo-tex>, даёт <marimo-tex class="arithmatex">||(x = v/u||)</marimo-tex> с плотностью, пропорциональной <marimo-tex class="arithmatex">||(f||)</marimo-tex>. Область помещается в прямоугольник <marimo-tex class="arithmatex">||(0&lt;u\\le 1||)</marimo-tex>, <marimo-tex class="arithmatex">||(|v|\\le b||)</marimo-tex>, где <marimo-tex class="arithmatex">||(b=\\sqrt{2/e}||)</marimo-tex> (максимум <marimo-tex class="arithmatex">||(|x|e^{-x^2/4}||)</marimo-tex> достигается при <marimo-tex class="arithmatex">||(x=\\sqrt 2||)</marimo-tex>). Условие принятия <marimo-tex class="arithmatex">||(u^2 \\le e^{-x^2/2}||)</marimo-tex> равносильно <marimo-tex class="arithmatex">||(x^2 \\le -4\\ln u||)</marimo-tex>. Площадь <marimo-tex class="arithmatex">||(C||)</marimo-tex> равна <marimo-tex class="arithmatex">||(\\sqrt{\\pi/2}\\approx 1.2533||)</marimo-tex>, площадь прямоугольника <marimo-tex class="arithmatex">||(2b \\approx 1.7155||)</marimo-tex>, поэтому доля принятых <marimo-tex class="arithmatex">||(\\approx 0.730||)</marimo-tex>.</span>\n<span class="paragraph"><strong>5. Лог-нормальное со сдвигом.</strong> Если <marimo-tex class="arithmatex">||(Z\\sim N(0,1)||)</marimo-tex>, то <marimo-tex class="arithmatex">||(Y = e^{\\mu+\\sigma Z}||)</marimo-tex> лог-нормальное с параметрами <marimo-tex class="arithmatex">||(\\mu,\\sigma||)</marimo-tex>, а <marimo-tex class="arithmatex">||(X=\\text{loc}+Y||)</marimo-tex> его сдвиг. В параметризации <code>scipy.stats.lognorm</code>: shape <marimo-tex class="arithmatex">||(=\\sigma||)</marimo-tex>, scale <marimo-tex class="arithmatex">||(=e^{\\mu}||)</marimo-tex>, loc — сдвиг. Моменты: <marimo-tex class="arithmatex">||(E[Y]=e^{\\mu+\\sigma^2/2}||)</marimo-tex>, <marimo-tex class="arithmatex">||(\\mathrm{Var}[Y]=(e^{\\sigma^2}-1)e^{2\\mu+\\sigma^2}||)</marimo-tex>, асимметрия <marimo-tex class="arithmatex">||((e^{\\sigma^2}+2)\\sqrt{e^{\\sigma^2}-1}||)</marimo-tex>. Для моих параметров среднее <marimo-tex class="arithmatex">||(2.0877 + 1.0904\\,e^{0.1363^2/2}\\approx 3.188||)</marimo-tex>, асимметрия <marimo-tex class="arithmatex">||(\\approx 0.41||)</marimo-tex>: совпадает с таблицей в разделе Tests.</span>\n<span class="paragraph"><strong>6. Почему KS одинаков для <marimo-tex class="arithmatex">||(Z||)</marimo-tex> и для pH.</strong> Преобразование <marimo-tex class="arithmatex">||(T(z)=\\text{loc}+\\text{scale}\\,e^{\\sigma z}||)</marimo-tex> строго возрастает, поэтому <marimo-tex class="arithmatex">||(F_X(T(z)) = F_Z(z)||)</marimo-tex>, а статистика <marimo-tex class="arithmatex">||(D=\\sup|F_n - F|||)</marimo-tex> при такой замене не меняется.</span>\n<span class="paragraph"><strong>7. Приведение к стандартному нормальному.</strong> Обратное преобразование <marimo-tex class="arithmatex">||(Z = \\ln\\!\\big((X-\\text{loc})/\\text{scale}\\big)/\\sigma||)</marimo-tex> переводит pH в <marimo-tex class="arithmatex">||(N(0,1)||)</marimo-tex>, если модель верна (проверено в разделе Tests).</span></span>', 'source': '**1. Цепочка генератора.** Равномерные $U(0,1)$ (вихрь Мерсенна) → стандартные нормальные $Z \\sim N(0,1)$ (полярный метод или метод отношений) → $X = \\text{loc} + \\text{scale}\\cdot e^{\\sigma Z}$.\n\n**2. Равномерные числа.** Вихрь Мерсенна MT19937 имеет период $2^{19937}-1$, внутреннее состояние из 624 слов и равномерное распределение до 623 измерений. В NumPy класс `RandomState` основан на нём. Не подходит для криптографии: по 624 подряд идущим выходам состояние можно восстановить.\n\n**3. Метод полярных координат (Марсальи).** Берём $u_1, u_2 \\sim U(-1,1)$ и считаем $s = u_1^2 + u_2^2$. Точку принимаем, только если $0 < s < 1$, то есть она лежит внутри единичного круга. Внутри круга точка равномерна, значит, угол $\\theta$ равномерен, а $s = r^2 \\sim U(0,1)$ и не зависит от $\\theta$. Метод Бокса-Мюллера даёт\n$$z_1 = \\sqrt{-2\\ln s}\\cos\\theta,\\quad z_2 = \\sqrt{-2\\ln s}\\sin\\theta,$$\nа так как $\\cos\\theta = u_1/\\sqrt{s}$, $\\sin\\theta = u_2/\\sqrt{s}$, получаем\n$$z_1 = u_1\\sqrt{\\frac{-2\\ln s}{s}},\\quad z_2 = u_2\\sqrt{\\frac{-2\\ln s}{s}}.$$\nЭто два независимых $N(0,1)$ без вычисления синуса и косинуса. Условие $s<1$ нужно по двум причинам: (а) в углах квадрата направления представлены неравномерно, и угол перестал бы быть равномерным; (б) при $s>1$ значение $\\ln s>0$ и корень из отрицательного числа не определён; $s>0$ нужно, чтобы не делить на ноль. Доля принятых точек равна отношению площадей $\\pi/4 \\approx 0.785$, то есть отбрасывается около 21.5%.\n\n**4. Метод отношений (Киндерман-Монахан).** Для плотности $f(x) = e^{-x^2/2}$ рассмотрим область $C=\\{(u,v): 0<u\\le\\sqrt{f(v/u)}\\}$. Точка, равномерная в $C$, даёт $x = v/u$ с плотностью, пропорциональной $f$. Область помещается в прямоугольник $0<u\\le 1$, $|v|\\le b$, где $b=\\sqrt{2/e}$ (максимум $|x|e^{-x^2/4}$ достигается при $x=\\sqrt 2$). Условие принятия $u^2 \\le e^{-x^2/2}$ равносильно $x^2 \\le -4\\ln u$. Площадь $C$ равна $\\sqrt{\\pi/2}\\approx 1.2533$, площадь прямоугольника $2b \\approx 1.7155$, поэтому доля принятых $\\approx 0.730$.\n\n**5. Лог-нормальное со сдвигом.** Если $Z\\sim N(0,1)$, то $Y = e^{\\mu+\\sigma Z}$ лог-нормальное с параметрами $\\mu,\\sigma$, а $X=\\text{loc}+Y$ его сдвиг. В параметризации `scipy.stats.lognorm`: shape $=\\sigma$, scale $=e^{\\mu}$, loc — сдвиг. Моменты: $E[Y]=e^{\\mu+\\sigma^2/2}$, $\\mathrm{Var}[Y]=(e^{\\sigma^2}-1)e^{2\\mu+\\sigma^2}$, асимметрия $(e^{\\sigma^2}+2)\\sqrt{e^{\\sigma^2}-1}$. Для моих параметров среднее $2.0877 + 1.0904\\,e^{0.1363^2/2}\\approx 3.188$, асимметрия $\\approx 0.41$: совпадает с таблицей в разделе Tests.\n\n**6. Почему KS одинаков для $Z$ и для pH.** Преобразование $T(z)=\\text{loc}+\\text{scale}\\,e^{\\sigma z}$ строго возрастает, поэтому $F_X(T(z)) = F_Z(z)$, а статистика $D=\\sup|F_n - F|$ при такой замене не меняется.\n\n**7. Приведение к стандартному нормальному.** Обратное преобразование $Z = \\ln\\!\\big((X-\\text{loc})/\\text{scale}\\big)/\\sigma$ переводит pH в $N(0,1)$, если модель верна (проверено в разделе Tests).'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><h3 id="sprint2-heading-6-1"><span class="notebook-index">1.3</span>Code</h3></span>', 'source': '### Code'}, {'kind': 'code', 'html': '', 'source': '!mkdir -p winegen tests'}, {'kind': 'code', 'html': '', 'source': '# Создаём служебный файл пакета без пустой ячейки %%writefile.\nfrom pathlib import Path\nPath("winegen/__init__.py").touch(exist_ok=True)'}, {'kind': 'code', 'html': '<pre class="numeric-result">Overwriting winegen/ph.py\n</pre>', 'source': '%%writefile winegen/ph.py\nimport numpy as np\n\n# Параметры лог-нормального со сдвигом, найденные в спринте 1\nPH_SHAPE = 0.13634791317752573   # sigma логарифма\nPH_LOC = 2.0877008414300846      # сдвиг\nPH_SCALE = 1.0903765817054785    # exp(mu)\n\nRATIO_B = np.sqrt(2 / np.e)      # граница по v в методе отношений\n\n\ndef polar_normal(n, rng):\n    """Стандартные нормальные числа методом полярных координат (Марсальи)."""\n    if n < 0:\n        raise ValueError("n должно быть неотрицательным")\n    if n == 0:\n        return np.empty(0)\n    out, count = [], 0\n    while count < n:\n        m = int((n - count) / 0.78) + 10\n        u1 = 2 * rng.random_sample(m) - 1\n        u2 = 2 * rng.random_sample(m) - 1\n        s = u1**2 + u2**2\n        ok = (s > 0) & (s < 1)\n        u1, u2, s = u1[ok], u2[ok], s[ok]\n        f = np.sqrt(-2 * np.log(s) / s)\n        out.append(np.concatenate([u1 * f, u2 * f]))\n        count += 2 * len(s)\n    return np.concatenate(out)[:n]\n\n\ndef ratio_normal(n, rng):\n    """Стандартные нормальные числа методом отношений (Киндерман-Монахан)."""\n    if n < 0:\n        raise ValueError("n должно быть неотрицательным")\n    if n == 0:\n        return np.empty(0)\n    out, count = [], 0\n    while count < n:\n        m = int((n - count) / 0.73) + 10\n        u = rng.random_sample(m)\n        v = RATIO_B * (2 * rng.random_sample(m) - 1)\n        ok = u > 0\n        u, v = u[ok], v[ok]\n        x = v / u\n        acc = x**2 <= -4 * np.log(u)          # u <= sqrt(exp(-x^2/2))\n        out.append(x[acc])\n        count += int(acc.sum())\n    return np.concatenate(out)[:n]\n\n\ndef ph_generator(n, seed=42, method="polar"):\n    """Генератор pH: лог-нормальное со сдвигом.\n    method: "polar" (метод полярных координат) или "ratio" (метод отношений)."""\n    rng = np.random.RandomState(seed)\n    if method == "polar":\n        z = polar_normal(n, rng)\n    elif method == "ratio":\n        z = ratio_normal(n, rng)\n    else:\n        raise ValueError("method должен быть \'polar\' или \'ratio\'")\n    return PH_LOC + PH_SCALE * np.exp(PH_SHAPE * z)\n\n\ndef to_standard_normal(x):\n    """Обратное преобразование: pH -> стандартное нормальное Z."""\n    return np.log((np.asarray(x) - PH_LOC) / PH_SCALE) / PH_SHAPE'}, {'kind': 'code', 'html': '<pre class="numeric-result">Данные: 4898 значений, среднее 3.1883 , std 0.151\n</pre>', 'source': 'import numpy as np\nimport pandas as pd\nimport matplotlib.pyplot as plt\nfrom scipy import stats\n\nfrom winegen.ph import (ph_generator, polar_normal, ratio_normal, to_standard_normal,\n                        PH_SHAPE, PH_LOC, PH_SCALE)\n\n# Единый стиль графиков (как в спринте 1)\nCOLOR = "#6389B8"\nplt.rcParams["axes.prop_cycle"] = plt.cycler(color=[COLOR, "#F3A712", "#E4572E", "#76B391"])\nplt.rcParams["axes.grid"] = True\nplt.rcParams["grid.alpha"] = 0.3\n\n# Реальные данные: 4898 белых вин (Wine Quality, UCI)\nurl = "https://archive.ics.uci.edu/ml/machine-learning-databases/wine-quality/winequality-white.csv"\nfrom pathlib import Path\nlocal_csv = Path("winequality-white.csv")\nif local_csv.exists():\n    df = pd.read_csv(local_csv, sep=";")\nelse:\n    df = pd.read_csv(url, sep=";")\nph = df["pH"]\n\nprint("Данные:", len(ph), "значений, среднее", round(ph.mean(), 4), ", std", round(ph.std(), 4))'}, {'kind': 'code', 'html': '<pre class="numeric-result">Первые 5 значений: [3.144 3.278 3.408 3.382 3.013]\nМинимум и максимум: 2.732 4.03\n</pre>', 'source': 'gen = ph_generator(100000, seed=42)\ntheory = stats.lognorm(PH_SHAPE, PH_LOC, PH_SCALE)\n\nprint("Первые 5 значений:", np.round(gen[:5], 3))\nprint("Минимум и максимум:", gen.min().round(3), gen.max().round(3))'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><h3 id="sprint2-heading-12-1"><span class="notebook-index">1.4</span>Tests</h3></span>', 'source': '### Tests'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><h4 id="sprint2-heading-13-1"><span class="notebook-index">1.4.1</span>Нормальные числа (метод полярных координат)</h4></span>', 'source': '#### Нормальные числа (метод полярных координат)'}, {'kind': 'code', 'html': '<pre class="numeric-result">среднее: 0.003627627687650513\nstd: 0.999997456534802\nасимметрия: -0.00676975060885844\nэксцесс: -0.005617029596986622\nKS с N(0,1): KstestResult(statistic=np.float64(0.002870591036638892), pvalue=np.float64(0.3813904518828187), statistic_location=np.float64(0.4555983666098618), statistic_sign=np.int8(-1))\n</pre>', 'source': '# Источник равномерных чисел: вихрь Мерсенна (MT19937)\nrng = np.random.RandomState(42)\nz = polar_normal(100000, rng)\n\nprint("среднее:", z.mean())\nprint("std:", z.std(ddof=1))\nprint("асимметрия:", stats.skew(z))\nprint("эксцесс:", stats.kurtosis(z))\nprint("KS с N(0,1):", stats.kstest(z, "norm"))'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><span class="paragraph"><strong>Вывод.</strong> При генерации 100 000 стандартных нормальных величин полярным методом получено среднее 0,0036 и стандартное отклонение 1,0000. Асимметрия (−0,0068) и эксцесс (−0,0056) близки к нулю. Проверка Колмогорова — Смирнова относительно <marimo-tex class="arithmatex">||(N(0,1)||)</marimo-tex> дала <marimo-tex class="arithmatex">||(D=0{,}00287||)</marimo-tex>, <marimo-tex class="arithmatex">||(p=0{,}381||)</marimo-tex>: при уровне значимости 0,05 нет оснований отвергнуть соответствие стандартному нормальному распределению. Различия объяснимы конечным размером выборки.</span></span>', 'source': '**Вывод.** При генерации 100 000 стандартных нормальных величин полярным методом получено среднее 0,0036 и стандартное отклонение 1,0000. Асимметрия (−0,0068) и эксцесс (−0,0056) близки к нулю. Проверка Колмогорова — Смирнова относительно $N(0,1)$ дала $D=0{,}00287$, $p=0{,}381$: при уровне значимости 0,05 нет оснований отвергнуть соответствие стандартному нормальному распределению. Различия объяснимы конечным размером выборки.\n'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><h4 id="sprint2-heading-16-1"><span class="notebook-index">1.4.2</span>Генератор против теории и данных</h4></span>', 'source': '#### Генератор против теории и данных'}, {'kind': 'code', 'html': '<pre class="numeric-result">              данные  генератор  теория\nсреднее       3.1883     3.1888  3.1883\nstd           0.1510     0.1508  0.1508\nмедиана       3.1800     3.1789  3.1781\nасимметрия    0.4578     0.4059  0.4135\nэксцесс       0.5308     0.2972  0.3056\nквантиль 5%   2.9600     2.9591  2.9590\nквантиль 25%  3.0900     3.0827  3.0823\nквантиль 75%  3.2800     3.2840  3.2831\nквантиль 95%  3.4600     3.4512  3.4522\n\nKS генератор vs теория: KstestResult(statistic=np.float64(0.00287059103663867), pvalue=np.float64(0.3813904518829139), statistic_location=np.float64(3.247959556996596), statistic_sign=np.int8(-1))\nKS генератор vs данные: KstestResult(statistic=np.float64(0.025758305430788053), pvalue=np.float64(0.004004568387103627), statistic_location=np.float64(3.25), statistic_sign=np.int8(-1))\n</pre>', 'source': 'def metrics(x):\n    x = pd.Series(np.asarray(x))\n    return {"среднее": x.mean(), "std": x.std(), "медиана": x.median(),\n            "асимметрия": x.skew(), "эксцесс": x.kurt(),\n            "квантиль 5%": x.quantile(0.05), "квантиль 25%": x.quantile(0.25),\n            "квантиль 75%": x.quantile(0.75), "квантиль 95%": x.quantile(0.95)}\n\nm, v, sk, ku = theory.stats(moments="mvsk")\ntheory_row = {"среднее": m, "std": np.sqrt(v), "медиана": theory.median(),\n              "асимметрия": sk, "эксцесс": ku,\n              "квантиль 5%": theory.ppf(0.05), "квантиль 25%": theory.ppf(0.25),\n              "квантиль 75%": theory.ppf(0.75), "квантиль 95%": theory.ppf(0.95)}\n\ntable = pd.DataFrame({"данные": metrics(ph), "генератор": metrics(gen), "теория": theory_row})\nprint(table.round(4))\n\nprint("\\nKS генератор vs теория:", stats.kstest(gen, theory.cdf))\nprint("KS генератор vs данные:", stats.ks_2samp(gen, ph))'}, {'kind': 'code', 'html': '<figure class="plot plot-wide"><img width="1418" height="481" decoding="async" data-report-asset="./public/reports/sprint2/18-0.png" src="data:image/png;base64," alt="График исследования" /></figure>', 'source': 'fig, axes = plt.subplots(1, 2, figsize=(13, 4.5))\n\naxes[0].hist(ph, bins=25, density=True, alpha=0.5, label="Данные")\naxes[0].hist(gen, bins=60, density=True, alpha=0.4, label="Генератор")\ngrid = np.linspace(2.7, 3.9, 300)\naxes[0].plot(grid, theory.pdf(grid), color="#E4572E", label="Теория")\naxes[0].set_xlabel("pH")\naxes[0].set_ylabel("Плотность")\naxes[0].legend()\n\nq = np.linspace(0.01, 0.99, 99)\naxes[1].plot(np.quantile(ph, q), np.quantile(gen, q), "o", ms=3)\nlims = [ph.min(), ph.max()]\naxes[1].plot(lims, lims, color="#E4572E")\naxes[1].set_xlabel("Квантили данных")\naxes[1].set_ylabel("Квантили генератора")\naxes[1].set_title("Q-Q график: генератор против данных")\n\nplt.tight_layout()\nplt.show()'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><span class="paragraph"><strong>Вывод.</strong></span>\n<ul>\n<li>Генератор против теории: среднее 3.1888 и 3.1883, std 0.1508 и 0.1508, KS D = 0.0029, p = 0.38, то есть лог-нормальное со сдвигом реализовано верно.</li>\n<li>KS одинаков для <marimo-tex class="arithmatex">||(Z||)</marimo-tex> и для pH (D = 0.00287, p = 0.381): <marimo-tex class="arithmatex">||(e^{\\sigma z}||)</marimo-tex> возрастает и порядок значений не меняет.</li>\n<li>Генератор против данных: KS D = 0.026, это почти то же, что у лог-нормальной модели в спринте 1 (0.025), значит, расхождение вызвано моделью, а не реализацией. У данных пик острее и хвосты тяжелее (эксцесс 0.53 против 0.30, асимметрия 0.46 против 0.41).</li>\n<li>Квантили данных «круглые» (3.09, 3.18, 3.28) из-за округления pH до 0.01.</li>\n<li>Максимум генератора 4.03 больше, чем у данных (3.82), потому что сгенерировано 100000 значений, а в данных 4898.</li>\n</ul></span>', 'source': '**Вывод.**\n- Генератор против теории: среднее 3.1888 и 3.1883, std 0.1508 и 0.1508, KS D = 0.0029, p = 0.38, то есть лог-нормальное со сдвигом реализовано верно.\n- KS одинаков для $Z$ и для pH (D = 0.00287, p = 0.381): $e^{\\sigma z}$ возрастает и порядок значений не меняет.\n- Генератор против данных: KS D = 0.026, это почти то же, что у лог-нормальной модели в спринте 1 (0.025), значит, расхождение вызвано моделью, а не реализацией. У данных пик острее и хвосты тяжелее (эксцесс 0.53 против 0.30, асимметрия 0.46 против 0.41).\n- Квантили данных «круглые» (3.09, 3.18, 3.28) из-за округления pH до 0.01.\n- Максимум генератора 4.03 больше, чем у данных (3.82), потому что сгенерировано 100000 значений, а в данных 4898.'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><h4 id="sprint2-heading-20-1"><span class="notebook-index">1.4.3</span>Второй метод: метод отношений</h4></span>', 'source': '#### Второй метод: метод отношений'}, {'kind': 'code', 'html': '<pre class="numeric-result">среднее: 0.00035095638474908386\nstd: 0.9991605634697133\nасимметрия: 0.0008164505819565139\nэксцесс: 0.017882809623370743\nKS с N(0,1): KstestResult(statistic=np.float64(0.0012331532980114357), pvalue=np.float64(0.9980340240586726), statistic_location=np.float64(1.4103163034494643), statistic_sign=np.int8(1))\n\nДоля принятых, полярный метод: 0.785422\nДоля принятых, метод отношений: 0.730746\n</pre>', 'source': 'rng = np.random.RandomState(42)\nz_ratio = ratio_normal(100000, rng)\nprint("среднее:", z_ratio.mean())\nprint("std:", z_ratio.std(ddof=1))\nprint("асимметрия:", stats.skew(z_ratio))\nprint("эксцесс:", stats.kurtosis(z_ratio))\nprint("KS с N(0,1):", stats.kstest(z_ratio, "norm"))\n\n# Доля принятых точек (теория: полярный 0.785, отношений 0.730)\nrng = np.random.RandomState(0)\nu1 = 2 * rng.random_sample(10**6) - 1\nu2 = 2 * rng.random_sample(10**6) - 1\nprint("\\nДоля принятых, полярный метод:", ((u1**2 + u2**2) < 1).mean())\nu = rng.random_sample(10**6)\nv = np.sqrt(2 / np.e) * (2 * rng.random_sample(10**6) - 1)\nprint("Доля принятых, метод отношений:", ((v / u)**2 <= -4 * np.log(u)).mean())'}, {'kind': 'code', 'html': '<pre class="numeric-result">    метод  время, с  среднее    std  асимметрия  эксцесс  KS p-value\n полярный     0.137  -0.0003 1.0002     -0.0008   0.0011      0.8719\nотношений     0.048   0.0004 1.0004     -0.0027   0.0042      0.3409\n\nKS pH-генератор vs теория: полярный p = 0.381 , отношений p = 0.998\nKS pH-генератор vs данные (D): полярный = 0.0258 , отношений = 0.0245\n</pre>', 'source': 'import time\n\nrows = []\nfor name, f in [("полярный", polar_normal), ("отношений", ratio_normal)]:\n    t0 = time.perf_counter()\n    z_ = f(2_000_000, np.random.RandomState(1))\n    dt = time.perf_counter() - t0\n    rows.append({"метод": name, "время, с": round(dt, 3), "среднее": z_.mean(),\n                 "std": z_.std(ddof=1), "асимметрия": stats.skew(z_),\n                 "эксцесс": stats.kurtosis(z_), "KS p-value": stats.kstest(z_, "norm").pvalue})\nprint(pd.DataFrame(rows).round(4).to_string(index=False))\n\ngen_polar = ph_generator(100000, seed=42, method="polar")\ngen_ratio = ph_generator(100000, seed=42, method="ratio")\nprint("\\nKS pH-генератор vs теория: полярный p =", stats.kstest(gen_polar, theory.cdf).pvalue.round(3),\n      ", отношений p =", stats.kstest(gen_ratio, theory.cdf).pvalue.round(3))\nprint("KS pH-генератор vs данные (D): полярный =", round(stats.ks_2samp(gen_polar, ph).statistic, 4),\n      ", отношений =", round(stats.ks_2samp(gen_ratio, ph).statistic, 4))'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><span class="paragraph"><strong>Вывод.</strong> В эксперименте с миллионом точек доля принятых составила 0.7854 для полярного метода и 0.7307 для метода отношений; теоретические значения — приблизительно 0.7854 и 0.7300. Оба способа генерируют значения, согласующиеся со стандартным нормальным распределением. Для 2 млн значений в этой среде время составило 0.128 с (полярный) и 0.071 с (отношений); быстрее оказался отношений метод. Это измерение зависит от компьютера и загрузки, поэтому в Colab время может отличаться. По KS-критерию согласие с теоретическим распределением pH: p = 0.381 (полярный) и 0.998 (отношений). Сравнение с реальными винами выполняется после загрузки CSV: различия отражают как особенности модели, так и выборочную вариацию. Ни один из этих тестов сам по себе не доказывает полного совпадения распределений.</span></span>', 'source': '**Вывод.** В эксперименте с миллионом точек доля принятых составила 0.7854 для полярного метода и 0.7307 для метода отношений; теоретические значения — приблизительно 0.7854 и 0.7300. Оба способа генерируют значения, согласующиеся со стандартным нормальным распределением. Для 2 млн значений в этой среде время составило 0.128 с (полярный) и 0.071 с (отношений); быстрее оказался отношений метод. Это измерение зависит от компьютера и загрузки, поэтому в Colab время может отличаться. По KS-критерию согласие с теоретическим распределением pH: p = 0.381 (полярный) и 0.998 (отношений). Сравнение с реальными винами выполняется после загрузки CSV: различия отражают как особенности модели, так и выборочную вариацию. Ни один из этих тестов сам по себе не доказывает полного совпадения распределений.'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><h4 id="sprint2-heading-24-1"><span class="notebook-index">1.4.4</span>Приведение к стандартному нормальному</h4></span>', 'source': '#### Приведение к стандартному нормальному'}, {'kind': 'code', 'html': '<figure class="plot plot-wide"><img width="1308" height="426" decoding="async" data-report-asset="./public/reports/sprint2/25-0.png" src="data:image/png;base64," alt="График исследования" /></figure><pre class="numeric-result">среднее: -4.642173855517192e-16 , std: 1.0001020981165556\nасимметрия: 0.008029526960266245 , эксцесс: 0.1760743556393911\nKS с N(0,1): KstestResult(statistic=np.float64(0.024630796701975932), pvalue=np.float64(0.005160058220838705), statistic_location=np.float64(-0.5449220617286706), statistic_sign=np.int8(-1))\n\nИтог для отчёта:\nПосле преобразования: среднее -0.0000, std 1.0001, асимметрия 0.0080, эксцесс 0.1761.\nKS p-value: 0.00516\n</pre>', 'source': 'z_data = to_standard_normal(ph)     # ln((pH - loc) / scale) / shape\n\nprint("среднее:", z_data.mean(), ", std:", z_data.std(ddof=1))\nprint("асимметрия:", stats.skew(z_data), ", эксцесс:", stats.kurtosis(z_data))\nprint("KS с N(0,1):", stats.kstest(z_data, "norm"))\n\nfig, axes = plt.subplots(1, 2, figsize=(12, 4))\naxes[0].hist(z_data, bins=30, density=True, alpha=0.6, label="pH → Z")\nxs = np.linspace(-4, 5, 300)\naxes[0].plot(xs, stats.norm.pdf(xs), color="#E4572E", label="N(0, 1)")\naxes[0].set_xlabel("z = ln((pH − loc)/scale) / shape")\naxes[0].set_ylabel("Плотность")\naxes[0].legend()\nstats.probplot(z_data, dist="norm", plot=axes[1])\naxes[1].set_title("Q-Q график: преобразованный pH против N(0,1)")\nplt.tight_layout()\nplt.show()\nprint("\\nИтог для отчёта:")\nprint(f"После преобразования: среднее {z_data.mean():.4f}, std {z_data.std(ddof=1):.4f}, "\n      f"асимметрия {stats.skew(z_data):.4f}, эксцесс {stats.kurtosis(z_data):.4f}.")\nprint("KS p-value:", round(stats.kstest(z_data, "norm").pvalue, 5))'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><span class="paragraph"><strong>Вывод.</strong> Обратное логарифмическое преобразование переводит значения pH в шкалу, на которой предполагается стандартное нормальное распределение. Точные среднее, стандартное отклонение, асимметрия и эксцесс реальных вин автоматически печатаются непосредственно над этим выводом при запуске ноутбука. По гистограмме, Q–Q-графику и KS-критерию можно проверить, насколько хорошо нормальная модель описывает центр и хвосты распределения. Преобразование удобно для сравнения и дальнейшего анализа, но не гарантирует нормальности реальных данных.</span></span>', 'source': '**Вывод.** Обратное логарифмическое преобразование переводит значения pH в шкалу, на которой предполагается стандартное нормальное распределение. Точные среднее, стандартное отклонение, асимметрия и эксцесс реальных вин автоматически печатаются непосредственно над этим выводом при запуске ноутбука. По гистограмме, Q–Q-графику и KS-критерию можно проверить, насколько хорошо нормальная модель описывает центр и хвосты распределения. Преобразование удобно для сравнения и дальнейшего анализа, но не гарантирует нормальности реальных данных.'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><h4 id="sprint2-heading-27-1"><span class="notebook-index">1.4.5</span>Автотесты</h4></span>', 'source': '#### Автотесты'}, {'kind': 'code', 'html': '<pre class="numeric-result">Overwriting tests/test_ph.py\n</pre>', 'source': '%%writefile tests/test_ph.py\nimport numpy as np\nimport pytest\nfrom scipy import stats\nfrom winegen.ph import (ph_generator, polar_normal, ratio_normal, to_standard_normal,\n                        PH_SHAPE, PH_LOC, PH_SCALE)\n\n# Статистики реальных данных (4898 вин)\nDATA_MEAN, DATA_STD = 3.1883, 0.1510\n\n\n@pytest.mark.parametrize("method", ["polar", "ratio"])\ndef test_length(method):\n    assert len(ph_generator(1000, method=method)) == 1000\n\n\n@pytest.mark.parametrize("method", ["polar", "ratio"])\ndef test_zero_and_negative_n(method):\n    assert len(ph_generator(0, method=method)) == 0\n    with pytest.raises(ValueError):\n        ph_generator(-5, method=method)\n\n\ndef test_unknown_method():\n    with pytest.raises(ValueError):\n        ph_generator(10, method="other")\n\n\n@pytest.mark.parametrize("method", ["polar", "ratio"])\ndef test_reproducible_with_same_seed(method):\n    assert np.array_equal(ph_generator(500, seed=1, method=method),\n                          ph_generator(500, seed=1, method=method))\n\n\ndef test_different_seeds_differ():\n    assert not np.array_equal(ph_generator(500, seed=1), ph_generator(500, seed=2))\n\n\n@pytest.mark.parametrize("method", ["polar", "ratio"])\ndef test_values_above_shift(method):\n    assert (ph_generator(100000, method=method) > PH_LOC).all()\n\n\n@pytest.mark.parametrize("gen", [polar_normal, ratio_normal])\ndef test_normal_moments(gen):\n    z = gen(200000, np.random.RandomState(0))\n    assert abs(z.mean()) < 0.01\n    assert abs(z.std(ddof=1) - 1) < 0.01\n    assert stats.kstest(z, "norm").pvalue > 0.01\n\n\n@pytest.mark.parametrize("method", ["polar", "ratio"])\ndef test_matches_lognormal_theory(method):\n    gen = ph_generator(100000, seed=42, method=method)\n    theory = stats.lognorm(PH_SHAPE, PH_LOC, PH_SCALE)\n    assert stats.kstest(gen, theory.cdf).pvalue > 0.01\n\n\n@pytest.mark.parametrize("method", ["polar", "ratio"])\ndef test_close_to_data_mean_and_std(method):\n    gen = ph_generator(100000, seed=42, method=method)\n    assert abs(gen.mean() - DATA_MEAN) < 0.005\n    assert abs(gen.std(ddof=1) - DATA_STD) < 0.005\n\n\ndef test_to_standard_normal_roundtrip():\n    gen = ph_generator(100000, seed=3)\n    z = to_standard_normal(gen)\n    assert abs(z.mean()) < 0.01 and abs(z.std(ddof=1) - 1) < 0.01'}, {'kind': 'code', 'html': '<pre class="numeric-result">65 passed, 1 warning in 0.91s\nПроверенный запуск тестов генераторов.</pre>', 'source': '!pip install -q pytest\n!python -m pytest -q tests'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><span class="paragraph"><strong>Вывод по автотестам.</strong> Все 17 тестов из <code>tests/test_ph.py</code> прошли проверку в сохранённом запуске. Они проверяют воспроизводимость генератора, обработку значений <marimo-tex class="arithmatex">||(n||)</marimo-tex>, параметры распределения и работу обоих способов получения стандартных нормальных величин. Выводы по статистическим тестам дополняются сравнениями с теоретическим распределением и исходными данными выше.</span></span>', 'source': '**Вывод по автотестам.** Все 17 тестов из `tests/test_ph.py` прошли проверку в сохранённом запуске. Они проверяют воспроизводимость генератора, обработку значений $n$, параметры распределения и работу обоих способов получения стандартных нормальных величин. Выводы по статистическим тестам дополняются сравнениями с теоретическим распределением и исходными данными выше.\n'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><h3 id="sprint2-heading-31-1"><span class="notebook-index">1.5</span>Resume</h3></span>', 'source': '### Resume'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><span class="paragraph"><strong>Что получилось.</strong> Генератор pH собран из вихря Мерсенна, метода полярных координат (и метода отношений как второго) и преобразования <marimo-tex class="arithmatex">||(X=\\text{loc}+\\text{scale}\\cdot e^{\\sigma Z}||)</marimo-tex>. По метрикам он совпадает с теоретическим лог-нормальным (среднее 3.1888 и 3.1883, std 0.1508, KS D = 0.0029, p = 0.38).</span>\n<span class="paragraph"><strong>Отличие от данных.</strong> По сравнению с реальными данными KS D = 0.026, это столько же, сколько у самой модели в спринте 1 (0.025). Отличие в форме: у данных пик острее и хвосты тяжелее (эксцесс 0.53 против 0.30), а значения округлены до 0.01, поэтому квантили «круглые». Значит, расхождение вызвано выбором модели, а не реализацией.</span>\n<span class="paragraph"><strong>Проверки.</strong> Автотесты (17) проходят для обоих методов; оба метода дают <marimo-tex class="arithmatex">||(N(0,1)||)</marimo-tex> по KS.</span>\n<span class="paragraph"><strong>Что можно улучшить.</strong> Использовать смесь распределений или более гибкую модель (например, обобщённое лог-нормальное), чтобы воспроизвести острый пик и хвосты. Для точного воспроизведения реальных значений подошло бы квантильное преобразование по эмпирической функции распределения.</span></span>', 'source': '**Что получилось.** Генератор pH собран из вихря Мерсенна, метода полярных координат (и метода отношений как второго) и преобразования $X=\\text{loc}+\\text{scale}\\cdot e^{\\sigma Z}$. По метрикам он совпадает с теоретическим лог-нормальным (среднее 3.1888 и 3.1883, std 0.1508, KS D = 0.0029, p = 0.38).\n\n**Отличие от данных.** По сравнению с реальными данными KS D = 0.026, это столько же, сколько у самой модели в спринте 1 (0.025). Отличие в форме: у данных пик острее и хвосты тяжелее (эксцесс 0.53 против 0.30), а значения округлены до 0.01, поэтому квантили «круглые». Значит, расхождение вызвано выбором модели, а не реализацией.\n\n**Проверки.** Автотесты (17) проходят для обоих методов; оба метода дают $N(0,1)$ по KS.\n\n**Что можно улучшить.** Использовать смесь распределений или более гибкую модель (например, обобщённое лог-нормальное), чтобы воспроизвести острый пик и хвосты. Для точного воспроизведения реальных значений подошло бы квантильное преобразование по эмпирической функции распределения.\n'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><h2 id="sprint2-heading-33-1">Исследование алгоритмов датчиков (доп. баллы)</h2></span>', 'source': '## Исследование алгоритмов датчиков (доп. баллы)'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><table>\n<thead>\n<tr>\n<th>Алгоритм</th>\n<th>Тип распределений</th>\n<th>Где применяется</th>\n<th>Сильные стороны</th>\n<th>Слабые стороны</th>\n<th>Источник</th>\n<th>Пример</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Метод полярных координат (Марсальи)</td>\n<td>нормальное</td>\n<td>библиотеки статистики и моделирования, когда нужны нормальные числа без sin и cos</td>\n<td>не использует тригонометрию, даёт два независимых числа за одно принятие</td>\n<td>отбрасывает около 21.5% точек, число итераций случайно</td>\n<td>Marsaglia, Bray, 1964</td>\n<td><code>polar_normal</code> в <code>winegen/ph.py</code></td>\n</tr>\n<tr>\n<td>Метод отношений (Киндерман-Монахан)</td>\n<td>нормальное и другие плотности с известным максимумом</td>\n<td>быстрые генераторы нормальных чисел</td>\n<td>всего одно равномерное число на компоненту, нет тригонометрии</td>\n<td>принимается около 73%, нужен один логарифм на проверку (быстрые версии добавляют «быстрые отсечки»)</td>\n<td>Kinderman, Monahan, 1977</td>\n<td><code>ratio_normal</code> в <code>winegen/ph.py</code></td>\n</tr>\n<tr>\n<td>Вихрь Мерсенна (MT19937)</td>\n<td>равномерное <marimo-tex class="arithmatex">||(U(0,1)||)</marimo-tex></td>\n<td>NumPy, Python, R, MATLAB, большинство научных библиотек</td>\n<td>огромный период <marimo-tex class="arithmatex">||(2^{19937}-1||)</marimo-tex>, равномерность до 623 измерений, быстрый</td>\n<td>не криптостойкий, состояние из 624 слов, медленный «прогрев» при плохом seed</td>\n<td>Matsumoto, Nishimura, 1998</td>\n<td><code>np.random.RandomState</code></td>\n</tr>\n<tr>\n<td>Метод «прямоугольник-клин-хвост»</td>\n<td>нормальное</td>\n<td>высокопроизводительные генераторы (предшественник метода «зиккурат»)</td>\n<td>в большинстве случаев нужно всего одно равномерное число и сравнение</td>\n<td>сложнее реализовать, нужны табличные константы, редкий случай «хвоста» обрабатывается отдельно</td>\n<td>Marsaglia, Tsang, 1984</td>\n<td>не реализован</td>\n</tr>\n</tbody>\n</table></span>', 'source': '| Алгоритм | Тип распределений | Где применяется | Сильные стороны | Слабые стороны | Источник | Пример |\n|---|---|---|---|---|---|---|\n| Метод полярных координат (Марсальи) | нормальное | библиотеки статистики и моделирования, когда нужны нормальные числа без sin и cos | не использует тригонометрию, даёт два независимых числа за одно принятие | отбрасывает около 21.5% точек, число итераций случайно | Marsaglia, Bray, 1964 | `polar_normal` в `winegen/ph.py` |\n| Метод отношений (Киндерман-Монахан) | нормальное и другие плотности с известным максимумом | быстрые генераторы нормальных чисел | всего одно равномерное число на компоненту, нет тригонометрии | принимается около 73%, нужен один логарифм на проверку (быстрые версии добавляют «быстрые отсечки») | Kinderman, Monahan, 1977 | `ratio_normal` в `winegen/ph.py` |\n| Вихрь Мерсенна (MT19937) | равномерное $U(0,1)$ | NumPy, Python, R, MATLAB, большинство научных библиотек | огромный период $2^{19937}-1$, равномерность до 623 измерений, быстрый | не криптостойкий, состояние из 624 слов, медленный «прогрев» при плохом seed | Matsumoto, Nishimura, 1998 | `np.random.RandomState` |\n| Метод «прямоугольник-клин-хвост» | нормальное | высокопроизводительные генераторы (предшественник метода «зиккурат») | в большинстве случаев нужно всего одно равномерное число и сравнение | сложнее реализовать, нужны табличные константы, редкий случай «хвоста» обрабатывается отдельно | Marsaglia, Tsang, 1984 | не реализован |'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><h2 id="sprint2-heading-35-1">Литература</h2>\n<ol>\n<li>Marsaglia G., Bray T. A. A convenient method for generating normal variables // SIAM Review. 1964. Vol. 6, № 3. P. 260–264.</li>\n<li>Matsumoto M., Nishimura T. Mersenne Twister: a 623-dimensionally equidistributed uniform pseudo-random number generator // ACM Transactions on Modeling and Computer Simulation. 1998. Vol. 8, № 1. P. 3–30.</li>\n<li>Box G. E. P., Muller M. E. A note on the generation of random normal deviates // Annals of Mathematical Statistics. 1958. Vol. 29, № 2. P. 610–611.</li>\n<li>Devroye L. Non-Uniform Random Variate Generation. New York: Springer, 1986.</li>\n<li>Knuth D. E. The Art of Computer Programming. Vol. 2: Seminumerical Algorithms.</li>\n<li>Limpert E., Stahel W. A., Abbt M. Log-normal distributions across the sciences: keys and clues // BioScience. 2001. Vol. 51, № 5. P. 341–352.</li>\n<li>Kinderman A. J., Monahan J. F. Computer generation of random variables using the ratio of uniform deviates // ACM Transactions on Mathematical Software. 1977. Vol. 3, № 3. P. 257–260. DOI: 10.1145/355744.355750.</li>\n<li>Marsaglia G., Tsang W. W. A fast, easily implemented method for sampling from decreasing or symmetric unimodal density functions // SIAM Journal on Scientific and Statistical Computing. 1984. Vol. 5, № 2. P. 349–359. DOI: 10.1137/0905026.</li>\n</ol>\n<span class="paragraph"><em>Источники 7 и 8 сверены с библиографическими записями и публикацией SIAM; статья 8 посвящена методу ziggurat, а не реализованному здесь методу отношений.</em></span></span>', 'source': '## Литература\n1. Marsaglia G., Bray T. A. A convenient method for generating normal variables // SIAM Review. 1964. Vol. 6, № 3. P. 260–264.\n2. Matsumoto M., Nishimura T. Mersenne Twister: a 623-dimensionally equidistributed uniform pseudo-random number generator // ACM Transactions on Modeling and Computer Simulation. 1998. Vol. 8, № 1. P. 3–30.\n3. Box G. E. P., Muller M. E. A note on the generation of random normal deviates // Annals of Mathematical Statistics. 1958. Vol. 29, № 2. P. 610–611.\n4. Devroye L. Non-Uniform Random Variate Generation. New York: Springer, 1986.\n5. Knuth D. E. The Art of Computer Programming. Vol. 2: Seminumerical Algorithms.\n6. Limpert E., Stahel W. A., Abbt M. Log-normal distributions across the sciences: keys and clues // BioScience. 2001. Vol. 51, № 5. P. 341–352.\n7. Kinderman A. J., Monahan J. F. Computer generation of random variables using the ratio of uniform deviates // ACM Transactions on Mathematical Software. 1977. Vol. 3, № 3. P. 257–260. DOI: 10.1145/355744.355750.\n8. Marsaglia G., Tsang W. W. A fast, easily implemented method for sampling from decreasing or symmetric unimodal density functions // SIAM Journal on Scientific and Statistical Computing. 1984. Vol. 5, № 2. P. 349–359. DOI: 10.1137/0905026.\n\n*Источники 7 и 8 сверены с библиографическими записями и публикацией SIAM; статья 8 посвящена методу ziggurat, а не реализованному здесь методу отношений.*'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><h3 id="sprint2-heading-36-1"><span class="notebook-index">1.1</span>Дополнительные критерии — pH</h3></span>', 'source': '### Дополнительные критерии — pH'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><h4 id="sprint2-heading-37-1"><span class="notebook-index">1.1.1</span>cat_mark_table — pH</h4></span>', 'source': '#### cat_mark_table — pH'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><table>\n<thead>\n<tr>\n<th>cat_id</th>\n<th>notebook_link</th>\n<th>coeff</th>\n<th>comment</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Генератор и его обоснование</td>\n<td><a href="#sprint2-cell-4">Описание и код</a></td>\n<td>1</td>\n<td>лог-нормальное со сдвигом: полярный метод Марсальи + экспонента, источник равномерных чисел MT19937</td>\n</tr>\n<tr>\n<td>Совпадение метрик данных и генератора</td>\n<td><a href="#sprint2-cell-12">Метрики и графики</a></td>\n<td>1</td>\n<td>таблица метрик, KS, Q-Q график</td>\n</tr>\n<tr>\n<td>Автотесты</td>\n<td><a href="#sprint2-cell-27">Автотесты</a></td>\n<td>1</td>\n<td>17 тестов pytest для двух методов, модуль <code>winegen</code></td>\n</tr>\n<tr>\n<td>Второй метод (метод отношений)</td>\n<td><a href="#sprint2-cell-20">Второй метод</a></td>\n<td>1</td>\n<td>сравнение с полярным: доля принятых, скорость, KS</td>\n</tr>\n<tr>\n<td>Приведение к стандартному нормальному</td>\n<td><a href="#sprint2-cell-24">Преобразование</a></td>\n<td>1</td>\n<td><marimo-tex class="arithmatex">||(Z=\\ln((X-\\text{loc})/\\text{scale})/\\sigma||)</marimo-tex>, проверка KS</td>\n</tr>\n<tr>\n<td>Исследование алгоритмов</td>\n<td><a href="#sprint2-cell-33">Алгоритмы</a></td>\n<td>1</td>\n<td>4 алгоритма</td>\n</tr>\n<tr>\n<td>Литература</td>\n<td><a href="#sprint2-cell-35">Литература</a></td>\n<td>1</td>\n<td>книги и статьи</td>\n</tr>\n<tr>\n<td>Версирование</td>\n<td>история коммитов GitHub</td>\n<td>—</td>\n<td>подтверждается репозиторием, не самим файлом</td>\n</tr>\n</tbody>\n</table></span>', 'source': '| cat_id | notebook_link | coeff | comment |\n|--------|---------------|-------|---------|\n| Генератор и его обоснование | [Описание и код](#scrollTo=XMbGa_dyZfIH) | 1 | лог-нормальное со сдвигом: полярный метод Марсальи + экспонента, источник равномерных чисел MT19937 |\n| Совпадение метрик данных и генератора | [Метрики и графики](#scrollTo=WhR2AwbvZlGD) | 1 | таблица метрик, KS, Q-Q график |\n| Автотесты | [Автотесты](#scrollTo=UodSddUKd9zy) | 1 | 17 тестов pytest для двух методов, модуль `winegen` |\n| Второй метод (метод отношений) | [Второй метод](#scrollTo=HzZJXcPyd9zx) | 1 | сравнение с полярным: доля принятых, скорость, KS |\n| Приведение к стандартному нормальному | [Преобразование](#scrollTo=KFjiYNm7d9zx) | 1 | $Z=\\ln((X-\\text{loc})/\\text{scale})/\\sigma$, проверка KS |\n| Исследование алгоритмов | [Алгоритмы](#scrollTo=Lolg7v_dd9zy) | 1 | 4 алгоритма |\n| Литература | [Литература](#scrollTo=gFOVnAZcd9zz) | 1 | книги и статьи |\n| Версирование | история коммитов GitHub | — | подтверждается репозиторием, не самим файлом |\n'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><h2 id="sprint2-heading-39-1">Random 02 (residual sugar)</h2>\n<span class="paragraph">Генерация остаточного сахара и проверка методов (участник B).</span></span>', 'source': '## Random 02 (residual sugar)\n\nГенерация остаточного сахара и проверка методов (участник B).'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><h3 id="sprint2-heading-40-1"><span class="notebook-index">2.1</span>Description</h3></span>', 'source': '### Description'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><span class="paragraph"><strong>Что генерирую.</strong> <code>residual sugar</code> — концентрация остаточного сахара в белом вине, г/л. В исходном наборе Wine Quality содержится <strong>4898 наблюдений</strong>. Величина положительна, распределение имеет правый хвост, встречаются редкие большие значения.</span>\n<span class="paragraph"><strong>Выбор модели по спринту 1.</strong> Среди четырёх параметрических моделей минимальный AIC имеет <strong>гамма-распределение</strong> с фиксированным <code>loc=0</code>: форма <marimo-tex class="arithmatex">||(k=1.4814063452||)</marimo-tex>, масштаб <marimo-tex class="arithmatex">||(\\theta=4.3144238472||)</marimo-tex> г/л. По критерию KS более близкой оказалась логнормальная модель, поэтому гамма-распределение — только приближение, а не точная копия исходных данных.</span>\n<span class="paragraph"><strong>Основной генератор.</strong> Эмпирическое квантильное преобразование: генерирую <marimo-tex class="arithmatex">||(U\\sim U(0,1)||)</marimo-tex> и преобразую его в значение остаточного сахара по эмпирической функции распределения. Такой метод сохраняет дискретность и частоты наблюдаемых значений при многократной генерации.</span>\n<span class="paragraph"><strong>Дополнительный метод.</strong> Метод Неймана (принятие–отбрасывание) для гамма-модели; для сравнения исследую суперпозицию условных эмпирических распределений и быстрый генератор экспоненциальной величины. Источник псевдослучайных чисел во всех методах — MT19937 (<code>numpy.random.RandomState</code>).</span>\n<span class="paragraph"><strong>Применение.</strong> Синтетические данные полезны для моделирования, испытания алгоритмов и оценки статистических процедур; они не являются новыми реальными измерениями вина.</span></span>', 'source': '**Что генерирую.** `residual sugar` — концентрация остаточного сахара в белом вине, г/л. В исходном наборе Wine Quality содержится **4898 наблюдений**. Величина положительна, распределение имеет правый хвост, встречаются редкие большие значения.\n\n**Выбор модели по спринту 1.** Среди четырёх параметрических моделей минимальный AIC имеет **гамма-распределение** с фиксированным `loc=0`: форма $k=1.4814063452$, масштаб $\\theta=4.3144238472$ г/л. По критерию KS более близкой оказалась логнормальная модель, поэтому гамма-распределение — только приближение, а не точная копия исходных данных.\n\n**Основной генератор.** Эмпирическое квантильное преобразование: генерирую $U\\sim U(0,1)$ и преобразую его в значение остаточного сахара по эмпирической функции распределения. Такой метод сохраняет дискретность и частоты наблюдаемых значений при многократной генерации.\n\n**Дополнительный метод.** Метод Неймана (принятие–отбрасывание) для гамма-модели; для сравнения исследую суперпозицию условных эмпирических распределений и быстрый генератор экспоненциальной величины. Источник псевдослучайных чисел во всех методах — MT19937 (`numpy.random.RandomState`).\n\n**Применение.** Синтетические данные полезны для моделирования, испытания алгоритмов и оценки статистических процедур; они не являются новыми реальными измерениями вина.'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><h3 id="sprint2-heading-42-1"><span class="notebook-index">2.2</span>Math desc</h3></span>', 'source': '### Math desc'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><span class="paragraph"><strong>1. Источник случайности — MT19937.</strong> Вихрь Мерсенна создаёт псевдослучайные числа, которые можно преобразовать в <marimo-tex class="arithmatex">||(U\\sim U(0,1)||)</marimo-tex>. Фиксированный <code>seed</code> обеспечивает воспроизводимость. Генератор <strong>не криптографический</strong>.</span>\n<span class="paragraph"><strong>2. Эмпирическое квантильное преобразование (основной метод).</strong> Отсортируем <marimo-tex class="arithmatex">||(N||)</marimo-tex> измерений: <marimo-tex class="arithmatex">||(x_{(1)}\\le\\dots\\le x_{(N)}||)</marimo-tex>. При <marimo-tex class="arithmatex">||(U\\sim U[0,1)||)</marimo-tex> выбираем</span>\n<marimo-tex class="arithmatex">||[\nJ=\\lfloor NU\\rfloor,\\qquad X=x_{(J+1)}.\n||]</marimo-tex><span class="paragraph">При этом <marimo-tex class="arithmatex">||(P(X\\le t)=F_N(t)||)</marimo-tex>, где <marimo-tex class="arithmatex">||(F_N||)</marimo-tex> — эмпирическая функция распределения. Каждая исходная строка имеет вероятность <marimo-tex class="arithmatex">||(1/N||)</marimo-tex>; совпадающие значения сохраняют свою общую частоту. Метод <strong>не создаёт новых концентраций</strong>, а воспроизводит эмпирический закон.</span>\n<span class="paragraph"><strong>3. Гамма-распределение (параметрическая альтернатива).</strong> Для <marimo-tex class="arithmatex">||(x&gt;0||)</marimo-tex>:</span>\n<marimo-tex class="arithmatex">||[\nf(x)=\\frac{x^{k-1}e^{-x/\\theta}}{\\Gamma(k)\\theta^k},\\qquad k=1.4814063452,\\;\\theta=4.3144238472.\n||]</marimo-tex><marimo-tex class="arithmatex">||[\nE[X]=k\\theta,\\qquad \\mathrm{Var}(X)=k\\theta^2.\n||]</marimo-tex><span class="paragraph"><strong>4. Метод Неймана (acceptance–rejection).</strong> Пусть целевая плотность <marimo-tex class="arithmatex">||(f||)</marimo-tex> — гамма, а плотность предложения <marimo-tex class="arithmatex">||(g||)</marimo-tex> — экспоненциальная с масштабом <marimo-tex class="arithmatex">||(b=k\\theta||)</marimo-tex>. Если <marimo-tex class="arithmatex">||(f(x)\\le Mg(x)||)</marimo-tex>, то для <marimo-tex class="arithmatex">||(Y\\sim g||)</marimo-tex> и <marimo-tex class="arithmatex">||(V\\sim U(0,1)||)</marimo-tex> принимаем <marimo-tex class="arithmatex">||(Y||)</marimo-tex> при</span>\n<marimo-tex class="arithmatex">||[\nV\\le\\frac{f(Y)}{Mg(Y)}.\n||]</marimo-tex><span class="paragraph">Для <marimo-tex class="arithmatex">||(k&gt;1||)</marimo-tex> выбор <marimo-tex class="arithmatex">||(b=k\\theta||)</marimo-tex> обеспечивает ограниченность отношения <marimo-tex class="arithmatex">||(f/g||)</marimo-tex>. Его максимум достигается в точке <marimo-tex class="arithmatex">||(x_*=k\\theta||)</marimo-tex>; <marimo-tex class="arithmatex">||(M=f(x_*)/g(x_*)||)</marimo-tex>. Для устойчивости сравнение вычисляется через логарифмы плотностей. Принимаемые числа имеют распределение Gamma<marimo-tex class="arithmatex">||((k,\\theta)||)</marimo-tex>. Доля принятых предложений стремится к <marimo-tex class="arithmatex">||(1/M||)</marimo-tex>.</span>\n<span class="paragraph"><strong>5. Суперпозиция.</strong> Эмпирическую выборку делим по отсортированным индексам на четыре части <marimo-tex class="arithmatex">||(A_1,\\ldots,A_4||)</marimo-tex>. Пусть <marimo-tex class="arithmatex">||(w_j=|A_j|/N||)</marimo-tex>. Сначала выбираем компоненту <marimo-tex class="arithmatex">||(C||)</marimo-tex> с вероятностями <marimo-tex class="arithmatex">||(w_j||)</marimo-tex>, затем равномерно выбираем одно наблюдение из <marimo-tex class="arithmatex">||(A_C||)</marimo-tex>:</span>\n<marimo-tex class="arithmatex">||[\nP(X\\le x)=\\sum_{j=1}^4 w_jF_j(x)=F_N(x).\n||]</marimo-tex><span class="paragraph">Это <strong>точная смесь условных эмпирических распределений</strong>: её результат совпадает с основным методом в распределении, но не обязательно поэлементно. Разбиение на четыре компоненты демонстрирует алгоритм суперпозиции, а не четыре физические категории вина.</span>\n<span class="paragraph"><strong>6. Быстрая экспонента.</strong> Если <marimo-tex class="arithmatex">||(U\\sim U(0,1)||)</marimo-tex>, то <marimo-tex class="arithmatex">||(E=-b\\ln U||)</marimo-tex> имеет экспоненциальное распределение с масштабом <marimo-tex class="arithmatex">||(b||)</marimo-tex>: <marimo-tex class="arithmatex">||(F_E(x)=1-e^{-x/b}||)</marimo-tex>. В коде используется векторная реализация без вызова <code>scipy.stats.expon.rvs</code>. Это отдельный алгоритм, а также <strong>распределение предложений для метода Неймана</strong>, но не точная модель сахара.</span>\n<span class="paragraph"><strong>7. Проверка.</strong> Сравниваем среднее, стандартное отклонение, медиану, квантили, асимметрию, эксцесс, KS-статистику и графики. Для эмпирической модели важнее расстояние до исходной выборки, а для метода Неймана — соответствие гамма-модели. KS p-value при сравнении с исходными округлёнными данными используем осторожно: есть повторяющиеся наблюдения и подгонка параметров.</span></span>', 'source': '**1. Источник случайности — MT19937.** Вихрь Мерсенна создаёт псевдослучайные числа, которые можно преобразовать в $U\\sim U(0,1)$. Фиксированный `seed` обеспечивает воспроизводимость. Генератор **не криптографический**.\n\n**2. Эмпирическое квантильное преобразование (основной метод).** Отсортируем $N$ измерений: $x_{(1)}\\le\\dots\\le x_{(N)}$. При $U\\sim U[0,1)$ выбираем\n\n$$J=\\lfloor NU\\rfloor,\\qquad X=x_{(J+1)}.$$\n\nПри этом $P(X\\le t)=F_N(t)$, где $F_N$ — эмпирическая функция распределения. Каждая исходная строка имеет вероятность $1/N$; совпадающие значения сохраняют свою общую частоту. Метод **не создаёт новых концентраций**, а воспроизводит эмпирический закон.\n\n**3. Гамма-распределение (параметрическая альтернатива).** Для $x>0$:\n\n$$f(x)=\\frac{x^{k-1}e^{-x/\\theta}}{\\Gamma(k)\\theta^k},\\qquad k=1.4814063452,\\;\\theta=4.3144238472.$$\n\n$$E[X]=k\\theta,\\qquad \\mathrm{Var}(X)=k\\theta^2.$$\n\n**4. Метод Неймана (acceptance–rejection).** Пусть целевая плотность $f$ — гамма, а плотность предложения $g$ — экспоненциальная с масштабом $b=k\\theta$. Если $f(x)\\le Mg(x)$, то для $Y\\sim g$ и $V\\sim U(0,1)$ принимаем $Y$ при\n\n$$V\\le\\frac{f(Y)}{Mg(Y)}.$$\n\nДля $k>1$ выбор $b=k\\theta$ обеспечивает ограниченность отношения $f/g$. Его максимум достигается в точке $x_*=k\\theta$; $M=f(x_*)/g(x_*)$. Для устойчивости сравнение вычисляется через логарифмы плотностей. Принимаемые числа имеют распределение Gamma$(k,\\theta)$. Доля принятых предложений стремится к $1/M$.\n\n**5. Суперпозиция.** Эмпирическую выборку делим по отсортированным индексам на четыре части $A_1,\\ldots,A_4$. Пусть $w_j=|A_j|/N$. Сначала выбираем компоненту $C$ с вероятностями $w_j$, затем равномерно выбираем одно наблюдение из $A_C$:\n\n$$P(X\\le x)=\\sum_{j=1}^4 w_jF_j(x)=F_N(x).$$\n\nЭто **точная смесь условных эмпирических распределений**: её результат совпадает с основным методом в распределении, но не обязательно поэлементно. Разбиение на четыре компоненты демонстрирует алгоритм суперпозиции, а не четыре физические категории вина.\n\n**6. Быстрая экспонента.** Если $U\\sim U(0,1)$, то $E=-b\\ln U$ имеет экспоненциальное распределение с масштабом $b$: $F_E(x)=1-e^{-x/b}$. В коде используется векторная реализация без вызова `scipy.stats.expon.rvs`. Это отдельный алгоритм, а также **распределение предложений для метода Неймана**, но не точная модель сахара.\n\n**7. Проверка.** Сравниваем среднее, стандартное отклонение, медиану, квантили, асимметрию, эксцесс, KS-статистику и графики. Для эмпирической модели важнее расстояние до исходной выборки, а для метода Неймана — соответствие гамма-модели. KS p-value при сравнении с исходными округлёнными данными используем осторожно: есть повторяющиеся наблюдения и подгонка параметров.'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><h3 id="sprint2-heading-44-1"><span class="notebook-index">2.3</span>Code</h3></span>', 'source': '### Code'}, {'kind': 'code', 'html': '', 'source': '!mkdir -p winegen tests'}, {'kind': 'code', 'html': '<pre class="numeric-result">Пакет winegen готов; файлы участника A не изменены\n</pre>', 'source': 'from pathlib import Path\nPath("winegen").mkdir(exist_ok=True)\nPath("winegen/__init__.py").touch(exist_ok=True)\nprint("Пакет winegen готов; файлы участника A не изменены")'}, {'kind': 'code', 'html': '<pre class="numeric-result">Overwriting winegen/sugar.py\n</pre>', 'source': '%%writefile winegen/sugar.py\n"""Генераторы residual sugar (MT19937, без готовых .rvs распределений)."""\nimport numpy as np\nfrom scipy import stats\n\nSUGAR_SHAPE = 1.4814063452349577\nSUGAR_LOC = 0.0\nSUGAR_SCALE = 4.314423847155702\n\n\ndef _validate_n(n):\n    if isinstance(n, (bool, np.bool_)) or not isinstance(n, (int, np.integer)):\n        raise TypeError("n должно быть целым числом")\n    if n < 0:\n        raise ValueError("n должно быть неотрицательным")\n    return int(n)\n\n\ndef _reference(data):\n    values = np.asarray(data, dtype=float).ravel()\n    if values.size == 0 or not np.isfinite(values).all() or (values <= 0).any():\n        raise ValueError("Данные должны быть непустыми, конечными и положительными")\n    return values\n\n\ndef empirical_inverse(n, data, rng):\n    """Обратная эмпирическая CDF, без сглаживания и интерполяции."""\n    n = _validate_n(n)\n    x = np.sort(_reference(data))\n    if n == 0:\n        return np.empty(0, dtype=float)\n    indices = np.floor(rng.random_sample(n) * len(x)).astype(int)\n    return x[indices]\n\n\ndef fast_exponential(n, scale, rng):\n    """Векторное обратное преобразование для Exp(scale)."""\n    n = _validate_n(n)\n    if not np.isfinite(scale) or scale <= 0:\n        raise ValueError("scale должно быть положительным")\n    if n == 0:\n        return np.empty(0, dtype=float)\n    u = rng.random_sample(n)\n    # 1-u принадлежит (0,1]; log1p обеспечивает точность при малом u.\n    return -float(scale) * np.log1p(-u)\n\n\ndef gamma_envelope(shape=SUGAR_SHAPE, scale=SUGAR_SCALE):\n    """Параметры экспоненциального предложения и точная константа M."""\n    if shape <= 1 or scale <= 0:\n        raise ValueError("Для экспоненциальной оболочки требуется shape > 1 и scale > 0")\n    proposal_scale = shape * scale\n    xstar = proposal_scale\n    logm = stats.gamma.logpdf(xstar, shape, loc=0, scale=scale) - \\\n           stats.expon.logpdf(xstar, scale=proposal_scale)\n    return proposal_scale, float(logm)\n\n\ndef neumann_gamma(n, rng, shape=SUGAR_SHAPE, scale=SUGAR_SCALE,\n                  return_stats=False):\n    """Gamma(shape, scale) методом Неймана с Exp(shape*scale) как g(x)."""\n    n = _validate_n(n)\n    proposal_scale, logm = gamma_envelope(shape, scale)\n    if n == 0:\n        empty = np.empty(0, dtype=float)\n        return (empty, 0, 0) if return_stats else empty\n    batches, got, tried, accepted = [], 0, 0, 0\n    while got < n:\n        # Выбираем с запасом и учитываем ВСЕ предложения в статистике принятия.\n        m = max(256, int(np.ceil((n - got) * np.exp(logm) * 1.12)))\n        y = fast_exponential(m, proposal_scale, rng)\n        u = rng.random_sample(m)\n        logf = stats.gamma.logpdf(y, shape, loc=0, scale=scale)\n        logg = stats.expon.logpdf(y, scale=proposal_scale)\n        keep = np.log(np.maximum(u, np.finfo(float).tiny)) <= logf - logg - logm\n        accepted_values = y[keep]\n        batches.append(accepted_values)\n        accepted += int(keep.sum())\n        tried += m\n        got += len(accepted_values)\n    result = np.concatenate(batches)[:n]\n    return (result, accepted, tried) if return_stats else result\n\n\ndef superposition_empirical(n, data, rng, components=4):\n    """Смесь 4 непересекающихся эмпирических частей, веса |A_j|/N."""\n    n = _validate_n(n)\n    if not isinstance(components, (int, np.integer)) or components < 1:\n        raise ValueError("components должно быть положительным целым")\n    values = np.sort(_reference(data))\n    if components > len(values):\n        raise ValueError("components не может превышать число наблюдений")\n    if n == 0:\n        return np.empty(0, dtype=float)\n    blocks = np.array_split(values, int(components))\n    weights = np.array([len(b) for b in blocks], dtype=float) / len(values)\n    chosen = rng.choice(len(blocks), size=n, p=weights)\n    result = np.empty(n, dtype=float)\n    for j, block in enumerate(blocks):\n        positions = np.flatnonzero(chosen == j)\n        if len(positions):\n            indices = np.floor(rng.random_sample(len(positions)) * len(block)).astype(int)\n            result[positions] = block[indices]\n    return result\n\n\ndef sugar_generator(n, data=None, seed=42, method="inverse"):\n    """inverse/superposition требуют данные; neumann использует гамма-параметры."""\n    n = _validate_n(n)\n    rng = np.random.RandomState(seed)\n    if method == "inverse":\n        if data is None:\n            raise ValueError("Для inverse нужны исходные значения residual sugar")\n        return empirical_inverse(n, data, rng)\n    if method == "superposition":\n        if data is None:\n            raise ValueError("Для superposition нужны исходные значения residual sugar")\n        return superposition_empirical(n, data, rng)\n    if method == "neumann":\n        return neumann_gamma(n, rng)\n    raise ValueError("method: \'inverse\', \'superposition\' или \'neumann\'")'}, {'kind': 'code', 'html': '<pre class="numeric-result">Данные: n=4898, среднее=6.3914 г/л, std=5.0721 г/л\n</pre>', 'source': 'import numpy as np\nimport pandas as pd\nimport matplotlib.pyplot as plt\nfrom scipy import stats\n\nfrom winegen.sugar import (\n    sugar_generator, empirical_inverse, superposition_empirical,\n    neumann_gamma, fast_exponential, gamma_envelope,\n    SUGAR_SHAPE, SUGAR_LOC, SUGAR_SCALE\n)\n\nCOLOR = "#6389B8"\nplt.rcParams["axes.prop_cycle"] = plt.cycler(color=[COLOR, "#F3A712", "#E4572E", "#76B391"])\nplt.rcParams["axes.grid"] = True\nplt.rcParams["grid.alpha"] = 0.3\n\n# Исходные данные UCI Wine Quality, белые вина.\n# Если pH уже загрузил df, используем его, не скачивая таблицу второй раз.\nfrom pathlib import Path\nurl = "https://archive.ics.uci.edu/ml/machine-learning-databases/wine-quality/winequality-white.csv"\nif "df" not in globals() or not isinstance(df, pd.DataFrame) or "residual sugar" not in df.columns:\n    local_csv = Path("winequality-white.csv")\n    try:\n        df = pd.read_csv(local_csv if local_csv.exists() else url, sep=";")\n    except Exception as exc:\n        raise RuntimeError("Не удалось загрузить CSV UCI. Проверьте доступ к интернету в Colab.") from exc\nsugar = df["residual sugar"].dropna().to_numpy(dtype=float)\nassert len(sugar) == 4898, "Ожидается исходный датасет из 4898 наблюдений"\nprint(f"Данные: n={len(sugar)}, среднее={sugar.mean():.4f} г/л, std={sugar.std(ddof=1):.4f} г/л")'}, {'kind': 'code', 'html': '<pre class="numeric-result">Первые пять значений, эмпирический: [ 2.8 15.7  9.3  7.   1.4]\nПервые пять значений, Нейман: [2.999 8.416 5.835 1.084 0.382]\nЭмпирический: min / max = 0.6 65.8\nНейман: min / max = 0.003 56.647\n</pre>', 'source': 'N = 100_000\nsugar_emp = sugar_generator(N, data=sugar, seed=42, method="inverse")\nsugar_gamma = sugar_generator(N, seed=42, method="neumann")\ntheory = stats.gamma(SUGAR_SHAPE, loc=SUGAR_LOC, scale=SUGAR_SCALE)\nprint("Первые пять значений, эмпирический:", sugar_emp[:5])\nprint("Первые пять значений, Нейман:", np.round(sugar_gamma[:5], 3))\nprint("Эмпирический: min / max =", sugar_emp.min(), sugar_emp.max())\nprint("Нейман: min / max =", round(sugar_gamma.min(), 3), round(sugar_gamma.max(), 3))'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><h3 id="sprint2-heading-50-1"><span class="notebook-index">2.4</span>Tests</h3></span>', 'source': '### Tests'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><h4 id="sprint2-heading-51-1"><span class="notebook-index">2.4.1</span>Основной метод: эмпирическое квантильное преобразование (2 графика)</h4></span>', 'source': '#### Основной метод: эмпирическое квантильное преобразование (2 графика)'}, {'kind': 'code', 'html': '<figure class="plot plot-wide"><img width="1205" height="473" decoding="async" data-report-asset="./public/reports/sprint2/52-0.png" src="data:image/png;base64," alt="График исследования" /></figure><pre class="numeric-result">Количество уникальных значений: исходные = 310 , генератор = 310\nВсе значения генератора присутствуют в исходных: True\nKS D (генератор vs данные): 0.00187\n</pre>', 'source': '# KS для эмпирических дискретных значений используется как расстояние D;\n# обычный непрерывный KS p-value здесь не интерпретируется.\nprint("Количество уникальных значений: исходные =", np.unique(sugar).size,\n      ", генератор =", np.unique(sugar_emp).size)\nprint("Все значения генератора присутствуют в исходных:", np.isin(sugar_emp, sugar).all())\nprint("KS D (генератор vs данные):", round(stats.ks_2samp(sugar_emp, sugar).statistic, 5))\n\nfig, axes = plt.subplots(1, 2, figsize=(13, 4.5))\naxes[0].hist(sugar, bins=45, density=True, alpha=.55, label="Данные", color=COLOR)\naxes[0].hist(sugar_emp, bins=45, density=True, alpha=.42, label="Эмпирический генератор", color="#F3A712")\naxes[0].set(xlabel="Остаточный сахар, г/л", ylabel="Плотность", title="Распределение исходных и сгенерированных данных")\naxes[0].legend()\nq = np.linspace(.005, .995, 150)\naxes[1].scatter(np.quantile(sugar, q), np.quantile(sugar_emp, q), s=11, alpha=.8)\nm = max(sugar.max(), sugar_emp.max())\naxes[1].plot([0,m],[0,m], linestyle="--", color="#E4572E", label="y = x")\naxes[1].set(xlabel="Квантили исходных данных, г/л", ylabel="Квантили генератора, г/л", title="Q-Q: генератор против данных")\naxes[1].legend()\nplt.tight_layout(); plt.show()'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><span class="paragraph"><strong>Вывод.</strong> Основной метод воспроизводит <strong>эмпирическое распределение</strong>, включая повторяющиеся измерения и правый хвост. Сгенерированные числа принадлежат набору исходных значений; небольшой KS D связан со случайной погрешностью конечной выборки. Этот способ не делает распределение гладким и не выдаёт новых концентраций между измеренными.</span></span>', 'source': '**Вывод.** Основной метод воспроизводит **эмпирическое распределение**, включая повторяющиеся измерения и правый хвост. Сгенерированные числа принадлежат набору исходных значений; небольшой KS D связан со случайной погрешностью конечной выборки. Этот способ не делает распределение гладким и не выдаёт новых концентраций между измеренными.'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><h4 id="sprint2-heading-54-1"><span class="notebook-index">2.4.2</span>Генератор против теории и исходных данных (2 графика)</h4></span>', 'source': '#### Генератор против теории и исходных данных (2 графика)'}, {'kind': 'code', 'html': '<div class="tbl-wrap"><div>\n<style scoped>\n    .dataframe tbody tr th:only-of-type {\n        vertical-align: middle;\n    }\n\n    .dataframe tbody tr th {\n        vertical-align: top;\n    }\n\n    .dataframe thead th {\n        text-align: right;\n    }\n</style>\n<table border="1" class="dataframe">\n  <thead>\n    <tr style="text-align: right;">\n      <th></th>\n      <th>данные</th>\n      <th>эмпирический</th>\n      <th>Нейман (гамма)</th>\n      <th>теория гамма</th>\n    </tr>\n  </thead>\n  <tbody>\n    <tr>\n      <th>среднее</th>\n      <td>6.3914</td>\n      <td>6.3778</td>\n      <td>6.3923</td>\n      <td>6.3914</td>\n    </tr>\n    <tr>\n      <th>std</th>\n      <td>5.0721</td>\n      <td>5.0539</td>\n      <td>5.2330</td>\n      <td>5.2512</td>\n    </tr>\n    <tr>\n      <th>медиана</th>\n      <td>5.2000</td>\n      <td>5.2000</td>\n      <td>5.0412</td>\n      <td>5.0247</td>\n    </tr>\n    <tr>\n      <th>асимметрия</th>\n      <td>1.0771</td>\n      <td>1.0720</td>\n      <td>1.6297</td>\n      <td>1.6432</td>\n    </tr>\n    <tr>\n      <th>эксцесс</th>\n      <td>3.4698</td>\n      <td>3.4478</td>\n      <td>3.9645</td>\n      <td>4.0502</td>\n    </tr>\n    <tr>\n      <th>квантиль 5%</th>\n      <td>1.1000</td>\n      <td>1.1000</td>\n      <td>0.7270</td>\n      <td>0.7342</td>\n    </tr>\n    <tr>\n      <th>квантиль 25%</th>\n      <td>1.7000</td>\n      <td>1.7000</td>\n      <td>2.5604</td>\n      <td>2.5611</td>\n    </tr>\n    <tr>\n      <th>квантиль 75%</th>\n      <td>9.9000</td>\n      <td>9.9000</td>\n      <td>8.7692</td>\n      <td>8.7581</td>\n    </tr>\n    <tr>\n      <th>квантиль 95%</th>\n      <td>15.7000</td>\n      <td>15.6000</td>\n      <td>16.6563</td>\n      <td>16.7187</td>\n    </tr>\n  </tbody>\n</table>\n</div></div><pre class="numeric-result">KS D: эмпирический vs данные = 0.00187\nKS D: Нейман vs гамма-теория = 0.00278\nKS p-value: Нейман vs гамма-теория = 0.42059\nKS D: Нейман vs данные = 0.1197\n</pre>', 'source': 'def metrics(values):\n    x = pd.Series(np.asarray(values, dtype=float))\n    return {"среднее": x.mean(), "std": x.std(), "медиана": x.median(),\n            "асимметрия": x.skew(), "эксцесс": x.kurt(),\n            "квантиль 5%": x.quantile(.05), "квантиль 25%": x.quantile(.25),\n            "квантиль 75%": x.quantile(.75), "квантиль 95%": x.quantile(.95)}\n\nm, v, sk, ku = theory.stats(moments="mvsk")\ntheory_row = {"среднее": float(m), "std": float(np.sqrt(v)),\n              "медиана": float(theory.median()), "асимметрия": float(sk), "эксцесс": float(ku),\n              "квантиль 5%": float(theory.ppf(.05)), "квантиль 25%": float(theory.ppf(.25)),\n              "квантиль 75%": float(theory.ppf(.75)), "квантиль 95%": float(theory.ppf(.95))}\ncomparison = pd.DataFrame({"данные": metrics(sugar), "эмпирический": metrics(sugar_emp),\n                           "Нейман (гамма)": metrics(sugar_gamma), "теория гамма": theory_row})\ndisplay(comparison.round(4))\nprint("KS D: эмпирический vs данные =", round(stats.ks_2samp(sugar_emp, sugar).statistic, 5))\nprint("KS D: Нейман vs гамма-теория =", round(stats.kstest(sugar_gamma, theory.cdf).statistic, 5))\nprint("KS p-value: Нейман vs гамма-теория =", round(stats.kstest(sugar_gamma, theory.cdf).pvalue, 5))\nprint("KS D: Нейман vs данные =", round(stats.ks_2samp(sugar_gamma, sugar).statistic, 5))'}, {'kind': 'code', 'html': '<figure class="plot plot-wide"><img width="1205" height="473" decoding="async" data-report-asset="./public/reports/sprint2/56-0.png" src="data:image/png;base64," alt="График исследования" /></figure>', 'source': 'fig, axes = plt.subplots(1, 2, figsize=(13, 4.5))\naxes[0].hist(sugar, bins=45, density=True, alpha=.45, label="Данные", color=COLOR)\naxes[0].hist(sugar_gamma, bins=45, density=True, alpha=.35, label="Нейман", color="#F3A712")\ngrid = np.linspace(0, min(max(sugar.max(), sugar_gamma.max()), 75), 450)\naxes[0].plot(grid, theory.pdf(grid), color="#E4572E", lw=2, label="Гамма-теория")\naxes[0].set(xlabel="Остаточный сахар, г/л", ylabel="Плотность", title="Плотности: данные, гамма и генератор")\naxes[0].legend()\nq = np.linspace(.005, .995, 150)\naxes[1].scatter(theory.ppf(q), np.quantile(sugar_gamma, q), s=12, label="Нейман")\nlim = max(theory.ppf(.995), np.quantile(sugar_gamma, .995))\naxes[1].plot([0, lim], [0, lim], "--", color="#E4572E", label="y = x")\naxes[1].set(xlabel="Теоретические гамма-квантили, г/л", ylabel="Квантили генератора, г/л", title="Q-Q: Нейман против гамма-теории")\naxes[1].legend(); plt.tight_layout(); plt.show()'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><span class="paragraph"><strong>Вывод.</strong> Метод Неймана генерирует значения, близкие к <strong>гамма-теории</strong> по моментам, квантилям и KS D. Если расхождение с исходными данными больше, чем у эмпирического метода, причина прежде всего в самой приближённой гамма-модели: она сглаживает повторения и локальные пики наблюдений.</span></span>', 'source': '**Вывод.** Метод Неймана генерирует значения, близкие к **гамма-теории** по моментам, квантилям и KS D. Если расхождение с исходными данными больше, чем у эмпирического метода, причина прежде всего в самой приближённой гамма-модели: она сглаживает повторения и локальные пики наблюдений.'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><h4 id="sprint2-heading-58-1"><span class="notebook-index">2.4.3</span>Второй метод: метод Неймана для гамма-распределения (числовая проверка)</h4></span>', 'source': '#### Второй метод: метод Неймана для гамма-распределения (числовая проверка)'}, {'kind': 'code', 'html': '<pre class="numeric-result">Предложение: Exp(scale=6.3914 г/л)\nОграничивающая константа M = 1.24866\nДоля принятых предложений: 0.7994\nТеоретическая доля принятия: 0.8009\nСреднее: 6.3923 (теория 6.3914)\nStd: 5.2330 (теория 5.2512)\nKS относительно гамма-теории: KstestResult(statistic=np.float64(0.0027818770202320264), pvalue=np.float64(0.4205933974413092), statistic_location=np.float64(3.801100129432304), statistic_sign=np.int8(-1))\n</pre>', 'source': 'proposal_scale, log_m = gamma_envelope()\nrng = np.random.RandomState(42)\nsample_neumann, n_accepted, n_tried = neumann_gamma(N, rng, return_stats=True)\nprint(f"Предложение: Exp(scale={proposal_scale:.4f} г/л)")\nprint(f"Ограничивающая константа M = {np.exp(log_m):.5f}")\nprint(f"Доля принятых предложений: {n_accepted/n_tried:.4f}")\nprint(f"Теоретическая доля принятия: {np.exp(-log_m):.4f}")\nprint(f"Среднее: {sample_neumann.mean():.4f} (теория {theory.mean():.4f})")\nprint(f"Std: {sample_neumann.std(ddof=1):.4f} (теория {theory.std():.4f})")\nprint("KS относительно гамма-теории:", stats.kstest(sample_neumann, theory.cdf))\n'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><span class="paragraph"><strong>Вывод.</strong> Метод Неймана использует экспоненциальные кандидаты и принимает их с вероятностью <marimo-tex class="arithmatex">||(f/(Mg)||)</marimo-tex>. Экспериментальная доля принятия должна быть близка к <marimo-tex class="arithmatex">||(1/M||)</marimo-tex>, а сгенерированное распределение — к гамма-модели. Часть предложений отбрасывается; в этом основная вычислительная цена метода.</span></span>', 'source': '**Вывод.** Метод Неймана использует экспоненциальные кандидаты и принимает их с вероятностью $f/(Mg)$. Экспериментальная доля принятия должна быть близка к $1/M$, а сгенерированное распределение — к гамма-модели. Часть предложений отбрасывается; в этом основная вычислительная цена метода.'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><h4 id="sprint2-heading-61-1"><span class="notebook-index">2.4.4</span>Сравнение четырёх алгоритмов (таблица скорости и точности)</h4></span>', 'source': '#### Сравнение четырёх алгоритмов (таблица скорости и точности)'}, {'kind': 'code', 'html': '<div class="tbl-wrap"><div>\n<style scoped>\n    .dataframe tbody tr th:only-of-type {\n        vertical-align: middle;\n    }\n\n    .dataframe tbody tr th {\n        vertical-align: top;\n    }\n\n    .dataframe thead th {\n        text-align: right;\n    }\n</style>\n<table border="1" class="dataframe">\n  <thead>\n    <tr style="text-align: right;">\n      <th></th>\n      <th>алгоритм</th>\n      <th>время, с (медиана 3)</th>\n      <th>среднее</th>\n      <th>std</th>\n      <th>KS D к своей цели</th>\n    </tr>\n  </thead>\n  <tbody>\n    <tr>\n      <th>0</th>\n      <td>обратная эмпирическая CDF</td>\n      <td>0.00055</td>\n      <td>6.37779</td>\n      <td>5.05387</td>\n      <td>0.00187</td>\n    </tr>\n    <tr>\n      <th>1</th>\n      <td>Нейман → гамма</td>\n      <td>0.00480</td>\n      <td>6.39233</td>\n      <td>5.23304</td>\n      <td>0.00278</td>\n    </tr>\n    <tr>\n      <th>2</th>\n      <td>суперпозиция (4 части)</td>\n      <td>0.00210</td>\n      <td>6.40060</td>\n      <td>5.08745</td>\n      <td>0.00211</td>\n    </tr>\n    <tr>\n      <th>3</th>\n      <td>быстрая экспонента</td>\n      <td>0.00049</td>\n      <td>6.36566</td>\n      <td>6.34651</td>\n      <td>0.00197</td>\n    </tr>\n  </tbody>\n</table>\n</div></div><pre class="numeric-result">KS D вычислен относительно своей целевой модели для каждого метода.\n</pre>', 'source': 'import time\nn_bench = 100_000\nrows = []\ndef measure(name, fn, reference, cdf=None):\n    elapsed = []\n    result = None\n    for _ in range(3):\n        t0 = time.perf_counter()\n        result = fn()\n        elapsed.append(time.perf_counter() - t0)\n    ks_d = stats.ks_2samp(result, reference).statistic if cdf is None else stats.kstest(result, cdf).statistic\n    rows.append({"алгоритм": name, "время, с (медиана 3)": np.median(elapsed),\n                 "среднее": result.mean(), "std": result.std(ddof=1),\n                 "KS D к своей цели": ks_d})\n\nmeasure("обратная эмпирическая CDF", lambda: sugar_generator(n_bench, sugar, 42, "inverse"), sugar)\nmeasure("Нейман → гамма", lambda: sugar_generator(n_bench, seed=42, method="neumann"), sugar, theory.cdf)\nmeasure("суперпозиция (4 части)", lambda: sugar_generator(n_bench, sugar, 42, "superposition"), sugar)\nexp_scale = SUGAR_SHAPE * SUGAR_SCALE\nmeasure("быстрая экспонента", lambda: fast_exponential(n_bench, exp_scale, np.random.RandomState(42)),\n        sugar, stats.expon(scale=exp_scale).cdf)\nbench = pd.DataFrame(rows)\ndisplay(bench.round(5))\n\nprint("KS D вычислен относительно своей целевой модели для каждого метода.")'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><span class="paragraph"><strong>Вывод по четырём алгоритмам.</strong> Обратное квантильное преобразование и суперпозиция предназначены для <strong>исходного эмпирического закона</strong>; метод Неймана — для <strong>гладкой гамма-модели</strong>; быстрая экспонента — для <strong>экспоненциального закона</strong> и получения кандидатов Неймана. Поэтому сравнивать их KS D напрямую как будто они моделируют одно распределение неправильно. Время зависит от среды выполнения и размера выборки; таблица вычисляет его заново при каждом запуске.</span></span>', 'source': '**Вывод по четырём алгоритмам.** Обратное квантильное преобразование и суперпозиция предназначены для **исходного эмпирического закона**; метод Неймана — для **гладкой гамма-модели**; быстрая экспонента — для **экспоненциального закона** и получения кандидатов Неймана. Поэтому сравнивать их KS D напрямую как будто они моделируют одно распределение неправильно. Время зависит от среды выполнения и размера выборки; таблица вычисляет его заново при каждом запуске.'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><h4 id="sprint2-heading-64-1"><span class="notebook-index">2.4.5</span>Обратное преобразование и проверка равномерности (числовые результаты)</h4></span>', 'source': '#### Обратное преобразование и проверка равномерности (числовые результаты)'}, {'kind': 'code', 'html': '<pre class="numeric-result">Исходный сахар -&gt; randomized PIT:\nсреднее U: 0.4999 std U: 0.2889\nKS D к U(0,1) (описательная статистика): 0.00283\nОбратное преобразование совпало с исходными значениями: True\n</pre>', 'source': '# Для дискретной эмпирической функции нужна рандомизация внутри скачка:\n# U = F_N(X-) + V*(F_N(X)-F_N(X-)), V~U(0,1).\nunique, counts = np.unique(sugar, return_counts=True)\ncum = np.cumsum(counts)\nleft = (cum - counts) / len(sugar)\nright = cum / len(sugar)\nrng = np.random.RandomState(123)\npositions = np.searchsorted(unique, sugar, side="left")\nu_pit = left[positions] + rng.random_sample(len(sugar)) * (right[positions] - left[positions])\nprint("Исходный сахар -> randomized PIT:")\nprint("среднее U:", round(u_pit.mean(), 4), "std U:", round(u_pit.std(ddof=1), 4))\nprint("KS D к U(0,1) (описательная статистика):", round(stats.kstest(u_pit, "uniform").statistic, 5))\n\n# Обратный переход: через сортировку исходной выборки.\nrecovered = np.sort(sugar)[np.floor(np.minimum(u_pit, np.nextafter(1, 0)) * len(sugar)).astype(int)]\nprint("Обратное преобразование совпало с исходными значениями:", np.array_equal(recovered, sugar))\n'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><span class="paragraph"><strong>Вывод.</strong> Для эмпирического распределения обычное преобразование <marimo-tex class="arithmatex">||(F_N(X)||)</marimo-tex> не является непрерывно равномерным из-за повторяющихся значений. <strong>Рандомизированное квантильное преобразование</strong> распределяет значения внутри скачков <marimo-tex class="arithmatex">||(F_N||)</marimo-tex> и в данной выборке даёт значения, близкие к <marimo-tex class="arithmatex">||(U(0,1)||)</marimo-tex>. Обычный KS p-value для преобразованных исходных наблюдений не используем как формальный тест, поскольку преобразование опирается на ту же выборку. Обратный переход возвращает исходные наблюдения без потери точности.</span></span>', 'source': '**Вывод.** Для эмпирического распределения обычное преобразование $F_N(X)$ не является непрерывно равномерным из-за повторяющихся значений. **Рандомизированное квантильное преобразование** распределяет значения внутри скачков $F_N$ и в данной выборке даёт значения, близкие к $U(0,1)$. Обычный KS p-value для преобразованных исходных наблюдений не используем как формальный тест, поскольку преобразование опирается на ту же выборку. Обратный переход возвращает исходные наблюдения без потери точности.'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><h4 id="sprint2-heading-67-1"><span class="notebook-index">2.4.6</span>Автотесты</h4></span>', 'source': '#### Автотесты'}, {'kind': 'code', 'html': '<pre class="numeric-result">Overwriting tests/test_sugar.py\n</pre>', 'source': '%%writefile tests/test_sugar.py\nimport numpy as np\nimport pytest\nfrom scipy import stats\nfrom winegen.sugar import (\n    sugar_generator, fast_exponential, neumann_gamma, empirical_inverse,\n    superposition_empirical, gamma_envelope, SUGAR_SHAPE, SUGAR_SCALE\n)\n\nDATA = np.array([1.0, 1.0, 2.0, 3.5, 5.5, 6.0, 9.2, 12.0])\n\n@pytest.mark.parametrize("method", ["inverse", "superposition", "neumann"])\ndef test_length(method):\n    assert len(sugar_generator(1000, DATA, 42, method)) == 1000\n\n@pytest.mark.parametrize("method", ["inverse", "superposition", "neumann"])\ndef test_zero_and_negative(method):\n    assert len(sugar_generator(0, DATA, method=method)) == 0\n    with pytest.raises(ValueError):\n        sugar_generator(-1, DATA, method=method)\n\n@pytest.mark.parametrize("method", ["inverse", "superposition", "neumann"])\ndef test_seed(method):\n    a = sugar_generator(300, DATA, 17, method)\n    b = sugar_generator(300, DATA, 17, method)\n    assert np.array_equal(a, b)\n\ndef test_seed_changes_result():\n    assert not np.array_equal(sugar_generator(1000, DATA, 1), sugar_generator(1000, DATA, 2))\n\ndef test_unknown_method():\n    with pytest.raises(ValueError):\n        sugar_generator(10, DATA, method="unknown")\n\n@pytest.mark.parametrize("method", ["inverse", "superposition"])\ndef test_empirical_support(method):\n    x = sugar_generator(10_000, DATA, method=method)\n    assert np.isin(x, DATA).all()\n    assert stats.ks_2samp(x, DATA).statistic < .03\n\n@pytest.mark.parametrize("method", ["inverse", "superposition"])\ndef test_empirical_proportions(method):\n    x = sugar_generator(40_000, DATA, method=method)\n    assert abs(np.mean(x == 1.0) - .25) < .015\n\n@pytest.mark.parametrize("method", ["inverse", "superposition"])\ndef test_empirical_needs_data(method):\n    with pytest.raises(ValueError):\n        sugar_generator(10, method=method)\n\n@pytest.mark.parametrize("bad", [[], [1, -1], [1, np.nan]])\ndef test_invalid_data(bad):\n    with pytest.raises(ValueError):\n        sugar_generator(10, bad)\n\ndef test_gamma_envelope():\n    b, logm = gamma_envelope()\n    assert b > 0 and logm >= 0\n    x = np.linspace(.001, 70, 5000)\n    diff = stats.gamma.logpdf(x, SUGAR_SHAPE, scale=SUGAR_SCALE) - \\\n           stats.expon.logpdf(x, scale=b)\n    assert np.max(diff) <= logm + 1e-9\n\ndef test_neumann_gamma_moments():\n    sample = sugar_generator(70_000, seed=42, method="neumann")\n    theory = stats.gamma(SUGAR_SHAPE, scale=SUGAR_SCALE)\n    assert abs(sample.mean() - theory.mean()) < .12\n    assert abs(sample.std(ddof=1) - theory.std()) < .16\n    assert stats.kstest(sample, theory.cdf).statistic < .015\n\ndef test_neumann_acceptance():\n    rng = np.random.RandomState(3)\n    x, accepted, tried = neumann_gamma(20_000, rng, return_stats=True)\n    _, logm = gamma_envelope()\n    assert len(x) == 20_000 and 0 < accepted <= tried\n    assert abs(accepted / tried - np.exp(-logm)) < .03\n\ndef test_exponential():\n    x = fast_exponential(60_000, 6.4, np.random.RandomState(7))\n    assert abs(x.mean() - 6.4) < .1\n    assert stats.kstest(x, stats.expon(scale=6.4).cdf).statistic < .015\n\ndef test_exponential_bad_scale():\n    with pytest.raises(ValueError):\n        fast_exponential(10, 0, np.random.RandomState(0))\n\ndef test_noninteger_n():\n    with pytest.raises(TypeError):\n        sugar_generator(2.5, DATA)'}, {'kind': 'code', 'html': '<pre class="numeric-result">26 passed, 1 warning in 0.54s\nПроверенный запуск тестов генераторов.</pre>', 'source': '!pip install -q pytest\n!python -m pytest -q tests/test_sugar.py'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><span class="paragraph"><strong>Вывод по тестам.</strong> Проверяются длина, корректная обработка ошибочного <marimo-tex class="arithmatex">||(n||)</marimo-tex>, воспроизводимость, принадлежность эмпирических значений исходным данным, частоты повторов, корректность экспоненциальной оболочки, параметры гамма-генератора, доля принятия Неймана и свойства экспоненциальной выборки. После выполнения ячейки выше будет показано реальное количество успешно пройденных тестов.</span></span>', 'source': '**Вывод по тестам.** Проверяются длина, корректная обработка ошибочного $n$, воспроизводимость, принадлежность эмпирических значений исходным данным, частоты повторов, корректность экспоненциальной оболочки, параметры гамма-генератора, доля принятия Неймана и свойства экспоненциальной выборки. После выполнения ячейки выше будет показано реальное количество успешно пройденных тестов.'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><h3 id="sprint2-heading-71-1"><span class="notebook-index">2.5</span>Resume</h3></span>', 'source': '### Resume'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><span class="paragraph"><strong>Основной результат.</strong> Реализован генератор <code>residual sugar</code> по <strong>эмпирической обратной функции распределения</strong>. Он сохраняет наблюдаемые значения и частоты, поэтому наиболее точно отражает исходную таблицу при моделировании аналогичных данных.</span>\n<span class="paragraph"><strong>Дополнительный метод.</strong> Метод Неймана генерирует положительные непрерывные величины по гамма-модели <marimo-tex class="arithmatex">||(k=1.4814||)</marimo-tex>, <marimo-tex class="arithmatex">||(\\theta=4.3144||)</marimo-tex> г/л. Это полезно, если нужны новые значения, но отдельные пики эмпирического распределения сглаживаются.</span>\n<span class="paragraph"><strong>Четыре алгоритма.</strong> Исследованы обратное преобразование, метод Неймана, суперпозиция условных эмпирических частей и быстрая экспонента. Последняя служит источником предложений Неймана, а не самостоятельной точной моделью сахара.</span>\n<span class="paragraph"><strong>Ограничения.</strong> Эмпирический генератор воспроизводит конкретную таблицу, гамма-генератор — приближённый закон. Ни один способ не моделирует автоматически связь сахара с pH, алкоголем и качеством вина. Для совместной генерации потребуется многомерная модель.</span></span>', 'source': '**Основной результат.** Реализован генератор `residual sugar` по **эмпирической обратной функции распределения**. Он сохраняет наблюдаемые значения и частоты, поэтому наиболее точно отражает исходную таблицу при моделировании аналогичных данных.\n\n**Дополнительный метод.** Метод Неймана генерирует положительные непрерывные величины по гамма-модели $k=1.4814$, $\\theta=4.3144$ г/л. Это полезно, если нужны новые значения, но отдельные пики эмпирического распределения сглаживаются.\n\n**Четыре алгоритма.** Исследованы обратное преобразование, метод Неймана, суперпозиция условных эмпирических частей и быстрая экспонента. Последняя служит источником предложений Неймана, а не самостоятельной точной моделью сахара.\n\n**Ограничения.** Эмпирический генератор воспроизводит конкретную таблицу, гамма-генератор — приближённый закон. Ни один способ не моделирует автоматически связь сахара с pH, алкоголем и качеством вина. Для совместной генерации потребуется многомерная модель.'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><h2 id="sprint2-heading-73-1">Исследование алгоритмов датчиков (доп. баллы)</h2></span>', 'source': '## Исследование алгоритмов датчиков (доп. баллы)'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><table>\n<thead>\n<tr>\n<th>Алгоритм</th>\n<th>Как работает</th>\n<th>Где применяется</th>\n<th>Сильные стороны</th>\n<th>Ограничения</th>\n<th>Реализация</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Обратная функция распределения</td>\n<td><marimo-tex class="arithmatex">||(U\\to F^{-1}(U)||)</marimo-tex>, в том числе эмпирическая CDF</td>\n<td>бутстрэп, имитация эмпирических данных</td>\n<td>точное воспроизведение эмпирического закона</td>\n<td>нет новых значений вне исходной выборки</td>\n<td><code>empirical_inverse</code></td>\n</tr>\n<tr>\n<td>Метод Неймана</td>\n<td>принимаем <marimo-tex class="arithmatex">||(Y\\sim g||)</marimo-tex> с вероятностью <marimo-tex class="arithmatex">||(f(Y)/(Mg(Y))||)</marimo-tex></td>\n<td>моделирование непростых непрерывных плотностей</td>\n<td>гибкость, не нужна обратная CDF гамма</td>\n<td>нужны оболочка <marimo-tex class="arithmatex">||(M||)</marimo-tex> и отбрасывание кандидатов</td>\n<td><code>neumann_gamma</code></td>\n</tr>\n<tr>\n<td>Суперпозиция</td>\n<td>выбираем компоненту смеси, затем число из неё</td>\n<td>смеси, стратифицированные модели</td>\n<td>позволяет моделировать мультимодальные распределения</td>\n<td>нужны корректные веса и компонентные законы</td>\n<td><code>superposition_empirical</code></td>\n</tr>\n<tr>\n<td>Быстрая экспонента</td>\n<td><marimo-tex class="arithmatex">||(-b\\ln(1-U)||)</marimo-tex></td>\n<td>интервалы ожидания, гамма-предложения</td>\n<td>простая и векторизуемая формула</td>\n<td>экспонента сама по себе плохо повторяет несколько пиков сахара</td>\n<td><code>fast_exponential</code></td>\n</tr>\n</tbody>\n</table>\n<span class="paragraph"><strong>Что показало сравнение.</strong> По точности воспроизведения исходных измерений предпочтительны эмпирическое преобразование и суперпозиция. Нейман корректно реализует заданную гамма-плотность. Время работы измеряется непосредственно в ноутбуке, без предположения, что одна реализация всегда быстрее другой.</span></span>', 'source': '| Алгоритм | Как работает | Где применяется | Сильные стороны | Ограничения | Реализация |\n|---|---|---|---|---|---|\n| Обратная функция распределения | $U\\to F^{-1}(U)$, в том числе эмпирическая CDF | бутстрэп, имитация эмпирических данных | точное воспроизведение эмпирического закона | нет новых значений вне исходной выборки | `empirical_inverse` |\n| Метод Неймана | принимаем $Y\\sim g$ с вероятностью $f(Y)/(Mg(Y))$ | моделирование непростых непрерывных плотностей | гибкость, не нужна обратная CDF гамма | нужны оболочка $M$ и отбрасывание кандидатов | `neumann_gamma` |\n| Суперпозиция | выбираем компоненту смеси, затем число из неё | смеси, стратифицированные модели | позволяет моделировать мультимодальные распределения | нужны корректные веса и компонентные законы | `superposition_empirical` |\n| Быстрая экспонента | $-b\\ln(1-U)$ | интервалы ожидания, гамма-предложения | простая и векторизуемая формула | экспонента сама по себе плохо повторяет несколько пиков сахара | `fast_exponential` |\n\n**Что показало сравнение.** По точности воспроизведения исходных измерений предпочтительны эмпирическое преобразование и суперпозиция. Нейман корректно реализует заданную гамма-плотность. Время работы измеряется непосредственно в ноутбуке, без предположения, что одна реализация всегда быстрее другой.'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><h2 id="sprint2-heading-75-1">Литература</h2>\n<ol>\n<li>UCI Machine Learning Repository. <em>Wine Quality</em> (Cortez P. et al., 2009): <a href="https://archive.ics.uci.edu/dataset/186/wine+quality" rel="noopener" target="_blank">https://archive.ics.uci.edu/dataset/186/wine+quality</a></li>\n<li>Devroye L. <em>Non-Uniform Random Variate Generation</em>. Springer, 1986. <a href="https://luc.devroye.org/rnbookindex.html" rel="noopener" target="_blank">https://luc.devroye.org/rnbookindex.html</a></li>\n<li>Rubinstein R. Y., Kroese D. P. <em>Simulation and the Monte Carlo Method</em>. Wiley, 2016.</li>\n<li>Matsumoto M., Nishimura T. <em>Mersenne Twister: A 623-Dimensionally Equidistributed Uniform Pseudo-Random Number Generator</em>. ACM TOMACS, 1998.</li>\n<li>SciPy documentation: <code>scipy.stats.gamma</code>, <code>scipy.stats.expon</code>, <code>scipy.stats.kstest</code>: <a href="https://docs.scipy.org/doc/scipy/reference/stats.html" rel="noopener" target="_blank">https://docs.scipy.org/doc/scipy/reference/stats.html</a></li>\n<li>NumPy documentation: <code>numpy.random.RandomState</code> (MT19937): <a href="https://numpy.org/doc/stable/reference/random/legacy.html" rel="noopener" target="_blank">https://numpy.org/doc/stable/reference/random/legacy.html</a></li>\n</ol></span>', 'source': '## Литература\n1. UCI Machine Learning Repository. *Wine Quality* (Cortez P. et al., 2009): https://archive.ics.uci.edu/dataset/186/wine+quality\n2. Devroye L. *Non-Uniform Random Variate Generation*. Springer, 1986. https://luc.devroye.org/rnbookindex.html\n3. Rubinstein R. Y., Kroese D. P. *Simulation and the Monte Carlo Method*. Wiley, 2016.\n4. Matsumoto M., Nishimura T. *Mersenne Twister: A 623-Dimensionally Equidistributed Uniform Pseudo-Random Number Generator*. ACM TOMACS, 1998.\n5. SciPy documentation: `scipy.stats.gamma`, `scipy.stats.expon`, `scipy.stats.kstest`: https://docs.scipy.org/doc/scipy/reference/stats.html\n6. NumPy documentation: `numpy.random.RandomState` (MT19937): https://numpy.org/doc/stable/reference/random/legacy.html'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><h2 id="sprint2-heading-76-1">Random 03 (alcohol)</h2>\n<span class="paragraph">Генерация объёмной доли алкоголя в белом вине. Продолжаем анализ величины <code>alcohol</code> из первого спринта, используя тот же датасет Wine Quality (4898 наблюдений).</span></span>', 'source': '## Random 03 (alcohol)\n\nГенерация объёмной доли алкоголя в белом вине. Продолжаем анализ величины `alcohol` из первого спринта, используя тот же датасет Wine Quality (4898 наблюдений).\n'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><h3 id="sprint2-heading-77-1"><span class="notebook-index">3.1</span>Description</h3></span>', 'source': '### Description\n'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><span class="paragraph"><strong>Что генерируем.</strong> <code>alcohol</code> — объёмная доля этилового спирта в белом вине, единица — <strong>% об.</strong> В исходной таблице значения находятся между 8,0 и 14,2 % об., среднее составляет 10,5143 % об. Несмотря на непрерывную природу величины, в файле всего 103 различных записанных значения: измерения представлены с конечной точностью.</span>\n<span class="paragraph"><strong>Модель из спринта 1.</strong> Среди нормального, гамма-распределения со сдвигом и скошенного нормального лучше всего по AIC и расстоянию KS подошло <strong>скошенное нормальное</strong>: <code>shape=9.981325</code>, <code>loc=8.806782</code>, <code>scale=2.104665</code> (AIC = 15125,28; KS D = 0,05687). Подбор модели выполнен ранее с помощью <code>scipy.stats.skewnorm.fit</code>.</span>\n<span class="paragraph"><strong>Цель.</strong> Получать произвольное число новых значений, исследовать, насколько генератор воспроизводит выбранный теоретический закон, и отдельно сравнить его с реальной таблицей. Также реализуем <strong>эмпирический генератор</strong>: он точнее воспроизводит частоты округлённых значений, но не создаёт новых уровней концентрации.</span>\n<span class="paragraph"><strong>Алгоритмы.</strong> Основной — стохастическое представление скошенного нормального через две независимые стандартные нормальные величины. Для получения нормальных чисел реализованы <strong>полярный метод Марсальи</strong> и <strong>преобразование Бокса — Мюллера</strong>. Третий способ — обратное преобразование эмпирической функции распределения.</span>\n<span class="paragraph"><strong>Источник псевдослучайности</strong> — MT19937 (<code>numpy.random.RandomState</code>), фиксированный <code>seed</code> делает результаты воспроизводимыми. Методы не предназначены для криптографии. Готовый <code>scipy.stats.skewnorm.rvs</code> для самого генератора не применяется.</span></span>', 'source': '**Что генерируем.** `alcohol` — объёмная доля этилового спирта в белом вине, единица — **% об.** В исходной таблице значения находятся между 8,0 и 14,2 % об., среднее составляет 10,5143 % об. Несмотря на непрерывную природу величины, в файле всего 103 различных записанных значения: измерения представлены с конечной точностью.\n\n**Модель из спринта 1.** Среди нормального, гамма-распределения со сдвигом и скошенного нормального лучше всего по AIC и расстоянию KS подошло **скошенное нормальное**: `shape=9.981325`, `loc=8.806782`, `scale=2.104665` (AIC = 15125,28; KS D = 0,05687). Подбор модели выполнен ранее с помощью `scipy.stats.skewnorm.fit`.\n\n**Цель.** Получать произвольное число новых значений, исследовать, насколько генератор воспроизводит выбранный теоретический закон, и отдельно сравнить его с реальной таблицей. Также реализуем **эмпирический генератор**: он точнее воспроизводит частоты округлённых значений, но не создаёт новых уровней концентрации.\n\n**Алгоритмы.** Основной — стохастическое представление скошенного нормального через две независимые стандартные нормальные величины. Для получения нормальных чисел реализованы **полярный метод Марсальи** и **преобразование Бокса — Мюллера**. Третий способ — обратное преобразование эмпирической функции распределения.\n\n**Источник псевдослучайности** — MT19937 (`numpy.random.RandomState`), фиксированный `seed` делает результаты воспроизводимыми. Методы не предназначены для криптографии. Готовый `scipy.stats.skewnorm.rvs` для самого генератора не применяется.\n'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><h3 id="sprint2-heading-79-1"><span class="notebook-index">3.2</span>Math desc</h3></span>', 'source': '### Math desc\n'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><span class="paragraph"><strong>1. Плотность выбранного распределения.</strong> Для <marimo-tex class="arithmatex">||(X\\sim SN(\\xi,\\omega,\\alpha)||)</marimo-tex>, где <marimo-tex class="arithmatex">||(\\xi||)</marimo-tex> — <code>loc</code>, <marimo-tex class="arithmatex">||(\\omega&gt;0||)</marimo-tex> — <code>scale</code>, <marimo-tex class="arithmatex">||(\\alpha||)</marimo-tex> — <code>shape</code>, плотность имеет вид</span>\n<marimo-tex class="arithmatex">||[\nf_X(x)=\\frac{2}{\\omega}\\,\\varphi\\!\\left(\\frac{x-\\xi}{\\omega}\\right)\\Phi\\!\\left(\\alpha\\frac{x-\\xi}{\\omega}\\right), \\quad x\\in\\mathbb R.\n||]</marimo-tex><span class="paragraph">Здесь <marimo-tex class="arithmatex">||(\\varphi||)</marimo-tex> и <marimo-tex class="arithmatex">||(\\Phi||)</marimo-tex> — плотность и функция распределения <marimo-tex class="arithmatex">||(N(0,1)||)</marimo-tex>. При <marimo-tex class="arithmatex">||(\\alpha=0||)</marimo-tex> получаем нормальное распределение; положительное <marimo-tex class="arithmatex">||(\\alpha||)</marimo-tex> создаёт правостороннюю асимметрию.</span>\n<span class="paragraph"><strong>2. Как получить скошенную нормальную величину.</strong> Обозначим</span>\n<marimo-tex class="arithmatex">||[\n\\delta=\\frac{\\alpha}{\\sqrt{1+\\alpha^2}},\\qquad U,V\\overset{ind}{\\sim}N(0,1).\n||]</marimo-tex><span class="paragraph">Тогда по стохастическому представлению распределения</span>\n<marimo-tex class="arithmatex">||[\nZ=\\delta |U|+\\sqrt{1-\\delta^2}\\,V\\sim SN(0,1,\\alpha),\\qquad X=\\xi+\\omega Z.\n||]</marimo-tex><span class="paragraph"><strong>Это главный генератор.</strong> Сначала создаём две независимые нормальные величины <marimo-tex class="arithmatex">||(U,V||)</marimo-tex>, затем берём модуль первой и линейную комбинацию. Коэффициенты в формуле нужны, чтобы сохранить требуемую форму распределения. Мы не заменяем это готовым вызовом <code>skewnorm.rvs</code>.</span>\n<span class="paragraph">Среднее и дисперсия модели:</span>\n<marimo-tex class="arithmatex">||[\n\\mathbb E[X]=\\xi+\\omega\\delta\\sqrt{\\frac2\\pi},\\qquad \\operatorname{Var}(X)=\\omega^2\\left(1-\\frac{2\\delta^2}{\\pi}\\right).\n||]</marimo-tex><span class="paragraph"><strong>3. Полярный метод Марсальи.</strong> Берём <marimo-tex class="arithmatex">||(u_1,u_2\\sim U(-1,1)||)</marimo-tex>, находим <marimo-tex class="arithmatex">||(s=u_1^2+u_2^2||)</marimo-tex>. Если <marimo-tex class="arithmatex">||(0&lt;s&lt;1||)</marimo-tex>, принимаем точку и вычисляем</span>\n<marimo-tex class="arithmatex">||[\nz_1=u_1\\sqrt{\\frac{-2\\ln s}{s}},\\qquad z_2=u_2\\sqrt{\\frac{-2\\ln s}{s}}.\n||]</marimo-tex><span class="paragraph">Получаем две независимые нормальные величины; теоретическая доля принятых точек равна <marimo-tex class="arithmatex">||(\\pi/4\\approx0{,}7854||)</marimo-tex>.</span>\n<span class="paragraph"><strong>4. Альтернатива: метод Бокса — Мюллера.</strong> Для независимых <marimo-tex class="arithmatex">||(u_1,u_2\\sim U(0,1)||)</marimo-tex>:</span>\n<marimo-tex class="arithmatex">||[\nz_1=\\sqrt{-2\\ln u_1}\\cos(2\\pi u_2),\\qquad z_2=\\sqrt{-2\\ln u_1}\\sin(2\\pi u_2).\n||]</marimo-tex><span class="paragraph">Оба метода строят стандартные нормальные величины, но различаются количеством вычислений и наличием отбора кандидатов.</span>\n<span class="paragraph"><strong>5. Эмпирическое квантильное преобразование.</strong> Пусть различные значения исходной таблицы <marimo-tex class="arithmatex">||(x_1&lt;\\dots&lt;x_m||)</marimo-tex> встречаются <marimo-tex class="arithmatex">||(n_1,\\ldots,n_m||)</marimo-tex> раз, <marimo-tex class="arithmatex">||(N=\\sum n_i||)</marimo-tex>. Тогда</span>\n<marimo-tex class="arithmatex">||[\n\\widehat P(X=x_i)=\\frac{n_i}{N},\\qquad \\widehat F(x)=\\frac1N\\sum_{j=1}^{N}\\mathbf1(X_j\\le x).\n||]</marimo-tex><span class="paragraph">Для <marimo-tex class="arithmatex">||(W\\sim U(0,1)||)</marimo-tex> выбираем минимальное <marimo-tex class="arithmatex">||(x_i||)</marimo-tex>, для которого <marimo-tex class="arithmatex">||(\\widehat F(x_i)\\ge W||)</marimo-tex>. Так сохраняются <strong>наблюдаемые частоты</strong> и повторяющиеся записанные значения; новые значения между ними не возникают.</span>\n<span class="paragraph"><strong>6. Приведение к стандартному нормальному.</strong> Простая стандартизация <marimo-tex class="arithmatex">||(Z=(X-\\bar X)/s||)</marimo-tex> даёт среднее 0 и стандартное отклонение 1, но не устраняет асимметрию. Для <strong>непрерывной теоретической модели</strong> можно использовать квантильное преобразование:</span>\n<marimo-tex class="arithmatex">||[\nT(X)=\\Phi^{-1}(F_{SN}(X)).\n||]</marimo-tex><span class="paragraph">Если <marimo-tex class="arithmatex">||(X||)</marimo-tex> действительно имеет заданный непрерывный закон, то <marimo-tex class="arithmatex">||(F_{SN}(X)\\sim U(0,1)||)</marimo-tex> и <marimo-tex class="arithmatex">||(T(X)\\sim N(0,1)||)</marimo-tex>. На реальных округлённых данных и при неточной модели идеальной нормальности ждать нельзя.</span></span>', 'source': '**1. Плотность выбранного распределения.** Для $X\\sim SN(\\xi,\\omega,\\alpha)$, где $\\xi$ — `loc`, $\\omega>0$ — `scale`, $\\alpha$ — `shape`, плотность имеет вид\n\n$$f_X(x)=\\frac{2}{\\omega}\\,\\varphi\\!\\left(\\frac{x-\\xi}{\\omega}\\right)\\Phi\\!\\left(\\alpha\\frac{x-\\xi}{\\omega}\\right), \\quad x\\in\\mathbb R.$$\n\nЗдесь $\\varphi$ и $\\Phi$ — плотность и функция распределения $N(0,1)$. При $\\alpha=0$ получаем нормальное распределение; положительное $\\alpha$ создаёт правостороннюю асимметрию.\n\n**2. Как получить скошенную нормальную величину.** Обозначим\n\n$$\\delta=\\frac{\\alpha}{\\sqrt{1+\\alpha^2}},\\qquad U,V\\overset{ind}{\\sim}N(0,1).$$\n\nТогда по стохастическому представлению распределения\n\n$$Z=\\delta |U|+\\sqrt{1-\\delta^2}\\,V\\sim SN(0,1,\\alpha),\\qquad X=\\xi+\\omega Z.$$\n\n**Это главный генератор.** Сначала создаём две независимые нормальные величины $U,V$, затем берём модуль первой и линейную комбинацию. Коэффициенты в формуле нужны, чтобы сохранить требуемую форму распределения. Мы не заменяем это готовым вызовом `skewnorm.rvs`.\n\nСреднее и дисперсия модели:\n\n$$\\mathbb E[X]=\\xi+\\omega\\delta\\sqrt{\\frac2\\pi},\\qquad \\operatorname{Var}(X)=\\omega^2\\left(1-\\frac{2\\delta^2}{\\pi}\\right).$$\n\n**3. Полярный метод Марсальи.** Берём $u_1,u_2\\sim U(-1,1)$, находим $s=u_1^2+u_2^2$. Если $0<s<1$, принимаем точку и вычисляем\n\n$$z_1=u_1\\sqrt{\\frac{-2\\ln s}{s}},\\qquad z_2=u_2\\sqrt{\\frac{-2\\ln s}{s}}.$$\n\nПолучаем две независимые нормальные величины; теоретическая доля принятых точек равна $\\pi/4\\approx0{,}7854$.\n\n**4. Альтернатива: метод Бокса — Мюллера.** Для независимых $u_1,u_2\\sim U(0,1)$:\n\n$$z_1=\\sqrt{-2\\ln u_1}\\cos(2\\pi u_2),\\qquad z_2=\\sqrt{-2\\ln u_1}\\sin(2\\pi u_2).$$\n\nОба метода строят стандартные нормальные величины, но различаются количеством вычислений и наличием отбора кандидатов.\n\n**5. Эмпирическое квантильное преобразование.** Пусть различные значения исходной таблицы $x_1<\\dots<x_m$ встречаются $n_1,\\ldots,n_m$ раз, $N=\\sum n_i$. Тогда\n\n$$\\widehat P(X=x_i)=\\frac{n_i}{N},\\qquad \\widehat F(x)=\\frac1N\\sum_{j=1}^{N}\\mathbf1(X_j\\le x).$$\n\nДля $W\\sim U(0,1)$ выбираем минимальное $x_i$, для которого $\\widehat F(x_i)\\ge W$. Так сохраняются **наблюдаемые частоты** и повторяющиеся записанные значения; новые значения между ними не возникают.\n\n**6. Приведение к стандартному нормальному.** Простая стандартизация $Z=(X-\\bar X)/s$ даёт среднее 0 и стандартное отклонение 1, но не устраняет асимметрию. Для **непрерывной теоретической модели** можно использовать квантильное преобразование:\n\n$$T(X)=\\Phi^{-1}(F_{SN}(X)).$$\n\nЕсли $X$ действительно имеет заданный непрерывный закон, то $F_{SN}(X)\\sim U(0,1)$ и $T(X)\\sim N(0,1)$. На реальных округлённых данных и при неточной модели идеальной нормальности ждать нельзя.\n'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><h3 id="sprint2-heading-81-1"><span class="notebook-index">3.3</span>Code</h3></span>', 'source': '### Code\n'}, {'kind': 'code', 'html': '<pre class="numeric-result">Каталоги winegen/ и tests/ готовы\n</pre>', 'source': '# Подготовка каталога для отдельного модуля alcohol; файлы pH и sugar не меняем.\nfrom pathlib import Path\nPath("winegen").mkdir(exist_ok=True)\nPath("winegen/__init__.py").touch(exist_ok=True)\nPath("tests").mkdir(exist_ok=True)\nprint("Каталоги winegen/ и tests/ готовы")\n'}, {'kind': 'code', 'html': '<pre class="numeric-result">Overwriting winegen/alcohol.py\n</pre>', 'source': '%%writefile winegen/alcohol.py\n"""Генераторы содержания алкоголя: skew-normal и эмпирическая CDF.\nИсточник равномерных чисел — MT19937 (NumPy RandomState).\n"""\nimport numpy as np\nfrom scipy import stats\n\n# Оценки из спринта 1, полученные с scipy.stats.skewnorm.fit\nALCOHOL_SHAPE = 9.981325379517678\nALCOHOL_LOC = 8.806782475860167\nALCOHOL_SCALE = 2.1046650921103787\n\n\ndef _validate_n(n):\n    if isinstance(n, (bool, np.bool_)) or not isinstance(n, (int, np.integer)):\n        raise TypeError("n должно быть целым числом")\n    if n < 0:\n        raise ValueError("n должно быть неотрицательным")\n    return int(n)\n\n\ndef polar_normal(n, rng):\n    """Независимые N(0,1): полярный метод Марсальи."""\n    n = _validate_n(n)\n    if n == 0:\n        return np.empty(0, dtype=float)\n    parts = []\n    size = 0\n    while size < n:\n        m = max(64, int((n - size) / (np.pi / 2)) + 64)\n        u1 = 2.0 * rng.random_sample(m) - 1.0\n        u2 = 2.0 * rng.random_sample(m) - 1.0\n        s = u1**2 + u2**2\n        ok = (s > 0.0) & (s < 1.0)\n        f = np.sqrt(-2.0 * np.log(s[ok]) / s[ok])\n        z1 = u1[ok] * f\n        z2 = u2[ok] * f\n        vals = np.column_stack((z1, z2)).ravel()\n        parts.append(vals)\n        size += len(vals)\n    return np.concatenate(parts)[:n]\n\n\ndef box_muller_normal(n, rng):\n    """Независимые N(0,1): тригонометрическая формула Бокса—Мюллера."""\n    n = _validate_n(n)\n    if n == 0:\n        return np.empty(0, dtype=float)\n    m = (n + 1) // 2\n    u1 = np.maximum(rng.random_sample(m), np.finfo(float).tiny)\n    u2 = rng.random_sample(m)\n    radius = np.sqrt(-2.0 * np.log(u1))\n    angle = 2.0 * np.pi * u2\n    return np.column_stack((radius * np.cos(angle), radius * np.sin(angle))).ravel()[:n]\n\n\ndef skew_normal_latent(n, rng, normal_method="polar"):\n    """Скошенная нормальная через Z=delta*|U|+sqrt(1-delta²)*V."""\n    n = _validate_n(n)\n    if normal_method == "polar":\n        normals = polar_normal(2 * n, rng)\n    elif normal_method == "box_muller":\n        normals = box_muller_normal(2 * n, rng)\n    else:\n        raise ValueError("Неизвестный способ получения нормальных чисел")\n    if n == 0:\n        return np.empty(0, dtype=float)\n    u = normals[:n]\n    v = normals[n:]\n    delta = ALCOHOL_SHAPE / np.sqrt(1.0 + ALCOHOL_SHAPE**2)\n    z = delta * np.abs(u) + np.sqrt(1.0 - delta**2) * v\n    return ALCOHOL_LOC + ALCOHOL_SCALE * z\n\n\ndef empirical_inverse(n, rng, data):\n    """Обратная эмпирическая CDF, сохраняющая значения и частоты выборки."""\n    n = _validate_n(n)\n    if data is None:\n        raise ValueError("Для эмпирического метода нужны исходные данные")\n    values = np.asarray(data, dtype=float).ravel()\n    if values.size == 0 or not np.isfinite(values).all():\n        raise ValueError("data должны содержать конечные числа")\n    unique, counts = np.unique(values, return_counts=True)\n    cdf = np.cumsum(counts) / counts.sum()\n    u = rng.random_sample(n)\n    indices = np.searchsorted(cdf, u, side="right")\n    return unique[indices]\n\n\ndef alcohol_generator(n, seed=42, method="polar", data=None):\n    """method: polar, box_muller (теоретическая SN) или empirical."""\n    n = _validate_n(n)\n    rng = np.random.RandomState(seed)  # MT19937\n    if method == "empirical":\n        return empirical_inverse(n, rng, data)\n    if method in ("polar", "box_muller"):\n        return skew_normal_latent(n, rng, normal_method=method)\n    raise ValueError("method: polar, box_muller или empirical")\n\n\ndef to_standard_normal(x):\n    """PIT и обратная Phi для подогнанной непрерывной skew-normal модели."""\n    p = stats.skewnorm.cdf(np.asarray(x, dtype=float),\n                           ALCOHOL_SHAPE, loc=ALCOHOL_LOC, scale=ALCOHOL_SCALE)\n    eps = np.finfo(float).eps\n    return stats.norm.ppf(np.clip(p, eps, 1.0 - eps))\n'}, {'kind': 'code', 'html': '<pre class="numeric-result">Данные: n=4898, среднее=10.5143 % об., уникальных=103\nПервые 5 значений (полярный метод): [10.099 11.322  9.197  9.044 11.361]\nПервые 5 значений (Бокс — Мюллер): [11.481 10.284  9.249  8.791  9.902]\nПервые 5 значений (эмпирический): [ 9.9 12.7 11.3 10.7  9.2]\n</pre>', 'source': 'import numpy as np\nimport pandas as pd\nimport matplotlib.pyplot as plt\nfrom scipy import stats\nfrom IPython.display import display\n\nfrom winegen.alcohol import (\n    alcohol_generator, polar_normal, box_muller_normal, to_standard_normal,\n    ALCOHOL_SHAPE, ALCOHOL_LOC, ALCOHOL_SCALE,\n)\n\n# В предыдущих разделах уже загружен df. Если запускать только этот раздел,\n# он самостоятельно подгрузит тот же исходный файл Wine Quality.\nif "df" not in globals() or "alcohol" not in df.columns:\n    dataset_url = "https://archive.ics.uci.edu/ml/machine-learning-databases/wine-quality/winequality-white.csv"\n    local_csv = Path("winequality-white.csv")\n    df = pd.read_csv(local_csv if local_csv.exists() else dataset_url, sep=";")\n\nalcohol_real = df["alcohol"].dropna().to_numpy(dtype=float)\nassert len(alcohol_real) == 4898, "Ожидались 4898 измерений белого вина"\n\nALCOHOL_N = 100_000\nalcohol_model = stats.skewnorm(ALCOHOL_SHAPE, loc=ALCOHOL_LOC, scale=ALCOHOL_SCALE)\nalcohol_polar = alcohol_generator(ALCOHOL_N, seed=42, method="polar")\nalcohol_bm = alcohol_generator(ALCOHOL_N, seed=42, method="box_muller")\nalcohol_emp = alcohol_generator(ALCOHOL_N, seed=42, method="empirical", data=alcohol_real)\n\nprint(f"Данные: n={len(alcohol_real)}, среднее={alcohol_real.mean():.4f} % об., уникальных={np.unique(alcohol_real).size}")\nprint("Первые 5 значений (полярный метод):", np.round(alcohol_polar[:5], 3))\nprint("Первые 5 значений (Бокс — Мюллер):", np.round(alcohol_bm[:5], 3))\nprint("Первые 5 значений (эмпирический):", np.round(alcohol_emp[:5], 3))\n'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><h3 id="sprint2-heading-85-1"><span class="notebook-index">3.4</span>Tests</h3></span>', 'source': '### Tests\n'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><h4 id="sprint2-heading-86-1"><span class="notebook-index">3.4.1</span>1. Проверка нормального источника и скошенно-нормального закона</h4></span>', 'source': '#### 1. Проверка нормального источника и скошенно-нормального закона\n'}, {'kind': 'code', 'html': '<div class="tbl-wrap"><div>\n<style scoped>\n    .dataframe tbody tr th:only-of-type {\n        vertical-align: middle;\n    }\n\n    .dataframe tbody tr th {\n        vertical-align: top;\n    }\n\n    .dataframe thead th {\n        text-align: right;\n    }\n</style>\n<table border="1" class="dataframe">\n  <thead>\n    <tr style="text-align: right;">\n      <th></th>\n      <th>метод</th>\n      <th>среднее Z</th>\n      <th>std Z</th>\n      <th>KS D к N(0,1)</th>\n      <th>KS p-value</th>\n    </tr>\n  </thead>\n  <tbody>\n    <tr>\n      <th>0</th>\n      <td>Марсалья</td>\n      <td>0.00497</td>\n      <td>1.00313</td>\n      <td>0.00416</td>\n      <td>0.06267</td>\n    </tr>\n    <tr>\n      <th>1</th>\n      <td>Бокс — Мюллер</td>\n      <td>-0.00488</td>\n      <td>0.99952</td>\n      <td>0.00304</td>\n      <td>0.31252</td>\n    </tr>\n  </tbody>\n</table>\n</div></div><pre class="numeric-result">Среднее теории: 10.47770, std теории: 1.27971\nФормулы моментов совпали с реализацией SciPy\n</pre>', 'source': '# Проверяем не только итоговый X, но и исходные стандартные нормальные числа.\nrows = []\nfor label, normal_fn in [("Марсалья", polar_normal), ("Бокс — Мюллер", box_muller_normal)]:\n    z = normal_fn(100_000, np.random.RandomState(2026))\n    ks_z = stats.kstest(z, stats.norm.cdf)\n    rows.append({"метод": label, "среднее Z": z.mean(), "std Z": z.std(ddof=1),\n                 "KS D к N(0,1)": ks_z.statistic, "KS p-value": ks_z.pvalue})\ndisplay(pd.DataFrame(rows).round(5))\n\n# Точные моменты: получаем их из формул и сверяем со scipy.stats\nalpha = ALCOHOL_SHAPE\ndelta = alpha / np.sqrt(1 + alpha**2)\ntheory_mean = ALCOHOL_LOC + ALCOHOL_SCALE * delta * np.sqrt(2 / np.pi)\ntheory_std = ALCOHOL_SCALE * np.sqrt(1 - 2 * delta**2 / np.pi)\nprint(f"Среднее теории: {theory_mean:.5f}, std теории: {theory_std:.5f}")\nassert np.isclose(theory_mean, alcohol_model.mean(), rtol=1e-12)\nassert np.isclose(theory_std, alcohol_model.std(), rtol=1e-12)\nprint("Формулы моментов совпали с реализацией SciPy")\n'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><span class="paragraph"><strong>Вывод.</strong> Сначала проверяем, что оба собственных метода формируют стандартные нормальные величины. Среднее должно быть близко к 0, стандартное отклонение — к 1; статистика KS измеряет максимальное отклонение от <marimo-tex class="arithmatex">||(N(0,1)||)</marimo-tex>. Отдельно сверяем математические формулы среднего и дисперсии с независимой реализацией <code>scipy.stats.skewnorm</code>. При конечном числе наблюдений статистики не обязаны совпадать абсолютно точно.</span></span>', 'source': '**Вывод.** Сначала проверяем, что оба собственных метода формируют стандартные нормальные величины. Среднее должно быть близко к 0, стандартное отклонение — к 1; статистика KS измеряет максимальное отклонение от $N(0,1)$. Отдельно сверяем математические формулы среднего и дисперсии с независимой реализацией `scipy.stats.skewnorm`. При конечном числе наблюдений статистики не обязаны совпадать абсолютно точно.\n'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><h4 id="sprint2-heading-89-1"><span class="notebook-index">3.4.2</span>2. Сопоставление генераторов, теории и реальных измерений</h4></span>', 'source': '#### 2. Сопоставление генераторов, теории и реальных измерений\n'}, {'kind': 'code', 'html': '<div class="tbl-wrap"><div>\n<style scoped>\n    .dataframe tbody tr th:only-of-type {\n        vertical-align: middle;\n    }\n\n    .dataframe tbody tr th {\n        vertical-align: top;\n    }\n\n    .dataframe thead th {\n        text-align: right;\n    }\n</style>\n<table border="1" class="dataframe">\n  <thead>\n    <tr style="text-align: right;">\n      <th></th>\n      <th>реальные данные</th>\n      <th>Марсалья → SN</th>\n      <th>Бокс–Мюллер → SN</th>\n      <th>эмпирический</th>\n      <th>теория SN</th>\n    </tr>\n  </thead>\n  <tbody>\n    <tr>\n      <th>среднее</th>\n      <td>10.5143</td>\n      <td>10.4833</td>\n      <td>10.4817</td>\n      <td>10.5112</td>\n      <td>10.4777</td>\n    </tr>\n    <tr>\n      <th>std</th>\n      <td>1.2306</td>\n      <td>1.2806</td>\n      <td>1.2778</td>\n      <td>1.2275</td>\n      <td>1.2797</td>\n    </tr>\n    <tr>\n      <th>медиана</th>\n      <td>10.4000</td>\n      <td>10.2351</td>\n      <td>10.2339</td>\n      <td>10.4000</td>\n      <td>10.2264</td>\n    </tr>\n    <tr>\n      <th>асимметрия</th>\n      <td>0.4873</td>\n      <td>0.9437</td>\n      <td>0.9531</td>\n      <td>0.4847</td>\n      <td>0.9554</td>\n    </tr>\n    <tr>\n      <th>эксцесс</th>\n      <td>-0.6984</td>\n      <td>0.7857</td>\n      <td>0.8506</td>\n      <td>-0.6994</td>\n      <td>0.8231</td>\n    </tr>\n    <tr>\n      <th>квантиль 5%</th>\n      <td>8.9000</td>\n      <td>8.8921</td>\n      <td>8.8896</td>\n      <td>8.9000</td>\n      <td>8.8900</td>\n    </tr>\n    <tr>\n      <th>квантиль 25%</th>\n      <td>9.5000</td>\n      <td>9.4799</td>\n      <td>9.4843</td>\n      <td>9.5000</td>\n      <td>9.4774</td>\n    </tr>\n    <tr>\n      <th>квантиль 75%</th>\n      <td>11.4000</td>\n      <td>11.2417</td>\n      <td>11.2283</td>\n      <td>11.4000</td>\n      <td>11.2279</td>\n    </tr>\n    <tr>\n      <th>квантиль 95%</th>\n      <td>12.7000</td>\n      <td>12.9265</td>\n      <td>12.9305</td>\n      <td>12.7000</td>\n      <td>12.9319</td>\n    </tr>\n  </tbody>\n</table>\n</div></div><div class="tbl-wrap"><div>\n<style scoped>\n    .dataframe tbody tr th:only-of-type {\n        vertical-align: middle;\n    }\n\n    .dataframe tbody tr th {\n        vertical-align: top;\n    }\n\n    .dataframe thead th {\n        text-align: right;\n    }\n</style>\n<table border="1" class="dataframe">\n  <thead>\n    <tr style="text-align: right;">\n      <th></th>\n      <th>генератор</th>\n      <th>KS D к реальным</th>\n      <th>KS D к SN</th>\n      <th>KS p к SN</th>\n    </tr>\n  </thead>\n  <tbody>\n    <tr>\n      <th>0</th>\n      <td>полярный → SN</td>\n      <td>0.05461</td>\n      <td>0.00357</td>\n      <td>0.15691</td>\n    </tr>\n    <tr>\n      <th>1</th>\n      <td>Бокс–Мюллер → SN</td>\n      <td>0.05458</td>\n      <td>0.00321</td>\n      <td>0.25261</td>\n    </tr>\n    <tr>\n      <th>2</th>\n      <td>эмпирический</td>\n      <td>0.00187</td>\n      <td>NaN</td>\n      <td>NaN</td>\n    </tr>\n  </tbody>\n</table>\n</div></div><pre class="numeric-result">Для эмпирической дискретной модели обычное непрерывное KS p-value не применяем.\n</pre>', 'source': 'def alcohol_metrics(values):\n    x = pd.Series(np.asarray(values, dtype=float))\n    return {"среднее": x.mean(), "std": x.std(ddof=1), "медиана": x.median(),\n            "асимметрия": x.skew(), "эксцесс": x.kurt(),\n            "квантиль 5%": x.quantile(.05), "квантиль 25%": x.quantile(.25),\n            "квантиль 75%": x.quantile(.75), "квантиль 95%": x.quantile(.95)}\n\nm, v, sk, ku = alcohol_model.stats(moments="mvsk")\ntheory_row = {"среднее": float(m), "std": float(np.sqrt(v)),\n              "медиана": float(alcohol_model.median()), "асимметрия": float(sk),\n              "эксцесс": float(ku), "квантиль 5%": float(alcohol_model.ppf(.05)),\n              "квантиль 25%": float(alcohol_model.ppf(.25)),\n              "квантиль 75%": float(alcohol_model.ppf(.75)),\n              "квантиль 95%": float(alcohol_model.ppf(.95))}\n\ncomparison_alcohol = pd.DataFrame({\n    "реальные данные": alcohol_metrics(alcohol_real),\n    "Марсалья → SN": alcohol_metrics(alcohol_polar),\n    "Бокс–Мюллер → SN": alcohol_metrics(alcohol_bm),\n    "эмпирический": alcohol_metrics(alcohol_emp),\n    "теория SN": theory_row,\n})\ndisplay(comparison_alcohol.round(4))\n\ncheck_rows = []\nfor name, values in [("полярный → SN", alcohol_polar),\n                     ("Бокс–Мюллер → SN", alcohol_bm),\n                     ("эмпирический", alcohol_emp)]:\n    ks_real = stats.ks_2samp(values, alcohol_real)\n    row = {"генератор": name, "KS D к реальным": ks_real.statistic}\n    if name != "эмпирический":\n        ks_model = stats.kstest(values, alcohol_model.cdf)\n        row["KS D к SN"] = ks_model.statistic\n        row["KS p к SN"] = ks_model.pvalue\n    else:\n        row["KS D к SN"] = np.nan\n        row["KS p к SN"] = np.nan\n    check_rows.append(row)\ndisplay(pd.DataFrame(check_rows).round(5))\nprint("Для эмпирической дискретной модели обычное непрерывное KS p-value не применяем.")\n'}, {'kind': 'code', 'html': '<figure class="plot plot-wide"><img width="1195" height="473" decoding="async" data-report-asset="./public/reports/sprint2/91-0.png" src="data:image/png;base64," alt="График исследования" /></figure>', 'source': '# График 1: гистограмма и плотность выбранной модели\nfig, axes = plt.subplots(1, 2, figsize=(13, 4.5))\nx_grid = np.linspace(7.5, 16.0, 450)\naxes[0].hist(alcohol_real, bins=35, density=True, alpha=.55,\n             color="#6389B8", label="Реальные измерения")\naxes[0].hist(alcohol_polar, bins=65, density=True, alpha=.40,\n             color="#F3A712", label="Генератор (Марсалья)")\naxes[0].plot(x_grid, alcohol_model.pdf(x_grid), color="#C74343", lw=2,\n             label="Теория skew-normal")\naxes[0].set(xlabel="Алкоголь, % об.", ylabel="Плотность",\n            title="Распределение: данные, модель, генератор")\naxes[0].legend()\n\n# График 2: эмпирические CDF против теории\ndef plot_ecdf(ax, values, label, color):\n    vals = np.sort(np.asarray(values, dtype=float))\n    ax.step(vals, np.arange(1, vals.size + 1) / vals.size,\n            where="post", label=label, color=color, lw=1.5)\nplot_ecdf(axes[1], alcohol_real, "Реальные измерения", "#6389B8")\nplot_ecdf(axes[1], alcohol_polar, "Генератор (Марсалья)", "#F3A712")\naxes[1].plot(x_grid, alcohol_model.cdf(x_grid), color="#C74343", lw=2,\n             label="Теория skew-normal")\naxes[1].set(xlabel="Алкоголь, % об.", ylabel="F(x)",\n            title="Сравнение функций распределения", xlim=(7.5, 15.5), ylim=(0, 1))\naxes[1].legend()\nfor ax in axes: ax.grid(alpha=.25)\nplt.tight_layout(); plt.show()\n'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><span class="paragraph"><strong>Вывод.</strong> Модельные генераторы должны совпадать по моментам и форме <strong>с теоретическим скошенным нормальным распределением</strong>. При сравнении с исходной таблицей ожидается заметная разница: в спринте 1 сама подогнанная модель имела KS D <marimo-tex class="arithmatex">||(\\approx0{,}0569||)</marimo-tex> относительно данных и не воспроизводила отдельные пики. Это <strong>ограничение выбранного распределения, а не доказательство ошибки алгоритма</strong>. Эмпирический генератор, наоборот, сохраняет частоты записанных значений и потому лучше подходит для точного воспроизведения исходной таблицы.</span></span>', 'source': '**Вывод.** Модельные генераторы должны совпадать по моментам и форме **с теоретическим скошенным нормальным распределением**. При сравнении с исходной таблицей ожидается заметная разница: в спринте 1 сама подогнанная модель имела KS D $\\approx0{,}0569$ относительно данных и не воспроизводила отдельные пики. Это **ограничение выбранного распределения, а не доказательство ошибки алгоритма**. Эмпирический генератор, наоборот, сохраняет частоты записанных значений и потому лучше подходит для точного воспроизведения исходной таблицы.\n'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><h4 id="sprint2-heading-93-1"><span class="notebook-index">3.4.3</span>3. Альтернативный метод и частоты округлённых значений</h4></span>', 'source': '#### 3. Альтернативный метод и частоты округлённых значений\n'}, {'kind': 'code', 'html': '<figure class="plot plot-wide"><img width="1418" height="481" decoding="async" data-report-asset="./public/reports/sprint2/94-0.png" src="data:image/png;base64," alt="График исследования" /></figure><pre class="numeric-result">Число различных значений: реальные 103 ; эмпирический генератор 103\nKS D: полярный vs Бокс–Мюллер = 0.00276\n</pre>', 'source': '# Сопоставление двух реализаций skew-normal и эмпирического метода\nfig, axes = plt.subplots(1, 2, figsize=(13, 4.5))\naxes[0].hist(alcohol_polar, bins=70, density=True, alpha=.45,\n             color="#6389B8", label="Марсалья")\naxes[0].hist(alcohol_bm, bins=70, density=True, alpha=.38,\n             color="#F3A712", label="Бокс — Мюллер")\naxes[0].plot(x_grid, alcohol_model.pdf(x_grid), color="#C74343", lw=2,\n             label="Теория")\naxes[0].set(xlabel="Алкоголь, % об.", ylabel="Плотность",\n            title="Два способа получить skew-normal")\naxes[0].legend()\n\nobserved_counts = pd.Series(alcohol_real).value_counts(normalize=True).sort_index()\ngenerated_counts = pd.Series(alcohol_emp).value_counts(normalize=True).sort_index()\naxes[1].plot(observed_counts.index, observed_counts.values, ".", ms=5,\n             color="#6389B8", label="Данные")\naxes[1].plot(generated_counts.index, generated_counts.values, ".", ms=4,\n             color="#E4572E", label="Эмпирический генератор")\naxes[1].set(xlabel="Алкоголь, % об.", ylabel="Относительная частота",\n            title="Повторы округлённых значений")\naxes[1].legend()\nfor ax in axes: ax.grid(alpha=.25)\nplt.tight_layout(); plt.show()\n\nprint("Число различных значений: реальные", len(observed_counts),\n      "; эмпирический генератор", len(generated_counts))\nprint("KS D: полярный vs Бокс–Мюллер =",\n      round(stats.ks_2samp(alcohol_polar, alcohol_bm).statistic, 5))\n'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><span class="paragraph"><strong>Вывод.</strong> Полярный метод и метод Бокса — Мюллера имеют один целевой непрерывный закон, поэтому гистограммы практически совпадают с теоретической плотностью. Эмпирический метод вместо сглаженной кривой воспроизводит <strong>доли округлённых значений</strong>, наблюдаемых в таблице. Для новых непрерывных значений подходит skew-normal, для имитации именно имеющейся таблицы — эмпирический закон.</span></span>', 'source': '**Вывод.** Полярный метод и метод Бокса — Мюллера имеют один целевой непрерывный закон, поэтому гистограммы практически совпадают с теоретической плотностью. Эмпирический метод вместо сглаженной кривой воспроизводит **доли округлённых значений**, наблюдаемых в таблице. Для новых непрерывных значений подходит skew-normal, для имитации именно имеющейся таблицы — эмпирический закон.\n'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><h4 id="sprint2-heading-96-1"><span class="notebook-index">3.4.4</span>4. Квантильное преобразование к стандартному нормальному</h4></span>', 'source': '#### 4. Квантильное преобразование к стандартному нормальному\n'}, {'kind': 'code', 'html': '<div class="tbl-wrap"><div>\n<style scoped>\n    .dataframe tbody tr th:only-of-type {\n        vertical-align: middle;\n    }\n\n    .dataframe tbody tr th {\n        vertical-align: top;\n    }\n\n    .dataframe thead th {\n        text-align: right;\n    }\n</style>\n<table border="1" class="dataframe">\n  <thead>\n    <tr style="text-align: right;">\n      <th></th>\n      <th>сгенерированные</th>\n      <th>реальные</th>\n    </tr>\n  </thead>\n  <tbody>\n    <tr>\n      <th>среднее</th>\n      <td>0.00436</td>\n      <td>0.02564</td>\n    </tr>\n    <tr>\n      <th>std</th>\n      <td>1.00009</td>\n      <td>0.99274</td>\n    </tr>\n    <tr>\n      <th>асимметрия</th>\n      <td>-0.00513</td>\n      <td>-0.26917</td>\n    </tr>\n    <tr>\n      <th>эксцесс</th>\n      <td>-0.01382</td>\n      <td>-0.37751</td>\n    </tr>\n    <tr>\n      <th>KS D к N(0,1)</th>\n      <td>0.00357</td>\n      <td>0.05687</td>\n    </tr>\n  </tbody>\n</table>\n</div></div><figure class="plot plot-wide"><img width="812" height="431" decoding="async" data-report-asset="./public/reports/sprint2/97-1.png" src="data:image/png;base64," alt="График исследования" /></figure>', 'source': '# PIT: применяем ФР skew-normal и обратную ФР нормального распределения.\n# Для генератора это должно давать N(0,1); для реальных данных — не обязательно.\nz_generated = to_standard_normal(alcohol_polar)\nz_real = to_standard_normal(alcohol_real)\nnormal_check = pd.DataFrame({\n    "сгенерированные": [z_generated.mean(), z_generated.std(ddof=1),\n                       stats.skew(z_generated), stats.kurtosis(z_generated),\n                       stats.kstest(z_generated, stats.norm.cdf).statistic],\n    "реальные": [z_real.mean(), z_real.std(ddof=1),\n                 stats.skew(z_real), stats.kurtosis(z_real),\n                 stats.kstest(z_real, stats.norm.cdf).statistic],\n}, index=["среднее", "std", "асимметрия", "эксцесс", "KS D к N(0,1)"])\ndisplay(normal_check.round(5))\n\nfig, ax = plt.subplots(figsize=(8.5, 4))\nax.hist(z_generated, bins=60, density=True, alpha=.55, color="#6389B8",\n        label="Преобразованный генератор")\nzz = np.linspace(-4, 4, 400)\nax.plot(zz, stats.norm.pdf(zz), lw=2, color="#C74343", label="N(0,1)")\nax.set(xlabel="Стандартная нормальная шкала", ylabel="Плотность",\n       title="Квантильное преобразование skew-normal → N(0,1)")\nax.legend(); ax.grid(alpha=.25)\nplt.tight_layout(); plt.show()\n'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><span class="paragraph"><strong>Вывод.</strong> Для сгенерированного из заданной непрерывной модели <marimo-tex class="arithmatex">||(X||)</marimo-tex> преобразование <marimo-tex class="arithmatex">||(\\Phi^{-1}(F_{SN}(X))||)</marimo-tex> восстанавливает стандартное нормальное распределение. Для исходной таблицы результат может отличаться от <marimo-tex class="arithmatex">||(N(0,1)||)</marimo-tex> из-за отклонения реальной формы от модели и повторяющихся округлённых значений. В отличие от простой <marimo-tex class="arithmatex">||(z||)</marimo-tex>-стандартизации, здесь используется <strong>вся функция распределения</strong>, а не только среднее и дисперсия.</span></span>', 'source': '**Вывод.** Для сгенерированного из заданной непрерывной модели $X$ преобразование $\\Phi^{-1}(F_{SN}(X))$ восстанавливает стандартное нормальное распределение. Для исходной таблицы результат может отличаться от $N(0,1)$ из-за отклонения реальной формы от модели и повторяющихся округлённых значений. В отличие от простой $z$-стандартизации, здесь используется **вся функция распределения**, а не только среднее и дисперсия.\n'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><h4 id="sprint2-heading-99-1"><span class="notebook-index">3.4.5</span>5. Сравнение скорости и качества трёх методов</h4></span>', 'source': '#### 5. Сравнение скорости и качества трёх методов\n'}, {'kind': 'code', 'html': '<div class="tbl-wrap"><div>\n<style scoped>\n    .dataframe tbody tr th:only-of-type {\n        vertical-align: middle;\n    }\n\n    .dataframe tbody tr th {\n        vertical-align: top;\n    }\n\n    .dataframe thead th {\n        text-align: right;\n    }\n</style>\n<table border="1" class="dataframe">\n  <thead>\n    <tr style="text-align: right;">\n      <th></th>\n      <th>метод</th>\n      <th>время, с (медиана 3 запусков)</th>\n      <th>среднее</th>\n      <th>std</th>\n      <th>KS D к своему закону</th>\n    </tr>\n  </thead>\n  <tbody>\n    <tr>\n      <th>0</th>\n      <td>Марсалья → skew-normal</td>\n      <td>0.00263</td>\n      <td>10.48165</td>\n      <td>1.28284</td>\n      <td>0.00258</td>\n    </tr>\n    <tr>\n      <th>1</th>\n      <td>Бокс–Мюллер → skew-normal</td>\n      <td>0.00381</td>\n      <td>10.46979</td>\n      <td>1.27341</td>\n      <td>0.00411</td>\n    </tr>\n    <tr>\n      <th>2</th>\n      <td>Эмпирическая обратная CDF</td>\n      <td>0.00357</td>\n      <td>10.51944</td>\n      <td>1.22990</td>\n      <td>0.00302</td>\n    </tr>\n  </tbody>\n</table>\n</div></div><pre class="numeric-result">Для двух skew-normal методов цель — теоретическая SN; для эмпирического — исходная таблица.\n</pre>', 'source': 'import time\nbench_rows = []\nfor title, method in [("Марсалья → skew-normal", "polar"),\n                      ("Бокс–Мюллер → skew-normal", "box_muller"),\n                      ("Эмпирическая обратная CDF", "empirical")]:\n    elapsed = []\n    values = None\n    for _ in range(3):\n        t0 = time.perf_counter()\n        values = alcohol_generator(100_000, seed=314, method=method,\n                                   data=alcohol_real if method == "empirical" else None)\n        elapsed.append(time.perf_counter() - t0)\n    ks_target = (stats.ks_2samp(values, alcohol_real).statistic if method == "empirical"\n                 else stats.kstest(values, alcohol_model.cdf).statistic)\n    bench_rows.append({"метод": title,\n                       "время, с (медиана 3 запусков)": np.median(elapsed),\n                       "среднее": values.mean(), "std": values.std(ddof=1),\n                       "KS D к своему закону": ks_target})\ndisplay(pd.DataFrame(bench_rows).round(5))\nprint("Для двух skew-normal методов цель — теоретическая SN; для эмпирического — исходная таблица.")\n'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><span class="paragraph"><strong>Вывод.</strong> Время сравнивается на одинаковом числе значений и фиксированном <code>seed</code>, а каждый метод оценивается относительно <strong>собственной цели</strong>: скошенного нормального или эмпирического закона. Более быстрое выполнение само по себе не означает более точного воспроизведения исходных данных. Реальная скорость зависит от версии Python, NumPy, SciPy и нагрузки на вычислительную среду.</span></span>', 'source': '**Вывод.** Время сравнивается на одинаковом числе значений и фиксированном `seed`, а каждый метод оценивается относительно **собственной цели**: скошенного нормального или эмпирического закона. Более быстрое выполнение само по себе не означает более точного воспроизведения исходных данных. Реальная скорость зависит от версии Python, NumPy, SciPy и нагрузки на вычислительную среду.\n'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><h4 id="sprint2-heading-102-1"><span class="notebook-index">3.4.6</span>6. Автотесты генератора</h4></span>', 'source': '#### 6. Автотесты генератора\n'}, {'kind': 'code', 'html': '<pre class="numeric-result">Overwriting tests/test_alcohol.py\n</pre>', 'source': '%%writefile tests/test_alcohol.py\nimport numpy as np\nimport pytest\nfrom scipy import stats\nfrom winegen.alcohol import (\n    alcohol_generator, polar_normal, box_muller_normal,\n    to_standard_normal, ALCOHOL_SHAPE, ALCOHOL_LOC, ALCOHOL_SCALE,\n)\n\nDATA = np.array([8.7, 9.5, 9.5, 10.0, 10.0, 10.0, 11.7, 12.2])\nMODEL = stats.skewnorm(ALCOHOL_SHAPE, loc=ALCOHOL_LOC, scale=ALCOHOL_SCALE)\n\n@pytest.mark.parametrize("method", ["polar", "box_muller", "empirical"])\ndef test_length_and_zero(method):\n    assert alcohol_generator(100, method=method, data=DATA).size == 100\n    assert alcohol_generator(0, method=method, data=DATA).size == 0\n\n@pytest.mark.parametrize("method", ["polar", "box_muller", "empirical"])\ndef test_seed_reproducibility(method):\n    a = alcohol_generator(300, seed=12, method=method, data=DATA)\n    b = alcohol_generator(300, seed=12, method=method, data=DATA)\n    assert np.array_equal(a, b)\n\n@pytest.mark.parametrize("bad_n", [-1, 2.5, "10", True])\ndef test_invalid_n(bad_n):\n    with pytest.raises((TypeError, ValueError)):\n        alcohol_generator(bad_n)\n\ndef test_invalid_method():\n    with pytest.raises(ValueError):\n        alcohol_generator(10, method="no_method")\n\ndef test_empirical_requires_data():\n    with pytest.raises(ValueError):\n        alcohol_generator(10, method="empirical")\n\n@pytest.mark.parametrize("bad_data", [[], [1.0, np.nan], [np.inf]])\ndef test_invalid_empirical_data(bad_data):\n    with pytest.raises(ValueError):\n        alcohol_generator(10, method="empirical", data=bad_data)\n\n@pytest.mark.parametrize("method", ["polar", "box_muller"])\ndef test_standard_normal(method):\n    rng = np.random.RandomState(7)\n    z = polar_normal(75_000, rng) if method == "polar" else box_muller_normal(75_000, rng)\n    assert abs(z.mean()) < 0.02\n    assert abs(z.std(ddof=1) - 1) < 0.02\n    assert stats.kstest(z, stats.norm.cdf).statistic < 0.012\n\n@pytest.mark.parametrize("method", ["polar", "box_muller"])\ndef test_skew_normal_against_theory(method):\n    x = alcohol_generator(80_000, seed=11, method=method)\n    assert np.isfinite(x).all()\n    assert abs(x.mean() - MODEL.mean()) < 0.04\n    assert abs(x.std(ddof=1) - MODEL.std()) < 0.04\n    assert stats.kstest(x, MODEL.cdf).statistic < 0.014\n\ndef test_two_methods_similar():\n    a = alcohol_generator(60_000, seed=1, method="polar")\n    b = alcohol_generator(60_000, seed=1, method="box_muller")\n    assert stats.ks_2samp(a, b).statistic < 0.02\n\ndef test_empirical_support_and_weights():\n    x = alcohol_generator(40_000, seed=17, method="empirical", data=DATA)\n    assert np.isin(x, DATA).all()\n    assert abs(np.mean(x == 10.0) - 3 / 8) < 0.015\n    assert stats.ks_2samp(x, DATA).statistic < 0.02\n\ndef test_normal_quantile_transform():\n    x = alcohol_generator(80_000, seed=23)\n    z = to_standard_normal(x)\n    assert abs(z.mean()) < 0.02\n    assert abs(z.std(ddof=1) - 1) < 0.02\n    assert stats.kstest(z, stats.norm.cdf).statistic < 0.014\n'}, {'kind': 'code', 'html': '<pre class="numeric-result">22 passed, 1 warning in 0.62s\nПроверенный запуск тестов генераторов.</pre>', 'source': '# Тестируем только свою часть; тесты pH и sugar остаются нетронутыми.\n!python -m pytest -q tests/test_alcohol.py\n'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><span class="paragraph"><strong>Вывод по автотестам.</strong> Проверяются корректная длина результата, нулевое и неверное <marimo-tex class="arithmatex">||(n||)</marimo-tex>, обработка недопустимых данных, повторяемость по <code>seed</code>, нормальность промежуточного источника, соответствие двум теоретическим распределениям, близость полярного метода и Бокса — Мюллера, эмпирические частоты и квантильное приведение к <marimo-tex class="arithmatex">||(N(0,1)||)</marimo-tex>. Численные критерии заданы с допуском на конечную выборку, а тесты воспроизводимы.</span></span>', 'source': '**Вывод по автотестам.** Проверяются корректная длина результата, нулевое и неверное $n$, обработка недопустимых данных, повторяемость по `seed`, нормальность промежуточного источника, соответствие двум теоретическим распределениям, близость полярного метода и Бокса — Мюллера, эмпирические частоты и квантильное приведение к $N(0,1)$. Численные критерии заданы с допуском на конечную выборку, а тесты воспроизводимы.\n'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><h3 id="sprint2-heading-106-1"><span class="notebook-index">3.5</span>Resume</h3></span>', 'source': '### Resume\n'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><span class="paragraph"><strong>Результат.</strong> Для случайной величины <code>alcohol</code> реализован собственный генератор скошенного нормального распределения на основе стохастического представления <marimo-tex class="arithmatex">||(X=\\xi+\\omega(\\delta|U|+\\sqrt{1-\\delta^2}V)||)</marimo-tex>. Нормальные величины <marimo-tex class="arithmatex">||(U,V||)</marimo-tex> получены двумя независимыми алгоритмами: полярным методом Марсальи и методом Бокса — Мюллера. Источником равномерных чисел служит MT19937, что обеспечивает воспроизводимость при фиксированном <code>seed</code>.</span>\n<span class="paragraph"><strong>Точность.</strong> Сравнение с теорией через моменты, квантили, графики плотности и CDF, а также расстояние KS позволяет отделить <strong>правильность самого генератора</strong> от <strong>качества подгонки модели</strong>. Скошенно-нормальное распределение лучше остальных проверенных кандидатов в спринте 1, но не повторяет пики и частоты округлённых измерений полностью.</span>\n<span class="paragraph"><strong>Альтернативный вариант.</strong> Дополнительно реализовано обратное эмпирическое квантильное преобразование. Оно сохраняет исходные значения и близкие к исходным частоты, но не генерирует непрерывные новые уровни содержания спирта. Для табличной имитации лучше оно; для гладкого статистического моделирования — скошенно-нормальный вариант.</span>\n<span class="paragraph"><strong>Приведение к <marimo-tex class="arithmatex">||(N(0,1)||)</marimo-tex>.</strong> Показано, что для непрерывной модели используется <marimo-tex class="arithmatex">||(\\Phi^{-1}(F_{SN}(X))||)</marimo-tex>, а не просто вычитание среднего и деление на стандартное отклонение.</span>\n<span class="paragraph"><strong>Ограничение.</strong> Реальная связь алкоголя и остаточного сахара отрицательная (<marimo-tex class="arithmatex">||(r\\approx-0{,}45||)</marimo-tex> в спринте 1). Независимая генерация трёх показателей не сохранит эти зависимости: для совместной генерации необходима многомерная модель.</span></span>', 'source': '**Результат.** Для случайной величины `alcohol` реализован собственный генератор скошенного нормального распределения на основе стохастического представления $X=\\xi+\\omega(\\delta|U|+\\sqrt{1-\\delta^2}V)$. Нормальные величины $U,V$ получены двумя независимыми алгоритмами: полярным методом Марсальи и методом Бокса — Мюллера. Источником равномерных чисел служит MT19937, что обеспечивает воспроизводимость при фиксированном `seed`.\n\n**Точность.** Сравнение с теорией через моменты, квантили, графики плотности и CDF, а также расстояние KS позволяет отделить **правильность самого генератора** от **качества подгонки модели**. Скошенно-нормальное распределение лучше остальных проверенных кандидатов в спринте 1, но не повторяет пики и частоты округлённых измерений полностью.\n\n**Альтернативный вариант.** Дополнительно реализовано обратное эмпирическое квантильное преобразование. Оно сохраняет исходные значения и близкие к исходным частоты, но не генерирует непрерывные новые уровни содержания спирта. Для табличной имитации лучше оно; для гладкого статистического моделирования — скошенно-нормальный вариант.\n\n**Приведение к $N(0,1)$.** Показано, что для непрерывной модели используется $\\Phi^{-1}(F_{SN}(X))$, а не просто вычитание среднего и деление на стандартное отклонение.\n\n**Ограничение.** Реальная связь алкоголя и остаточного сахара отрицательная ($r\\approx-0{,}45$ в спринте 1). Независимая генерация трёх показателей не сохранит эти зависимости: для совместной генерации необходима многомерная модель.\n'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><h2 id="sprint2-heading-108-1">Исследование алгоритмов датчиков (доп. баллы) — alcohol</h2></span>', 'source': '## Исследование алгоритмов датчиков (доп. баллы) — alcohol\n'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><table>\n<thead>\n<tr>\n<th>Алгоритм</th>\n<th>Распределение и механизм</th>\n<th>Применение</th>\n<th>Преимущества</th>\n<th>Ограничения</th>\n<th>Реализация</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Вихрь Мерсенна MT19937</td>\n<td>псевдослучайные <marimo-tex class="arithmatex">||(U(0,1)||)</marimo-tex></td>\n<td>исходный источник для моделирования</td>\n<td>воспроизводимость, большой период</td>\n<td>не криптографический</td>\n<td><code>np.random.RandomState</code></td>\n</tr>\n<tr>\n<td>Полярный метод Марсальи</td>\n<td><marimo-tex class="arithmatex">||(U(-1,1)^2\\to N(0,1)||)</marimo-tex>, отбор внутри круга</td>\n<td>нормальные числа в моделировании</td>\n<td>нет <code>sin</code> и <code>cos</code>, два нормальных значения за принятую пару</td>\n<td>часть кандидатов отбрасывается</td>\n<td><code>polar_normal</code></td>\n</tr>\n<tr>\n<td>Бокс — Мюллер</td>\n<td><marimo-tex class="arithmatex">||(U(0,1)^2\\to N(0,1)^2||)</marimo-tex></td>\n<td>эталонное преобразование для нормальных величин</td>\n<td>точная аналитическая формула, без отбрасывания</td>\n<td>используются <code>sin</code>, <code>cos</code>, <code>log</code></td>\n<td><code>box_muller_normal</code></td>\n</tr>\n<tr>\n<td>Стохастическое представление skew-normal</td>\n<td><marimo-tex class="arithmatex">||(\\delta\\vert U\\vert +\\sqrt{1-\\delta^2}V||)</marimo-tex></td>\n<td>моделирование асимметричных величин</td>\n<td>простая формула через нормальные величины</td>\n<td>модель может не отражать локальные пики данных</td>\n<td><code>skew_normal_latent</code></td>\n</tr>\n<tr>\n<td>Обратная эмпирическая CDF</td>\n<td><marimo-tex class="arithmatex">||(U\\to\\widehat F^{-1}(U)||)</marimo-tex></td>\n<td>бутстрэп, имитация частот наблюдений</td>\n<td>воспроизводит значения и частоты таблицы</td>\n<td>нет новых промежуточных значений</td>\n<td><code>empirical_inverse</code></td>\n</tr>\n<tr>\n<td>Квантильное преобразование</td>\n<td><marimo-tex class="arithmatex">||(\\Phi^{-1}(F_{SN}(x))||)</marimo-tex></td>\n<td>приведение непрерывной модели к <marimo-tex class="arithmatex">||(N(0,1)||)</marimo-tex></td>\n<td>использует полную форму распределения</td>\n<td>требует достаточно точного <marimo-tex class="arithmatex">||(F_{SN}||)</marimo-tex></td>\n<td><code>to_standard_normal</code></td>\n</tr>\n</tbody>\n</table>\n<span class="paragraph">Скорость и точность трёх непосредственно реализованных генераторов сравниваются в разделе <strong>Tests</strong>. Для эмпирического и для непрерывного вариантов используются разные целевые распределения.</span></span>', 'source': '| Алгоритм | Распределение и механизм | Применение | Преимущества | Ограничения | Реализация |\n|---|---|---|---|---|---|\n| Вихрь Мерсенна MT19937 | псевдослучайные $U(0,1)$ | исходный источник для моделирования | воспроизводимость, большой период | не криптографический | `np.random.RandomState` |\n| Полярный метод Марсальи | $U(-1,1)^2\\to N(0,1)$, отбор внутри круга | нормальные числа в моделировании | нет `sin` и `cos`, два нормальных значения за принятую пару | часть кандидатов отбрасывается | `polar_normal` |\n| Бокс — Мюллер | $U(0,1)^2\\to N(0,1)^2$ | эталонное преобразование для нормальных величин | точная аналитическая формула, без отбрасывания | используются `sin`, `cos`, `log` | `box_muller_normal` |\n| Стохастическое представление skew-normal | $\\delta|U|+\\sqrt{1-\\delta^2}V$ | моделирование асимметричных величин | простая формула через нормальные величины | модель может не отражать локальные пики данных | `skew_normal_latent` |\n| Обратная эмпирическая CDF | $U\\to\\widehat F^{-1}(U)$ | бутстрэп, имитация частот наблюдений | воспроизводит значения и частоты таблицы | нет новых промежуточных значений | `empirical_inverse` |\n| Квантильное преобразование | $\\Phi^{-1}(F_{SN}(x))$ | приведение непрерывной модели к $N(0,1)$ | использует полную форму распределения | требует достаточно точного $F_{SN}$ | `to_standard_normal` |\n\nСкорость и точность трёх непосредственно реализованных генераторов сравниваются в разделе **Tests**. Для эмпирического и для непрерывного вариантов используются разные целевые распределения.\n'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><h2 id="sprint2-heading-110-1">Литература — alcohol</h2>\n<ol>\n<li>Cortez P., Cerdeira A., Almeida F., Matos T., Reis J. <em>Wine Quality</em> [Dataset]. UCI Machine Learning Repository, 2009. <a href="https://doi.org/10.24432/C56S3T" rel="noopener" target="_blank">https://doi.org/10.24432/C56S3T</a></li>\n<li>Azzalini A. A class of distributions which includes the normal ones // <em>Scandinavian Journal of Statistics</em>. 1985. Vol. 12, No. 2. P. 171–178.</li>\n<li>Azzalini A., Capitanio A. Statistical applications of the multivariate skew-normal distribution // <em>Journal of the Royal Statistical Society B</em>. 1999. Vol. 61. P. 579–602. <a href="https://arxiv.org/abs/0911.2093" rel="noopener" target="_blank">https://arxiv.org/abs/0911.2093</a></li>\n<li>Marsaglia G., Bray T. A convenient method for generating normal variables // <em>SIAM Review</em>. 1964. Vol. 6, No. 3. P. 260–264.</li>\n<li>Box G. E. P., Muller M. E. A note on the generation of random normal deviates // <em>The Annals of Mathematical Statistics</em>. 1958. Vol. 29, No. 2. P. 610–611. <a href="https://doi.org/10.1214/aoms/1177706645" rel="noopener" target="_blank">https://doi.org/10.1214/aoms/1177706645</a></li>\n<li>Matsumoto M., Nishimura T. Mersenne Twister: A 623-dimensionally equidistributed uniform pseudo-random number generator // <em>ACM Transactions on Modeling and Computer Simulation</em>. 1998. Vol. 8, No. 1. P. 3–30.</li>\n<li>Devroye L. <em>Non-Uniform Random Variate Generation</em>. Springer, 1986. <a href="https://luc.devroye.org/rnbookindex.html" rel="noopener" target="_blank">https://luc.devroye.org/rnbookindex.html</a></li>\n<li>SciPy documentation: <code>scipy.stats.skewnorm</code>. <a href="https://docs.scipy.org/doc/scipy/reference/generated/scipy.stats.skewnorm.html" rel="noopener" target="_blank">https://docs.scipy.org/doc/scipy/reference/generated/scipy.stats.skewnorm.html</a></li>\n<li>NumPy documentation: <code>numpy.random.RandomState</code> (MT19937). <a href="https://numpy.org/doc/stable/reference/random/legacy.html" rel="noopener" target="_blank">https://numpy.org/doc/stable/reference/random/legacy.html</a></li>\n</ol></span>', 'source': '## Литература — alcohol\n\n1. Cortez P., Cerdeira A., Almeida F., Matos T., Reis J. *Wine Quality* [Dataset]. UCI Machine Learning Repository, 2009. https://doi.org/10.24432/C56S3T\n2. Azzalini A. A class of distributions which includes the normal ones // *Scandinavian Journal of Statistics*. 1985. Vol. 12, No. 2. P. 171–178.\n3. Azzalini A., Capitanio A. Statistical applications of the multivariate skew-normal distribution // *Journal of the Royal Statistical Society B*. 1999. Vol. 61. P. 579–602. https://arxiv.org/abs/0911.2093\n4. Marsaglia G., Bray T. A convenient method for generating normal variables // *SIAM Review*. 1964. Vol. 6, No. 3. P. 260–264.\n5. Box G. E. P., Muller M. E. A note on the generation of random normal deviates // *The Annals of Mathematical Statistics*. 1958. Vol. 29, No. 2. P. 610–611. https://doi.org/10.1214/aoms/1177706645\n6. Matsumoto M., Nishimura T. Mersenne Twister: A 623-dimensionally equidistributed uniform pseudo-random number generator // *ACM Transactions on Modeling and Computer Simulation*. 1998. Vol. 8, No. 1. P. 3–30.\n7. Devroye L. *Non-Uniform Random Variate Generation*. Springer, 1986. https://luc.devroye.org/rnbookindex.html\n8. SciPy documentation: `scipy.stats.skewnorm`. https://docs.scipy.org/doc/scipy/reference/generated/scipy.stats.skewnorm.html\n9. NumPy documentation: `numpy.random.RandomState` (MT19937). https://numpy.org/doc/stable/reference/random/legacy.html\n'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><h2 id="sprint2-heading-111-1">Lab resume — sprint 2 (общее)</h2></span>', 'source': '## Lab resume — sprint 2 (общее)\n'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><h3 id="sprint2-heading-112-1"><span class="notebook-index">4.1</span>Итоговая проверка автотестов всех генераторов</h3></span>', 'source': '### Итоговая проверка автотестов всех генераторов'}, {'kind': 'code', 'html': '<pre class="numeric-result">65 passed, 1 warning in 0.78s\nПроверенный запуск тестов генераторов.</pre>', 'source': '!python -m pytest -q tests'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><span class="paragraph">Три генератора охватывают разные свойства исходных измерений. Для <strong>pH</strong> реализовано сдвинутое лог-нормальное распределение, для <strong>residual sugar</strong> — эмпирическое распределение и гамма-модель, для <strong>alcohol</strong> — скошенное нормальное и эмпирический закон. Проверки включают математическое описание алгоритмов, сравнение характеристик с целевыми распределениями, визуализации и автоматические тесты.</span>\n<span class="paragraph"><strong>Ключевое ограничение.</strong> Проверяется качество отдельных <strong>маргинальных</strong> распределений. При независимой генерации pH, сахара и алкоголя не сохраняются эмпирические корреляции между признаками: для полноценного искусственного набора вин потребуется совместная модель.</span>\n<span class="paragraph"><strong>Проверяемость.</strong> Код разделён на <code>winegen/ph.py</code>, <code>winegen/sugar.py</code>, <code>winegen/alcohol.py</code>; тесты — на <code>tests/test_ph.py</code>, <code>tests/test_sugar.py</code>, <code>tests/test_alcohol.py</code>. Все файлы создаются соответствующими ячейками <code>%%writefile</code> при последовательном запуске ноутбука.</span></span>', 'source': 'Три генератора охватывают разные свойства исходных измерений. Для **pH** реализовано сдвинутое лог-нормальное распределение, для **residual sugar** — эмпирическое распределение и гамма-модель, для **alcohol** — скошенное нормальное и эмпирический закон. Проверки включают математическое описание алгоритмов, сравнение характеристик с целевыми распределениями, визуализации и автоматические тесты.\n\n**Ключевое ограничение.** Проверяется качество отдельных **маргинальных** распределений. При независимой генерации pH, сахара и алкоголя не сохраняются эмпирические корреляции между признаками: для полноценного искусственного набора вин потребуется совместная модель.\n\n**Проверяемость.** Код разделён на `winegen/ph.py`, `winegen/sugar.py`, `winegen/alcohol.py`; тесты — на `tests/test_ph.py`, `tests/test_sugar.py`, `tests/test_alcohol.py`. Все файлы создаются соответствующими ячейками `%%writefile` при последовательном запуске ноутбука.\n'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><h3 id="sprint2-heading-115-1"><span class="notebook-index">4.2</span>cat_mark_table — sprint 2</h3></span>', 'source': '### cat_mark_table — sprint 2\n'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><table>\n<thead>\n<tr>\n<th>cat_id</th>\n<th>notebook_link</th>\n<th style="text-align: right;">coeff</th>\n<th>comment</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Алгоритм генератора и математика</td>\n<td><a href="#sprint2-cell-1">pH</a> · <a href="#sprint2-cell-39">sugar</a> · <a href="#sprint2-cell-76">alcohol</a></td>\n<td style="text-align: right;">1</td>\n<td>три типа распределений; собственные преобразования из MT19937</td>\n</tr>\n<tr>\n<td>Проверка соответствия генератора теории</td>\n<td><a href="#sprint2-cell-12">Тесты pH</a> · <a href="#sprint2-cell-50">sugar</a> · <a href="#sprint2-cell-85">alcohol</a></td>\n<td style="text-align: right;">1</td>\n<td>моменты, квантили, KS, графики</td>\n</tr>\n<tr>\n<td>Сравнение с реальными данными</td>\n<td><a href="#sprint2-cell-85">Графики и метрики</a></td>\n<td style="text-align: right;">1</td>\n<td>статистики, визуализации, ограничения моделей</td>\n</tr>\n<tr>\n<td>Альтернативные алгоритмы</td>\n<td><a href="#sprint2-cell-108">Альтернативные методы</a></td>\n<td style="text-align: right;">1</td>\n<td>полярный метод, отношения, Бокс—Мюллер, квантильный, Нейман</td>\n</tr>\n<tr>\n<td>Математическое обоснование</td>\n<td><a href="#sprint2-cell-79">Математика</a></td>\n<td style="text-align: right;">1</td>\n<td>плотности, стохастические представления, преобразования</td>\n</tr>\n<tr>\n<td>Литература и методы</td>\n<td><a href="#sprint2-cell-110">Источники</a></td>\n<td style="text-align: right;">1</td>\n<td>книги, статьи, документация</td>\n</tr>\n<tr>\n<td>Автотесты генераторов</td>\n<td><a href="#sprint2-cell-102">Автотесты</a></td>\n<td style="text-align: right;">1</td>\n<td>параметры, воспроизводимость, соответствие законам</td>\n</tr>\n<tr>\n<td>Табличные итоговые метрики</td>\n<td><a href="#sprint2-cell-85">Таблицы</a></td>\n<td style="text-align: right;">1</td>\n<td>описательные статистики, статистики KS, бенчмарки</td>\n</tr>\n</tbody>\n</table>\n<span class="paragraph">Значения <code>coeff</code> в таблице — заявленные выполненные категории; фактическое оценивание остаётся за преподавателем.</span></span>', 'source': '| cat_id | notebook_link | coeff | comment |\n|---|---|---:|---|\n| Алгоритм генератора и математика | [pH](#scrollTo=YdLqs4sSZYju) · [sugar](#scrollTo=19f0e692) · [alcohol](#scrollTo=dbc54b98f8) | 1 | три типа распределений; собственные преобразования из MT19937 |\n| Проверка соответствия генератора теории | [Тесты pH](#scrollTo=WhR2AwbvZlGD) · [sugar](#scrollTo=9fc9bd51) · [alcohol](#scrollTo=1101d7b2fb) | 1 | моменты, квантили, KS, графики |\n| Сравнение с реальными данными | [Графики и метрики](#scrollTo=1101d7b2fb) | 1 | статистики, визуализации, ограничения моделей |\n| Альтернативные алгоритмы | [Альтернативные методы](#scrollTo=a9a88985d4) | 1 | полярный метод, отношения, Бокс—Мюллер, квантильный, Нейман |\n| Математическое обоснование | [Математика](#scrollTo=fe2db26b6e) | 1 | плотности, стохастические представления, преобразования |\n| Литература и методы | [Источники](#scrollTo=b18f427b27) | 1 | книги, статьи, документация |\n| Автотесты генераторов | [Автотесты](#scrollTo=9c15f051f3) | 1 | параметры, воспроизводимость, соответствие законам |\n| Табличные итоговые метрики | [Таблицы](#scrollTo=1101d7b2fb) | 1 | описательные статистики, статистики KS, бенчмарки |\n\nЗначения `coeff` в таблице — заявленные выполненные категории; фактическое оценивание остаётся за преподавателем.\n'}], 'uicrit': [{'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"></span>', 'source': '<a href="https://colab.research.google.com/drive/1uQRGACVyQVj8FsCbnmhHF_yVGJDOYaf0?usp=sharing" target="_parent"><img src="https://colab.research.google.com/assets/colab-badge.svg" alt="Open In Colab"/></a>'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><h1 id="uicrit-heading-1-1"><strong>Лабораторная 1 - доп КТвД</strong></h1></span>', 'source': '# **Лабораторная 1 - доп КТвД**'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><span class="paragraph"><a id="uicrit-data"></a></span>\n<h2 id="uicrit-heading-2-1"><strong>1. Датасет, его описание и загрузка</strong></h2>\n<h3 id="uicrit-heading-2-2"><strong>О датасете</strong></h3>\n<span class="paragraph"><strong>Данные для анализа:</strong>\nUICrit — это набор данных, который содержит написанные людьми текстовые замечания к дизайну, рамки (области экрана), к которым относится каждое замечание, и оценки качества дизайна для 1000 экранов мобильных приложений из набора RICO.</span>\n<span class="paragraph">По сути UICrit - это набор экранов мобильных приложений с оценками и замечаниями к их дизайну. Его суть - зафиксировать, как люди воспринимают интерфейсы: насколько они красивые, понятные и удобные.</span>\n<span class="paragraph">Нас зацепил этот датасет тем, что каждый экран оценивали 3 аннотатора, а у каждого замечания указан его источник: <code>human</code> — то, что заметил человек, <code>llm</code> — что заметила нейросеть (в датасете используется Gemini), и <code>both</code> — что заметили и человек, и нейросеть. Сами оценки в баллах ставили только люди. Благодаря этому отзывы на один продукт могут отличаться, что делает этот датасет достаточно разнообразным. Но дальше мы перейдем к анализу, и это будет еще интереснее :)</span>\n<span class="paragraph"><strong>Для начала разберемся, за что отвечает каждый столбец в датасете:</strong></span>\n<table>\n<thead>\n<tr>\n<th>Столбец</th>\n<th>Что содержит</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong><code>rico_id</code></strong></td>\n<td>Идентификатор экрана в исходном наборе RICO. Одинаковый ID в нескольких строках означает, что люди оценивали один и тот же экран.</td>\n</tr>\n<tr>\n<td><strong><code>task</code></strong></td>\n<td>Основная задача интерфейса: например, зарегистрироваться, найти товар или изменить настройки</td>\n</tr>\n<tr>\n<td><strong><code>aesthetics_rating</code></strong></td>\n<td>Оценка <strong>эстетики</strong> от <strong>1 до 10</strong>: насколько качественно и красиво выглядит интерфейс</td>\n</tr>\n<tr>\n<td><strong><code>learnability</code></strong></td>\n<td>Оценка <strong>интуитивной понятности</strong> от <strong>1 до 5</strong>: насколько легко человеку разобраться, что здесь можно делать и как</td>\n</tr>\n<tr>\n<td><strong><code>efficency</code></strong></td>\n<td>Оценка <strong>эффективности</strong> от <strong>1 до 5</strong>: насколько интерфейс, по мнению аннотатора, позволяет быстро выполнить задачу</td>\n</tr>\n<tr>\n<td><strong><code>usability_rating</code></strong></td>\n<td>Общая оценка <strong>удобства использования</strong> от <strong>1 до 10</strong>, с учётом понятности и эффективности.</td>\n</tr>\n<tr>\n<td><strong><code>design_quality_rating</code></strong></td>\n<td>Итоговая оценка <strong>качества дизайна</strong> от <strong>1 до 10</strong>, которую человек выставляет с учётом эстетики и удобства. Важное уточнение - это не всегда среднее арифметическое всех показателей!</td>\n</tr>\n<tr>\n<td><strong><code>comments_source</code></strong></td>\n<td>Список источников комментариев: <code>human</code> — замечание человека; <code>llm</code> — замечание Gemini, принятое человеком; <code>both</code> — проблему отметили и человек, и Gemini.</td>\n</tr>\n<tr>\n<td><strong><code>comments</code></strong></td>\n<td>Список самих замечаний к дизайну и координаты областей экрана, к которым они относятся. Координаты нормированы относительно размеров скриншота.</td>\n</tr>\n</tbody>\n</table>\n<blockquote>\n<span class="paragraph">Источник: <a href="https://github.com/google-research-datasets/uicrit/tree/main" rel="noopener" target="_blank">https://github.com/google-research-datasets/uicrit/tree/main</a></span>\n</blockquote></span>', 'source': '<a id="data"></a>\n## **1. Датасет, его описание и загрузка**\n\n### **О датасете**\n\n**Данные для анализа:**\nUICrit — это набор данных, который содержит написанные людьми текстовые замечания к дизайну, рамки (области экрана), к которым относится каждое замечание, и оценки качества дизайна для 1000 экранов мобильных приложений из набора RICO.\n\nПо сути UICrit - это набор экранов мобильных приложений с оценками и замечаниями к их дизайну. Его суть - зафиксировать, как люди воспринимают интерфейсы: насколько они красивые, понятные и удобные.\n\nНас зацепил этот датасет тем, что каждый экран оценивали 3 аннотатора, а у каждого замечания указан его источник: `human` — то, что заметил человек, `llm` — что заметила нейросеть (в датасете используется Gemini), и `both` — что заметили и человек, и нейросеть. Сами оценки в баллах ставили только люди. Благодаря этому отзывы на один продукт могут отличаться, что делает этот датасет достаточно разнообразным. Но дальше мы перейдем к анализу, и это будет еще интереснее :)\n\n\n**Для начала разберемся, за что отвечает каждый столбец в датасете:**\n\n| Столбец | Что содержит |\n|---|---|\n| **`rico_id`** | Идентификатор экрана в исходном наборе RICO. Одинаковый ID в нескольких строках означает, что люди оценивали один и тот же экран. |\n| **`task`** | Основная задача интерфейса: например, зарегистрироваться, найти товар или изменить настройки |\n| **`aesthetics_rating`** | Оценка **эстетики** от **1 до 10**: насколько качественно и красиво выглядит интерфейс |\n| **`learnability`** | Оценка **интуитивной понятности** от **1 до 5**: насколько легко человеку разобраться, что здесь можно делать и как |\n| **`efficency`** | Оценка **эффективности** от **1 до 5**: насколько интерфейс, по мнению аннотатора, позволяет быстро выполнить задачу |\n| **`usability_rating`** | Общая оценка **удобства использования** от **1 до 10**, с учётом понятности и эффективности. |\n| **`design_quality_rating`** | Итоговая оценка **качества дизайна** от **1 до 10**, которую человек выставляет с учётом эстетики и удобства. Важное уточнение - это не всегда среднее арифметическое всех показателей! |\n| **`comments_source`** | Список источников комментариев: `human` — замечание человека; `llm` — замечание Gemini, принятое человеком; `both` — проблему отметили и человек, и Gemini. |\n| **`comments`** | Список самих замечаний к дизайну и координаты областей экрана, к которым они относятся. Координаты нормированы относительно размеров скриншота. |\n\n\n\n> Источник: https://github.com/google-research-datasets/uicrit/tree/main\n\n'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><h3 id="uicrit-heading-3-1"><strong>Вопрос исследования и гипотеза</strong></h3>\n<span class="paragraph"><strong>Вопрос, который мы будем исследовать:</strong> Зависят ли друг от друга эстетика интерфейса и его удобство?</span>\n<span class="paragraph"><strong>Гипотеза, которую мы будем рассматривать в течение исследования:</strong> Показатель эстетики имеет положительную связь с показателем удобства - чем выше показатель эстетики, тем выше оценка удобства экрана приложения</span></span>', 'source': '### **Вопрос исследования и гипотеза**\n\n**Вопрос, который мы будем исследовать:** Зависят ли друг от друга эстетика интерфейса и его удобство?\n\n**Гипотеза, которую мы будем рассматривать в течение исследования:** Показатель эстетики имеет положительную связь с показателем удобства - чем выше показатель эстетики, тем выше оценка удобства экрана приложения'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><h3 id="uicrit-heading-4-1"><strong>Загрузка датасета в ноутбук</strong></h3></span>', 'source': '### **Загрузка датасета в ноутбук**'}, {'kind': 'code', 'html': '', 'source': '# но сначала подгрузим основные библиотеки и сам датасет в наш коллаб\n\n# Работа с таблицами и числовыми данными\nimport pandas as pd\nimport numpy as np\n\n# Построение графиков\nimport matplotlib.pyplot as plt\nimport seaborn as sns\n\n# Статистические расчёты и проверка гипотез\nfrom scipy import stats\n\n# Преобразование текстовых списков в настоящие списки Python\nimport ast\n\n# Удобный вывод таблиц\nfrom IPython.display import display\nimport ipywidgets as widgets\nfrom IPython.display import clear_output'}, {'kind': 'code', 'html': '', 'source': '# Единое оформление графиков\nsns.set_theme(style="whitegrid", palette="deep")\n\nplt.rcParams.update({\n    "figure.figsize": (10, 5),\n    "font.size": 12,\n    "axes.titlesize": 14,\n    "axes.labelsize": 12,\n    "figure.dpi": 110,\n})\n\n# Настройки отображения таблиц\npd.set_option("display.max_columns", None)\npd.set_option("display.max_colwidth", 100)\n\n# Для воспроизводимости случайных выборок и расчётов\nSEED = 42\nrng = np.random.default_rng(SEED)\n\n# Палитра для графиков раздела 5\nC = {\n    "ink": "#203747",\n    "muted": "#607D8B",\n    "paper": "#F4F9FC",\n    "grid": "#DFEBF2",\n    "data": "#559FCB",\n    "alt": "#36718F",\n    "ref": "#D58A55",\n    "gold": "#D5AD59",\n}'}, {'kind': 'code', 'html': '<div class="tbl-wrap"><div>\n<style scoped>\n    .dataframe tbody tr th:only-of-type {\n        vertical-align: middle;\n    }\n\n    .dataframe tbody tr th {\n        vertical-align: top;\n    }\n\n    .dataframe thead th {\n        text-align: right;\n    }\n</style>\n<table border="1" class="dataframe">\n  <thead>\n    <tr style="text-align: right;">\n      <th></th>\n      <th>rico_id</th>\n      <th>task</th>\n      <th>aesthetics_rating</th>\n      <th>learnability</th>\n      <th>efficency</th>\n      <th>usability_rating</th>\n      <th>design_quality_rating</th>\n      <th>comments_source</th>\n      <th>comments</th>\n    </tr>\n  </thead>\n  <tbody>\n    <tr>\n      <th>0</th>\n      <td>10089</td>\n      <td>Follow events to keep track on your favorite games/teams</td>\n      <td>6</td>\n      <td>3.0</td>\n      <td>3</td>\n      <td>6</td>\n      <td>6</td>\n      <td>[\'human\', \'human\', \'human\', \'human\', \'both\', \'both\', \'both\']</td>\n      <td>["Comment 1\\nThe expected standard is that the text’s visual treatment and formatting should mak...</td>\n    </tr>\n    <tr>\n      <th>1</th>\n      <td>10089</td>\n      <td>Explore the ACC Tournament schedules and match locations for the North Carolina team.</td>\n      <td>6</td>\n      <td>2.0</td>\n      <td>3</td>\n      <td>5</td>\n      <td>6</td>\n      <td>[\'human\', \'human\', \'human\', \'human\', \'human\', \'human\', \'both\']</td>\n      <td>[\'Comment 1\\nThe expected standard is to make the most important information visually dominant.\\...</td>\n    </tr>\n    <tr>\n      <th>2</th>\n      <td>10089</td>\n      <td>Check the sport\'s schedule .</td>\n      <td>7</td>\n      <td>4.0</td>\n      <td>4</td>\n      <td>7</td>\n      <td>7</td>\n      <td>[\'human\', \'human\', \'human\', \'both\']</td>\n      <td>[\'LLM Comment 1\\nThe expected standard is for UI elements, such as the menu icon, to be fully vi...</td>\n    </tr>\n    <tr>\n      <th>3</th>\n      <td>10112</td>\n      <td>Click "Register" or "Login" to join Eskimi.</td>\n      <td>7</td>\n      <td>3.0</td>\n      <td>4</td>\n      <td>7</td>\n      <td>7</td>\n      <td>[\'human\', \'human\', \'llm\', \'llm\', \'llm\']</td>\n      <td>[\'Comment 1\\nThe expected standard is that the design should be visually appealing and easy to u...</td>\n    </tr>\n    <tr>\n      <th>4</th>\n      <td>10112</td>\n      <td>Register or login to Eskimi</td>\n      <td>6</td>\n      <td>3.0</td>\n      <td>3</td>\n      <td>6</td>\n      <td>6</td>\n      <td>[\'human\', \'both\']</td>\n      <td>[\'Comment 1\\nThe expected tandard is to ensure sufficient contrast between buttons and their bac...</td>\n    </tr>\n  </tbody>\n</table>\n</div></div><pre class="numeric-result">Количество строк: 2981\nКоличество столбцов: 9\nКоличество уникальных экранов: 1000\n</pre>', 'source': '#теперь подгрузим наш датасет\n\n# Загружаем датасет из официального репозитория\nDATA_URL = (\n    "https://raw.githubusercontent.com/"\n    "google-research-datasets/uicrit/main/uicrit_public.csv"\n)\n\ndf = pd.read_csv(DATA_URL)\n\n# Показываем первые пять строк\ndisplay(df.head())\n\n# Проверяем размер таблицы\nprint("Количество строк:", df.shape[0])\nprint("Количество столбцов:", df.shape[1])\nprint("Количество уникальных экранов:", df["rico_id"].nunique())'}, {'kind': 'code', 'html': '<pre class="numeric-result">&lt;class &#x27;pandas.core.frame.DataFrame&#x27;&gt;\nRangeIndex: 2981 entries, 0 to 2980\nData columns (total 9 columns):\n #   Column                 Non-Null Count  Dtype  \n---  ------                 --------------  -----  \n 0   rico_id                2981 non-null   int64  \n 1   task                   2979 non-null   object \n 2   aesthetics_rating      2981 non-null   int64  \n 3   learnability           2980 non-null   float64\n 4   efficency              2981 non-null   int64  \n 5   usability_rating       2981 non-null   int64  \n 6   design_quality_rating  2981 non-null   int64  \n 7   comments_source        2981 non-null   object \n 8   comments               2981 non-null   object \ndtypes: float64(1), int64(5), object(3)\nmemory usage: 209.7+ KB\n</pre>', 'source': 'df.info()'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><h3 id="uicrit-heading-9-1">Проверка качества данных</h3>\n<span class="paragraph">Перед анализом проверим пропуски, полные дубликаты строк,\nдиапазоны оценок и количество записей для каждого экрана.\nИсходную таблицу пока не изменяем.</span></span>', 'source': '### Проверка качества данных\n\nПеред анализом проверим пропуски, полные дубликаты строк,\nдиапазоны оценок и количество записей для каждого экрана.\nИсходную таблицу пока не изменяем.'}, {'kind': 'code', 'html': '<div class="tbl-wrap"><div>\n<style scoped>\n    .dataframe tbody tr th:only-of-type {\n        vertical-align: middle;\n    }\n\n    .dataframe tbody tr th {\n        vertical-align: top;\n    }\n\n    .dataframe thead th {\n        text-align: right;\n    }\n</style>\n<table border="1" class="dataframe">\n  <thead>\n    <tr style="text-align: right;">\n      <th></th>\n      <th>Количество пропусков</th>\n    </tr>\n  </thead>\n  <tbody>\n    <tr>\n      <th>rico_id</th>\n      <td>0</td>\n    </tr>\n    <tr>\n      <th>task</th>\n      <td>2</td>\n    </tr>\n    <tr>\n      <th>aesthetics_rating</th>\n      <td>0</td>\n    </tr>\n    <tr>\n      <th>learnability</th>\n      <td>1</td>\n    </tr>\n    <tr>\n      <th>efficency</th>\n      <td>0</td>\n    </tr>\n    <tr>\n      <th>usability_rating</th>\n      <td>0</td>\n    </tr>\n    <tr>\n      <th>design_quality_rating</th>\n      <td>0</td>\n    </tr>\n    <tr>\n      <th>comments_source</th>\n      <td>0</td>\n    </tr>\n    <tr>\n      <th>comments</th>\n      <td>0</td>\n    </tr>\n  </tbody>\n</table>\n</div></div>', 'source': 'display(\n    df.isna().sum().to_frame(name="Количество пропусков")\n)'}, {'kind': 'code', 'html': '<pre class="numeric-result">Количество полных дубликатов: 0\n</pre>', 'source': 'print("Количество полных дубликатов:", df.duplicated().sum())'}, {'kind': 'code', 'html': '<div class="tbl-wrap"><div>\n<style scoped>\n    .dataframe tbody tr th:only-of-type {\n        vertical-align: middle;\n    }\n\n    .dataframe tbody tr th {\n        vertical-align: top;\n    }\n\n    .dataframe thead th {\n        text-align: right;\n    }\n</style>\n<table border="1" class="dataframe">\n  <thead>\n    <tr style="text-align: right;">\n      <th></th>\n      <th>Минимум</th>\n      <th>Максимум</th>\n      <th>Пропуски</th>\n      <th>Нечисловые значения</th>\n      <th>Вне диапазона</th>\n    </tr>\n    <tr>\n      <th>Столбец</th>\n      <th></th>\n      <th></th>\n      <th></th>\n      <th></th>\n      <th></th>\n    </tr>\n  </thead>\n  <tbody>\n    <tr>\n      <th>aesthetics_rating</th>\n      <td>1.0</td>\n      <td>10.0</td>\n      <td>0</td>\n      <td>0</td>\n      <td>0</td>\n    </tr>\n    <tr>\n      <th>learnability</th>\n      <td>1.0</td>\n      <td>5.0</td>\n      <td>1</td>\n      <td>0</td>\n      <td>0</td>\n    </tr>\n    <tr>\n      <th>efficency</th>\n      <td>1.0</td>\n      <td>5.0</td>\n      <td>0</td>\n      <td>0</td>\n      <td>0</td>\n    </tr>\n    <tr>\n      <th>usability_rating</th>\n      <td>1.0</td>\n      <td>10.0</td>\n      <td>0</td>\n      <td>0</td>\n      <td>0</td>\n    </tr>\n    <tr>\n      <th>design_quality_rating</th>\n      <td>1.0</td>\n      <td>9.0</td>\n      <td>0</td>\n      <td>0</td>\n      <td>0</td>\n    </tr>\n  </tbody>\n</table>\n</div></div>', 'source': '# проверяем допустимость оценок, чтобы наши данные соответсвовали основному диапозону\n\nrating_limits = {\n    "aesthetics_rating": (1, 10),\n    "learnability": (1, 5),\n    "efficency": (1, 5),\n    "usability_rating": (1, 10),\n    "design_quality_rating": (1, 10),\n}\n\nquality_rows = []\n\nfor column, (lower, upper) in rating_limits.items():\n    values = pd.to_numeric(df[column], errors="coerce")\n\n    quality_rows.append({\n        "Столбец": column,\n        "Минимум": values.min(),\n        "Максимум": values.max(),\n        "Пропуски": df[column].isna().sum(),\n        "Нечисловые значения": (\n            df[column].notna() & values.isna()\n        ).sum(),\n        "Вне диапазона": (\n            values.notna() & ~values.between(lower, upper)\n        ).sum(),\n    })\n\ndisplay(pd.DataFrame(quality_rows).set_index("Столбец"))'}, {'kind': 'code', 'html': '<div class="tbl-wrap"><div>\n<style scoped>\n    .dataframe tbody tr th:only-of-type {\n        vertical-align: middle;\n    }\n\n    .dataframe tbody tr th {\n        vertical-align: top;\n    }\n\n    .dataframe thead th {\n        text-align: right;\n    }\n</style>\n<table border="1" class="dataframe">\n  <thead>\n    <tr style="text-align: right;">\n      <th></th>\n      <th>Количество экранов</th>\n    </tr>\n    <tr>\n      <th>Количество записей на экран</th>\n      <th></th>\n    </tr>\n  </thead>\n  <tbody>\n    <tr>\n      <th>1</th>\n      <td>1</td>\n    </tr>\n    <tr>\n      <th>2</th>\n      <td>25</td>\n    </tr>\n    <tr>\n      <th>3</th>\n      <td>966</td>\n    </tr>\n    <tr>\n      <th>4</th>\n      <td>8</td>\n    </tr>\n  </tbody>\n</table>\n</div></div><pre class="numeric-result">Строк без идентификатора экрана: 0\n</pre>', 'source': 'ratings_per_screen = df.groupby("rico_id").size()\n\nscreen_counts = (\n    ratings_per_screen\n    .value_counts()\n    .sort_index()\n    .rename_axis("Количество записей на экран")\n    .to_frame(name="Количество экранов")\n)\n\ndisplay(screen_counts)\n\nprint("Строк без идентификатора экрана:", df["rico_id"].isna().sum())'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><h3 id="uicrit-heading-14-1">Вывод</h3>\n<span class="paragraph">Данные для исследования являются достаточно чистыми, нет потеряных строк(у всех есть свой идентификатор в rico_id) или вовсе пустых. Наблюдается только 1 пропуск в столбце <code>learnability</code> и 2 в <code>task</code>, который не влияет на основное исследование, поскольку мы анализируем оценки эстетики и удобства, в которых пропусков нет. НО количество записей на экран различается, поэтому при подготовке данных будем рассчитывать средние по фактически доступным корректным оценкам каждого экрана</span></span>', 'source': '### Вывод\n\nДанные для исследования являются достаточно чистыми, нет потеряных строк(у всех есть свой идентификатор в rico_id) или вовсе пустых. Наблюдается только 1 пропуск в столбце `learnability` и 2 в `task`, который не влияет на основное исследование, поскольку мы анализируем оценки эстетики и удобства, в которых пропусков нет. НО количество записей на экран различается, поэтому при подготовке данных будем рассчитывать средние по фактически доступным корректным оценкам каждого экрана\n\n'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><span class="paragraph"><a id="uicrit-random"></a></span>\n<h2 id="uicrit-heading-15-1"><strong>2. Случайные величины и обоснование их случайной природы</strong></h2>\n<h3 id="uicrit-heading-15-2"><strong>Какие величины мы будем исследовать</strong></h3>\n<span class="paragraph">В исследовании рассматриваются две величины:</span>\n<ul>\n<li><marimo-tex class="arithmatex">||(X||)</marimo-tex> — средняя оценка эстетики экрана;</li>\n<li><marimo-tex class="arithmatex">||(Y||)</marimo-tex> — средняя оценка удобства этого же экрана.</li>\n</ul>\n<span class="paragraph">Одна строка исходного датасета содержит оценки одного экрана\nодним аннотатором. Для основного анализа мы будем объединять\nзаписи по идентификатору <code>rico_id</code> и рассчитывать средние оценки.\nТаким образом, единицей наблюдения станет один экран.</span></span>', 'source': '<a id="random"></a>\n## **2. Случайные величины и обоснование их случайной природы**\n\n### **Какие величины мы будем исследовать**\n\nВ исследовании рассматриваются две величины:\n\n- $X$ — средняя оценка эстетики экрана;\n- $Y$ — средняя оценка удобства этого же экрана.\n\nОдна строка исходного датасета содержит оценки одного экрана\nодним аннотатором. Для основного анализа мы будем объединять\nзаписи по идентификатору `rico_id` и рассчитывать средние оценки.\nТаким образом, единицей наблюдения станет один экран.\n'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><h3 id="uicrit-heading-16-1"><strong>В чём заключается случайность эксперимента</strong></h3>\n<span class="paragraph">Представим, что мы случайным образом выбираем один экран\nиз набора UICrit. До выбора неизвестно, какой экран нам попадётся и какие оценки эстетики и удобства ему соответствуют.</span>\n<span class="paragraph">Таким образом, каждому возможному исходу для выбранного экрана\nсопоставляются два числовых значения: <marimo-tex class="arithmatex">||(X||)</marimo-tex> и <marimo-tex class="arithmatex">||(Y||)</marimo-tex>.\nПоэтому при случайном выборе экрана эти оценки рассматриваются\nкак случайные величины.</span>\n<h3 id="uicrit-heading-16-2">Почему оценки имеют стохастическую природу</h3>\n<span class="paragraph">Оценки основаны на человеческом восприятии интерфейса.\nНа них могут влиять опыт аннотатора, его визуальные предпочтения\nи понимание задачи экрана, поэтому разные люди могут оценивать\nодин и тот же интерфейс по-разному, даже используя общие критерии</span>\n<span class="paragraph">В рамках исследования мы не располагаем правилом, которое\nоднозначно определяет человеческую оценку по внешнему виду экрана.\nПри этом оценки не произвольны: аннотаторы руководствовались\nкритериями качества дизайна.</span>\n<h3 id="uicrit-heading-16-3">Почему усреднение не устраняет случайность</h3>\n<span class="paragraph">Для каждого экрана средние оценки рассчитываются по формулам:</span>\n<marimo-tex class="arithmatex">||[\nX_i = \\frac{1}{m_i}\\sum_{j=1}^{m_i} x_{ij},\n\\qquad\nY_i = \\frac{1}{m_i}\\sum_{j=1}^{m_i} y_{ij},\n||]</marimo-tex><span class="paragraph">где <marimo-tex class="arithmatex">||(m_i||)</marimo-tex> — число используемых оценок экрана <marimo-tex class="arithmatex">||(i||)</marimo-tex>,\nа <marimo-tex class="arithmatex">||(x_{ij}||)</marimo-tex> и <marimo-tex class="arithmatex">||(y_{ij}||)</marimo-tex> — оценки эстетики и удобства,\nвыставленные аннотатором <marimo-tex class="arithmatex">||(j||)</marimo-tex>.</span>\n<span class="paragraph">Формулы позволяют получить среднее по уже известным оценкам,\nно не предсказывают исходные оценки заранее.\nПри случайном выборе экрана его средние оценки также\nявляются случайными величинами.</span></span>', 'source': '### **В чём заключается случайность эксперимента**\n\nПредставим, что мы случайным образом выбираем один экран\nиз набора UICrit. До выбора неизвестно, какой экран нам попадётся и какие оценки эстетики и удобства ему соответствуют.\n\nТаким образом, каждому возможному исходу для выбранного экрана\nсопоставляются два числовых значения: $X$ и $Y$.\nПоэтому при случайном выборе экрана эти оценки рассматриваются\nкак случайные величины.\n\n### Почему оценки имеют стохастическую природу\n\nОценки основаны на человеческом восприятии интерфейса.\nНа них могут влиять опыт аннотатора, его визуальные предпочтения\nи понимание задачи экрана, поэтому разные люди могут оценивать\nодин и тот же интерфейс по-разному, даже используя общие критерии\n\nВ рамках исследования мы не располагаем правилом, которое\nоднозначно определяет человеческую оценку по внешнему виду экрана.\nПри этом оценки не произвольны: аннотаторы руководствовались\nкритериями качества дизайна.\n\n### Почему усреднение не устраняет случайность\n\nДля каждого экрана средние оценки рассчитываются по формулам:\n\n$$\nX_i = \\frac{1}{m_i}\\sum_{j=1}^{m_i} x_{ij},\n\\qquad\nY_i = \\frac{1}{m_i}\\sum_{j=1}^{m_i} y_{ij},\n$$\n\nгде $m_i$ — число используемых оценок экрана $i$,\nа $x_{ij}$ и $y_{ij}$ — оценки эстетики и удобства,\nвыставленные аннотатором $j$.\n\nФормулы позволяют получить среднее по уже известным оценкам,\nно не предсказывают исходные оценки заранее.\nПри случайном выборе экрана его средние оценки также\nявляются случайными величинами.'}, {'kind': 'code', 'html': '<pre class="numeric-result">Случайный выбор экрана доступен в интерактивном блоке сайта.\n</pre>', 'source': '# это просто визуальный пример для понимания выборки\n\ndemo_data = df[\n    ["rico_id", "aesthetics_rating", "usability_rating"]\n].copy()\n\nfor column in ["aesthetics_rating", "usability_rating"]:\n    demo_data[column] = pd.to_numeric(\n        demo_data[column], errors="coerce"\n    )\n\ndemo_data = demo_data.loc[\n    demo_data["rico_id"].notna()\n    & demo_data["aesthetics_rating"].between(1, 10)\n    & demo_data["usability_rating"].between(1, 10)\n].copy()\n\n# Выбираем среди уникальных экранов:\n# каждый экран имеет одинаковую вероятность выбора\nscreen_ids = demo_data["rico_id"].unique()\n\n# Отдельный генератор для интерактива\ndemo_rng = np.random.default_rng(SEED)\n\nbutton = widgets.Button(\n    description="Выбрать случайный экран",\n    layout=widgets.Layout(width="260px")\n)\n\noutput = widgets.Output()\n\n\ndef show_random_screen(_=None):\n    screen_id = demo_rng.choice(screen_ids)\n    ratings = demo_data.loc[\n        demo_data["rico_id"] == screen_id\n    ]\n\n    aesthetics = ratings["aesthetics_rating"].to_numpy()\n    usability = ratings["usability_rating"].to_numpy()\n\n    means = [aesthetics.mean(), usability.mean()]\n\n    with output:\n        clear_output(wait=True)\n\n        print(f"ID экрана: {screen_id}")\n        print(f"Количество пар оценок: {len(ratings)}")\n        print(\n            f"Средняя эстетика: {means[0]:.2f} | "\n            f"Среднее удобство: {means[1]:.2f}"\n        )\n\n        fig, ax = plt.subplots(figsize=(8, 4))\n\n        ax.bar(\n            [0, 1],\n            means,\n            width=0.5,\n            color=sns.color_palette("deep", 2),\n            alpha=0.5,\n            label="Средняя оценка"\n        )\n\n        # Небольшое горизонтальное смещение,\n        # чтобы одинаковые оценки не перекрывались\n        offsets = np.linspace(-0.13, 0.13, len(ratings))\n\n        ax.scatter(\n            offsets,\n            aesthetics,\n            color="black",\n            s=45,\n            zorder=3,\n            label="Отдельные оценки"\n        )\n        ax.scatter(\n            1 + offsets,\n            usability,\n            color="black",\n            s=45,\n            zorder=3\n        )\n\n        ax.set_xticks([0, 1])\n        ax.set_xticklabels(["Эстетика", "Удобство"])\n        ax.set_ylabel("Оценка, баллы")\n        ax.set_ylim(0, 10.7)\n        ax.set_yticks(range(0, 11))\n        ax.set_title(f"Оценки выбранного экрана {screen_id}")\n        ax.legend(loc="upper center", bbox_to_anchor=(0.5, -0.16),\n                  ncol=2)\n\n        plt.tight_layout()\n        plt.show()\n\n\nbutton.on_click(show_random_screen)\n\ndisplay(button, output)\nshow_random_screen()'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><h3 id="uicrit-heading-18-1"><strong>Вывод</strong></h3>\n<span class="paragraph">Случайность нашей выборки основывается на случайности величин за счет случайно выбранного экрана: то есть случайный выбор экрана дает нам данные величин для дальнейшего анализа и заранее неизвестно, какие данные мы получим. Также это можно подкрепить человеческим фактором: оценка все равно не является чем-то предсказуемым, тк у аннотаторов могут быть разные взгляды на один и тот же интерфейс(могут влиять личный опыт аннотатора, предпочтения и т.д.)</span></span>', 'source': '### **Вывод**\n\nСлучайность нашей выборки основывается на случайности величин за счет случайно выбранного экрана: то есть случайный выбор экрана дает нам данные величин для дальнейшего анализа и заранее неизвестно, какие данные мы получим. Также это можно подкрепить человеческим фактором: оценка все равно не является чем-то предсказуемым, тк у аннотаторов могут быть разные взгляды на один и тот же интерфейс(могут влиять личный опыт аннотатора, предпочтения и т.д.)'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><span class="paragraph"><a id="uicrit-eda"></a></span>\n<h2 id="uicrit-heading-19-1"><strong>3. EDA для случайных величин</strong></h2>\n<span class="paragraph">Перед тем, как перейти к анализу, необходимо подготовить данные. Для этого объединим оценки по идентификатору экрана, а для каждого экрана рассчитаем средние оценки эстетики и удобства и сохраним количество использованных оценок.</span>\n<span class="paragraph">В дальнейшем одна строка будет соответствовать одному экрану, а каждый экран будет иметь одинаковый вес в анализе.</span></span>', 'source': '<a id="eda"></a>\n## **3. EDA для случайных величин**\n\nПеред тем, как перейти к анализу, необходимо подготовить данные. Для этого объединим оценки по идентификатору экрана, а для каждого экрана рассчитаем средние оценки эстетики и удобства и сохраним количество использованных оценок.\n\nВ дальнейшем одна строка будет соответствовать одному экрану, а каждый экран будет иметь одинаковый вес в анализе.'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><h3 id="uicrit-heading-20-1">Подготовка данных</h3></span>', 'source': '### Подготовка данных'}, {'kind': 'code', 'html': '<div class="tbl-wrap"><div>\n<style scoped>\n    .dataframe tbody tr th:only-of-type {\n        vertical-align: middle;\n    }\n\n    .dataframe tbody tr th {\n        vertical-align: top;\n    }\n\n    .dataframe thead th {\n        text-align: right;\n    }\n</style>\n<table border="1" class="dataframe">\n  <thead>\n    <tr style="text-align: right;">\n      <th></th>\n      <th>rico_id</th>\n      <th>aesthetics_mean</th>\n      <th>usability_mean</th>\n      <th>n_ratings</th>\n    </tr>\n  </thead>\n  <tbody>\n    <tr>\n      <th>0</th>\n      <td>15</td>\n      <td>5.33</td>\n      <td>5.33</td>\n      <td>3</td>\n    </tr>\n    <tr>\n      <th>1</th>\n      <td>28</td>\n      <td>5.00</td>\n      <td>4.67</td>\n      <td>3</td>\n    </tr>\n    <tr>\n      <th>2</th>\n      <td>67</td>\n      <td>5.67</td>\n      <td>5.00</td>\n      <td>3</td>\n    </tr>\n    <tr>\n      <th>3</th>\n      <td>190</td>\n      <td>6.67</td>\n      <td>6.67</td>\n      <td>3</td>\n    </tr>\n    <tr>\n      <th>4</th>\n      <td>193</td>\n      <td>5.00</td>\n      <td>5.33</td>\n      <td>3</td>\n    </tr>\n    <tr>\n      <th>5</th>\n      <td>233</td>\n      <td>4.33</td>\n      <td>5.00</td>\n      <td>3</td>\n    </tr>\n    <tr>\n      <th>6</th>\n      <td>288</td>\n      <td>5.00</td>\n      <td>4.67</td>\n      <td>3</td>\n    </tr>\n    <tr>\n      <th>7</th>\n      <td>342</td>\n      <td>5.33</td>\n      <td>5.00</td>\n      <td>3</td>\n    </tr>\n    <tr>\n      <th>8</th>\n      <td>422</td>\n      <td>6.00</td>\n      <td>5.67</td>\n      <td>3</td>\n    </tr>\n    <tr>\n      <th>9</th>\n      <td>445</td>\n      <td>6.67</td>\n      <td>6.67</td>\n      <td>3</td>\n    </tr>\n  </tbody>\n</table>\n</div></div><pre class="numeric-result">rico_id            0\naesthetics_mean    0\nusability_mean     0\nn_ratings          0\ndtype: int64</pre><pre class="numeric-result">Количество экранов: 1000\nПропуски в итоговой таблице:\n</pre>', 'source': 'analysis_rows = df[\n    ["rico_id", "aesthetics_rating", "usability_rating"]\n].copy()\n\nscreens = (\n    analysis_rows\n    .groupby("rico_id", as_index=False)\n    .agg(\n        aesthetics_mean=("aesthetics_rating", "mean"),\n        usability_mean=("usability_rating", "mean"),\n        n_ratings=("aesthetics_rating", "size")\n    )\n)\n\ndisplay(screens.head(10).round(2))\n\nprint("Количество экранов:", len(screens))\nprint("Пропуски в итоговой таблице:")\ndisplay(screens.isna().sum())'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><h3 id="uicrit-heading-22-1"><strong>3.1 EDA &amp; Distribution средней оценки эстетики</strong></h3>\n<span class="paragraph">Рассмотрим распределение средней оценки эстетики случайно выбранного экрана.</span>\n<span class="paragraph">Выясним:</span>\n<ul>\n<li>какие оценки наиболее характерны;</li>\n<li>насколько сильно оценки различаются между экранами;</li>\n<li>симметрично ли распределение;</li>\n<li>встречаются ли необычно низкие или высокие значения.</li>\n</ul></span>', 'source': '### **3.1 EDA & Distribution средней оценки эстетики**\nРассмотрим распределение средней оценки эстетики случайно выбранного экрана.\n\nВыясним:\n* какие оценки наиболее характерны;\n* насколько сильно оценки различаются между экранами;\n* симметрично ли распределение;\n* встречаются ли необычно низкие или высокие значения.'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><h4 id="uicrit-heading-23-1"><strong>Описательные статистики</strong></h4>\n<span class="paragraph">Рассчитаем характеристики центра, разброса и формы распределения. Каждый экран участвует в анализе с одинаковым весом.</span></span>', 'source': '#### **Описательные статистики**\nРассчитаем характеристики центра, разброса и формы распределения. Каждый экран участвует в анализе с одинаковым весом.'}, {'kind': 'code', 'html': '<div class="tbl-wrap"><div>\n<style scoped>\n    .dataframe tbody tr th:only-of-type {\n        vertical-align: middle;\n    }\n\n    .dataframe tbody tr th {\n        vertical-align: top;\n    }\n\n    .dataframe thead th {\n        text-align: right;\n    }\n</style>\n<table border="1" class="dataframe">\n  <thead>\n    <tr style="text-align: right;">\n      <th></th>\n      <th>Средняя оценка эстетики</th>\n    </tr>\n  </thead>\n  <tbody>\n    <tr>\n      <th>Количество экранов</th>\n      <td>1000.000</td>\n    </tr>\n    <tr>\n      <th>Среднее</th>\n      <td>5.748</td>\n    </tr>\n    <tr>\n      <th>Медиана</th>\n      <td>5.667</td>\n    </tr>\n    <tr>\n      <th>Стандартное отклонение</th>\n      <td>0.642</td>\n    </tr>\n    <tr>\n      <th>Выборочная дисперсия</th>\n      <td>0.412</td>\n    </tr>\n    <tr>\n      <th>Минимум</th>\n      <td>3.667</td>\n    </tr>\n    <tr>\n      <th>Первый квартиль (Q1)</th>\n      <td>5.333</td>\n    </tr>\n    <tr>\n      <th>Третий квартиль (Q3)</th>\n      <td>6.333</td>\n    </tr>\n    <tr>\n      <th>Максимум</th>\n      <td>7.667</td>\n    </tr>\n    <tr>\n      <th>Межквартильный размах (IQR)</th>\n      <td>1.000</td>\n    </tr>\n    <tr>\n      <th>Асимметрия</th>\n      <td>-0.309</td>\n    </tr>\n  </tbody>\n</table>\n</div></div>', 'source': 'x = screens["aesthetics_mean"]\n\nq1 = x.quantile(0.25)\nq3 = x.quantile(0.75)\niqr = q3 - q1\n\naesthetics_summary = pd.Series({\n    "Количество экранов": x.count(),\n    "Среднее": x.mean(),\n    "Медиана": x.median(),\n    "Стандартное отклонение": x.std(ddof=1),\n    "Выборочная дисперсия": x.var(ddof=1),\n    "Минимум": x.min(),\n    "Первый квартиль (Q1)": q1,\n    "Третий квартиль (Q3)": q3,\n    "Максимум": x.max(),\n    "Межквартильный размах (IQR)": iqr,\n    "Асимметрия": x.skew(),\n}, name="Средняя оценка эстетики")\n\ndisplay(aesthetics_summary.to_frame().round(3))'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><h4 id="uicrit-heading-25-1"><strong>Распределение: гистограмма с моделями, boxplot и Q–Q</strong></h4>\n<span class="paragraph">Слева показаны данные и две подобранные по ним математические модели. Высота столбиков — плотность, а не количество экранов: суммарная площадь столбиков равна 1. Это позволяет сравнивать гистограмму с кривыми плотности.</span>\n<ul>\n<li>Нормальная модель — симметричный колокол. По данным оцениваются центр μ и масштаб σ.</li>\n<li>Бета-модель — гибкая форма, ограниченная интервалом. Фиксируем границы исходной шкалы [1, 10] и оцениваем параметры формы α и β. Удобство модели не гарантирует её соответствия данным.</li>\n<li>Boxplot показывает медиану, интервал Q1–Q3 и наблюдения за пределами усов 1,5 IQR. Эти наблюдения автоматически не удаляем.</li>\n<li>Q–Q к нормальному сопоставляет наблюдаемые и нормальные квантили. Близость к прямой означает приблизительное сходство формы, а не доказательство нормальности.</li>\n</ul>\n<span class="paragraph">Средние оценки принимают отдельные значения. Обе кривые — непрерывные приближения. Их плотность не является вероятностью конкретного балла. Горизонтальные ступени Q–Q связаны с повторяющимися средними. Для читаемости графики приближены к диапазону наблюдений; исходная шкала остаётся 1–10.</span></span>', 'source': '#### **Распределение: гистограмма с моделями, boxplot и Q–Q**\n\nСлева показаны данные и две подобранные по ним математические модели. Высота столбиков — плотность, а не количество экранов: суммарная площадь столбиков равна 1. Это позволяет сравнивать гистограмму с кривыми плотности.\n\n* Нормальная модель — симметричный колокол. По данным оцениваются центр μ и масштаб σ.\n* Бета-модель — гибкая форма, ограниченная интервалом. Фиксируем границы исходной шкалы [1, 10] и оцениваем параметры формы α и β. Удобство модели не гарантирует её соответствия данным.\n* Boxplot показывает медиану, интервал Q1–Q3 и наблюдения за пределами усов 1,5 IQR. Эти наблюдения автоматически не удаляем.\n* Q–Q к нормальному сопоставляет наблюдаемые и нормальные квантили. Близость к прямой означает приблизительное сходство формы, а не доказательство нормальности.\n\nСредние оценки принимают отдельные значения. Обе кривые — непрерывные приближения. Их плотность не является вероятностью конкретного балла. Горизонтальные ступени Q–Q связаны с повторяющимися средними. Для читаемости графики приближены к диапазону наблюдений; исходная шкала остаётся 1–10.'}, {'kind': 'code', 'html': '<figure class="plot plot-wide"><img width="1772" height="540" decoding="async" data-report-asset="./public/reports/uicrit/26-0.png" src="data:image/png;base64," alt="График исследования" /></figure><pre class="numeric-result">Нормальная модель: μ = 5.748, σ = 0.642\nБета-модель на [1, 10]: α = 25.334, β = 22.701\n</pre>', 'source': '# Все расчёты выполняются по средним оценкам экранов\nv = screens["aesthetics_mean"].dropna().to_numpy()\nmu, sigma = stats.norm.fit(v)\n# Границы шкалы фиксированы: loc=1, scale=9, то есть [1, 10]\na, b, loc, scale = stats.beta.fit(v, floc=1, fscale=9)\n\nprint(f"Нормальная модель: μ = {mu:.3f}, σ = {sigma:.3f}")\nprint(f"Бета-модель на [1, 10]: α = {a:.3f}, β = {b:.3f}")\n\nfig, axes = plt.subplots(\n    1, 3, figsize=(16, 4.8),\n    gridspec_kw={"width_ratios": [1.5, 0.65, 1.2]},\n    constrained_layout=True\n)\ncolor, accent = "#7463C7", "#DB8744"\nlo = max(1, np.floor(v.min()) - 0.5)\nhi = min(10, np.ceil(v.max()) + 0.5)\ngrid = np.linspace(lo, hi, 600)\nq1, q3 = np.quantile(v, [0.25, 0.75])\n\naxes[0].hist(v, bins=np.arange(lo, hi + 0.25, 0.5), density=True,\n             color=color, alpha=0.4, edgecolor="white", label="Данные")\naxes[0].plot(grid, stats.norm.pdf(grid, mu, sigma),\n             color="#3976AB", lw=2, label="Нормальное")\naxes[0].plot(grid, stats.beta.pdf(grid, a, b, loc=loc, scale=scale),\n             color=accent, lw=2, linestyle="--", label="Бета на [1, 10]")\naxes[0].set(title="Гистограмма и модели", xlabel="Средняя эстетика, баллы",\n            ylabel="Плотность", xlim=(lo, hi))\naxes[0].legend(frameon=False, fontsize=9)\n\naxes[1].boxplot(v, vert=True, widths=0.45, patch_artist=True,\n    boxprops={"facecolor": color, "alpha": 0.45},\n    medianprops={"color": accent, "linewidth": 2},\n    flierprops={"marker": "o", "markersize": 4,\n                "markerfacecolor": color, "markeredgecolor": color})\naxes[1].set(title="Ящик с усами", ylabel="Средняя эстетика, баллы", ylim=(lo, hi))\naxes[1].set_xticks([])\n\n(theoretical, observed), (slope, intercept, _) = stats.probplot(v, dist="norm")\naxes[2].scatter(theoretical, observed, s=10, color=color, alpha=0.5, edgecolors="none")\naxes[2].plot(theoretical, intercept + slope * theoretical, color=accent, lw=2)\naxes[2].set(title="Q–Q к нормальному", xlabel="Теоретические квантили N(0, 1)",\n            ylabel="Наблюдаемые оценки, баллы", ylim=(lo, hi))\nfor ax in axes:\n    ax.grid(alpha=0.2)\n    ax.set_axisbelow(True)\n    ax.spines["top"].set_visible(False)\n    ax.spines["right"].set_visible(False)\nfig.suptitle("Средняя оценка эстетики · исходная шкала 1–10", fontsize=15)\nplt.show()\n'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><h4 id="uicrit-heading-27-1"><strong>Выводы по эстетике</strong></h4>\n<span class="paragraph">По таблице мы можем увидеть, что исследованы 1000 экранов, каждый с одинаковым весом. Средняя оценка эстетики составляет 5.748, медиана — 5.667 балла(можем заметить, что значения достаточно близки друг к другу). Центральные 50% наблюдений находятся между 5.333 и 6.333 балла, те центральную часть распределения показывает сам ящик между квартилями, хотя расстояние между квартилями составляет всего 1 балл. У самого ящика большая часть значений сконцентрированы внутри, но ниже нижнего уса видна отдельная точка, которая показывает значение оценки экрана, отличное от общей части, и эта оценка достаточно низкая.</span>\n<span class="paragraph">Асиметричность -0.309 показывает небольшой перекос в сторону низких оценок: нижний хвост несколько выраженнее, но при этом визуально график близок к симметричному</span>\n<span class="paragraph">Что касается гистограммы, самый высокий столбик сосредоточен в районе 6-6.5 баллов, те максимальное колчиество экранов получили оценку в этом диапозоне. Форма моделей и самого графика в целом совпадает, но не идеально, но все равно в отличие от формы колокола и бета-модели у гистограммы есть 2 локальные пики, но их выраженность зависит от разбиения на интервалы</span>\n<span class="paragraph">На графике Q-Q значения имеют ступенчатый вид, поскольку оценки повторяются, а также они максимально приближены к прямой, но крайние значения имеют небольшие отклонения, особенно в нижней части(возможно это связано как раз с нашей ассиметричностью, которая как раз имеет небольшой перекос именно в этой части). Это говорит нам о том, что значения максимально похоже на нормальное, но опять же график не гарантирует ее</span></span>', 'source': '#### **Выводы по эстетике**\n\nПо таблице мы можем увидеть, что исследованы 1000 экранов, каждый с одинаковым весом. Средняя оценка эстетики составляет 5.748, медиана — 5.667 балла(можем заметить, что значения достаточно близки друг к другу). Центральные 50% наблюдений находятся между 5.333 и 6.333 балла, те центральную часть распределения показывает сам ящик между квартилями, хотя расстояние между квартилями составляет всего 1 балл. У самого ящика большая часть значений сконцентрированы внутри, но ниже нижнего уса видна отдельная точка, которая показывает значение оценки экрана, отличное от общей части, и эта оценка достаточно низкая.\n\nАсиметричность -0.309 показывает небольшой перекос в сторону низких оценок: нижний хвост несколько выраженнее, но при этом визуально график близок к симметричному\n\nЧто касается гистограммы, самый высокий столбик сосредоточен в районе 6-6.5 баллов, те максимальное колчиество экранов получили оценку в этом диапозоне. Форма моделей и самого графика в целом совпадает, но не идеально, но все равно в отличие от формы колокола и бета-модели у гистограммы есть 2 локальные пики, но их выраженность зависит от разбиения на интервалы\n\nНа графике Q-Q значения имеют ступенчатый вид, поскольку оценки повторяются, а также они максимально приближены к прямой, но крайние значения имеют небольшие отклонения, особенно в нижней части(возможно это связано как раз с нашей ассиметричностью, которая как раз имеет небольшой перекос именно в этой части). Это говорит нам о том, что значения максимально похоже на нормальное, но опять же график не гарантирует ее'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><h3 id="uicrit-heading-28-1"><strong>3.2. EDA &amp; Distribution средней оценки удобства</strong></h3>\n<span class="paragraph">Изучим среднюю оценку удобства случайно выбранного экрана:\nеё типичные значения, разброс и форму распределения.</span>\n<span class="paragraph">Каждое наблюдение соответствует одному экрану.\nРассматриваем экспертную оценку удобства по изображению интерфейса, а не результаты измерения скорости выполнения задач пользователями.</span></span>', 'source': '### **3.2. EDA & Distribution средней оценки удобства**\n\nИзучим среднюю оценку удобства случайно выбранного экрана:\nеё типичные значения, разброс и форму распределения.\n\nКаждое наблюдение соответствует одному экрану.\nРассматриваем экспертную оценку удобства по изображению интерфейса, а не результаты измерения скорости выполнения задач пользователями.'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><h4 id="uicrit-heading-29-1"><strong>Описательные статистики</strong></h4>\n<span class="paragraph">Аналогично эстетике измерим те же показатели у удобства интерфейса</span></span>', 'source': '#### **Описательные статистики**\n\nАналогично эстетике измерим те же показатели у удобства интерфейса'}, {'kind': 'code', 'html': '<div class="tbl-wrap"><div>\n<style scoped>\n    .dataframe tbody tr th:only-of-type {\n        vertical-align: middle;\n    }\n\n    .dataframe tbody tr th {\n        vertical-align: top;\n    }\n\n    .dataframe thead th {\n        text-align: right;\n    }\n</style>\n<table border="1" class="dataframe">\n  <thead>\n    <tr style="text-align: right;">\n      <th></th>\n      <th>Средняя оценка удобства</th>\n    </tr>\n  </thead>\n  <tbody>\n    <tr>\n      <th>Количество экранов</th>\n      <td>1000.000</td>\n    </tr>\n    <tr>\n      <th>Среднее</th>\n      <td>5.816</td>\n    </tr>\n    <tr>\n      <th>Медиана</th>\n      <td>5.667</td>\n    </tr>\n    <tr>\n      <th>Стандартное отклонение</th>\n      <td>0.643</td>\n    </tr>\n    <tr>\n      <th>Выборочная дисперсия</th>\n      <td>0.414</td>\n    </tr>\n    <tr>\n      <th>Минимум</th>\n      <td>3.333</td>\n    </tr>\n    <tr>\n      <th>Первый квартиль (Q1)</th>\n      <td>5.333</td>\n    </tr>\n    <tr>\n      <th>Третий квартиль (Q3)</th>\n      <td>6.333</td>\n    </tr>\n    <tr>\n      <th>Максимум</th>\n      <td>7.667</td>\n    </tr>\n    <tr>\n      <th>Межквартильный размах (IQR)</th>\n      <td>1.000</td>\n    </tr>\n    <tr>\n      <th>Асимметрия</th>\n      <td>-0.134</td>\n    </tr>\n  </tbody>\n</table>\n</div></div>', 'source': 'y = screens["usability_mean"].dropna()\n\nusability_summary = pd.Series({\n    "Количество экранов": y.count(),\n    "Среднее": y.mean(),\n    "Медиана": y.median(),\n    "Стандартное отклонение": y.std(ddof=1),\n    "Выборочная дисперсия": y.var(ddof=1),\n    "Минимум": y.min(),\n    "Первый квартиль (Q1)": y.quantile(0.25),\n    "Третий квартиль (Q3)": y.quantile(0.75),\n    "Максимум": y.max(),\n    "Межквартильный размах (IQR)": (\n        y.quantile(0.75) - y.quantile(0.25)\n    ),\n    "Асимметрия": y.skew(),\n}, name="Средняя оценка удобства")\n\ndisplay(usability_summary.to_frame().round(3))'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><h4 id="uicrit-heading-31-1"><strong>Распределение: гистограмма с моделями, boxplot и Q–Q</strong></h4>\n<span class="paragraph">На гистограмме сравним данные с нормальной и бета-моделями.\nГраницы бета-распределения фиксируем по исходной шкале: от 1 до 10.\nОбе модели являются непрерывными приближениями дискретных средних оценок.</span>\n<span class="paragraph">Boxplot покажет медиану, квартили и наблюдения за пределами усов.\nQ–Q позволит оценить, где форма распределения отличается от нормальной.</span></span>', 'source': '#### **Распределение: гистограмма с моделями, boxplot и Q–Q**\n\nНа гистограмме сравним данные с нормальной и бета-моделями.\nГраницы бета-распределения фиксируем по исходной шкале: от 1 до 10.\nОбе модели являются непрерывными приближениями дискретных средних оценок.\n\nBoxplot покажет медиану, квартили и наблюдения за пределами усов.\nQ–Q позволит оценить, где форма распределения отличается от нормальной.'}, {'kind': 'code', 'html': '<figure class="plot plot-wide"><img width="1772" height="540" decoding="async" data-report-asset="./public/reports/uicrit/32-0.png" src="data:image/png;base64," alt="График исследования" /></figure><pre class="numeric-result">Нормальная модель: μ = 5.816, σ = 0.643\nБета-модель на [1, 10]: α = 25.525, β = 22.179\n</pre>', 'source': 'from scipy import stats\n\nu_values = y.to_numpy()\n\n# Подбираем параметры моделей по данным\nu_mu, u_sigma = stats.norm.fit(u_values)\n\n# Бета-модель с фиксированными границами [1, 10]\nu_a, u_b, u_loc, u_scale = stats.beta.fit(\n    u_values,\n    floc=1,\n    fscale=9\n)\n\nprint(\n    f"Нормальная модель: "\n    f"μ = {u_mu:.3f}, σ = {u_sigma:.3f}"\n)\nprint(\n    f"Бета-модель на [1, 10]: "\n    f"α = {u_a:.3f}, β = {u_b:.3f}"\n)\n\n# Общий диапазон для сравнения с эстетикой\nboth_values = screens[\n    ["aesthetics_mean", "usability_mean"]\n].to_numpy()\n\nplot_lower = max(1, np.floor(np.nanmin(both_values)) - 0.5)\nplot_upper = min(10, np.ceil(np.nanmax(both_values)) + 0.5)\n\nu_grid = np.linspace(plot_lower, plot_upper, 600)\nu_bins = np.arange(plot_lower, plot_upper + 0.25, 0.5)\n\ncolor = "#438F92"\naccent = "#DB8744"\n\nfig, axes = plt.subplots(\n    1, 3,\n    figsize=(16, 4.8),\n    gridspec_kw={"width_ratios": [1.5, 0.65, 1.2]},\n    constrained_layout=True\n)\n\n# 1. Гистограмма и теоретические модели\naxes[0].hist(\n    u_values,\n    bins=u_bins,\n    density=True,\n    color=color,\n    alpha=0.4,\n    edgecolor="white",\n    label="Данные"\n)\n\naxes[0].plot(\n    u_grid,\n    stats.norm.pdf(u_grid, u_mu, u_sigma),\n    color="#3976AB",\n    linewidth=2,\n    label="Нормальное"\n)\n\naxes[0].plot(\n    u_grid,\n    stats.beta.pdf(\n        u_grid, u_a, u_b,\n        loc=u_loc,\n        scale=u_scale\n    ),\n    color=accent,\n    linewidth=2,\n    linestyle="--",\n    label="Бета на [1, 10]"\n)\n\naxes[0].set(\n    title="Гистограмма и модели",\n    xlabel="Среднее удобство, баллы",\n    ylabel="Плотность",\n    xlim=(plot_lower, plot_upper)\n)\naxes[0].legend(frameon=False, fontsize=9)\n\n# 2. Boxplot\naxes[1].boxplot(\n    u_values,\n    vert=True,\n    widths=0.45,\n    patch_artist=True,\n    boxprops={\n        "facecolor": color,\n        "alpha": 0.45\n    },\n    medianprops={\n        "color": accent,\n        "linewidth": 2\n    },\n    flierprops={\n        "marker": "o",\n        "markersize": 4,\n        "markerfacecolor": color,\n        "markeredgecolor": color,\n        "alpha": 0.6\n    }\n)\n\naxes[1].set(\n    title="Ящик с усами",\n    ylabel="Среднее удобство, баллы",\n    ylim=(plot_lower, plot_upper)\n)\naxes[1].set_xticks([])\n\n# 3. Q–Q к нормальному распределению\n(u_theoretical, u_observed), (\n    u_slope, u_intercept, _\n) = stats.probplot(u_values, dist="norm")\n\naxes[2].scatter(\n    u_theoretical,\n    u_observed,\n    s=10,\n    color=color,\n    alpha=0.5,\n    edgecolors="none"\n)\n\naxes[2].plot(\n    u_theoretical,\n    u_intercept + u_slope * u_theoretical,\n    color=accent,\n    linewidth=2\n)\n\naxes[2].set(\n    title="Q–Q к нормальному",\n    xlabel="Теоретические квантили N(0, 1)",\n    ylabel="Наблюдаемые оценки, баллы",\n    ylim=(plot_lower, plot_upper)\n)\n\nfor ax in axes:\n    ax.grid(alpha=0.2)\n    ax.set_axisbelow(True)\n    ax.spines["top"].set_visible(False)\n    ax.spines["right"].set_visible(False)\n\nfig.suptitle(\n    "Средняя оценка удобства · исходная шкала 1–10",\n    fontsize=15\n)\n\nplt.show()'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><h4 id="uicrit-heading-33-1"><strong>Выводы по удобству</strong></h4>\n<span class="paragraph">Настолько подробно расписывать этот график не имеет смысла, поскольку он максимально похож на предыдущий: и по значениям, и по визуальной составляющей</span>\n<span class="paragraph">Хочется отметить, что у ящика с усами значения буквально совпадают с эстетикой, но при этом ниже усов видны уже 2 отдельные точки, которые отображают оценку меньше основной массы.</span>\n<span class="paragraph">Асиметрия у удобства ниже - удобство чуть симметричнее эстетики, что особенно заметно на графике Q-Q</span>\n<span class="paragraph">Также у гистограммы удобства 2 пика выражены меньше, чем у эстетики, при этом форма нормальной и бета-модели также остаются приближенными. Самый высокий столбик снова соответствует интервалу 6–6,5 балла</span></span>', 'source': '#### **Выводы по удобству**\n\nНастолько подробно расписывать этот график не имеет смысла, поскольку он максимально похож на предыдущий: и по значениям, и по визуальной составляющей\n\nХочется отметить, что у ящика с усами значения буквально совпадают с эстетикой, но при этом ниже усов видны уже 2 отдельные точки, которые отображают оценку меньше основной массы.\n\nАсиметрия у удобства ниже - удобство чуть симметричнее эстетики, что особенно заметно на графике Q-Q\n\nТакже у гистограммы удобства 2 пика выражены меньше, чем у эстетики, при этом форма нормальной и бета-модели также остаются приближенными. Самый высокий столбик снова соответствует интервалу 6–6,5 балла\n\n\n\n'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><h3 id="uicrit-heading-34-1">3.3. <strong>Проверка нормальности и численное сравнение моделей</strong></h3>\n<span class="paragraph">Можно также дополнить визуальное сравнение численными характеристиками, для этого проверяем оба показателя на уровне средних оценок экранов с помощью Шапиро — Уилка. До этого мы оценивали по гистограмме совпадение, а сейчас проверим согласованность наших данных с этим нормальным распределением</span>\n<span class="paragraph"><strong>Шапиро — Уилк:</strong> <marimo-tex class="arithmatex">||(H_0||)</marimo-tex> — распределение нормальное; <marimo-tex class="arithmatex">||(H_1||)</marimo-tex> — отличается от нормального. Используем <marimo-tex class="arithmatex">||(\\alpha = 0{,}05||)</marimo-tex> и поправку Холма для двух проверок. Оценки дискретны и ограничены, поэтому нормальная модель — лишь приближение. Отклонение <marimo-tex class="arithmatex">||(H_0||)</marimo-tex> не запрещает её использование для описания данных или расчёт корреляций.</span>\n<span class="paragraph"><strong>Сравнение моделей:</strong> рассматриваем нормальное и бета-распределение с фиксированными границами <marimo-tex class="arithmatex">||([1, 10]||)</marimo-tex>.</span>\n<marimo-tex class="arithmatex">||[\n\\mathrm{AIC} = 2k - 2\\ln \\hat{L},\n||]</marimo-tex><span class="paragraph">где <marimo-tex class="arithmatex">||(k = 2||)</marimo-tex> для обеих моделей, а <marimo-tex class="arithmatex">||(\\hat{L}||)</marimo-tex> — максимальное правдоподобие. Меньший AIC предпочтительнее при сравнении моделей одного показателя. Для дискретных оценок это описательное сравнение непрерывных приближений, а не поиск истинного распределения.</span>\n<span class="paragraph"><strong>Расстояние между распределениями:</strong></span>\n<marimo-tex class="arithmatex">||[\nD = \\sup_x \\left|F_n(x) - F_{\\hat{\\theta}}(x)\\right|,\n||]</marimo-tex><span class="paragraph">где <marimo-tex class="arithmatex">||(F_n||)</marimo-tex> — эмпирическая функция распределения, а <marimo-tex class="arithmatex">||(F_{\\hat{\\theta}}||)</marimo-tex> — подобранная модель. Чем меньше <marimo-tex class="arithmatex">||(D||)</marimo-tex>, тем ближе распределения. Стандартное p-value теста KS не используем из-за оценки параметров на тех же данных и повторяющихся значений.</span>\n<span class="paragraph">Обе метрики описывают подгонку на исходных данных. Проверки предполагают независимость экранов; возможные связи через приложения и оценщиков остаются ограничением.</span></span>', 'source': '### 3.3. **Проверка нормальности и численное сравнение моделей**\n\nМожно также дополнить визуальное сравнение численными характеристиками, для этого проверяем оба показателя на уровне средних оценок экранов с помощью Шапиро — Уилка. До этого мы оценивали по гистограмме совпадение, а сейчас проверим согласованность наших данных с этим нормальным распределением\n\n**Шапиро — Уилк:** $H_0$ — распределение нормальное; $H_1$ — отличается от нормального. Используем $\\alpha = 0{,}05$ и поправку Холма для двух проверок. Оценки дискретны и ограничены, поэтому нормальная модель — лишь приближение. Отклонение $H_0$ не запрещает её использование для описания данных или расчёт корреляций.\n\n**Сравнение моделей:** рассматриваем нормальное и бета-распределение с фиксированными границами $[1, 10]$.\n\n$$\n\\mathrm{AIC} = 2k - 2\\ln \\hat{L},\n$$\n\nгде $k = 2$ для обеих моделей, а $\\hat{L}$ — максимальное правдоподобие. Меньший AIC предпочтительнее при сравнении моделей одного показателя. Для дискретных оценок это описательное сравнение непрерывных приближений, а не поиск истинного распределения.\n\n**Расстояние между распределениями:**\n\n$$\nD = \\sup_x \\left|F_n(x) - F_{\\hat{\\theta}}(x)\\right|,\n$$\n\nгде $F_n$ — эмпирическая функция распределения, а $F_{\\hat{\\theta}}$ — подобранная модель. Чем меньше $D$, тем ближе распределения. Стандартное p-value теста KS не используем из-за оценки параметров на тех же данных и повторяющихся значений.\n\nОбе метрики описывают подгонку на исходных данных. Проверки предполагают независимость экранов; возможные связи через приложения и оценщиков остаются ограничением.'}, {'kind': 'code', 'html': '<div class="tbl-wrap"><div>\n<style scoped>\n    .dataframe tbody tr th:only-of-type {\n        vertical-align: middle;\n    }\n\n    .dataframe tbody tr th {\n        vertical-align: top;\n    }\n\n    .dataframe thead th {\n        text-align: right;\n    }\n</style>\n<table border="1" class="dataframe">\n  <thead>\n    <tr style="text-align: right;">\n      <th></th>\n      <th>Показатель</th>\n      <th>n</th>\n      <th>W</th>\n      <th>p-value</th>\n      <th>p-value Холма</th>\n      <th>Отвергаем нормальность</th>\n    </tr>\n  </thead>\n  <tbody>\n    <tr>\n      <th>0</th>\n      <td>Эстетика</td>\n      <td>1000</td>\n      <td>0.972162</td>\n      <td>6.417e-13</td>\n      <td>1.283e-12</td>\n      <td>True</td>\n    </tr>\n    <tr>\n      <th>1</th>\n      <td>Удобство</td>\n      <td>1000</td>\n      <td>0.976766</td>\n      <td>1.481e-11</td>\n      <td>1.481e-11</td>\n      <td>True</td>\n    </tr>\n  </tbody>\n</table>\n</div></div><div class="tbl-wrap"><div>\n<style scoped>\n    .dataframe tbody tr th:only-of-type {\n        vertical-align: middle;\n    }\n\n    .dataframe tbody tr th {\n        vertical-align: top;\n    }\n\n    .dataframe thead th {\n        text-align: right;\n    }\n</style>\n<table border="1" class="dataframe">\n  <thead>\n    <tr style="text-align: right;">\n      <th></th>\n      <th>Показатель</th>\n      <th>Модель</th>\n      <th>Оцениваемых параметров k</th>\n      <th>AIC (непрерывное приближение)</th>\n      <th>Расстояние D</th>\n      <th>ΔAIC внутри показателя</th>\n    </tr>\n  </thead>\n  <tbody>\n    <tr>\n      <th>0</th>\n      <td>Эстетика</td>\n      <td>Нормальное</td>\n      <td>2</td>\n      <td>1954.8657</td>\n      <td>0.1217</td>\n      <td>1.1854</td>\n    </tr>\n    <tr>\n      <th>1</th>\n      <td>Эстетика</td>\n      <td>Бета [1, 10]</td>\n      <td>2</td>\n      <td>1953.6803</td>\n      <td>0.1187</td>\n      <td>0.0000</td>\n    </tr>\n    <tr>\n      <th>2</th>\n      <td>Удобство</td>\n      <td>Нормальное</td>\n      <td>2</td>\n      <td>1958.6139</td>\n      <td>0.1091</td>\n      <td>0.2121</td>\n    </tr>\n    <tr>\n      <th>3</th>\n      <td>Удобство</td>\n      <td>Бета [1, 10]</td>\n      <td>2</td>\n      <td>1958.4018</td>\n      <td>0.1083</td>\n      <td>0.0000</td>\n    </tr>\n  </tbody>\n</table>\n</div></div>', 'source': 'distribution_test_rows, model_comparison_rows = [], []\nfor metric_name, column in {"Эстетика": "aesthetics_mean", "Удобство": "usability_mean"}.items():\n    values = screens[column].dropna().to_numpy()\n    shapiro_result = stats.shapiro(values)\n    distribution_test_rows.append({"Показатель": metric_name, "n": len(values),\n        "W": shapiro_result.statistic, "p-value": shapiro_result.pvalue})\n    normal_params = stats.norm.fit(values)\n    beta_params = stats.beta.fit(values, floc=1, fscale=9)\n    sorted_values = np.sort(values)\n    for model_name, distribution, params in [\n        ("Нормальное", stats.norm, normal_params),\n        ("Бета [1, 10]", stats.beta, beta_params)]:\n        log_likelihood = distribution.logpdf(values, *params).sum()\n        fitted_cdf = distribution.cdf(sorted_values, *params)\n        # Максимальное расхождение с правой и левой границами ступеней ECDF.\n        d_plus = np.max(np.arange(1, len(values)+1)/len(values) - fitted_cdf)\n        d_minus = np.max(fitted_cdf - np.arange(len(values))/len(values))\n        model_comparison_rows.append({"Показатель": metric_name, "Модель": model_name,\n            "Оцениваемых параметров k": 2, "AIC (непрерывное приближение)": 4-2*log_likelihood,\n            "Расстояние D": max(d_plus, d_minus)})\ndistribution_tests = pd.DataFrame(distribution_test_rows)\npvals = distribution_tests["p-value"].to_numpy()\norder = np.argsort(pvals)\nadjusted = np.empty(len(pvals))\nadjusted[order] = np.minimum(1, np.maximum.accumulate(\n    (len(pvals)-np.arange(len(pvals))) * pvals[order]))\ndistribution_tests["p-value Холма"] = adjusted\ndistribution_tests["Отвергаем нормальность"] = adjusted < .05\nmodel_comparisons = pd.DataFrame(model_comparison_rows)\nmodel_comparisons["ΔAIC внутри показателя"] = (\n    model_comparisons["AIC (непрерывное приближение)"]\n    - model_comparisons.groupby("Показатель")["AIC (непрерывное приближение)"].transform("min"))\ndistribution_display = distribution_tests.copy()\nfor p_column in ["p-value", "p-value Холма"]:\n    distribution_display[p_column] = distribution_display[p_column].map(lambda value: f"{value:.3e}")\ndisplay(distribution_display)\ndisplay(model_comparisons.round(4))'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><h4 id="uicrit-heading-36-1"><strong>Вывод</strong></h4>\n<span class="paragraph">График действительно имеет некоторую схожесть визуально с нормальным распределением, но по таблицам мы видим, что показатель p-value заметно ниже нашего порога 0.05, поэтому нормальность мы отрицаем</span>\n<span class="paragraph">На второй таблице мы сравниваем нормальную и бета-модели по AIC и D. У бета-распределения оба значения немного меньше, однако различия\nмежду моделями невелики. Поэтому рассматриваем их как приближённое\nописание распределений средних оценок.</span></span>', 'source': '####**Вывод**\n\nГрафик действительно имеет некоторую схожесть визуально с нормальным распределением, но по таблицам мы видим, что показатель p-value заметно ниже нашего порога 0.05, поэтому нормальность мы отрицаем\n\nНа второй таблице мы сравниваем нормальную и бета-модели по AIC и D. У бета-распределения оба значения немного меньше, однако различия\nмежду моделями невелики. Поэтому рассматриваем их как приближённое\nописание распределений средних оценок.'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><h3 id="uicrit-heading-37-1"><strong>Общие выводы по эстетике и удобству</strong></h3>\n<span class="paragraph">Хочется в первую очередь отметить, что графики эстетики и удобства и по значениям, и визуально очень похожи друг на друга: у них близкие центр, разброс и форма, а некоторые числовые характеристики совпадают.  Оба распределения визуально близки к симметричным, с небольшим перекосом в сторону низких оценок, где у удобства этот перекос выражен слабее. Несмотря на то, что графики очень похожи между собой, это не доказывает их зависимость. Также благодаря проверки нормальности мы убедились в том, что несмотря на визуальное соответствие гистограмм с нормальным распределением, гипотеза нормальности отвергается для обоих показателей, так что модели просто дают приближенное описание данных.</span>\n<span class="paragraph">Чтобы не предполагать на схожести данных о их зависимости, тк это вообще не является достоверным подтверждением гипотезы, на следующем этапе исследуем зависимость, сопоставляя пары оценок каждого экрана</span></span>', 'source': '### **Общие выводы по эстетике и удобству**\n\nХочется в первую очередь отметить, что графики эстетики и удобства и по значениям, и визуально очень похожи друг на друга: у них близкие центр, разброс и форма, а некоторые числовые характеристики совпадают.  Оба распределения визуально близки к симметричным, с небольшим перекосом в сторону низких оценок, где у удобства этот перекос выражен слабее. Несмотря на то, что графики очень похожи между собой, это не доказывает их зависимость. Также благодаря проверки нормальности мы убедились в том, что несмотря на визуальное соответствие гистограмм с нормальным распределением, гипотеза нормальности отвергается для обоих показателей, так что модели просто дают приближенное описание данных.\n\nЧтобы не предполагать на схожести данных о их зависимости, тк это вообще не является достоверным подтверждением гипотезы, на следующем этапе исследуем зависимость, сопоставляя пары оценок каждого экрана'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><span class="paragraph"><a id="uicrit-dependence"></a></span>\n<h2 id="uicrit-heading-38-1"><strong>4. Зависимость эстетики и удобства</strong></h2>\n<span class="paragraph">Проверим, связана ли средняя оценка эстетики экрана со средней оценкой его удобства.</span>\n<span class="paragraph">Каждая точка соответствует одному экрану:</span>\n<ul>\n<li>по горизонтали — средняя оценка эстетики;</li>\n<li>по вертикали — средняя оценка удобства.</li>\n</ul>\n<span class="paragraph">Точки полупрозрачные: чем темнее место на графике, тем больше экранов с такой парой средних оценок.</span>\n<span class="paragraph">МНК — метод наименьших квадратов: он подбирает прямую, минимизируя сумму квадратов вертикальных отклонений точек.</span></span>', 'source': '<a id="dependence"></a>\n## **4. Зависимость эстетики и удобства**\n\nПроверим, связана ли средняя оценка эстетики экрана со средней оценкой его удобства.\n\nКаждая точка соответствует одному экрану:\n- по горизонтали — средняя оценка эстетики;\n- по вертикали — средняя оценка удобства.\n\nТочки полупрозрачные: чем темнее место на графике, тем больше экранов с такой парой средних оценок.\n\nМНК — метод наименьших квадратов: он подбирает прямую, минимизируя сумму квадратов вертикальных отклонений точек.'}, {'kind': 'code', 'html': '<figure class="plot plot-square"><img width="609" height="642" decoding="async" data-report-asset="./public/reports/uicrit/39-0.png" src="data:image/png;base64," alt="График исследования" /></figure>', 'source': '# Сохраняем пары оценок одних и тех же экранов\ndependence_data = screens[\n    ["aesthetics_mean", "usability_mean"]\n].dropna()\n\ndep_x = dependence_data["aesthetics_mean"].to_numpy()\ndep_y = dependence_data["usability_mean"].to_numpy()\n\n# Линейная регрессия: Y ≈ intercept + slope * X\nregression = stats.linregress(dep_x, dep_y)\n\nline_x = np.linspace(dep_x.min(), dep_x.max(), 200)\nline_y = regression.intercept + regression.slope * line_x\n\nfig, ax = plt.subplots(figsize=(10, 6))\n\nax.scatter(\n    dep_x,\n    dep_y,\n    s=45,\n    color="#7463C7",\n    alpha=0.35,\n    edgecolors="white",\n    linewidths=0.4,\n    label=f"Экраны, n = {len(dependence_data)}"\n)\n\nax.plot(\n    line_x,\n    line_y,\n    color="#252525",\n    linestyle="--",\n    linewidth=2.2,\n    label=(\n        f"МНК: Y ≈ {regression.intercept:.2f} "\n        f"{regression.slope:+.2f}·X"\n    )\n)\n\nlower = max(1, np.floor(min(dep_x.min(), dep_y.min())) - 0.5)\nupper = min(10, np.ceil(max(dep_x.max(), dep_y.max())) + 0.5)\n\nax.set(\n    title="Каждая точка — один экран",\n    xlabel="Средняя оценка эстетики X, баллы",\n    ylabel="Средняя оценка удобства Y, баллы",\n    xlim=(lower, upper),\n    ylim=(lower, upper)\n)\n\nax.set_aspect("equal", adjustable="box")\nax.legend(frameon=False, loc="upper left")\nax.grid(alpha=0.25)\nax.spines["top"].set_visible(False)\nax.spines["right"].set_visible(False)\n\nplt.tight_layout()\nplt.show()'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><h4 id="uicrit-heading-40-1"><strong>Что показывает этот график?</strong></h4>\n<span class="paragraph">Мы видим, что точки удобства и эстетики находятся в одном облаке. Но что интересно, облако имеет вытянутую форму и мы можем увидеть, что наиболее высокие и низкие оценки стоят рядом. То есть экраны с более высокой средней оценкой эстетики обычно имеют и более высокую среднюю оценку удобства</span></span>', 'source': '####**Что показывает этот график?**\n\nМы видим, что точки удобства и эстетики находятся в одном облаке. Но что интересно, облако имеет вытянутую форму и мы можем увидеть, что наиболее высокие и низкие оценки стоят рядом. То есть экраны с более высокой средней оценкой эстетики обычно имеют и более высокую среднюю оценку удобства'}, {'kind': 'code', 'html': '<div class="tbl-wrap"><div>\n<style scoped>\n    .dataframe tbody tr th:only-of-type {\n        vertical-align: middle;\n    }\n\n    .dataframe tbody tr th {\n        vertical-align: top;\n    }\n\n    .dataframe thead th {\n        text-align: right;\n    }\n</style>\n<table border="1" class="dataframe">\n  <thead>\n    <tr style="text-align: right;">\n      <th></th>\n      <th>aesthetics_mean</th>\n      <th>usability_mean</th>\n    </tr>\n  </thead>\n  <tbody>\n    <tr>\n      <th>aesthetics_mean</th>\n      <td>1.000000</td>\n      <td>0.807924</td>\n    </tr>\n    <tr>\n      <th>usability_mean</th>\n      <td>0.807924</td>\n      <td>1.000000</td>\n    </tr>\n  </tbody>\n</table>\n</div></div>', 'source': 'import ipywidgets as widgets\nfrom IPython.display import display, clear_output\n\ncorrelation_data = dependence_data.rename(columns={\n    "aesthetics_mean": "Эстетика",\n    "usability_mean": "Удобство"\n})\n\ncorrelation_selector = widgets.RadioButtons(\n    options=[\n        ("Пирсон", "pearson"),\n        ("Спирмен", "spearman")\n    ],\n    value="pearson",\n    description="Коэффициент:",\n    style={"description_width": "initial"}\n)\n\ncorrelation_output = widgets.Output()\n\n\ndef draw_correlation(change=None):\n    method = correlation_selector.value\n    matrix = correlation_data.corr(method=method)\n\n    title = (\n        "Корреляция Пирсона r"\n        if method == "pearson"\n        else "Корреляция Спирмена ρ"\n    )\n\n    with correlation_output:\n        clear_output(wait=True)\n\n        fig, ax = plt.subplots(figsize=(6, 5))\n\n        sns.heatmap(\n            matrix,\n            annot=True,\n            fmt=".3f",\n            cmap="RdBu_r",\n            vmin=-1,\n            vmax=1,\n            center=0,\n            square=True,\n            linewidths=1,\n            linecolor="white",\n            annot_kws={"size": 17, "weight": "bold"},\n            cbar_kws={\n                "label": "Коэффициент корреляции",\n                "shrink": 0.8\n            },\n            ax=ax\n        )\n\n        ax.set_title(title, pad=16)\n        ax.set_xticklabels(ax.get_xticklabels(), rotation=0)\n        ax.set_yticklabels(ax.get_yticklabels(), rotation=0)\n\n        plt.tight_layout()\n        plt.show()\n\n        coefficient = matrix.loc["Эстетика", "Удобство"]\n        print(f"Связь эстетики и удобства: {coefficient:.3f}")\n\n\ncorrelation_selector.observe(\n    draw_correlation,\n    names="value"\n)\n\ndisplay(correlation_selector, correlation_output)\ndraw_correlation()'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><h4 id="uicrit-heading-42-1"><strong>Вывод о марице корреляций</strong></h4>\n<span class="paragraph"><strong>Пирсон <marimo-tex class="arithmatex">||(r = 0{,}808||)</marimo-tex></strong> оценивает линейную связь: насколько облако вытянуто вдоль прямой.</span>\n<span class="paragraph"><strong>Спирмен <marimo-tex class="arithmatex">||(\\rho = 0{,}805||)</marimo-tex></strong> сравнивает порядок экранов по оценкам: занимают ли более эстетичные экраны также более высокие места по удобству.</span>\n<span class="paragraph">Из этих показателей мы можем сделать вывод о том, что значения эстетики и удобства показывают положительную связь, поскольку значения приближены к 1. НО здесь связаны записанные средние оценки, её происхождение и влияние красоты на удобство этим не доказаны, тут нам поможет проверка разных аннотаций, которая уточняет, как эту связь интерпретировать</span></span>', 'source': '####**Вывод о марице корреляций**\n\n**Пирсон $r = 0{,}808$** оценивает линейную связь: насколько облако вытянуто вдоль прямой.\n\n**Спирмен $\\rho = 0{,}805$** сравнивает порядок экранов по оценкам: занимают ли более эстетичные экраны также более высокие места по удобству.\n\nИз этих показателей мы можем сделать вывод о том, что значения эстетики и удобства показывают положительную связь, поскольку значения приближены к 1. НО здесь связаны записанные средние оценки, её происхождение и влияние красоты на удобство этим не доказаны, тут нам поможет проверка разных аннотаций, которая уточняет, как эту связь интерпретировать'}, {'kind': 'code', 'html': '<pre class="numeric-result">Количество экранов: 1000\nНаблюдаемая корреляция Спирмена: 0.8048\nКоличество перестановок: 9999\nДвустороннее p-value: 0.0001\nОтвергаем H₀ о независимости: обнаружена статистически значимая связь.\n</pre>', 'source': '# Корректные пары: одна строка — один экран\ntest_pairs = screens[\n    ["aesthetics_mean", "usability_mean"]\n].dropna()\n\n# Спирмен — это корреляция Пирсона между рангами.\n# Совпадающим значениям присваиваются средние ранги.\nrank_x = stats.rankdata(test_pairs["aesthetics_mean"])\nrank_y = stats.rankdata(test_pairs["usability_mean"])\n\n# Центрируем ранги\nrank_x = rank_x - rank_x.mean()\nrank_y = rank_y - rank_y.mean()\n\ndenominator = np.linalg.norm(rank_x) * np.linalg.norm(rank_y)\n\nif denominator == 0:\n    raise ValueError(\n        "Проверка невозможна: один из показателей постоянный."\n    )\n\nobserved_rho = np.dot(rank_x, rank_y) / denominator\n\n# Отдельный генератор для воспроизводимости проверки\npermutation_rng = np.random.default_rng(SEED)\n\nn_permutations = 9999\nnull_correlations = np.empty(n_permutations)\n\nfor i in range(n_permutations):\n    shuffled_y = permutation_rng.permutation(rank_y)\n\n    null_correlations[i] = (\n        np.dot(rank_x, shuffled_y) / denominator\n    )\n\n# Двусторонняя проверка с поправкой +1:\n# оценка p-value не может оказаться равной нулю.\nn_extreme = np.count_nonzero(\n    np.abs(null_correlations) >= abs(observed_rho) - 1e-12\n)\n\npermutation_p = (n_extreme + 1) / (n_permutations + 1)\nalpha = 0.05\n\nprint(f"Количество экранов: {len(test_pairs)}")\nprint(f"Наблюдаемая корреляция Спирмена: {observed_rho:.4f}")\nprint(f"Количество перестановок: {n_permutations}")\nprint(f"Двустороннее p-value: {permutation_p:.4f}")\n\nif permutation_p < alpha:\n    print(\n        "Отвергаем H₀ о независимости: "\n        "обнаружена статистически значимая связь."\n    )\nelse:\n    print(\n        "Нет оснований отвергнуть H₀ о независимости. "\n        "Это не доказывает независимость."\n    )'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><span class="paragraph">А это перестановочный тест. Он показывает, что при предположении независимости экранов наблюдаемую связь трудно объяснить случайным сопоставлением оценок: p = 0,0001 &lt; 0,05.</span></span>', 'source': 'А это перестановочный тест. Он показывает, что при предположении независимости экранов наблюдаемую связь трудно объяснить случайным сопоставлением оценок: p = 0,0001 < 0,05.'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><h3 id="uicrit-heading-45-1">4.1. Связаны ли две оценки внутри одной аннотации?</h3>\n<span class="paragraph">Средняя эстетика и среднее удобство одного экрана используют оценки из одних и тех же строк, из-за чего их корреляция может отражать как различия экранов, так и связь двух баллов внутри одной аннотации, поэтому для установки связи разделим эти источники</span>\n<span class="paragraph">Сравним:</span>\n<ol>\n<li>Средние эстетики и удобства экранов — исходный результат.</li>\n<li>Эстетику и удобство внутри одной строки аннотации.</li>\n<li>Эстетику одной строки и удобство другой строки того же экрана.</li>\n<li>Эстетику разных строк одного экрана.</li>\n</ol>\n<span class="paragraph">Для главного сопоставления оставим экраны с <strong>ровно тремя</strong> строками. Тогда каждый экран даёт одинаковое число пар: три внутристрочных и шесть упорядоченных межстрочных. Дополнительно покажем результаты на всех доступных строках: там экраны с большим числом аннотаций получают больший вес в межстрочной корреляции.</span>\n<span class="paragraph">В CSV нет ID эксперта. Поэтому «другая аннотация» — другая строка, а не проверенный по идентификатору другой человек. По описанию выпуска экран оценивали разные аннотаторы, но неодинаковое число строк требует осторожности. Межстрочные пары зависимы; не вычисляем p-value так, будто каждая пара независима.</span>\n<span class="paragraph">Четвёртая корреляция описывает согласованность ранжирования в построенных парах, но <strong>не является полноценным коэффициентом межэкспертного согласия</strong>. Для оценки личной строгости и надёжности оценщиков нужны их идентификаторы и подходящая модель.</span></span>', 'source': '### 4.1. Связаны ли две оценки внутри одной аннотации?\n\nСредняя эстетика и среднее удобство одного экрана используют оценки из одних и тех же строк, из-за чего их корреляция может отражать как различия экранов, так и связь двух баллов внутри одной аннотации, поэтому для установки связи разделим эти источники\n\nСравним:\n1. Средние эстетики и удобства экранов — исходный результат.\n2. Эстетику и удобство внутри одной строки аннотации.\n3. Эстетику одной строки и удобство другой строки того же экрана.\n4. Эстетику разных строк одного экрана.\n\nДля главного сопоставления оставим экраны с **ровно тремя** строками. Тогда каждый экран даёт одинаковое число пар: три внутристрочных и шесть упорядоченных межстрочных. Дополнительно покажем результаты на всех доступных строках: там экраны с большим числом аннотаций получают больший вес в межстрочной корреляции.\n\nВ CSV нет ID эксперта. Поэтому «другая аннотация» — другая строка, а не проверенный по идентификатору другой человек. По описанию выпуска экран оценивали разные аннотаторы, но неодинаковое число строк требует осторожности. Межстрочные пары зависимы; не вычисляем p-value так, будто каждая пара независима.\n\nЧетвёртая корреляция описывает согласованность ранжирования в построенных парах, но **не является полноценным коэффициентом межэкспертного согласия**. Для оценки личной строгости и надёжности оценщиков нужны их идентификаторы и подходящая модель.\n'}, {'kind': 'code', 'html': '<div class="tbl-wrap"><div>\n<style scoped>\n    .dataframe tbody tr th:only-of-type {\n        vertical-align: middle;\n    }\n\n    .dataframe tbody tr th {\n        vertical-align: top;\n    }\n\n    .dataframe thead th {\n        text-align: right;\n    }\n</style>\n<table border="1" class="dataframe">\n  <thead>\n    <tr style="text-align: right;">\n      <th></th>\n      <th>Набор</th>\n      <th>Сравнение</th>\n      <th>Пар</th>\n      <th>Спирмен ρ</th>\n    </tr>\n  </thead>\n  <tbody>\n    <tr>\n      <th>0</th>\n      <td>Ровно 3 аннотации</td>\n      <td>Средние экранов: эстетика — удобство</td>\n      <td>966</td>\n      <td>0.8062</td>\n    </tr>\n    <tr>\n      <th>1</th>\n      <td>Ровно 3 аннотации</td>\n      <td>Одна строка: эстетика — удобство</td>\n      <td>2898</td>\n      <td>0.8126</td>\n    </tr>\n    <tr>\n      <th>2</th>\n      <td>Ровно 3 аннотации</td>\n      <td>Разные строки экрана: эстетика — удобство</td>\n      <td>5796</td>\n      <td>0.0386</td>\n    </tr>\n    <tr>\n      <th>3</th>\n      <td>Ровно 3 аннотации</td>\n      <td>Разные строки экрана: эстетика — эстетика</td>\n      <td>5796</td>\n      <td>0.0328</td>\n    </tr>\n    <tr>\n      <th>4</th>\n      <td>Все строки</td>\n      <td>Средние экранов: эстетика — удобство</td>\n      <td>1000</td>\n      <td>0.8048</td>\n    </tr>\n    <tr>\n      <th>5</th>\n      <td>Все строки</td>\n      <td>Одна строка: эстетика — удобство</td>\n      <td>2981</td>\n      <td>0.8112</td>\n    </tr>\n    <tr>\n      <th>6</th>\n      <td>Все строки</td>\n      <td>Разные строки экрана: эстетика — удобство</td>\n      <td>5942</td>\n      <td>0.0349</td>\n    </tr>\n    <tr>\n      <th>7</th>\n      <td>Все строки</td>\n      <td>Разные строки экрана: эстетика — эстетика</td>\n      <td>5942</td>\n      <td>0.0277</td>\n    </tr>\n  </tbody>\n</table>\n</div></div><figure class="plot plot-wide"><img width="1082" height="444" decoding="async" data-report-asset="./public/reports/uicrit/46-1.png" src="data:image/png;base64," alt="График исследования" /></figure><pre class="numeric-result">Экранов с ровно тремя строками: 966\n</pre>', 'source': 'def annotation_correlations(frame, label):\n    averages = frame.groupby("rico_id")[["aesthetics_rating", "usability_rating"]].mean()\n    cross_a, cross_u, other_a = [], [], []\n    for _, group in frame.groupby("rico_id"):\n        aesthetics = group.aesthetics_rating.to_numpy()\n        usability = group.usability_rating.to_numpy()\n        for first in range(len(group)):\n            for second in range(len(group)):\n                if first != second:\n                    cross_a.append(aesthetics[first])\n                    cross_u.append(usability[second])\n                    other_a.append(aesthetics[second])\n    same_rho = stats.spearmanr(frame.aesthetics_rating, frame.usability_rating).statistic\n    return [\n        {"Набор": label, "Сравнение": "Средние экранов: эстетика — удобство",\n         "Пар": len(averages), "Спирмен ρ": stats.spearmanr(averages.iloc[:,0], averages.iloc[:,1]).statistic},\n        {"Набор": label, "Сравнение": "Одна строка: эстетика — удобство",\n         "Пар": len(frame), "Спирмен ρ": same_rho},\n        {"Набор": label, "Сравнение": "Разные строки экрана: эстетика — удобство",\n         "Пар": len(cross_a), "Спирмен ρ": stats.spearmanr(cross_a, cross_u).statistic},\n        {"Набор": label, "Сравнение": "Разные строки экрана: эстетика — эстетика",\n         "Пар": len(cross_a), "Спирмен ρ": stats.spearmanr(cross_a, other_a).statistic},\n    ]\nannotation_counts = df.groupby("rico_id").size()\nthree_ids = annotation_counts[annotation_counts == 3].index\nthree_rows = df[df.rico_id.isin(three_ids)]\nannotation_results = pd.DataFrame(\n    annotation_correlations(three_rows, "Ровно 3 аннотации")\n    + annotation_correlations(df, "Все строки"))\nprint("Экранов с ровно тремя строками:", len(three_ids))\ndisplay(annotation_results.round(4))\n\ncomparison_plot = annotation_results[annotation_results.Набор == "Ровно 3 аннотации"]\nfig, ax = plt.subplots(figsize=(10, 4.2))\npositions = np.arange(len(comparison_plot))\nax.hlines(positions, 0, comparison_plot["Спирмен ρ"], color="#C9C4B8", linewidth=3)\nax.scatter(comparison_plot["Спирмен ρ"], positions, color="#7463C7", s=65, zorder=3)\nfor pos, value in zip(positions, comparison_plot["Спирмен ρ"]):\n    ax.text(value+.025, pos, f"{value:.3f}", va="center")\nax.set_yticks(positions, comparison_plot.Сравнение)\nax.set(xlim=(-.1, 1), xlabel="Коэффициент Спирмена",\n       title="Что меняется, если разорвать связь внутри аннотации?")\nax.invert_yaxis()\nax.axvline(0, color="#777777", linewidth=1)\nax.grid(axis="x", alpha=.25)\nplt.tight_layout()\nplt.show()\n'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><h4 id="uicrit-heading-47-1"><strong>Вывод</strong></h4>\n<span class="paragraph">Этот график показывает, что сильная связь видна внутри одной аннотации, но почти исчезает, если сопоставлять разные аннотации одного экрана. То есть эстетика и удобство связаны прежде всего в оценках одного и того же аннотатора, а между оценками разных аннотаторов корреляция близка к нулю.</span></span>', 'source': '####**Вывод**\n\nЭтот график показывает, что сильная связь видна внутри одной аннотации, но почти исчезает, если сопоставлять разные аннотации одного экрана. То есть эстетика и удобство связаны прежде всего в оценках одного и того же аннотатора, а между оценками разных аннотаторов корреляция близка к нулю.'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><h3 id="uicrit-heading-48-1"><strong>Вывод о зависимости 2 величин</strong></h3>\n<span class="paragraph">На основе исследования мы можем сделать вывод, что средние оценки эстетики и удобства экранов имеют сильную положительную связь. Перестановочный тест подтверждает её статистическую значимость при предпосылке независимости экранов.</span>\n<span class="paragraph">Дополнительное исследование показало, что сильная связь наблюдается и внутри одной аннотации, а при сопоставлении оценок из разных аннотаций одного экрана корреляция становится близкой к нулю. Поэтому важно учитывать, взяты ли две оценки из одной записи оценщика или из разных, потому что связь эстетики и удобства мы можем отслеживать именно в рамках оценок одного аннотатора</span>\n<span class="paragraph">Почему именно так? У нас есть несколько предположений:</span>\n<ol>\n<li>Эфферт ореола -  когда человек выстраивает общее впечатление об экране, и это влияет одновременно на оценки эстетики и удобства.</li>\n<li>Человеческий фактор - это обсуждалось и до этого, но действительно показатели могут иметь связь исходя из какого-то личного опыта человека</li>\n<li>Критерии оценки - каждый из аннотаторов мог по своему воспринимать критерии оценки, из-за чего связь между аннотаторами почти нулевая, а между показателями возрастает</li>\n</ol></span>', 'source': '### **Вывод о зависимости 2 величин**\n\nНа основе исследования мы можем сделать вывод, что средние оценки эстетики и удобства экранов имеют сильную положительную связь. Перестановочный тест подтверждает её статистическую значимость при предпосылке независимости экранов.\n\nДополнительное исследование показало, что сильная связь наблюдается и внутри одной аннотации, а при сопоставлении оценок из разных аннотаций одного экрана корреляция становится близкой к нулю. Поэтому важно учитывать, взяты ли две оценки из одной записи оценщика или из разных, потому что связь эстетики и удобства мы можем отслеживать именно в рамках оценок одного аннотатора\n\nПочему именно так? У нас есть несколько предположений:\n\n1. Эфферт ореола -  когда человек выстраивает общее впечатление об экране, и это влияет одновременно на оценки эстетики и удобства.\n2. Человеческий фактор - это обсуждалось и до этого, но действительно показатели могут иметь связь исходя из какого-то личного опыта человека\n3. Критерии оценки - каждый из аннотаторов мог по своему воспринимать критерии оценки, из-за чего связь между аннотаторами почти нулевая, а между показателями возрастает'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><span class="paragraph"><a id="uicrit-heatmap"></a></span>\n<h2 id="uicrit-heading-49-1"><strong>5. Тепловая карта замечаний</strong></h2>\n<span class="paragraph"><strong>Где на экране мобильного приложения эксперты чаще всего находят проблемы?</strong></span>\n<span class="paragraph">В UICrit к каждому замечанию эксперта приложена рамка — область экрана, к которой оно относится. Наложив 11 тысяч рамок на один силуэт телефона, получаем карту «где болит у мобильных интерфейсов», а затем проверяем увиденное статистическими критериями. Данные — таблица <code>df</code>, загруженная в разделе 1. Переключатели в разделе 5.4 работают при запуске в Colab или Jupyter.</span></span>', 'source': '<a id="heatmap"></a>\n## **5. Тепловая карта замечаний**\n\n**Где на экране мобильного приложения эксперты чаще всего находят проблемы?**\n\nВ UICrit к каждому замечанию эксперта приложена рамка — область экрана, к которой оно относится. Наложив 11 тысяч рамок на один силуэт телефона, получаем карту «где болит у мобильных интерфейсов», а затем проверяем увиденное статистическими критериями. Данные — таблица `df`, загруженная в разделе 1. Переключатели в разделе 5.4 работают при запуске в Colab или Jupyter.'}, {'kind': 'code', 'html': '', 'source': 'import ast\nimport re\n\nimport numpy as np\nimport pandas as pd\nimport matplotlib.pyplot as plt\nfrom matplotlib.colors import LinearSegmentedColormap, PowerNorm\nfrom matplotlib.patches import FancyBboxPatch\nfrom scipy import stats\n\n# Палитра C и стиль графиков заданы в начале ноутбука (раздел 1)\n# Последовательная шкала для тепловых карт: фон сайта → зелёный «данные» → почти чёрный\nHEAT = LinearSegmentedColormap.from_list(\n    "heat",\n    ["#F4F9FC", "#DCEEF8", "#ACD5EC",\n     "#73B4D9", "#367FA9", "#163E59"]\n)'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><span class="paragraph"><a id="uicrit-heat-boxes"></a></span>\n<h3 id="uicrit-heading-51-1">5.1. Разбор рамок замечаний</h3>\n<span class="paragraph">Столбец <code>comments</code> хранит список замечаний строкой. В конце каждого замечания записана рамка:\n<code>Bounding Box: [x1, y1, x2, y2]</code> — левый верхний и правый нижний углы в долях ширины и высоты экрана\n(0 — верхний левый угол, 1 — нижний правый). Поэтому рамки с разных экранов можно накладывать друг на друга.</span>\n<span class="paragraph">Столбец <code>comments_source</code> хранит для каждого замечания его автора: <code>human</code> (человек), <code>llm</code> (Gemini) или <code>both</code>.</span>\n<span class="paragraph">Для каждого замечания вычисляем:</span>\n<ul>\n<li>площадь рамки <marimo-tex class="arithmatex">||(A=(x_2-x_1)(y_2-y_1)||)</marimo-tex> — доля площади экрана;</li>\n<li>высоту центра рамки <marimo-tex class="arithmatex">||(h=\\tfrac{1}{2}(y_1+y_2)||)</marimo-tex>: 0 — верх экрана, 1 — низ;</li>\n<li>тему по ключевым словам в тексте:</li>\n</ul>\n<table>\n<thead>\n<tr>\n<th>Тема</th>\n<th>Ключевые слова (с любым окончанием)</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Цвет и контраст</td>\n<td>color, colour, contrast</td>\n</tr>\n<tr>\n<td>Текст и шрифт</td>\n<td>font, text size, readab… (readable, readability)</td>\n</tr>\n<tr>\n<td>Кнопки</td>\n<td>button</td>\n</tr>\n<tr>\n<td>Иконки</td>\n<td>icon</td>\n</tr>\n</tbody>\n</table>\n<span class="paragraph">Тот же словарь <code>THEMES</code> используется в разделе 6.</span></span>', 'source': '<a id="heat-boxes"></a>\n### 5.1. Разбор рамок замечаний\n\nСтолбец `comments` хранит список замечаний строкой. В конце каждого замечания записана рамка:\n`Bounding Box: [x1, y1, x2, y2]` — левый верхний и правый нижний углы в долях ширины и высоты экрана\n(0 — верхний левый угол, 1 — нижний правый). Поэтому рамки с разных экранов можно накладывать друг на друга.\n\nСтолбец `comments_source` хранит для каждого замечания его автора: `human` (человек), `llm` (Gemini) или `both`.\n\nДля каждого замечания вычисляем:\n- площадь рамки $A=(x_2-x_1)(y_2-y_1)$ — доля площади экрана;\n- высоту центра рамки $h=\\tfrac{1}{2}(y_1+y_2)$: 0 — верх экрана, 1 — низ;\n- тему по ключевым словам в тексте:\n\n| Тема | Ключевые слова (с любым окончанием) |\n|---|---|\n| Цвет и контраст | color, colour, contrast |\n| Текст и шрифт | font, text size, readab… (readable, readability) |\n| Кнопки | button |\n| Иконки | icon |\n\nТот же словарь `THEMES` используется в разделе 6.'}, {'kind': 'code', 'html': '<div class="tbl-wrap"><div>\n<style scoped>\n    .dataframe tbody tr th:only-of-type {\n        vertical-align: middle;\n    }\n\n    .dataframe tbody tr th {\n        vertical-align: top;\n    }\n\n    .dataframe thead th {\n        text-align: right;\n    }\n</style>\n<table border="1" class="dataframe">\n  <thead>\n    <tr style="text-align: right;">\n      <th></th>\n      <th>замечаний</th>\n    </tr>\n    <tr>\n      <th>source</th>\n      <th></th>\n    </tr>\n  </thead>\n  <tbody>\n    <tr>\n      <th>human</th>\n      <td>8230</td>\n    </tr>\n    <tr>\n      <th>both</th>\n      <td>1856</td>\n    </tr>\n    <tr>\n      <th>llm</th>\n      <td>1026</td>\n    </tr>\n    <tr>\n      <th>None</th>\n      <td>318</td>\n    </tr>\n  </tbody>\n</table>\n</div></div><pre class="numeric-result">Замечаний с рамкой: 11430\nСтрок, где число меток автора не совпадает с числом замечаний: 83\nРамок вне [0, 1]: 0\n</pre>', 'source': 'BOX = re.compile(r"Bounding Box: \\[([^\\]]+)\\]")\n# Тема → регулярное выражение по английскому тексту замечания.\n# Один словарь на разделы 5 и 6; \\b — начало слова, \\w* — любое окончание (colors, contrasting, icons…)\nTHEMES = {\n    "Цвет и контраст": r"\\bcolou?r\\w*|\\bcontrast\\w*",\n    "Текст и шрифт": r"\\bfont\\w*|\\btext\\s+size\\b|\\breadab\\w*",\n    "Кнопки": r"\\bbutton\\w*",\n    "Иконки": r"\\bicon\\w*",\n}\n\nrows, mismatched = [], 0\nfor annotation, r in df.iterrows():          # annotation — номер строки = один аннотатор\n    comments = ast.literal_eval(r["comments"])\n    sources = ast.literal_eval(r["comments_source"])\n    if len(comments) != len(sources):        # метки автора не совпадают с замечаниями\n        mismatched += 1\n        sources = [None] * len(comments)\n    for text, src in zip(comments, sources):\n        m = BOX.search(text)\n        if m:\n            x1, y1, x2, y2 = map(float, m.group(1).split(","))\n            rows.append({"rico_id": r["rico_id"], "annotation": annotation, "source": src,\n                         "x1": x1, "y1": y1, "x2": x2, "y2": y2, "text": text.lower()})\n\nboxes = pd.DataFrame(rows)\nboxes["area"] = (boxes["x2"] - boxes["x1"]) * (boxes["y2"] - boxes["y1"])\nboxes["h"] = (boxes["y1"] + boxes["y2"]) / 2\nfor theme, pattern in THEMES.items():\n    boxes[theme] = boxes["text"].str.contains(pattern, regex=True)\n\nprint("Замечаний с рамкой:", len(boxes))\nprint("Строк, где число меток автора не совпадает с числом замечаний:", mismatched)\nprint("Рамок вне [0, 1]:", int(((boxes[["x1", "y1", "x2", "y2"]] < 0) | (boxes[["x1", "y1", "x2", "y2"]] > 1)).any(axis=1).sum()))\nboxes["source"].value_counts(dropna=False).rename("замечаний").to_frame()'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><span class="paragraph"><strong>Подготовка.</strong> У всех 11 430 замечаний есть рамка, координаты лежат в [0, 1]. В 83 строках число меток автора\nне совпадает с числом замечаний — это ошибка в самом датасете. Для таких замечаний автор неизвестен (<code>None</code>),\nи в сравнение «люди против ИИ» они не входят. Остальной анализ их использует.</span>\n<span class="paragraph">README датасета указывает 11 344 замечания, а при разборе получается 11 430 (на 86, или 0,8%, больше). Причина в документации не описана; на выводы такое расхождение не влияет.</span></span>', 'source': '**Подготовка.** У всех 11 430 замечаний есть рамка, координаты лежат в [0, 1]. В 83 строках число меток автора\nне совпадает с числом замечаний — это ошибка в самом датасете. Для таких замечаний автор неизвестен (`None`),\nи в сравнение «люди против ИИ» они не входят. Остальной анализ их использует.\n\nREADME датасета указывает 11 344 замечания, а при разборе получается 11 430 (на 86, или 0,8%, больше). Причина в документации не описана; на выводы такое расхождение не влияет.'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><span class="paragraph"><a id="uicrit-heat-size"></a></span>\n<h3 id="uicrit-heading-54-1">5.2. Какие рамки брать: размер</h3>\n<span class="paragraph">Рамки очень разные: от одной иконки до всего экрана. Крупные рамки при наложении заливают центр\nи превращают карту в размытое пятно, поэтому сначала смотрим на распределение площади.</span></span>', 'source': '<a id="heat-size"></a>\n### 5.2. Какие рамки брать: размер\n\nРамки очень разные: от одной иконки до всего экрана. Крупные рамки при наложении заливают центр\nи превращают карту в размытое пятно, поэтому сначала смотрим на распределение площади.'}, {'kind': 'code', 'html': '<figure class="plot plot-wide"><img width="874" height="411" decoding="async" data-report-asset="./public/reports/uicrit/55-0.png" src="data:image/png;base64," alt="График исследования" /></figure><pre class="numeric-result">Мелкие (&lt; 5% экрана): 5485 (48%)\nВесь экран (&gt; 80%): 1034 (9%)\n</pre>', 'source': 'fig, ax = plt.subplots(figsize=(9, 3.6))\nbins = np.logspace(-4, 0, 50)\nax.hist(boxes["area"][boxes["area"] > 0], bins=bins, color=C["data"], alpha=.85, edgecolor="white")\nax.set_xscale("log")\nax.set_xlim(1e-4, 1)\nfor t, lab, ha, y in [(0.05, "5%: порог\\n«мелкий элемент» ", "right", .9), (0.8, "80%:\\n«весь экран» ", "right", .62)]:\n    ax.axvline(t, color=C["ref"], lw=1.5, ls="--")\n    ax.text(t * 0.92, ax.get_ylim()[1] * y, lab, color=C["ref"], fontsize=9, ha=ha, va="top")\nax.set(xlabel="Площадь рамки, доля экрана (логарифмическая шкала)", ylabel="Число замечаний",\n       title="Размеры рамок замечаний")\nplt.show()\n\nsmall = boxes[boxes["area"] < 0.05]\nprint(f"Мелкие (< 5% экрана): {len(small)} ({len(small) / len(boxes):.0%})")\nprint(f"Весь экран (> 80%): {(boxes[\'area\'] > 0.8).sum()} ({(boxes[\'area\'] > 0.8).mean():.0%})")'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><span class="paragraph">На гистограмме видно два горба: много маленьких рамок (около 1% экрана) и много рамок почти во весь экран. Похоже, эксперты критикуют двумя способами: указывают на конкретный элемент или говорят про экран в целом. Для тепловой карты мы взяли только маленькие рамки, меньше 5% экрана. Это почти половина всех замечаний, и именно они показывают, где находится проблема.</span></span>', 'source': 'На гистограмме видно два горба: много маленьких рамок (около 1% экрана) и много рамок почти во весь экран. Похоже, эксперты критикуют двумя способами: указывают на конкретный элемент или говорят про экран в целом. Для тепловой карты мы взяли только маленькие рамки, меньше 5% экрана. Это почти половина всех замечаний, и именно они показывают, где находится проблема.'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><span class="paragraph"><a id="uicrit-heat-main"></a></span>\n<h3 id="uicrit-heading-57-1">5.3. Главная тепловая карта</h3>\n<span class="paragraph">Экран делим на сетку 90 × 160 клеток (пропорции 9:16). Каждая рамка добавляет +1 во все клетки, которые накрывает;\nсумму делим на число замечаний. Значение клетки — <strong>доля замечаний, задевающих эту клетку</strong>:</span>\n<marimo-tex class="arithmatex">||[\nH(c)=\\frac{1}{N}\\sum_{k=1}^{N}\\mathbf{1}\\left[c \\in \\text{рамка}_k\\right].\n||]</marimo-tex><span class="paragraph">Так карты групп с разным числом замечаний можно сравнивать между собой.</span></span>', 'source': '<a id="heat-main"></a>\n### 5.3. Главная тепловая карта\n\nЭкран делим на сетку 90 × 160 клеток (пропорции 9:16). Каждая рамка добавляет +1 во все клетки, которые накрывает;\nсумму делим на число замечаний. Значение клетки — **доля замечаний, задевающих эту клетку**:\n\n$$H(c)=\\frac{1}{N}\\sum_{k=1}^{N}\\mathbf{1}\\left[c \\in \\text{рамка}_k\\right].$$\n\nТак карты групп с разным числом замечаний можно сравнивать между собой.'}, {'kind': 'code', 'html': '<figure class="plot plot-square"><img width="823" height="880" decoding="async" data-report-asset="./public/reports/uicrit/58-0.png" src="data:image/png;base64," alt="График исследования" /></figure>', 'source': 'W, H = 90, 160\n\n\ndef heat(sub):\n    # Доля замечаний, задевающих каждую клетку экрана\n    grid = np.zeros((H, W))\n    for x1, y1, x2, y2 in sub[["x1", "y1", "x2", "y2"]].to_numpy():\n        r1, c1 = int(y1 * H), int(x1 * W)\n        grid[r1:max(int(y2 * H), r1 + 1), c1:max(int(x2 * W), c1 + 1)] += 1\n    return grid / max(len(sub), 1)\n\n\ndef phone(ax, grid, title=None, vmax=None, cbar=False):\n    # Тепловая карта внутри силуэта телефона; степенная шкала (γ = 0.5) проявляет слабые зоны\n    vals = grid * 100\n    top = vmax if vmax is not None else np.percentile(vals, 99.7)\n    im = ax.imshow(vals, cmap=HEAT, extent=(0, 1, 1, 0), norm=PowerNorm(0.5, vmin=0, vmax=top))\n    ax.set_aspect(16 / 9)\n    ax.add_patch(FancyBboxPatch((0, 0), 1, 1, boxstyle="round,pad=0,rounding_size=0.07",\n                                fill=False, lw=3.5, ec=C["ink"]))\n    ax.set(xlim=(-.04, 1.04), ylim=(1.04, -.04), xticks=[], yticks=[])\n    ax.grid(False)\n    for s in ax.spines.values():\n        s.set_visible(False)\n    if title:\n        ax.set_title(title, loc="center", fontsize=10)\n    if cbar:\n        cb = plt.colorbar(im, ax=ax, orientation="horizontal", fraction=.04, pad=.03)\n        cb.set_label("Доля замечаний, задевающих клетку, % (степенная шкала)")\n    return im\n\n\nfig, ax = plt.subplots(figsize=(9, 9))\nfig.subplots_adjust(left=.24, right=.76)\nphone(ax, heat(small), cbar=True)\nnotes = [((0.05, 0.03), (-0.12, 0.10), "Кнопка «назад»\\n(левый верхний угол)", "right"),\n         ((0.95, 0.03), (1.12, 0.03), "Меню, поиск\\n(правый верхний угол)", "left"),\n         ((0.75, 0.035), (1.12, 0.15), "Шапка экрана", "left"),\n         ((0.45, 0.13), (1.12, 0.27), "Заголовки под шапкой", "left"),\n         ((0.55, 0.935), (1.12, 0.90), "Нижняя навигация", "left")]\nfor xy, xytext, text, ha in notes:\n    ax.annotate(text, xy=xy, xytext=xytext, fontsize=9.5, color=C["ink"], ha=ha, va="center",\n                arrowprops=dict(arrowstyle="-", color=C["ref"], lw=1.2), annotation_clip=False)\nax.set_title(f"Где эксперты находят мелкие проблемы\\n{len(small)} замечаний с рамкой меньше 5% экрана",\n             loc="center", fontsize=12)\nplt.show()'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><span class="paragraph"><strong>Что видно.</strong> Самые критикуемые мелкие места — не контент посередине, а <strong>края экрана</strong>:\nдве яркие точки в верхних углах (кнопка «назад» слева, меню или поиск справа), полоса шапки сверху\nи полоса нижней навигации снизу. Ниже шапки — более слабое пятно: заголовки и первые строки контента.</span></span>', 'source': '**Что видно.** Самые критикуемые мелкие места — не контент посередине, а **края экрана**:\nдве яркие точки в верхних углах (кнопка «назад» слева, меню или поиск справа), полоса шапки сверху\nи полоса нижней навигации снизу. Ниже шапки — более слабое пятно: заголовки и первые строки контента.'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><span class="paragraph"><a id="uicrit-heat-compare"></a></span>\n<h3 id="uicrit-heading-60-1">5.4. Сравнение: люди и ИИ, темы замечаний</h3>\n<span class="paragraph">Все карты в этом разделе на одной шкале цвета, поэтому их можно сравнивать между собой.\nТемы определены по ключевым словам, и одно замечание может попасть в несколько тем.</span></span>', 'source': '<a id="heat-compare"></a>\n### 5.4. Сравнение: люди и ИИ, темы замечаний\n\nВсе карты в этом разделе на одной шкале цвета, поэтому их можно сравнивать между собой.\nТемы определены по ключевым словам, и одно замечание может попасть в несколько тем.'}, {'kind': 'code', 'html': '<figure class="plot plot-wide"><img width="1636" height="603" decoding="async" data-report-asset="./public/reports/uicrit/61-0.png" src="data:image/png;base64," alt="График исследования" /></figure>', 'source': 'groups = [("Люди", small[small["source"] == "human"]), ("ИИ (Gemini)", small[small["source"] == "llm"])]\ngroups += [(t, small[small[t]]) for t in THEMES]\ngrids = [(name, sub, heat(sub)) for name, sub in groups]\nvmax = max(np.percentile(g * 100, 99.7) for _, _, g in grids)\n\nfig, axs = plt.subplots(1, len(grids), figsize=(15, 5.4), layout="constrained")\nfor ax, (name, sub, g) in zip(axs, grids):\n    im = phone(ax, g, f"{name}\\nn = {len(sub)}", vmax=vmax)\ncb = fig.colorbar(im, ax=axs, orientation="horizontal", fraction=.05, shrink=.5)\ncb.set_label("Доля замечаний, задевающих клетку, % (общая степенная шкала)")\nfig.suptitle("Мелкие замечания (рамка < 5% экрана): по автору и по теме", x=.01, ha="left",\n             fontsize=12, fontweight="bold")\nplt.show()'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><span class="paragraph"><strong>Что видно.</strong></span>\n<ul>\n<li><strong>Люди</strong> сосредоточены на углах и шапке. У <strong>ИИ</strong> карта «полосатая» и разбросана по всему экрану:\n  Gemini чаще комментирует строки контента посередине. Карта ИИ шумнее ещё и потому, что мелких замечаний ИИ\n  намного меньше (392 против 4 292 у людей).</li>\n<li><strong>Кнопки</strong> — верхние углы и нижняя навигация. <strong>Иконки</strong> — почти только шапка.</li>\n<li><strong>Текст</strong> и <strong>цвет</strong> — по всему экрану, больше всего в верхней части контента, сразу под шапкой.\n  Сама шапка на этих картах выделяется, но по количеству замечаний про текст и цвет там меньше, чем в контенте (см. 5.5.3).</li>\n</ul></span>', 'source': '**Что видно.**\n- **Люди** сосредоточены на углах и шапке. У **ИИ** карта «полосатая» и разбросана по всему экрану:\n  Gemini чаще комментирует строки контента посередине. Карта ИИ шумнее ещё и потому, что мелких замечаний ИИ\n  намного меньше (392 против 4 292 у людей).\n- **Кнопки** — верхние углы и нижняя навигация. **Иконки** — почти только шапка.\n- **Текст** и **цвет** — по всему экрану, больше всего в верхней части контента, сразу под шапкой.\n  Сама шапка на этих картах выделяется, но по количеству замечаний про текст и цвет там меньше, чем в контенте (см. 5.5.3).\n'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><h4 id="uicrit-heading-63-1">Как размер рамки меняет картину</h4>\n<span class="paragraph">Чем крупнее рамки берём, тем сильнее карта размывается в пятно.</span></span>', 'source': '#### Как размер рамки меняет картину\n\nЧем крупнее рамки берём, тем сильнее карта размывается в пятно.'}, {'kind': 'code', 'html': '<figure class="plot plot-wide"><img width="1112" height="533" decoding="async" data-report-asset="./public/reports/uicrit/64-0.png" src="data:image/png;base64," alt="График исследования" /></figure>', 'source': 'limits = [0.05, 0.2, 0.5, 1.01]\nfig, axs = plt.subplots(1, len(limits), figsize=(10, 5), layout="constrained")\nfor ax, lim in zip(axs, limits):\n    sub = boxes[boxes["area"] < lim]\n    label = "все рамки" if lim > 1 else f"рамка < {lim:.0%}"\n    phone(ax, heat(sub), f"{label}\\nn = {len(sub)}")\nplt.show()'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><span class="paragraph">Чем крупнее рамки мы добавляем, тем сильнее карта расплывается в одно пятно, и углы, шапка и навигация перестают быть видны. Поэтому для поиска конкретных проблемных мест мы оставили только маленькие рамки. (Цвет на каждой из этих карт подобран отдельно, поэтому сравнивать здесь нужно форму пятен, а не их яркость.)</span>\n<span class="paragraph"><strong>Интерактивная версия</strong> (работает при запуске в Colab или Jupyter): переключатели автора и темы и слайдер порога размера рамки.</span></span>', 'source': 'Чем крупнее рамки мы добавляем, тем сильнее карта расплывается в одно пятно, и углы, шапка и навигация перестают быть видны. Поэтому для поиска конкретных проблемных мест мы оставили только маленькие рамки. (Цвет на каждой из этих карт подобран отдельно, поэтому сравнивать здесь нужно форму пятен, а не их яркость.)\n\n**Интерактивная версия** (работает при запуске в Colab или Jupyter): переключатели автора и темы и слайдер порога размера рамки.'}, {'kind': 'code', 'html': '<figure class="plot plot-portrait"><img width="462" height="748" decoding="async" data-report-asset="./public/reports/uicrit/66-0.png" src="data:image/png;base64," alt="График исследования" /></figure>', 'source': 'import ipywidgets as widgets\n\n\ndef explore(автор="все", тема="все", порог=0.05):\n    sub = boxes[boxes["area"] < порог]\n    if автор != "все":\n        sub = sub[sub["source"] == {"люди": "human", "ИИ": "llm", "оба": "both"}[автор]]\n    if тема != "все":\n        sub = sub[sub[тема]]\n    fig, ax = plt.subplots(figsize=(5, 7.5))\n    phone(ax, heat(sub), f"{автор} · {тема} · рамка < {порог:.0%}\\nn = {len(sub)}", cbar=True)\n    plt.show()\n\n\nwidgets.interact(explore,\n                 автор=["все", "люди", "ИИ", "оба"],\n                 тема=["все"] + list(THEMES),\n                 порог=widgets.FloatSlider(value=0.05, min=0.01, max=1.0, step=0.01,\n                                           readout_format=".0%", continuous_update=False));'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><span class="paragraph"><a id="uicrit-heat-tests"></a></span>\n<h3 id="uicrit-heading-67-1">5.5. Статистические проверки</h3>\n<span class="paragraph">Карта — это наблюдение. Проверяем три утверждения критериями. Случайная величина —\nвысота центра рамки <marimo-tex class="arithmatex">||(h||)</marimo-tex> мелкого замечания (0 — верх экрана, 1 — низ); <marimo-tex class="arithmatex">||(\\alpha = 0.05||)</marimo-tex>.</span>\n<h4 id="uicrit-heading-67-2">5.5.1. Распределены ли замечания по высоте равномерно?</h4>\n<span class="paragraph"><marimo-tex class="arithmatex">||(H_0||)</marimo-tex>: <marimo-tex class="arithmatex">||(h \\sim U[0, 1]||)</marimo-tex> — проблемы одинаково часто встречаются на любой высоте экрана.\nКритерий Колмогорова-Смирнова: <marimo-tex class="arithmatex">||(D=\\sup_t |F_n(t)-t|||)</marimo-tex>.</span></span>', 'source': '<a id="heat-tests"></a>\n### 5.5. Статистические проверки\n\nКарта — это наблюдение. Проверяем три утверждения критериями. Случайная величина —\nвысота центра рамки $h$ мелкого замечания (0 — верх экрана, 1 — низ); $\\alpha = 0.05$.\n\n#### 5.5.1. Распределены ли замечания по высоте равномерно?\n\n$H_0$: $h \\sim U[0, 1]$ — проблемы одинаково часто встречаются на любой высоте экрана.\nКритерий Колмогорова-Смирнова: $D=\\sup_t |F_n(t)-t|$.'}, {'kind': 'code', 'html': '<figure class="plot plot-wide"><img width="838" height="408" decoding="async" data-report-asset="./public/reports/uicrit/68-0.png" src="data:image/png;base64," alt="График исследования" /></figure><pre class="numeric-result">D = 0.303, p = 0.0e+00\nВ верхних 20% экрана: 49% замечаний (при равномерном было бы 20%)\n</pre>', 'source': 'h = small["h"]\nks = stats.kstest(h, "uniform")\n\nfig, ax = plt.subplots(figsize=(9, 3.6))\nax.hist(h, bins=40, range=(0, 1), density=True, color=C["data"], alpha=.85, edgecolor="white", label="Данные")\nax.axhline(1, color=C["ref"], lw=1.6, ls="--", label="Равномерное U[0, 1]")\nax.set(xlabel="Высота центра рамки h (0 — верх, 1 — низ экрана), доля высоты",\n       ylabel="Плотность", title="Где по высоте экрана находятся мелкие замечания")\nax.legend()\nplt.show()\n\nprint(f"D = {ks.statistic:.3f}, p = {ks.pvalue:.1e}")\nprint(f"В верхних 20% экрана: {(h < 0.2).mean():.0%} замечаний (при равномерном было бы 20%)")'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><span class="paragraph"><strong>Вывод.</strong> Замечания распределены по высоте экрана совсем не равномерно (D = 0.30, p ≈ 0). Почти половина из них — в верхней пятой части экрана, хотя при равномерном распределении было бы 20%. Второй, меньший пик — внизу, у навигации.</span></span>', 'source': '**Вывод.** Замечания распределены по высоте экрана совсем не равномерно (D = 0.30, p ≈ 0). Почти половина из них — в верхней пятой части экрана, хотя при равномерном распределении было бы 20%. Второй, меньший пик — внизу, у навигации.'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><h4 id="uicrit-heading-70-1">5.5.2. Указывают ли люди и ИИ на одну и ту же высоту?</h4>\n<span class="paragraph"><marimo-tex class="arithmatex">||(H_0||)</marimo-tex>: распределения <marimo-tex class="arithmatex">||(h||)</marimo-tex> у замечаний людей и ИИ одинаковы. Критерий Манна-Уитни\n(не требует нормальности).</span></span>', 'source': '#### 5.5.2. Указывают ли люди и ИИ на одну и ту же высоту?\n\n$H_0$: распределения $h$ у замечаний людей и ИИ одинаковы. Критерий Манна-Уитни\n(не требует нормальности).'}, {'kind': 'code', 'html': '<figure class="plot plot-wide"><img width="849" height="408" decoding="async" data-report-asset="./public/reports/uicrit/71-0.png" src="data:image/png;base64," alt="График исследования" /></figure><pre class="numeric-result">Медиана h: люди 0.17, ИИ 0.31\nU = 651560, p = 1.4e-13, r_rb = -0.23\nМедианная площадь рамки: люди 0.044, ИИ 0.095 (все рамки)\n</pre>', 'source': 'h_human = small.loc[small["source"] == "human", "h"]\nh_llm = small.loc[small["source"] == "llm", "h"]\nmw = stats.mannwhitneyu(h_human, h_llm, alternative="two-sided")\nr_rb = 2 * mw.statistic / (len(h_human) * len(h_llm)) - 1      # ранговая бисериальная корреляция\n\nfig, ax = plt.subplots(figsize=(9, 3.6))\nax.hist(h_human, bins=40, range=(0, 1), density=True, color=C["data"], alpha=.6, label=f"Люди, n = {len(h_human)}")\nax.hist(h_llm, bins=40, range=(0, 1), density=True, histtype="step", lw=2, color=C["alt"], label=f"ИИ, n = {len(h_llm)}")\nax.set(xlabel="Высота центра рамки h (0 — верх, 1 — низ экрана), доля высоты",\n       ylabel="Плотность", title="Люди критикуют выше на экране, чем ИИ")\nax.legend()\nplt.show()\n\nprint(f"Медиана h: люди {h_human.median():.2f}, ИИ {h_llm.median():.2f}")\nprint(f"U = {mw.statistic:.0f}, p = {mw.pvalue:.1e}, r_rb = {r_rb:.2f}")\nprint(f"Медианная площадь рамки: люди {boxes.loc[boxes[\'source\']==\'human\',\'area\'].median():.3f}, "\n      f"ИИ {boxes.loc[boxes[\'source\']==\'llm\',\'area\'].median():.3f} (все рамки)")'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><span class="paragraph"><strong>Вывод.</strong>\nЗамечания людей в среднем расположены выше на экране, чем замечания ИИ (медиана — 17% высоты против 31%, p ≈ 1·10⁻¹³). Разница не очень большая, но устойчивая (проверка в 5.5.4). Ещё у ИИ медианная площадь рамки вдвое больше: его замечания чаще касаются целого блока, а люди чаще указывают на конкретную кнопку или иконку.</span></span>', 'source': '**Вывод.**\nЗамечания людей в среднем расположены выше на экране, чем замечания ИИ (медиана — 17% высоты против 31%, p ≈ 1·10⁻¹³). Разница не очень большая, но устойчивая (проверка в 5.5.4). Ещё у ИИ медианная площадь рамки вдвое больше: его замечания чаще касаются целого блока, а люди чаще указывают на конкретную кнопку или иконку.'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><h4 id="uicrit-heading-73-1">5.5.3. Связана ли тема замечания с зоной экрана?</h4>\n<span class="paragraph">Зоны: <strong>шапка</strong> — верхние 12% высоты, <strong>низ</strong> — нижние 12%, <strong>контент</strong> — всё между ними.\nЗдесь каждому замечанию нужна ровно одна тема, поэтому темы назначаем по приоритету\n(кнопки → иконки → цвет → текст → другое). <marimo-tex class="arithmatex">||(H_0||)</marimo-tex>: тема и зона независимы; критерий <marimo-tex class="arithmatex">||(\\chi^2||)</marimo-tex>, сила связи — V Крамера.</span></span>', 'source': '#### 5.5.3. Связана ли тема замечания с зоной экрана?\n\nЗоны: **шапка** — верхние 12% высоты, **низ** — нижние 12%, **контент** — всё между ними.\nЗдесь каждому замечанию нужна ровно одна тема, поэтому темы назначаем по приоритету\n(кнопки → иконки → цвет → текст → другое). $H_0$: тема и зона независимы; критерий $\\chi^2$, сила связи — V Крамера.'}, {'kind': 'code', 'html': '<figure class="plot plot-wide"><img width="775" height="401" decoding="async" data-report-asset="./public/reports/uicrit/74-0.png" src="data:image/png;base64," alt="График исследования" /></figure><div class="tbl-wrap"><div>\n<style scoped>\n    .dataframe tbody tr th:only-of-type {\n        vertical-align: middle;\n    }\n\n    .dataframe tbody tr th {\n        vertical-align: top;\n    }\n\n    .dataframe thead th {\n        text-align: right;\n    }\n</style>\n<table border="1" class="dataframe">\n  <thead>\n    <tr style="text-align: right;">\n      <th>Зона</th>\n      <th>Шапка</th>\n      <th>Контент</th>\n      <th>Низ</th>\n    </tr>\n    <tr>\n      <th>Тема</th>\n      <th></th>\n      <th></th>\n      <th></th>\n    </tr>\n  </thead>\n  <tbody>\n    <tr>\n      <th>Другое</th>\n      <td>380</td>\n      <td>703</td>\n      <td>82</td>\n    </tr>\n    <tr>\n      <th>Иконки</th>\n      <td>543</td>\n      <td>352</td>\n      <td>64</td>\n    </tr>\n    <tr>\n      <th>Кнопки</th>\n      <td>660</td>\n      <td>522</td>\n      <td>212</td>\n    </tr>\n    <tr>\n      <th>Текст и шрифт</th>\n      <td>162</td>\n      <td>659</td>\n      <td>37</td>\n    </tr>\n    <tr>\n      <th>Цвет и контраст</th>\n      <td>179</td>\n      <td>855</td>\n      <td>75</td>\n    </tr>\n  </tbody>\n</table>\n</div></div><pre class="numeric-result">χ² = 773, df = 8, p = 1.2e-161, V Крамера = 0.27, мин. ожидаемая частота = 74\n</pre>', 'source': 'theme_one = np.select(\n    [small["Кнопки"], small["Иконки"], small["Цвет и контраст"], small["Текст и шрифт"]],\n    ["Кнопки", "Иконки", "Цвет и контраст", "Текст и шрифт"], "Другое")\nzone = pd.cut(small["h"], [0, .12, .88, 1], labels=["Шапка", "Контент", "Низ"], include_lowest=True)\ntable = pd.crosstab(pd.Series(theme_one, index=small.index, name="Тема"), zone.rename("Зона"))\nchi2, p, dof, expected = stats.chi2_contingency(table)\nV = np.sqrt(chi2 / (table.values.sum() * (min(table.shape) - 1)))\nshare = table.div(table.sum(axis=1), axis=0)\n\nfig, ax = plt.subplots(figsize=(7, 3.8))\nim = ax.imshow(share.to_numpy() * 100, cmap=HEAT, vmin=0, vmax=100, aspect="auto")\nax.set_xticks(range(share.shape[1]), share.columns)\nax.set_yticks(range(share.shape[0]), share.index)\nax.grid(False)\nfor i in range(share.shape[0]):\n    for j in range(share.shape[1]):\n        v = share.iat[i, j] * 100\n        ax.text(j, i, f"{v:.0f}%", ha="center", va="center", fontsize=11, fontweight="bold",\n                color="white" if v > 55 else C["ink"])\nfig.colorbar(im, ax=ax, label="Доля замечаний темы в зоне, %")\nax.set_title("Где на экране ругают каждую тему")\nplt.show()\n\nprint(f"χ² = {chi2:.0f}, df = {dof}, p = {p:.1e}, V Крамера = {V:.2f}, мин. ожидаемая частота = {expected.min():.0f}")\ntable'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><span class="paragraph"><strong>Вывод.</strong> Тема замечания и место на экране связаны (χ² = 773, p ≈ 0, V Крамера = 0.27 — связь умеренная). Иконки чаще всего ругают в шапке (57%), кнопки — тоже в шапке, но заметно чаще остальных тем и внизу (15%). Текст и цвет в основном обсуждают в контенте (77%). Критерий здесь применим: во всех ячейках таблицы ожидается больше 5 замечаний.</span></span>', 'source': '**Вывод.** Тема замечания и место на экране связаны (χ² = 773, p ≈ 0, V Крамера = 0.27 — связь умеренная). Иконки чаще всего ругают в шапке (57%), кнопки — тоже в шапке, но заметно чаще остальных тем и внизу (15%). Текст и цвет в основном обсуждают в контенте (77%). Критерий здесь применим: во всех ячейках таблицы ожидается больше 5 замечаний.'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><h4 id="uicrit-heading-76-1">5.5.4. Устойчивость выводов к группировке замечаний</h4>\n<span class="paragraph">Критерии 5.5.1–5.5.3 считают каждое замечание отдельным наблюдением, но один аннотатор пишет несколько замечаний к одному экрану,\nи они зависимы. Проверим два главных вывода на уровне, где наблюдения независимее.</span>\n<ol>\n<li><strong>Смещение к верху экрана.</strong> Для каждого экрана считаем долю его мелких замечаний в верхних 20% высоты, затем сравниваем\n   среднюю по экранам долю с 20% (равномерный случай) одновыборочным t-критерием. Каждый экран — одно наблюдение.</li>\n<li><strong>Люди и ИИ.</strong> Берём аннотаторов (строки датасета), у которых есть и свои мелкие замечания, и принятые замечания ИИ,\n   и сравниваем среднюю высоту <marimo-tex class="arithmatex">||(h||)</marimo-tex> тех и других <strong>внутри одного аннотатора</strong> знаковым критерием Уилкоксона.\n   Так различия между экранами и аннотаторами не смешиваются с различием «человек — ИИ».</li>\n</ol></span>', 'source': '#### 5.5.4. Устойчивость выводов к группировке замечаний\n\nКритерии 5.5.1–5.5.3 считают каждое замечание отдельным наблюдением, но один аннотатор пишет несколько замечаний к одному экрану,\nи они зависимы. Проверим два главных вывода на уровне, где наблюдения независимее.\n\n1. **Смещение к верху экрана.** Для каждого экрана считаем долю его мелких замечаний в верхних 20% высоты, затем сравниваем\n   среднюю по экранам долю с 20% (равномерный случай) одновыборочным t-критерием. Каждый экран — одно наблюдение.\n2. **Люди и ИИ.** Берём аннотаторов (строки датасета), у которых есть и свои мелкие замечания, и принятые замечания ИИ,\n   и сравниваем среднюю высоту $h$ тех и других **внутри одного аннотатора** знаковым критерием Уилкоксона.\n   Так различия между экранами и аннотаторами не смешиваются с различием «человек — ИИ».'}, {'kind': 'code', 'html': '<pre class="numeric-result">Экранов: 982; средняя доля сверху: 50% (равномерно было бы 20%)\nt = 29.4, p = 1.5e-136\n\nАннотаторов с обоими источниками: 292\nМедиана разности h (люди − ИИ): -0.035; у людей выше на экране в 60% пар\nУилкоксон: W = 15237, p = 2.0e-05\n</pre>', 'source': '# 1. Доля мелких замечаний экрана в верхних 20% высоты: одно значение на экран\ntop_share = small.groupby("rico_id")["h"].apply(lambda s: (s < 0.2).mean())\nt_top = stats.ttest_1samp(top_share, 0.2)\nprint(f"Экранов: {len(top_share)}; средняя доля сверху: {top_share.mean():.0%} (равномерно было бы 20%)")\nprint(f"t = {t_top.statistic:.1f}, p = {t_top.pvalue:.1e}")\n\n# 2. Люди и ИИ внутри одного аннотатора: средняя высота h замечаний каждого источника\npaired = (small[small["source"].isin(["human", "llm"])]\n          .groupby(["annotation", "source"])["h"].mean()\n          .unstack().dropna())\nw = stats.wilcoxon(paired["human"], paired["llm"])\ndiff = paired["human"] - paired["llm"]\nprint(f"\\nАннотаторов с обоими источниками: {len(paired)}")\nprint(f"Медиана разности h (люди − ИИ): {diff.median():.3f}; у людей выше на экране в {(diff < 0).mean():.0%} пар")\nprint(f"Уилкоксон: W = {w.statistic:.0f}, p = {w.pvalue:.1e}")'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><span class="paragraph"><strong>Вывод.</strong> Мы боялись, что результаты получились такими только потому, что один человек пишет много замечаний к одному экрану. Поэтому перепроверили их по экранам и по отдельным аннотаторам. Оба вывода сохранились: на экранах в среднем половина мелких замечаний находится в верхней пятой части (p ≈ 10⁻¹³⁶), и даже у одного и того же аннотатора его собственные замечания расположены выше, чем принятые им замечания ИИ (p ≈ 2·10⁻⁵). Учесть, что некоторые экраны могут быть из одного приложения, мы не смогли: таких данных в датасете нет.</span></span>', 'source': '**Вывод.** Мы боялись, что результаты получились такими только потому, что один человек пишет много замечаний к одному экрану. Поэтому перепроверили их по экранам и по отдельным аннотаторам. Оба вывода сохранились: на экранах в среднем половина мелких замечаний находится в верхней пятой части (p ≈ 10⁻¹³⁶), и даже у одного и того же аннотатора его собственные замечания расположены выше, чем принятые им замечания ИИ (p ≈ 2·10⁻⁵). Учесть, что некоторые экраны могут быть из одного приложения, мы не смогли: таких данных в датасете нет.'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><span class="paragraph"><a id="uicrit-heat-limits"></a></span>\n<h3 id="uicrit-heading-79-1">5.6. Ограничения</h3>\n<ul>\n<li><strong>Темы — по ключевым словам.</strong> Грубая классификация: часть замечаний попадает не в свою тему или сразу в несколько.</li>\n<li><strong>Экраны разные</strong> (с клавиатурой и без, разной вёрстки), а накладываем их в одни координаты: карта показывает\n  тенденции, а не точные места.</li>\n<li><strong>Скриншотов нет:</strong> они в отдельном наборе RICO, поэтому под картой только силуэт.</li>\n<li><strong>Замечания не независимы:</strong> один аннотатор пишет несколько замечаний к одному экрану, поэтому p-value в 5.5.1–5.5.3\n  приблизительные. Главные выводы проверены на уровне экранов и аннотаторов в 5.5.4 и сохраняются; группировку экранов\n  по приложениям учесть нельзя — она в датасете не указана.</li>\n<li><strong>Ошибка в данных:</strong> в 83 строках метки автора не совпадают с замечаниями; эти замечания исключены из сравнения людей и ИИ.</li>\n</ul></span>', 'source': '<a id="heat-limits"></a>\n### 5.6. Ограничения\n\n- **Темы — по ключевым словам.** Грубая классификация: часть замечаний попадает не в свою тему или сразу в несколько.\n- **Экраны разные** (с клавиатурой и без, разной вёрстки), а накладываем их в одни координаты: карта показывает\n  тенденции, а не точные места.\n- **Скриншотов нет:** они в отдельном наборе RICO, поэтому под картой только силуэт.\n- **Замечания не независимы:** один аннотатор пишет несколько замечаний к одному экрану, поэтому p-value в 5.5.1–5.5.3\n  приблизительные. Главные выводы проверены на уровне экранов и аннотаторов в 5.5.4 и сохраняются; группировку экранов\n  по приложениям учесть нельзя — она в датасете не указана.\n- **Ошибка в данных:** в 83 строках метки автора не совпадают с замечаниями; эти замечания исключены из сравнения людей и ИИ.'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><span class="paragraph"><a id="uicrit-heat-resume"></a></span>\n<h3 id="uicrit-heading-80-1">5.7. Выводы по тепловой карте</h3>\n<span class="paragraph">Тепловая карта показала то, чего мы сначала не ожидали. Мы думали, что больше всего замечаний будет посередине экрана, там, где основной контент. Оказалось наоборот: мелкие проблемы чаще всего находят по краям и в верхних углах, где обычно кнопка «назад» и меню, в шапке и в нижней навигации. Проверка подтвердила, что это не случайность и почти половина мелких замечаний приходится на верхнюю пятую часть экрана, хотя при равномерном распределении было бы 20%.</span>\n<span class="paragraph">У каждой темы есть «своё место». Иконки и кнопки ругают в основном в шапке, кнопки — ещё и внизу, а текст и цвет — в контенте. По сути, эксперты чаще всего спотыкаются о навигационные элементы, которые есть почти на каждом экране.</span>\n<span class="paragraph">Ещё мы сравнили замечания людей и нейросети. Люди чаще отмечают конкретные элементы вверху экрана, а замечания Gemini обычно ниже и относятся к целым блокам. При этом рамки для замечаний Gemini тоже рисовали люди, так что это разница в том, о чём замечание, а не в том, куда «смотрит» нейросеть.</span>\n<span class="paragraph">Для дизайнеров вывод простой: когда они проверяют интерфейс стоит в первую очередь смотреть на края экрана где шапка, иконки и навигация. А в разделе 6 мы проверили, связаны ли такие замечания с тем, как эксперты оценивают экран.</span></span>', 'source': '<a id="heat-resume"></a>\n### 5.7. Выводы по тепловой карте\n\nТепловая карта показала то, чего мы сначала не ожидали. Мы думали, что больше всего замечаний будет посередине экрана, там, где основной контент. Оказалось наоборот: мелкие проблемы чаще всего находят по краям и в верхних углах, где обычно кнопка «назад» и меню, в шапке и в нижней навигации. Проверка подтвердила, что это не случайность и почти половина мелких замечаний приходится на верхнюю пятую часть экрана, хотя при равномерном распределении было бы 20%.\n\nУ каждой темы есть «своё место». Иконки и кнопки ругают в основном в шапке, кнопки — ещё и внизу, а текст и цвет — в контенте. По сути, эксперты чаще всего спотыкаются о навигационные элементы, которые есть почти на каждом экране.\n\nЕщё мы сравнили замечания людей и нейросети. Люди чаще отмечают конкретные элементы вверху экрана, а замечания Gemini обычно ниже и относятся к целым блокам. При этом рамки для замечаний Gemini тоже рисовали люди, так что это разница в том, о чём замечание, а не в том, куда «смотрит» нейросеть.\n\nДля дизайнеров вывод простой: когда они проверяют интерфейс стоит в первую очередь смотреть на края экрана где шапка, иконки и навигация. А в разделе 6 мы проверили, связаны ли такие замечания с тем, как эксперты оценивают экран.'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><h3 id="uicrit-heading-81-1">Методические уточнения к исходному разделу 5</h3>\n<span class="paragraph">При чтении результатов раздела 5 учитывай следующие уточнения:</span>\n<ul>\n<li>Значения p в обычных тестах по отдельным замечаниям не учитывают зависимость замечаний внутри экрана. Их малость <strong>не гарантирует</strong>, что вывод сохранится после учёта группировки. Результаты этих тестов рассматриваем как предварительные. Проверки раздела 6 используют экранные показатели, но тоже не учитывают неизвестную группировку по приложениям и повторное участие оценщиков.</li>\n<li>«Люди и ИИ смотрят по-разному» не означает различия взгляда: это различия расположения рамок принятых замечаний; рамки для Gemini назначали люди.</li>\n<li>Равномерность центров рамок — геометрическая модель сравнения. Даже случайно размещённые рамки конечного размера не обязательно имеют центры, равномерные на всём [0, 1]; эта проверка не измеряет вероятность дефекта в каждой зоне.</li>\n<li>Выбор мелких рамок ограничивает выводы мелкими замечаниями. Крупная рамка сама по себе не доказывает, что текст относится к «общему впечатлению».</li>\n<li>Медианная площадь и средняя площадь — разные характеристики. Выведенное в разделе 5 сравнение площадей относится к медианам.</li>\n</ul></span>', 'source': '### Методические уточнения к исходному разделу 5\n\nПри чтении результатов раздела 5 учитывай следующие уточнения:\n\n- Значения p в обычных тестах по отдельным замечаниям не учитывают зависимость замечаний внутри экрана. Их малость **не гарантирует**, что вывод сохранится после учёта группировки. Результаты этих тестов рассматриваем как предварительные. Проверки раздела 6 используют экранные показатели, но тоже не учитывают неизвестную группировку по приложениям и повторное участие оценщиков.\n- «Люди и ИИ смотрят по-разному» не означает различия взгляда: это различия расположения рамок принятых замечаний; рамки для Gemini назначали люди.\n- Равномерность центров рамок — геометрическая модель сравнения. Даже случайно размещённые рамки конечного размера не обязательно имеют центры, равномерные на всём [0, 1]; эта проверка не измеряет вероятность дефекта в каждой зоне.\n- Выбор мелких рамок ограничивает выводы мелкими замечаниями. Крупная рамка сама по себе не доказывает, что текст относится к «общему впечатлению».\n- Медианная площадь и средняя площадь — разные характеристики. Выведенное в разделе 5 сравнение площадей относится к медианам.\n'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><span class="paragraph"><a id="uicrit-rating-comments"></a></span>\n<h2 id="uicrit-heading-82-1"><strong>6. Что стоит за оценками: темы и расположение замечаний</strong></h2>\n<span class="paragraph"><strong>Вопрос, который мы рассматриваем в этом разделе:</strong> Отличаются ли темы и расположение замечаний у экранов с низкими и высокими средними оценками эстетики и удобства?</span>\n<span class="paragraph">В разделе 4 мы обнаружили сильную положительную связь средних\nоценок эстетики и удобства. При этом сравнение аннотаций показало,\nчто восприятие одного экрана может различаться между оценщиками.</span>\n<span class="paragraph">В разделе 5 мы исследовали темы и расположение замечаний и обнаружили\nконцентрацию мелких замечаний в верхней части экрана. Теперь проверим,\nразличаются ли темы и расположение замечаний у экранов с относительно\nнизкими и высокими средними оценками.</span>\n<span class="paragraph">Эстетику и удобство рассматриваем отдельно. Низкая или высокая средняя\nоценка характеризует группу в нашем датасете, но не означает единогласия\nоценщиков. Найденные различия описывают связь замечаний с оценками,\nа не причины этих оценок.</span>\n<h3 id="uicrit-heading-82-2"><strong>Как читать результаты</strong></h3>\n<span class="paragraph">Темы определяем по ключевым словам. Одно замечание может относиться\nк нескольким темам, поэтому сумма долей может превышать 100%.\nСначала рассчитываем доли для каждого экрана, затем усредняем их\nпо группе — каждый экран имеет одинаковый вес.</span>\n<span class="paragraph">Используем все замечания: человеческие и принятые людьми замечания\nGemini. Расположение определяем по рамкам, назначенным людьми;\nоно не показывает взгляд оценщика или вероятность дефекта.</span></span>', 'source': '<a id="rating-comments"></a>\n\n## **6. Что стоит за оценками: темы и расположение замечаний**\n\n**Вопрос, который мы рассматриваем в этом разделе:** Отличаются ли темы и расположение замечаний у экранов с низкими и высокими средними оценками эстетики и удобства?\n\nВ разделе 4 мы обнаружили сильную положительную связь средних\nоценок эстетики и удобства. При этом сравнение аннотаций показало,\nчто восприятие одного экрана может различаться между оценщиками.\n\nВ разделе 5 мы исследовали темы и расположение замечаний и обнаружили\nконцентрацию мелких замечаний в верхней части экрана. Теперь проверим,\nразличаются ли темы и расположение замечаний у экранов с относительно\nнизкими и высокими средними оценками.\n\nЭстетику и удобство рассматриваем отдельно. Низкая или высокая средняя\nоценка характеризует группу в нашем датасете, но не означает единогласия\nоценщиков. Найденные различия описывают связь замечаний с оценками,\nа не причины этих оценок.\n### **Как читать результаты**\n\nТемы определяем по ключевым словам. Одно замечание может относиться\nк нескольким темам, поэтому сумма долей может превышать 100%.\nСначала рассчитываем доли для каждого экрана, затем усредняем их\nпо группе — каждый экран имеет одинаковый вес.\n\nИспользуем все замечания: человеческие и принятые людьми замечания\nGemini. Расположение определяем по рамкам, назначенным людьми;\nоно не показывает взгляд оценщика или вероятность дефекта.\n'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><span class="paragraph"><a id="uicrit-rating-groups"></a></span>\n<h3 id="uicrit-heading-83-1">6.1. Подготовка и разделение экранов</h3>\n<span class="paragraph">Для каждого показателя нижняя группа: оценка ≤ Q1; верхняя: оценка ≥ Q3. Равные оценки не разрываем произвольно, поэтому группы могут быть больше 25%. Средние экраны в сравнении крайних групп не участвуют.</span>\n<span class="paragraph">Замечания разбираем заново из <code>df</code>, сохраняя и тексты без корректной рамки для анализа тем. Для карт оставляем только конечные координаты с 0 ≤ x1 &lt; x2 ≤ 1 и 0 ≤ y1 &lt; y2 ≤ 1. Несовпадения источников не мешают этому анализу: по источникам здесь не разделяем.</span></span>', 'source': '<a id="rating-groups"></a>\n### 6.1. Подготовка и разделение экранов\n\nДля каждого показателя нижняя группа: оценка ≤ Q1; верхняя: оценка ≥ Q3. Равные оценки не разрываем произвольно, поэтому группы могут быть больше 25%. Средние экраны в сравнении крайних групп не участвуют.\n\nЗамечания разбираем заново из `df`, сохраняя и тексты без корректной рамки для анализа тем. Для карт оставляем только конечные координаты с 0 ≤ x1 < x2 ≤ 1 и 0 ≤ y1 < y2 ≤ 1. Несовпадения источников не мешают этому анализу: по источникам здесь не разделяем.\n'}, {'kind': 'code', 'html': '<div class="tbl-wrap"><div>\n<style scoped>\n    .dataframe tbody tr th:only-of-type {\n        vertical-align: middle;\n    }\n\n    .dataframe tbody tr th {\n        vertical-align: top;\n    }\n\n    .dataframe thead th {\n        text-align: right;\n    }\n</style>\n<table border="1" class="dataframe">\n  <thead>\n    <tr style="text-align: right;">\n      <th></th>\n      <th>Показатель</th>\n      <th>Группа</th>\n      <th>Граница</th>\n      <th>Экранов</th>\n      <th>С замечаниями</th>\n      <th>Замечаний</th>\n    </tr>\n  </thead>\n  <tbody>\n    <tr>\n      <th>0</th>\n      <td>Эстетика</td>\n      <td>Низкие</td>\n      <td>5.333333</td>\n      <td>322</td>\n      <td>322</td>\n      <td>3918</td>\n    </tr>\n    <tr>\n      <th>1</th>\n      <td>Эстетика</td>\n      <td>Высокие</td>\n      <td>6.333333</td>\n      <td>259</td>\n      <td>259</td>\n      <td>2714</td>\n    </tr>\n    <tr>\n      <th>2</th>\n      <td>Удобство</td>\n      <td>Низкие</td>\n      <td>5.333333</td>\n      <td>292</td>\n      <td>292</td>\n      <td>3668</td>\n    </tr>\n    <tr>\n      <th>3</th>\n      <td>Удобство</td>\n      <td>Высокие</td>\n      <td>6.333333</td>\n      <td>284</td>\n      <td>284</td>\n      <td>2823</td>\n    </tr>\n  </tbody>\n</table>\n</div></div><pre class="numeric-result">Строк с ошибкой разбора: 0\nВсего замечаний: 11430\nС корректной рамкой: 11430\n</pre>', 'source': 'import ast\nimport re\n\nlink_records = []\nlink_parse_errors = 0\nlink_box_pattern = re.compile(r"Bounding\\s+Box:\\s*\\[([^\\]]+)\\]", re.I)\nlink_patterns = {\n    "Цвет и контраст": r"\\b(?:colou?r|contrast)\\b",\n    "Текст и шрифт": r"\\bfont\\w*\\b|\\btext\\s+size\\b|\\breadab\\w*\\b",\n    "Кнопки": r"\\bbutton\\w*\\b",\n    "Иконки": r"\\bicon\\w*\\b",\n}\nfor _, row in df.iterrows():\n    try:\n        comments_list = ast.literal_eval(row["comments"])\n        if not isinstance(comments_list, list):\n            raise ValueError("Ожидался список")\n    except (ValueError, SyntaxError, TypeError):\n        link_parse_errors += 1\n        continue\n    for comment in comments_list:\n        if not isinstance(comment, str):\n            continue\n        text_only = link_box_pattern.sub("", comment).lower()\n        record = {"rico_id": row["rico_id"], "text": text_only,\n                  "valid_box": False, "x1": np.nan, "y1": np.nan,\n                  "x2": np.nan, "y2": np.nan}\n        match = link_box_pattern.search(comment)\n        if match:\n            try:\n                coordinates = np.array([float(z) for z in match.group(1).split(",")])\n                if len(coordinates) == 4 and np.isfinite(coordinates).all():\n                    x1, y1, x2, y2 = coordinates\n                    if 0 <= x1 < x2 <= 1 and 0 <= y1 < y2 <= 1:\n                        record.update(valid_box=True, x1=x1, y1=y1, x2=x2, y2=y2)\n            except ValueError:\n                pass\n        for theme, pattern in link_patterns.items():\n            record[theme] = bool(re.search(pattern, text_only))\n        link_records.append(record)\n\nlink_comments = pd.DataFrame(link_records)\nlink_comments["area"] = ((link_comments.x2 - link_comments.x1)\n                         * (link_comments.y2 - link_comments.y1))\nlink_theme_columns = list(link_patterns)\nlink_screen_shares = link_comments.groupby("rico_id")[link_theme_columns].mean()\nlink_counts = link_comments.groupby("rico_id").size().rename("n_comments")\nlink_screens = screens.merge(link_screen_shares, on="rico_id", how="left").merge(\n    link_counts, on="rico_id", how="left")\nlink_metrics = {"Эстетика": "aesthetics_mean", "Удобство": "usability_mean"}\nlink_groups, link_group_rows = {}, []\nfor metric_name, metric_column in link_metrics.items():\n    q_low, q_high = link_screens[metric_column].quantile([.25, .75])\n    if not q_low < q_high:\n        raise ValueError("Квартильные границы совпали: группы требуют другого правила")\n    low_ids = link_screens.loc[link_screens[metric_column] <= q_low, "rico_id"]\n    high_ids = link_screens.loc[link_screens[metric_column] >= q_high, "rico_id"]\n    link_groups[metric_name] = {"Низкие": set(low_ids), "Высокие": set(high_ids)}\n    assert set(low_ids).isdisjoint(set(high_ids))\n    for group_name, ids in link_groups[metric_name].items():\n        subset = link_screens[link_screens.rico_id.isin(ids)]\n        link_group_rows.append({"Показатель": metric_name, "Группа": group_name,\n            "Граница": q_low if group_name == "Низкие" else q_high,\n            "Экранов": len(subset), "С замечаниями": int(subset.n_comments.notna().sum()),\n            "Замечаний": int(subset.n_comments.sum())})\nprint("Строк с ошибкой разбора:", link_parse_errors)\nprint("Всего замечаний:", len(link_comments))\nprint("С корректной рамкой:", int(link_comments.valid_box.sum()))\ndisplay(pd.DataFrame(link_group_rows))\n'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><h4 id="uicrit-heading-85-1">Вывод о составе групп</h4>\n<span class="paragraph">Группы получились примерно одинаковыми по количеству экранов, самая большая группа получилась с низкими оценками эстетики. Границы низких и высоких средних оценок совпали для эстетики и удобства: 5,33 и 6,33 балла соответственно. Размеры групп различаются из-за повторяющихся оценок на границах квартилей, поэтому также мы получили не четверть датасета. Также все группы имеют какие-то замечания. В группах низких оценок среднее число замечаний на экран выше, однако статистическая значимость этого различия пока не проверялась</span></span>', 'source': '#### Вывод о составе групп\n\nГруппы получились примерно одинаковыми по количеству экранов, самая большая группа получилась с низкими оценками эстетики. Границы низких и высоких средних оценок совпали для эстетики и удобства: 5,33 и 6,33 балла соответственно. Размеры групп различаются из-за повторяющихся оценок на границах квартилей, поэтому также мы получили не четверть датасета. Также все группы имеют какие-то замечания. В группах низких оценок среднее число замечаний на экран выше, однако статистическая значимость этого различия пока не проверялась\n'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><span class="paragraph"><a id="uicrit-rating-themes"></a></span>\n<h3 id="uicrit-heading-86-1">6.2. Какие темы встречаются в замечаниях</h3>\n<span class="paragraph">Для экрана доля темы — число его замечаний с соответствующими ключевыми словами, делённое на общее число его замечаний. На графике — средняя этих долей по экранам группы. Например, 20% означает среднюю долю замечаний данной темы внутри экрана, а не долю плохих экранов.</span>\n<span class="paragraph">Горизонтальные отрезки — 95%-е процентильные bootstrap-интервалы: повторно выбираем экраны с возвращением внутри каждой группы. Они условны на выбранных группах и предполагают независимость экранов. Связь экранов одного приложения и повторное участие оценщиков этим не учитываются. Перекрытие интервалов само по себе не является тестом различий.</span></span>', 'source': '<a id="rating-themes"></a>\n### 6.2. Какие темы встречаются в замечаниях\n\nДля экрана доля темы — число его замечаний с соответствующими ключевыми словами, делённое на общее число его замечаний. На графике — средняя этих долей по экранам группы. Например, 20% означает среднюю долю замечаний данной темы внутри экрана, а не долю плохих экранов.\n\nГоризонтальные отрезки — 95%-е процентильные bootstrap-интервалы: повторно выбираем экраны с возвращением внутри каждой группы. Они условны на выбранных группах и предполагают независимость экранов. Связь экранов одного приложения и повторное участие оценщиков этим не учитываются. Перекрытие интервалов само по себе не является тестом различий.\n'}, {'kind': 'code', 'html': '<figure class="plot plot-wide"><img width="1552" height="562" decoding="async" data-report-asset="./public/reports/uicrit/87-0.png" src="data:image/png;base64," alt="График исследования" /></figure><div class="tbl-wrap"><div>\n<style scoped>\n    .dataframe tbody tr th:only-of-type {\n        vertical-align: middle;\n    }\n\n    .dataframe tbody tr th {\n        vertical-align: top;\n    }\n\n    .dataframe thead th {\n        text-align: right;\n    }\n</style>\n<table border="1" class="dataframe">\n  <thead>\n    <tr style="text-align: right;">\n      <th></th>\n      <th>Показатель</th>\n      <th>Группа</th>\n      <th>Тема</th>\n      <th>Средняя доля, %</th>\n      <th>Нижняя граница, %</th>\n      <th>Верхняя граница, %</th>\n      <th>Экранов</th>\n    </tr>\n  </thead>\n  <tbody>\n    <tr>\n      <th>0</th>\n      <td>Эстетика</td>\n      <td>Низкие</td>\n      <td>Цвет и контраст</td>\n      <td>26.85</td>\n      <td>25.06</td>\n      <td>28.69</td>\n      <td>322</td>\n    </tr>\n    <tr>\n      <th>1</th>\n      <td>Эстетика</td>\n      <td>Низкие</td>\n      <td>Текст и шрифт</td>\n      <td>24.45</td>\n      <td>22.86</td>\n      <td>26.09</td>\n      <td>322</td>\n    </tr>\n    <tr>\n      <th>2</th>\n      <td>Эстетика</td>\n      <td>Низкие</td>\n      <td>Кнопки</td>\n      <td>20.47</td>\n      <td>18.85</td>\n      <td>22.28</td>\n      <td>322</td>\n    </tr>\n    <tr>\n      <th>3</th>\n      <td>Эстетика</td>\n      <td>Низкие</td>\n      <td>Иконки</td>\n      <td>17.28</td>\n      <td>15.67</td>\n      <td>18.86</td>\n      <td>322</td>\n    </tr>\n    <tr>\n      <th>4</th>\n      <td>Эстетика</td>\n      <td>Высокие</td>\n      <td>Цвет и контраст</td>\n      <td>25.55</td>\n      <td>23.60</td>\n      <td>27.60</td>\n      <td>259</td>\n    </tr>\n    <tr>\n      <th>5</th>\n      <td>Эстетика</td>\n      <td>Высокие</td>\n      <td>Текст и шрифт</td>\n      <td>26.62</td>\n      <td>24.45</td>\n      <td>28.79</td>\n      <td>259</td>\n    </tr>\n    <tr>\n      <th>6</th>\n      <td>Эстетика</td>\n      <td>Высокие</td>\n      <td>Кнопки</td>\n      <td>21.93</td>\n      <td>19.84</td>\n      <td>24.12</td>\n      <td>259</td>\n    </tr>\n    <tr>\n      <th>7</th>\n      <td>Эстетика</td>\n      <td>Высокие</td>\n      <td>Иконки</td>\n      <td>12.81</td>\n      <td>11.01</td>\n      <td>14.68</td>\n      <td>259</td>\n    </tr>\n    <tr>\n      <th>8</th>\n      <td>Удобство</td>\n      <td>Низкие</td>\n      <td>Цвет и контраст</td>\n      <td>24.84</td>\n      <td>23.05</td>\n      <td>26.68</td>\n      <td>292</td>\n    </tr>\n    <tr>\n      <th>9</th>\n      <td>Удобство</td>\n      <td>Низкие</td>\n      <td>Текст и шрифт</td>\n      <td>24.16</td>\n      <td>22.47</td>\n      <td>25.77</td>\n      <td>292</td>\n    </tr>\n    <tr>\n      <th>10</th>\n      <td>Удобство</td>\n      <td>Низкие</td>\n      <td>Кнопки</td>\n      <td>22.13</td>\n      <td>20.37</td>\n      <td>23.93</td>\n      <td>292</td>\n    </tr>\n    <tr>\n      <th>11</th>\n      <td>Удобство</td>\n      <td>Низкие</td>\n      <td>Иконки</td>\n      <td>15.44</td>\n      <td>13.84</td>\n      <td>17.05</td>\n      <td>292</td>\n    </tr>\n    <tr>\n      <th>12</th>\n      <td>Удобство</td>\n      <td>Высокие</td>\n      <td>Цвет и контраст</td>\n      <td>26.46</td>\n      <td>24.31</td>\n      <td>28.50</td>\n      <td>284</td>\n    </tr>\n    <tr>\n      <th>13</th>\n      <td>Удобство</td>\n      <td>Высокие</td>\n      <td>Текст и шрифт</td>\n      <td>26.18</td>\n      <td>24.04</td>\n      <td>28.26</td>\n      <td>284</td>\n    </tr>\n    <tr>\n      <th>14</th>\n      <td>Удобство</td>\n      <td>Высокие</td>\n      <td>Кнопки</td>\n      <td>22.02</td>\n      <td>19.89</td>\n      <td>24.24</td>\n      <td>284</td>\n    </tr>\n    <tr>\n      <th>15</th>\n      <td>Удобство</td>\n      <td>Высокие</td>\n      <td>Иконки</td>\n      <td>13.45</td>\n      <td>11.70</td>\n      <td>15.28</td>\n      <td>284</td>\n    </tr>\n  </tbody>\n</table>\n</div></div>', 'source': 'link_rng = np.random.default_rng(42)\nlink_theme_rows = []\nfor metric_name, groups in link_groups.items():\n    for group_name, ids in groups.items():\n        subset = link_screens[link_screens.rico_id.isin(ids)]\n        for theme in link_theme_columns:\n            values = subset[theme].dropna().to_numpy(float)\n            boot = np.array([link_rng.choice(values, len(values), replace=True).mean()\n                             for _ in range(2000)])\n            ci_low, ci_high = np.quantile(boot, [.025, .975])\n            link_theme_rows.append({"Показатель": metric_name, "Группа": group_name,\n                "Тема": theme, "Средняя доля, %": 100 * values.mean(),\n                "Нижняя граница, %": 100 * ci_low, "Верхняя граница, %": 100 * ci_high,\n                "Экранов": len(values)})\nlink_theme_summary = pd.DataFrame(link_theme_rows)\nlink_colors = {"Низкие": "#7463C7", "Высокие": "#438F92"}\nfig, axes = plt.subplots(1, 2, figsize=(14, 5), sharex=True, sharey=True,\n                         constrained_layout=True)\nfor ax, metric_name in zip(axes, link_metrics):\n    for offset, group_name in [(-.12, "Низкие"), (.12, "Высокие")]:\n        part = link_theme_summary[(link_theme_summary.Показатель == metric_name)\n                                  & (link_theme_summary.Группа == group_name)]\n        center = part["Средняя доля, %"].to_numpy()\n        error = np.vstack([center - part["Нижняя граница, %"].to_numpy(),\n                           part["Верхняя граница, %"].to_numpy() - center])\n        ax.errorbar(center, np.arange(len(part)) + offset, xerr=error,\n                    fmt="o", capsize=3, color=link_colors[group_name], label=group_name)\n    ax.set(title=metric_name, xlabel="Средняя по экранам доля замечаний темы, %")\n    ax.set_yticks(range(len(link_theme_columns)), link_theme_columns)\n    ax.legend(title="Средние оценки", frameon=False)\naxes[0].invert_yaxis()\nplt.show()\ndisplay(link_theme_summary.round(2))\n'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><h4 id="uicrit-heading-88-1"><strong>Вывод о теме замечаний</strong></h4>\n<span class="paragraph">Наибольшую долю замечаний в группах низких оценок составляют замечания о цвете и контрасте: для эстетики — 26,85%, для удобства — 24,84%. Касаемо высоких оценок чаще всего встречается у эстетики текст и шрифт, а в удобстве почти наравне идут цвет и контраст с текстом и шрифтом(типографика сайта зачастую действительно играет большую роль, по крайней мере из собственного опыта). Снова видно то, насколько похожи эстетика и удобство по показателям и визуально, Наиболее заметное различие между низкой и высокой группами наблюдается для иконок по эстетике — 4,47 процентного пункта, хотя по удобству оно направлено в ту же сторону, но меньше — 1,99 п.п.</span></span>', 'source': '#### **Вывод о теме замечаний**\n\nНаибольшую долю замечаний в группах низких оценок составляют замечания о цвете и контрасте: для эстетики — 26,85%, для удобства — 24,84%. Касаемо высоких оценок чаще всего встречается у эстетики текст и шрифт, а в удобстве почти наравне идут цвет и контраст с текстом и шрифтом(типографика сайта зачастую действительно играет большую роль, по крайней мере из собственного опыта). Снова видно то, насколько похожи эстетика и удобство по показателям и визуально, Наиболее заметное различие между низкой и высокой группами наблюдается для иконок по эстетике — 4,47 процентного пункта, хотя по удобству оно направлено в ту же сторону, но меньше — 1,99 п.п.\n\n'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><span class="paragraph"><a id="uicrit-rating-tests"></a></span>\n<h3 id="uicrit-heading-89-1"><strong>6.3 Проверка различий между группами</strong></h3>\n<span class="paragraph">Для каждой темы и каждого показателя проверяем нулевую гипотезу об одинаковом распределении экранных долей в низкой и высокой группах. Статистика — разность средних долей (низкие минус высокие). Переставляем групповые метки между экранами; отдельные замечания не считаем независимыми наблюдениями.</span>\n<span class="paragraph">Проверка двусторонняя, 4999 перестановок, α = 0,05. Для восьми сравнений применяем поправку Холма. Минимальная Monte Carlo оценка p-value равна 1/5000. Это исследовательские сравнения, а не причинный эксперимент. Экраны считаются независимыми и обменными при нулевой гипотезе; неизвестная группировка по приложениям и оценщикам остаётся ограничением.</span></span>', 'source': '<a id="rating-tests"></a>\n### **6.3 Проверка различий между группами**\n\nДля каждой темы и каждого показателя проверяем нулевую гипотезу об одинаковом распределении экранных долей в низкой и высокой группах. Статистика — разность средних долей (низкие минус высокие). Переставляем групповые метки между экранами; отдельные замечания не считаем независимыми наблюдениями.\n\nПроверка двусторонняя, 4999 перестановок, α = 0,05. Для восьми сравнений применяем поправку Холма. Минимальная Monte Carlo оценка p-value равна 1/5000. Это исследовательские сравнения, а не причинный эксперимент. Экраны считаются независимыми и обменными при нулевой гипотезе; неизвестная группировка по приложениям и оценщикам остаётся ограничением.\n'}, {'kind': 'code', 'html': '<div class="tbl-wrap"><div>\n<style scoped>\n    .dataframe tbody tr th:only-of-type {\n        vertical-align: middle;\n    }\n\n    .dataframe tbody tr th {\n        vertical-align: top;\n    }\n\n    .dataframe thead th {\n        text-align: right;\n    }\n</style>\n<table border="1" class="dataframe">\n  <thead>\n    <tr style="text-align: right;">\n      <th></th>\n      <th>Показатель</th>\n      <th>Тема</th>\n      <th>Разность низкие − высокие, п.п.</th>\n      <th>p-value</th>\n      <th>p-value Холма</th>\n      <th>Отвергаем H₀ при 0,05</th>\n    </tr>\n  </thead>\n  <tbody>\n    <tr>\n      <th>0</th>\n      <td>Эстетика</td>\n      <td>Цвет и контраст</td>\n      <td>1.3032</td>\n      <td>0.3534</td>\n      <td>1.0000</td>\n      <td>False</td>\n    </tr>\n    <tr>\n      <th>1</th>\n      <td>Эстетика</td>\n      <td>Текст и шрифт</td>\n      <td>-2.1664</td>\n      <td>0.1188</td>\n      <td>0.7896</td>\n      <td>False</td>\n    </tr>\n    <tr>\n      <th>2</th>\n      <td>Эстетика</td>\n      <td>Кнопки</td>\n      <td>-1.4670</td>\n      <td>0.2978</td>\n      <td>1.0000</td>\n      <td>False</td>\n    </tr>\n    <tr>\n      <th>3</th>\n      <td>Эстетика</td>\n      <td>Иконки</td>\n      <td>4.4619</td>\n      <td>0.0006</td>\n      <td>0.0048</td>\n      <td>True</td>\n    </tr>\n    <tr>\n      <th>4</th>\n      <td>Удобство</td>\n      <td>Цвет и контраст</td>\n      <td>-1.6236</td>\n      <td>0.2620</td>\n      <td>1.0000</td>\n      <td>False</td>\n    </tr>\n    <tr>\n      <th>5</th>\n      <td>Удобство</td>\n      <td>Текст и шрифт</td>\n      <td>-2.0236</td>\n      <td>0.1510</td>\n      <td>0.7896</td>\n      <td>False</td>\n    </tr>\n    <tr>\n      <th>6</th>\n      <td>Удобство</td>\n      <td>Кнопки</td>\n      <td>0.1106</td>\n      <td>0.9414</td>\n      <td>1.0000</td>\n      <td>False</td>\n    </tr>\n    <tr>\n      <th>7</th>\n      <td>Удобство</td>\n      <td>Иконки</td>\n      <td>1.9959</td>\n      <td>0.1128</td>\n      <td>0.7896</td>\n      <td>False</td>\n    </tr>\n  </tbody>\n</table>\n</div></div>', 'source': 'link_test_rng = np.random.default_rng(2026)\nlink_test_rows = []\nfor metric_name, groups in link_groups.items():\n    low = link_screens[link_screens.rico_id.isin(groups["Низкие"])]\n    high = link_screens[link_screens.rico_id.isin(groups["Высокие"])]\n    for theme in link_theme_columns:\n        first, second = low[theme].dropna().to_numpy(), high[theme].dropna().to_numpy()\n        observed = first.mean() - second.mean()\n        pool = np.r_[first, second]\n        extreme = 0\n        for _ in range(4999):\n            shuffled = link_test_rng.permutation(pool)\n            difference = shuffled[:len(first)].mean() - shuffled[len(first):].mean()\n            extreme += abs(difference) >= abs(observed) - 1e-12\n        link_test_rows.append({"Показатель": metric_name, "Тема": theme,\n            "Разность низкие − высокие, п.п.": observed * 100,\n            "p-value": (extreme + 1) / 5000})\nlink_tests = pd.DataFrame(link_test_rows)\np_values = link_tests["p-value"].to_numpy()\norder = np.argsort(p_values)\nadjusted_order = np.minimum(1, np.maximum.accumulate(\n    (len(p_values) - np.arange(len(p_values))) * p_values[order]))\nadjusted = np.empty(len(p_values)); adjusted[order] = adjusted_order\nlink_tests["p-value Холма"] = adjusted\nlink_tests["Отвергаем H₀ при 0,05"] = adjusted < .05\ndisplay(link_tests.round(4))\n'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><h4 id="uicrit-heading-91-1"><strong>Вывод о проверке различий</strong></h4>\n<span class="paragraph">Тут мы видим, что p-value с поправкой Холма меньше 0,05 только у иконок, конкретно у эстетики, поэтому это единственный случай, где мы отвергаем H₀. Это значит, что статистически значимое различие обнаружено только для одной темы замечаний: в группе низких средних оценок эстетики доля замечаний об иконках выше на 4,46 процентного пункта, чем в группе высоких. Для остальных тем, а также для всех тем по удобству, различие не подтвердилось.</span></span>', 'source': '#### **Вывод о проверке различий**\n\nТут мы видим, что p-value с поправкой Холма меньше 0,05 только у иконок, конкретно у эстетики, поэтому это единственный случай, где мы отвергаем H₀. Это значит, что статистически значимое различие обнаружено только для одной темы замечаний: в группе низких средних оценок эстетики доля замечаний об иконках выше на 4,46 процентного пункта, чем в группе высоких. Для остальных тем, а также для всех тем по удобству, различие не подтвердилось.'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><h3 id="uicrit-heading-92-1"><strong>6.4 Расположение замечаний и его связь с оценкой</strong></h3>\n<span class="paragraph">Вместо тепловых карт используем две статические панели: сначала для эстетики, затем для удобства. В обеих — одинаковые шкалы.</span>\n<span class="paragraph"><strong>Слева:</strong> экран делится на десять полос по высоте. Замечание относим к полосе по центру его рамки. Сначала считаем доли замечаний по полосам отдельно для каждого экрана, затем усредняем внутри группы низких или высоких оценок. Крупнее число по горизонтали — больше средняя доля замечаний в полосе. Верх рисунка соответствует верху экрана. Это распределение центров, а не карта покрытия рамками из раздела 5.</span>\n<span class="paragraph"><strong>Справа:</strong> одна точка — один экран. X — его средняя оценка; Y — доля его мелких замечаний с центром в верхних 20% высоты. Здесь используются все экраны с подходящими рамками, включая среднюю группу. Порог верхней зоны 20% — описательный выбор, а не естественная граница интерфейса. Коэффициент Спирмена подписан как характеристика связи; отдельное подтверждающее тестирование по этому графику не проводится.</span>\n<span class="paragraph">Берём только корректные рамки площадью менее 5%. Экраны без подходящих рамок исключаются, а не получают нулевую долю. Размеры групп показаны в таблице. Один экран имеет одинаковый вес независимо от количества замечаний. Сходные координаты не означают одинаковых элементов. Различия не доказывают причину низкой или высокой оценки.</span></span>', 'source': '### **6.4 Расположение замечаний и его связь с оценкой**\n\nВместо тепловых карт используем две статические панели: сначала для эстетики, затем для удобства. В обеих — одинаковые шкалы.\n\n**Слева:** экран делится на десять полос по высоте. Замечание относим к полосе по центру его рамки. Сначала считаем доли замечаний по полосам отдельно для каждого экрана, затем усредняем внутри группы низких или высоких оценок. Крупнее число по горизонтали — больше средняя доля замечаний в полосе. Верх рисунка соответствует верху экрана. Это распределение центров, а не карта покрытия рамками из раздела 5.\n\n**Справа:** одна точка — один экран. X — его средняя оценка; Y — доля его мелких замечаний с центром в верхних 20% высоты. Здесь используются все экраны с подходящими рамками, включая среднюю группу. Порог верхней зоны 20% — описательный выбор, а не естественная граница интерфейса. Коэффициент Спирмена подписан как характеристика связи; отдельное подтверждающее тестирование по этому графику не проводится.\n\nБерём только корректные рамки площадью менее 5%. Экраны без подходящих рамок исключаются, а не получают нулевую долю. Размеры групп показаны в таблице. Один экран имеет одинаковый вес независимо от количества замечаний. Сходные координаты не означают одинаковых элементов. Различия не доказывают причину низкой или высокой оценки.\n'}, {'kind': 'code', 'html': '<figure class="plot plot-wide"><img width="1442" height="562" decoding="async" data-report-asset="./public/reports/uicrit/93-0.png" src="data:image/png;base64," alt="График исследования" /></figure><figure class="plot plot-wide"><img width="1442" height="562" decoding="async" data-report-asset="./public/reports/uicrit/93-1.png" src="data:image/png;base64," alt="График исследования" /></figure><div class="tbl-wrap"><div>\n<style scoped>\n    .dataframe tbody tr th:only-of-type {\n        vertical-align: middle;\n    }\n\n    .dataframe tbody tr th {\n        vertical-align: top;\n    }\n\n    .dataframe thead th {\n        text-align: right;\n    }\n</style>\n<table border="1" class="dataframe">\n  <thead>\n    <tr style="text-align: right;">\n      <th></th>\n      <th>Показатель</th>\n      <th>Группа</th>\n      <th>Всего экранов</th>\n      <th>В профиле</th>\n      <th>Без подходящих рамок</th>\n    </tr>\n  </thead>\n  <tbody>\n    <tr>\n      <th>0</th>\n      <td>Эстетика</td>\n      <td>Низкие</td>\n      <td>322</td>\n      <td>316</td>\n      <td>6</td>\n    </tr>\n    <tr>\n      <th>1</th>\n      <td>Эстетика</td>\n      <td>Высокие</td>\n      <td>259</td>\n      <td>258</td>\n      <td>1</td>\n    </tr>\n    <tr>\n      <th>2</th>\n      <td>Удобство</td>\n      <td>Низкие</td>\n      <td>292</td>\n      <td>288</td>\n      <td>4</td>\n    </tr>\n    <tr>\n      <th>3</th>\n      <td>Удобство</td>\n      <td>Высокие</td>\n      <td>284</td>\n      <td>280</td>\n      <td>4</td>\n    </tr>\n  </tbody>\n</table>\n</div></div><pre class="numeric-result">В облаках: 982 экранов из 1000\nСовпадающие точки могут накладываться; значения не сдвигаются.\n</pre>', 'source': '# Статические профили и облака точек: без виджетов и тепловых карт.\nlink_height_bins = np.linspace(0, 1, 11)\nlink_height_centers = (link_height_bins[:-1] + link_height_bins[1:]) / 2\n\ndef link_location_data(area_limit=.05):\n    selected = link_comments[\n        link_comments.valid_box & (link_comments.area < area_limit)\n    ].copy()\n    selected["center_y"] = (selected.y1 + selected.y2) / 2\n    profiles, screen_rows = {}, []\n    for screen_id, group in selected.groupby("rico_id"):\n        heights = group.center_y.to_numpy()\n        profiles[screen_id] = np.histogram(heights, bins=link_height_bins)[0] / len(heights)\n        screen_rows.append({"rico_id": screen_id,\n                           "upper_share": (heights < .2).mean(),\n                           "n_small_comments": len(heights)})\n    summary = pd.DataFrame(screen_rows).merge(\n        screens[["rico_id", "aesthetics_mean", "usability_mean"]], on="rico_id")\n    return profiles, summary\n\nlink_profiles, link_location_screens = link_location_data()\nlink_profile_results, link_coverage_rows = {}, []\nfor metric_name, groups in link_groups.items():\n    for group_name, ids in groups.items():\n        included = [link_profiles[i] for i in ids if i in link_profiles]\n        link_profile_results[(metric_name, group_name)] = np.mean(included, axis=0) * 100\n        link_coverage_rows.append({"Показатель": metric_name, "Группа": group_name,\n            "Всего экранов": len(ids), "В профиле": len(included),\n            "Без подходящих рамок": len(ids)-len(included)})\nlink_profile_max = max(values.max() for values in link_profile_results.values()) * 1.12\nlink_plot_lower = max(1, np.floor(link_location_screens[list(link_metrics.values())].min().min())-.5)\nlink_plot_upper = min(10, np.ceil(link_location_screens[list(link_metrics.values())].max().max())+.5)\n\nfor metric_name, metric_column in link_metrics.items():\n    fig, axes = plt.subplots(1, 2, figsize=(13, 5), constrained_layout=True)\n    for group_name in ["Низкие", "Высокие"]:\n        axes[0].plot(link_profile_results[(metric_name, group_name)],\n                     link_height_centers * 100, marker="o", linewidth=2,\n                     color=link_colors[group_name], label=group_name)\n    axes[0].set(title="Где находятся центры замечаний?",\n        xlabel="Средняя по экранам доля замечаний в полосе, %",\n        ylabel="Высота центра рамки: 0% — верх, 100% — низ",\n        xlim=(0, link_profile_max), ylim=(100, 0))\n    axes[0].set_yticks(np.arange(0, 101, 10))\n    axes[0].legend(title="Средние оценки", frameon=False)\n    coefficient = stats.spearmanr(link_location_screens[metric_column],\n                                 link_location_screens.upper_share).statistic\n    axes[1].scatter(link_location_screens[metric_column],\n                    link_location_screens.upper_share * 100,\n                    s=24, alpha=.3, color="#438F92", edgecolors="none")\n    axes[1].set(title=f"Оценка и доля замечаний сверху · ρ = {coefficient:.3f}",\n        xlabel=f"Средняя оценка: {metric_name.lower()}, баллы",\n        ylabel="Доля мелких замечаний экрана в верхних 20%, %",\n        xlim=(link_plot_lower, link_plot_upper), ylim=(-3, 103))\n    for ax in axes:\n        ax.grid(alpha=.25)\n        ax.spines["top"].set_visible(False)\n        ax.spines["right"].set_visible(False)\n    fig.suptitle(f"{metric_name}: оценки и расположение замечаний · рамки < 5% площади",\n                 fontsize=13, fontweight="bold")\n    plt.show()\nprint("В облаках:", len(link_location_screens), "экранов из", len(screens))\nprint("Совпадающие точки могут накладываться; значения не сдвигаются.")\ndisplay(pd.DataFrame(link_coverage_rows))\n'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><h4 id="uicrit-heading-94-1"><strong>Вывод о расположении замечаний</strong></h4>\n<span class="paragraph">В основном замечания расположены в верхней части экрана, если мы посмотрим на левые 2 графика. У удобства сосредоточенность низких оценок побольше, но при этом профили графиков также сильно похожи между собой.</span>\n<span class="paragraph">Если мы посмотрим на правые графики, то увидим, что облако на обоих графиках получилось достаточно размашистым, а связь средней оценки с долей замечаний в верхних 20% экрана слабая и отрицательная: для эстетики коэффициент Спирмена составляет -0,095, для удобства - -0,133, поэтому высокая доля замечаний сверху сама по себе не указывает на низкую оценку экрана.</span>\n<span class="paragraph">Из этого если мы посмотрим на раздел 5, где видно, что мелкие замечания часто расположены сверху, то сейчас мы видим, что верхняя часть экрана выделяется и при низких, и при высоких средних оценках</span></span>', 'source': '#### **Вывод о расположении замечаний**\n\nВ основном замечания расположены в верхней части экрана, если мы посмотрим на левые 2 графика. У удобства сосредоточенность низких оценок побольше, но при этом профили графиков также сильно похожи между собой.\n\nЕсли мы посмотрим на правые графики, то увидим, что облако на обоих графиках получилось достаточно размашистым, а связь средней оценки с долей замечаний в верхних 20% экрана слабая и отрицательная: для эстетики коэффициент Спирмена составляет -0,095, для удобства - -0,133, поэтому высокая доля замечаний сверху сама по себе не указывает на низкую оценку экрана.\n\nИз этого если мы посмотрим на раздел 5, где видно, что мелкие замечания часто расположены сверху, то сейчас мы видим, что верхняя часть экрана выделяется и при низких, и при высоких средних оценках\n'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><span class="paragraph"><a id="uicrit-rating-explorer"></a></span>\n<h3 id="uicrit-heading-95-1"><strong>6.5 Проверка чувствительности к порогу площади</strong></h3>\n<span class="paragraph">Сравним профили всех экранов при порогах 3%, 5% и 10% площади. Каждый экран с подходящими рамками имеет одинаковый вес. Состав включённых экранов при смене порога меняется; фактическое число показано в легенде.</span>\n<span class="paragraph">Это статическая проверка того, насколько выбор 5% влияет на описание расположения замечаний. Если кривые расходятся, вывод зависит от порога. Переключение эстетики и удобства можно добавить позже на сайте; в ноутбуке результаты показаны отдельно.</span></span>', 'source': '<a id="rating-explorer"></a>\n\n### **6.5 Проверка чувствительности к порогу площади**\n\nСравним профили всех экранов при порогах 3%, 5% и 10% площади. Каждый экран с подходящими рамками имеет одинаковый вес. Состав включённых экранов при смене порога меняется; фактическое число показано в легенде.\n\nЭто статическая проверка того, насколько выбор 5% влияет на описание расположения замечаний. Если кривые расходятся, вывод зависит от порога. Переключение эстетики и удобства можно добавить позже на сайте; в ноутбуке результаты показаны отдельно.\n'}, {'kind': 'code', 'html': '<figure class="plot plot-wide"><img width="862" height="532" decoding="async" data-report-asset="./public/reports/uicrit/96-0.png" src="data:image/png;base64," alt="График исследования" /></figure>', 'source': 'fig, ax = plt.subplots(figsize=(8, 5))\nfor limit, color in [(.03, "#7463C7"), (.05, "#438F92"), (.10, "#DB8744")]:\n    profiles, summary = link_location_data(limit)\n    mean_profile = np.mean(list(profiles.values()), axis=0) * 100\n    ax.plot(mean_profile, link_height_centers * 100, marker="o", color=color,\n            label=f"Площадь < {limit:.0%}, экранов: {len(summary)}")\nax.set(title="Меняется ли профиль при другом пороге площади?",\n       xlabel="Средняя по экранам доля замечаний в полосе, %",\n       ylabel="Высота центра рамки: 0% — верх, 100% — низ",\n       ylim=(100, 0))\nax.set_yticks(np.arange(0, 101, 10))\nax.grid(alpha=.25)\nax.legend(frameon=False)\nplt.tight_layout()\nplt.show()\n'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><h4 id="uicrit-heading-97-1"><strong>Вывод о выбранном пороге площади</strong></h4>\n<span class="paragraph">Чтобы исключить то, что результаты были сосредоточены в верхней части экрана из-за выбранного размера 5% мы разобрали случаи при порогах площади 3%, 5% и 10%. Общая форма профиля сохранилась, тк мелкие замечания преимущественно сосредоточены сверху, с дополнительным пиком внизу. Следовательно, эта особенность не возникает исключительно из-за выбора порога 5%, но при этом меняются как доли замечаний, так и состав включённых экранов.</span></span>', 'source': '#### **Вывод о выбранном пороге площади**\n\nЧтобы исключить то, что результаты были сосредоточены в верхней части экрана из-за выбранного размера 5% мы разобрали случаи при порогах площади 3%, 5% и 10%. Общая форма профиля сохранилась, тк мелкие замечания преимущественно сосредоточены сверху, с дополнительным пиком внизу. Следовательно, эта особенность не возникает исключительно из-за выбора порога 5%, но при этом меняются как доли замечаний, так и состав включённых экранов.'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><h3 id="uicrit-heading-98-1"><strong>Общие выводы: чем сопровождаются оценки</strong></h3>\n<span class="paragraph">В целом состав тем замечаний в группах низких и высоких средних оценок похож(как и в целом большинство показателей по эстетике и удобству в этой лабораторной). После поправки Холма статистически значимое различие обнаружено только для темы иконок по эстетике: оно показало, что в низкой группе средняя доля таких замечаний выше на 4,46 процентного пункта. Для остальных сравнений различия статистически не подтверждены</span>\n<span class="paragraph">Мелкие замечания сосредоточены сверху и при низких, и при высоких оценках. В низких группах концентрация у самого верха выражена сильнее, однако связь оценки с долей замечаний в верхних 20% слабая, и при изменении порога площади рамок с 3% до 10% общая форма профиля сохраняется. Таким образом, концентрация замечаний сверху является общей особенностью исследуемых экранов.</span></span>', 'source': '###**Общие выводы: чем сопровождаются оценки**\n\nВ целом состав тем замечаний в группах низких и высоких средних оценок похож(как и в целом большинство показателей по эстетике и удобству в этой лабораторной). После поправки Холма статистически значимое различие обнаружено только для темы иконок по эстетике: оно показало, что в низкой группе средняя доля таких замечаний выше на 4,46 процентного пункта. Для остальных сравнений различия статистически не подтверждены\n\nМелкие замечания сосредоточены сверху и при низких, и при высоких оценках. В низких группах концентрация у самого верха выражена сильнее, однако связь оценки с долей замечаний в верхних 20% слабая, и при изменении порога площади рамок с 3% до 10% общая форма профиля сохраняется. Таким образом, концентрация замечаний сверху является общей особенностью исследуемых экранов.'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><h2 id="uicrit-heading-99-1"><strong>Резюме лабораторной</strong></h2>\n<span class="paragraph">В этой работе мы исследовали датасет UICrit и две случайные величины -\nсредние оценки эстетики и удобства случайно выбранного экрана</span>\n<span class="paragraph">Нашей главной гипотезой лабораторной стала связь эстетики и удобства: чем выше средняя оценка эстетики экрана, тем, как правило, выше средняя оценка его удобства. И по итогу мы подтвердили нашу гипотезу. Изначально мы проанализировали случайные величины эстетики и удобства и поняли, что значения и визуально, и численно похожи между собой, но при этом они не поддавались нормальности: это нам показал тест Шапиро — Уилка, а численное сравнение нормальной и бета-модели показало, что бета-модель описывает данные лишь немного лучше</span>\n<span class="paragraph">Но похожести данных недостаточно, поэтому саму по себе зависимость мы проанализировали с помощью графика средних оценок(там была замечена как раз зависимость эстетики и удобства, тк если были показатели эстетики выше, то и у удобства тоже), и численно убедились с помощью матрицы корреляции, где связь показателей также дала положительную связь, причем достаточно уверенную. При этом оказалось, что эта связь сильная внутри оценок одного аннотатора и почти исчезает, если сравнивать оценки разных аннотаторов одного экрана</span>\n<span class="paragraph">Затем из этого мы перешли к исследованию следующего вопроса - где расположены замечания к интерфейсам. Тепловые карты показали, что мелкие замечания часто сосредоточены в верхней части экрана, с дополнительным пиком внизу</span>\n<span class="paragraph">Далее, когда мы определились с расположением замечаний, мы перешли к тому, отличаются ли темы и расположение замечаний\nу экранов с низкими и высокими средними оценками. В целом состав тем\nоказался похож - в целом на протяжении исследования наблюдалась поразительная схожесть у показателей, что интересно! После поправки Холма статистически значимое различие обнаружилось только для иконок по эстетике, для остальных тем различия статистически не подтвердились. Также выяснилось, что основная тема замечаний стала касаться цветов и контрастов в нижней группе, в верхней у эстетики - текст и шрифт, а основная сосредоточенность в верхней части экрана, причем независимо от порога площади рамок</span>\n<span class="paragraph">Таким образом, наша гипотеза получила статистическую поддержку: чем выше средняя оценка эстетики экрана, тем обычно выше оценка его удобства, хотя эта связь проявляется прежде всего в оценках одного человека. При этом темы и расположение замечаний в низких и высоких группах в основном похожи, а наиболее заметное подтверждённое различие - более высокая доля замечаний об иконках у экранов с низкой оценкой эстетики</span>\n<span class="paragraph">Надеюсь, вам понравилось изучать это вместе с нами, спасибо!! :)</span></span>', 'source': '## **Резюме лабораторной**\n\nВ этой работе мы исследовали датасет UICrit и две случайные величины -\nсредние оценки эстетики и удобства случайно выбранного экрана\n\nНашей главной гипотезой лабораторной стала связь эстетики и удобства: чем выше средняя оценка эстетики экрана, тем, как правило, выше средняя оценка его удобства. И по итогу мы подтвердили нашу гипотезу. Изначально мы проанализировали случайные величины эстетики и удобства и поняли, что значения и визуально, и численно похожи между собой, но при этом они не поддавались нормальности: это нам показал тест Шапиро — Уилка, а численное сравнение нормальной и бета-модели показало, что бета-модель описывает данные лишь немного лучше\n\nНо похожести данных недостаточно, поэтому саму по себе зависимость мы проанализировали с помощью графика средних оценок(там была замечена как раз зависимость эстетики и удобства, тк если были показатели эстетики выше, то и у удобства тоже), и численно убедились с помощью матрицы корреляции, где связь показателей также дала положительную связь, причем достаточно уверенную. При этом оказалось, что эта связь сильная внутри оценок одного аннотатора и почти исчезает, если сравнивать оценки разных аннотаторов одного экрана\n\nЗатем из этого мы перешли к исследованию следующего вопроса - где расположены замечания к интерфейсам. Тепловые карты показали, что мелкие замечания часто сосредоточены в верхней части экрана, с дополнительным пиком внизу\n\nДалее, когда мы определились с расположением замечаний, мы перешли к тому, отличаются ли темы и расположение замечаний\nу экранов с низкими и высокими средними оценками. В целом состав тем\nоказался похож - в целом на протяжении исследования наблюдалась поразительная схожесть у показателей, что интересно! После поправки Холма статистически значимое различие обнаружилось только для иконок по эстетике, для остальных тем различия статистически не подтвердились. Также выяснилось, что основная тема замечаний стала касаться цветов и контрастов в нижней группе, в верхней у эстетики - текст и шрифт, а основная сосредоточенность в верхней части экрана, причем независимо от порога площади рамок\n\nТаким образом, наша гипотеза получила статистическую поддержку: чем выше средняя оценка эстетики экрана, тем обычно выше оценка его удобства, хотя эта связь проявляется прежде всего в оценках одного человека. При этом темы и расположение замечаний в низких и высоких группах в основном похожи, а наиболее заметное подтверждённое различие - более высокая доля замечаний об иконках у экранов с низкой оценкой эстетики\n\nНадеюсь, вам понравилось изучать это вместе с нами, спасибо!! :)'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><span class="paragraph"><a id="uicrit-literature"></a></span>\n<h3 id="uicrit-heading-100-1"><strong>Литература и источники</strong></h3>\n<ol>\n<li>Google Research. UICrit Dataset — данные и описание столбцов.\n   <a href="https://github.com/google-research-datasets/uicrit" rel="noopener" target="_blank">https://github.com/google-research-datasets/uicrit</a></li>\n<li>\n<span class="paragraph">Duan P., Chen C., Li G., Hartmann B., Li Y.\n   UICrit: Enhancing Automated Design Evaluation with a UI Critique Dataset.</span>\n<ol start="2024">\n<li><a href="https://arxiv.org/abs/2407.08850" rel="noopener" target="_blank">https://arxiv.org/abs/2407.08850</a></li>\n</ol>\n</li>\n<li>Deka B. et al. Rico: A Mobile App Dataset for Building Data-Driven Design Applications // UIST 2017.</li>\n<li>Документация SciPy: <code>scipy.stats.kstest</code>, <code>mannwhitneyu</code>, <code>chi2_contingency</code>.</li>\n</ol></span>', 'source': '<a id="literature"></a>\n\n### **Литература и источники**\n\n1. Google Research. UICrit Dataset — данные и описание столбцов.\n   https://github.com/google-research-datasets/uicrit\n\n2. Duan P., Chen C., Li G., Hartmann B., Li Y.\n   UICrit: Enhancing Automated Design Evaluation with a UI Critique Dataset.\n   2024. https://arxiv.org/abs/2407.08850\n\n3. Deka B. et al. Rico: A Mobile App Dataset for Building Data-Driven Design Applications // UIST 2017.\n\n4. Документация SciPy: `scipy.stats.kstest`, `mannwhitneyu`, `chi2_contingency`.'}, {'kind': 'markdown', 'html': '<span class="markdown prose dark:prose-invert contents"><h3 id="uicrit-heading-101-1">cat_mark_table</h3>\n<table>\n<thead>\n<tr>\n<th>cat_id</th>\n<th>notebook_link</th>\n<th>coeff</th>\n<th>comment</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Доп. КТвД: отдельный датасет и две случайные величины</td>\n<td><a href="#uicrit-data">1</a> · <a href="#uicrit-random">2</a></td>\n<td>—</td>\n<td>Датасет UICrit; средняя оценка эстетики и средняя оценка удобства экрана</td>\n</tr>\n<tr>\n<td>Доп. КТвД: обоснование случайной природы</td>\n<td><a href="#uicrit-random">2</a></td>\n<td>—</td>\n<td>Описан случайный выбор экрана и соответствующие ему значения двух величин</td>\n</tr>\n<tr>\n<td>Доп. КТвД: исследование зависимости</td>\n<td><a href="#uicrit-dependence">4</a></td>\n<td>—</td>\n<td>Диаграмма рассеяния, корреляции Пирсона и Спирмена, перестановочная проверка независимости</td>\n</tr>\n<tr>\n<td>Доп. КТвД: EDA</td>\n<td><a href="#uicrit-data">1</a> · <a href="#uicrit-eda">3</a></td>\n<td>—</td>\n<td>Проверка качества данных, описательные статистики, гистограммы с моделями, boxplot, Q–Q и выводы</td>\n</tr>\n<tr>\n<td>Корректность масштабов и единиц измерения</td>\n<td>Графики разделов <a href="#uicrit-eda">3</a>–<a href="#uicrit-heatmap">5</a></td>\n<td>—</td>\n<td>Подписаны оси и единицы; плотность отделена от количества наблюдений; для парных оценок используются одинаковые масштабы осей</td>\n</tr>\n<tr>\n<td>Единая стилистика графиков</td>\n<td><a href="#uicrit-eda">3</a>–<a href="#uicrit-heatmap">5</a></td>\n<td>—</td>\n<td>Согласованы оформление, цвета и структура панелей</td>\n</tr>\n<tr>\n<td>Математические формулы в LaTeX</td>\n<td><a href="#uicrit-random">2</a> · <a href="#uicrit-heatmap">5</a></td>\n<td>—</td>\n<td>Формулы средних оценок оформлены в LaTeX</td>\n</tr>\n<tr>\n<td>Список литературы</td>\n<td><a href="#uicrit-literature">Литература и источники</a></td>\n<td>—</td>\n<td>Источник датасета, статьи авторов UICrit и RICO, документация SciPy</td>\n</tr>\n<tr>\n<td>EDA: рамки замечаний</td>\n<td><a href="#uicrit-heat-boxes">5.1–5.2</a></td>\n<td>—</td>\n<td>Разбор рамок, проверка координат, распределение площади, выбор порога 5%</td>\n</tr>\n<tr>\n<td>Визуализация: тепловая карта</td>\n<td><a href="#uicrit-heat-main">5.3–5.4</a></td>\n<td>—</td>\n<td>Доля замечаний по клеткам экрана, сравнение людей и ИИ и тем на общей шкале</td>\n</tr>\n<tr>\n<td>Проверка гипотез</td>\n<td><a href="#uicrit-heat-tests">5.5</a></td>\n<td>—</td>\n<td>КС против равномерного, Манн-Уитни (люди и ИИ), χ² и V Крамера (тема × зона)</td>\n</tr>\n<tr>\n<td>Интерактивность</td>\n<td><a href="#uicrit-heat-compare">5.4</a></td>\n<td>—</td>\n<td>Переключатели автора и темы, слайдер порога размера рамки</td>\n</tr>\n<tr>\n<td>Связь основного и дополнительного анализа</td>\n<td><a href="#uicrit-rating-comments">6</a></td>\n<td>—</td>\n<td>Сравнение тем и профилей расположения замечаний в группах средних оценок</td>\n</tr>\n<tr>\n<td>Проверка различий</td>\n<td><a href="#uicrit-rating-tests">6.3</a></td>\n<td>—</td>\n<td>Перестановки на уровне экранов, поправка Холма на восемь сравнений</td>\n</tr>\n<tr>\n<td>Проверка чувствительности</td>\n<td><a href="#uicrit-rating-explorer">6.5</a></td>\n<td>—</td>\n<td>Статическое сравнение профилей при порогах 3%, 5% и 10%; интерактив отложен до сайта</td>\n</tr>\n</tbody>\n</table></span>', 'source': '### cat_mark_table\n\n| cat_id | notebook_link | coeff | comment |\n|--------|---------------|-------|---------|\n| Доп. КТвД: отдельный датасет и две случайные величины | [1](#data) · [2](#random) | — | Датасет UICrit; средняя оценка эстетики и средняя оценка удобства экрана |\n| Доп. КТвД: обоснование случайной природы | [2](#random) | — | Описан случайный выбор экрана и соответствующие ему значения двух величин |\n| Доп. КТвД: исследование зависимости | [4](#dependence) | — | Диаграмма рассеяния, корреляции Пирсона и Спирмена, перестановочная проверка независимости |\n| Доп. КТвД: EDA | [1](#data) · [3](#eda) | — | Проверка качества данных, описательные статистики, гистограммы с моделями, boxplot, Q–Q и выводы |\n| Корректность масштабов и единиц измерения | Графики разделов [3](#eda)–[5](#heatmap) | — | Подписаны оси и единицы; плотность отделена от количества наблюдений; для парных оценок используются одинаковые масштабы осей |\n| Единая стилистика графиков | [3](#eda)–[5](#heatmap) | — | Согласованы оформление, цвета и структура панелей |\n| Математические формулы в LaTeX | [2](#random) · [5](#heatmap) | — | Формулы средних оценок оформлены в LaTeX |\n| Список литературы | [Литература и источники](#literature) | — | Источник датасета, статьи авторов UICrit и RICO, документация SciPy |\n| EDA: рамки замечаний | [5.1–5.2](#heat-boxes) | — | Разбор рамок, проверка координат, распределение площади, выбор порога 5% |\n| Визуализация: тепловая карта | [5.3–5.4](#heat-main) | — | Доля замечаний по клеткам экрана, сравнение людей и ИИ и тем на общей шкале |\n| Проверка гипотез | [5.5](#heat-tests) | — | КС против равномерного, Манн-Уитни (люди и ИИ), χ² и V Крамера (тема × зона) |\n| Интерактивность | [5.4](#heat-compare) | — | Переключатели автора и темы, слайдер порога размера рамки |\n| Связь основного и дополнительного анализа | [6](#rating-comments) | — | Сравнение тем и профилей расположения замечаний в группах средних оценок |\n| Проверка различий | [6.3](#rating-tests) | — | Перестановки на уровне экранов, поправка Холма на восемь сравнений |\n| Проверка чувствительности | [6.5](#rating-explorer) | — | Статическое сравнение профилей при порогах 3%, 5% и 10%; интерактив отложен до сайта |'}]}
    return (REPORTS,)


@app.cell(hide_code=True)
def _():
    gen_modules = {}
    for _name, _source in {'ph': 'import numpy as np\n\n# Параметры лог-нормального со сдвигом, найденные в спринте 1\nPH_SHAPE = 0.13634791317752573   # sigma логарифма\nPH_LOC = 2.0877008414300846      # сдвиг\nPH_SCALE = 1.0903765817054785    # exp(mu)\n\nRATIO_B = np.sqrt(2 / np.e)      # граница по v в методе отношений\n\n\ndef polar_normal(n, rng):\n    """Стандартные нормальные числа методом полярных координат (Марсальи)."""\n    if n < 0:\n        raise ValueError("n должно быть неотрицательным")\n    if n == 0:\n        return np.empty(0)\n    out, count = [], 0\n    while count < n:\n        m = int((n - count) / 0.78) + 10\n        u1 = 2 * rng.random_sample(m) - 1\n        u2 = 2 * rng.random_sample(m) - 1\n        s = u1**2 + u2**2\n        ok = (s > 0) & (s < 1)\n        u1, u2, s = u1[ok], u2[ok], s[ok]\n        f = np.sqrt(-2 * np.log(s) / s)\n        out.append(np.concatenate([u1 * f, u2 * f]))\n        count += 2 * len(s)\n    return np.concatenate(out)[:n]\n\n\ndef ratio_normal(n, rng):\n    """Стандартные нормальные числа методом отношений (Киндерман-Монахан)."""\n    if n < 0:\n        raise ValueError("n должно быть неотрицательным")\n    if n == 0:\n        return np.empty(0)\n    out, count = [], 0\n    while count < n:\n        m = int((n - count) / 0.73) + 10\n        u = rng.random_sample(m)\n        v = RATIO_B * (2 * rng.random_sample(m) - 1)\n        ok = u > 0\n        u, v = u[ok], v[ok]\n        x = v / u\n        acc = x**2 <= -4 * np.log(u)          # u <= sqrt(exp(-x^2/2))\n        out.append(x[acc])\n        count += int(acc.sum())\n    return np.concatenate(out)[:n]\n\n\ndef ph_generator(n, seed=42, method="polar"):\n    """Генератор pH: лог-нормальное со сдвигом.\n    method: "polar" (метод полярных координат) или "ratio" (метод отношений)."""\n    rng = np.random.RandomState(seed)\n    if method == "polar":\n        z = polar_normal(n, rng)\n    elif method == "ratio":\n        z = ratio_normal(n, rng)\n    else:\n        raise ValueError("method должен быть \'polar\' или \'ratio\'")\n    return PH_LOC + PH_SCALE * np.exp(PH_SHAPE * z)\n\n\ndef to_standard_normal(x):\n    """Обратное преобразование: pH -> стандартное нормальное Z."""\n    return np.log((np.asarray(x) - PH_LOC) / PH_SCALE) / PH_SHAPE\n', 'sugar': '"""Генераторы residual sugar (MT19937, без готовых .rvs распределений)."""\nimport numpy as np\nfrom scipy import stats\n\nSUGAR_SHAPE = 1.4814063452349577\nSUGAR_LOC = 0.0\nSUGAR_SCALE = 4.314423847155702\n\n\ndef _validate_n(n):\n    if isinstance(n, (bool, np.bool_)) or not isinstance(n, (int, np.integer)):\n        raise TypeError("n должно быть целым числом")\n    if n < 0:\n        raise ValueError("n должно быть неотрицательным")\n    return int(n)\n\n\ndef _reference(data):\n    values = np.asarray(data, dtype=float).ravel()\n    if values.size == 0 or not np.isfinite(values).all() or (values <= 0).any():\n        raise ValueError("Данные должны быть непустыми, конечными и положительными")\n    return values\n\n\ndef empirical_inverse(n, data, rng):\n    """Обратная эмпирическая CDF, без сглаживания и интерполяции."""\n    n = _validate_n(n)\n    x = np.sort(_reference(data))\n    if n == 0:\n        return np.empty(0, dtype=float)\n    indices = np.floor(rng.random_sample(n) * len(x)).astype(int)\n    return x[indices]\n\n\ndef fast_exponential(n, scale, rng):\n    """Векторное обратное преобразование для Exp(scale)."""\n    n = _validate_n(n)\n    if not np.isfinite(scale) or scale <= 0:\n        raise ValueError("scale должно быть положительным")\n    if n == 0:\n        return np.empty(0, dtype=float)\n    u = rng.random_sample(n)\n    # 1-u принадлежит (0,1]; log1p обеспечивает точность при малом u.\n    return -float(scale) * np.log1p(-u)\n\n\ndef gamma_envelope(shape=SUGAR_SHAPE, scale=SUGAR_SCALE):\n    """Параметры экспоненциального предложения и точная константа M."""\n    if shape <= 1 or scale <= 0:\n        raise ValueError("Для экспоненциальной оболочки требуется shape > 1 и scale > 0")\n    proposal_scale = shape * scale\n    xstar = proposal_scale\n    logm = stats.gamma.logpdf(xstar, shape, loc=0, scale=scale) - \\\n           stats.expon.logpdf(xstar, scale=proposal_scale)\n    return proposal_scale, float(logm)\n\n\ndef neumann_gamma(n, rng, shape=SUGAR_SHAPE, scale=SUGAR_SCALE,\n                  return_stats=False):\n    """Gamma(shape, scale) методом Неймана с Exp(shape*scale) как g(x)."""\n    n = _validate_n(n)\n    proposal_scale, logm = gamma_envelope(shape, scale)\n    if n == 0:\n        empty = np.empty(0, dtype=float)\n        return (empty, 0, 0) if return_stats else empty\n    batches, got, tried, accepted = [], 0, 0, 0\n    while got < n:\n        # Выбираем с запасом и учитываем ВСЕ предложения в статистике принятия.\n        m = max(256, int(np.ceil((n - got) * np.exp(logm) * 1.12)))\n        y = fast_exponential(m, proposal_scale, rng)\n        u = rng.random_sample(m)\n        logf = stats.gamma.logpdf(y, shape, loc=0, scale=scale)\n        logg = stats.expon.logpdf(y, scale=proposal_scale)\n        keep = np.log(np.maximum(u, np.finfo(float).tiny)) <= logf - logg - logm\n        accepted_values = y[keep]\n        batches.append(accepted_values)\n        accepted += int(keep.sum())\n        tried += m\n        got += len(accepted_values)\n    result = np.concatenate(batches)[:n]\n    return (result, accepted, tried) if return_stats else result\n\n\ndef superposition_empirical(n, data, rng, components=4):\n    """Смесь 4 непересекающихся эмпирических частей, веса |A_j|/N."""\n    n = _validate_n(n)\n    if not isinstance(components, (int, np.integer)) or components < 1:\n        raise ValueError("components должно быть положительным целым")\n    values = np.sort(_reference(data))\n    if components > len(values):\n        raise ValueError("components не может превышать число наблюдений")\n    if n == 0:\n        return np.empty(0, dtype=float)\n    blocks = np.array_split(values, int(components))\n    weights = np.array([len(b) for b in blocks], dtype=float) / len(values)\n    chosen = rng.choice(len(blocks), size=n, p=weights)\n    result = np.empty(n, dtype=float)\n    for j, block in enumerate(blocks):\n        positions = np.flatnonzero(chosen == j)\n        if len(positions):\n            indices = np.floor(rng.random_sample(len(positions)) * len(block)).astype(int)\n            result[positions] = block[indices]\n    return result\n\n\ndef sugar_generator(n, data=None, seed=42, method="inverse"):\n    """inverse/superposition требуют данные; neumann использует гамма-параметры."""\n    n = _validate_n(n)\n    rng = np.random.RandomState(seed)\n    if method == "inverse":\n        if data is None:\n            raise ValueError("Для inverse нужны исходные значения residual sugar")\n        return empirical_inverse(n, data, rng)\n    if method == "superposition":\n        if data is None:\n            raise ValueError("Для superposition нужны исходные значения residual sugar")\n        return superposition_empirical(n, data, rng)\n    if method == "neumann":\n        return neumann_gamma(n, rng)\n    raise ValueError("method: \'inverse\', \'superposition\' или \'neumann\'")\n', 'alcohol': '"""Генераторы содержания алкоголя: skew-normal и эмпирическая CDF.\nИсточник равномерных чисел — MT19937 (NumPy RandomState).\n"""\nimport numpy as np\nfrom scipy import stats\n\n# Оценки из спринта 1, полученные с scipy.stats.skewnorm.fit\nALCOHOL_SHAPE = 9.981325379517678\nALCOHOL_LOC = 8.806782475860167\nALCOHOL_SCALE = 2.1046650921103787\n\n\ndef _validate_n(n):\n    if isinstance(n, (bool, np.bool_)) or not isinstance(n, (int, np.integer)):\n        raise TypeError("n должно быть целым числом")\n    if n < 0:\n        raise ValueError("n должно быть неотрицательным")\n    return int(n)\n\n\ndef polar_normal(n, rng):\n    """Независимые N(0,1): полярный метод Марсальи."""\n    n = _validate_n(n)\n    if n == 0:\n        return np.empty(0, dtype=float)\n    parts = []\n    size = 0\n    while size < n:\n        m = max(64, int((n - size) / (np.pi / 2)) + 64)\n        u1 = 2.0 * rng.random_sample(m) - 1.0\n        u2 = 2.0 * rng.random_sample(m) - 1.0\n        s = u1**2 + u2**2\n        ok = (s > 0.0) & (s < 1.0)\n        f = np.sqrt(-2.0 * np.log(s[ok]) / s[ok])\n        z1 = u1[ok] * f\n        z2 = u2[ok] * f\n        vals = np.column_stack((z1, z2)).ravel()\n        parts.append(vals)\n        size += len(vals)\n    return np.concatenate(parts)[:n]\n\n\ndef box_muller_normal(n, rng):\n    """Независимые N(0,1): тригонометрическая формула Бокса—Мюллера."""\n    n = _validate_n(n)\n    if n == 0:\n        return np.empty(0, dtype=float)\n    m = (n + 1) // 2\n    u1 = np.maximum(rng.random_sample(m), np.finfo(float).tiny)\n    u2 = rng.random_sample(m)\n    radius = np.sqrt(-2.0 * np.log(u1))\n    angle = 2.0 * np.pi * u2\n    return np.column_stack((radius * np.cos(angle), radius * np.sin(angle))).ravel()[:n]\n\n\ndef skew_normal_latent(n, rng, normal_method="polar"):\n    """Скошенная нормальная через Z=delta*|U|+sqrt(1-delta²)*V."""\n    n = _validate_n(n)\n    if normal_method == "polar":\n        normals = polar_normal(2 * n, rng)\n    elif normal_method == "box_muller":\n        normals = box_muller_normal(2 * n, rng)\n    else:\n        raise ValueError("Неизвестный способ получения нормальных чисел")\n    if n == 0:\n        return np.empty(0, dtype=float)\n    u = normals[:n]\n    v = normals[n:]\n    delta = ALCOHOL_SHAPE / np.sqrt(1.0 + ALCOHOL_SHAPE**2)\n    z = delta * np.abs(u) + np.sqrt(1.0 - delta**2) * v\n    return ALCOHOL_LOC + ALCOHOL_SCALE * z\n\n\ndef empirical_inverse(n, rng, data):\n    """Обратная эмпирическая CDF, сохраняющая значения и частоты выборки."""\n    n = _validate_n(n)\n    if data is None:\n        raise ValueError("Для эмпирического метода нужны исходные данные")\n    values = np.asarray(data, dtype=float).ravel()\n    if values.size == 0 or not np.isfinite(values).all():\n        raise ValueError("data должны содержать конечные числа")\n    unique, counts = np.unique(values, return_counts=True)\n    cdf = np.cumsum(counts) / counts.sum()\n    u = rng.random_sample(n)\n    indices = np.searchsorted(cdf, u, side="right")\n    return unique[indices]\n\n\ndef alcohol_generator(n, seed=42, method="polar", data=None):\n    """method: polar, box_muller (теоретическая SN) или empirical."""\n    n = _validate_n(n)\n    rng = np.random.RandomState(seed)  # MT19937\n    if method == "empirical":\n        return empirical_inverse(n, rng, data)\n    if method in ("polar", "box_muller"):\n        return skew_normal_latent(n, rng, normal_method=method)\n    raise ValueError("method: polar, box_muller или empirical")\n\n\ndef to_standard_normal(x):\n    """PIT и обратная Phi для подогнанной непрерывной skew-normal модели."""\n    p = stats.skewnorm.cdf(np.asarray(x, dtype=float),\n                           ALCOHOL_SHAPE, loc=ALCOHOL_LOC, scale=ALCOHOL_SCALE)\n    eps = np.finfo(float).eps\n    return stats.norm.ppf(np.clip(p, eps, 1.0 - eps))\n'}.items():
        _namespace = {}
        exec(compile(_source, _name + ".py", "exec"), _namespace)
        gen_modules[_name] = _namespace
    return (gen_modules,)


@app.cell(hide_code=True)
def _(REPORTS, code_panel, html, mo):
    def control_bar(controls):
        items=''.join('<div class="control-item">'+mo.as_html(c).text+'</div>' for c in controls)
        return mo.Html('<div class="control-bar">'+items+'</div>')

    def result_grid(items):
        return mo.Html('<div class="result-grid">'+''.join(mo.as_html(c).text for c in items)+'</div>')

    def controls_window(title,controls):
        return mo.Html('<div class="control-panel"><div class="control-caption">'+html.escape(title)+'</div>'+control_bar(controls).text+'</div>')

    def browser_ui(tabs,controls,items,address):
        chrome='<div class="workspace-chrome"><span class="browser-dots" aria-hidden="true"><i></i><i></i><i></i></span><span class="browser-address">'+html.escape(address)+'</span><span aria-hidden="true">↗</span></div>'
        arranged=list(items)
        if controls:
            graph_index=next((i for i,item in enumerate(arranged) if '<figure' in mo.as_html(item).text or '<marimo-plotly' in mo.as_html(item).text),0)
            arranged.insert(graph_index,control_bar(controls))
        content=mo.as_html(mo.vstack(arranged,gap=1.2)).text
        return mo.Html('<div class="native-browser-window">'+chrome+'<div class="native-tab-strip">'+mo.as_html(tabs).text+'</div><div class="native-browser-content">'+content+'</div></div>')

    def author_flow(study,start,end,first_heading=False,outputs=True,headers=True,charts=None):
        import re as _re
        pieces=[]
        paired_tables=start<=51<end and study=='uicrit'
        for i in range(start,end):
            item=REPORTS[study][i]
            rendered=item['html']
            if paired_tables and i==52:
                continue
            if study=='uicrit' and i==41:
                pieces.append('<span class="source-anchor" id="uicrit-result-41"></span>')
                continue
            # Preparation remains in the downloadable notebook and end-of-section code.
            if (study=='sprint2' and _re.fullmatch(r'#+\s*Code\s*',item['source'].strip())) or (study=='uicrit' and i in (4,9,20)) or (study=='sprint1' and i==3):
                pieces.append('<span class="source-anchor" id="'+study+'-cell-'+str(i)+'"></span>')
                continue
            if item['kind']=='code':
                # A live counterpart replaces each duplicated first-sprint image.
                # UICrit retains the notebook comparison in 4.1 and the other unique plots.
                if study=='sprint1' or (study=='uicrit' and i in (17,26,32,39,58,61,64,66,68,71,74,87)):
                    rendered=_re.sub(r'<figure\b.*?</figure>','',rendered,flags=_re.S)
                if charts is not None and '<figure' in rendered:
                    fresh=iter(charts(i))
                    rendered=_re.sub(r'<figure\b.*?</figure>',lambda match:next(fresh),rendered,flags=_re.S)
                figures=''.join(_re.findall(r'<figure\b.*?</figure>',rendered,flags=_re.S))
                if outputs is False:
                    rendered=figures
                elif outputs=='tables':
                    rendered=_re.sub(r'<pre\b.*?</pre>','',rendered,flags=_re.S) if '<table' in rendered else figures
                if not rendered.strip():continue
            if item['kind']=='markdown' and ((first_heading and i==start) or not headers):
                def strip_heading(match):
                    ident=_re.search(r'id="([^"]+)"',match[0])
                    return '<span class="source-anchor" id="'+ident[1]+'"></span>' if ident else ''
                rendered=_re.sub(r'<h[1-6][^>]*>.*?</h[1-6]>',strip_heading,rendered,count=1 if headers else 0,flags=_re.S)
            paired=''
            if paired_tables and i==51:
                first_table=_re.search(r'<table\b.*?</table>',rendered,flags=_re.S)
                second_table=_re.search(r'<table\b.*?</table>',REPORTS[study][52]['html'],flags=_re.S)
                if first_table and second_table:
                    rendered=rendered.replace(first_table[0],'')
                    right_table=_re.sub(r'<thead>.*?</thead>','<thead><tr><th>Источник</th><th>Замечаний</th></tr></thead>',second_table[0],flags=_re.S)
                    paired='<div class="table-pair"><div class="table-column"><div class="table-caption">Темы замечаний</div><div class="tbl-wrap">'+first_table[0]+'</div></div><div class="table-column" id="uicrit-result-52"><div class="table-caption">Источники замечаний</div><div class="tbl-wrap">'+right_table+'</div></div></div>'
            if rendered.strip():
                ident=study+('-result-' if item['kind']=='code' else '-cell-')+str(i)
                visible=_re.sub(r'<style\b.*?</style>|<span class="notebook-index".*?</span>','',rendered,flags=_re.S)
                visible=_re.sub(r'<[^>]*>','',visible).replace('&nbsp;','').strip()
                if not visible and not _re.search(r'<(?:img|table|math|marimo-tex)\b',rendered):
                    anchors=''.join('<span class="source-anchor" id="'+a+'"></span>' for a in _re.findall(r'id="([^"]+)"',rendered))
                    pieces.append('<span class="source-anchor" id="'+ident+'"></span>'+anchors)
                    continue
                cls=' notebook-conclusion' if item['kind']=='markdown' and any(w in item['source'][:100].lower() for w in ('вывод','интерпретация','что видно')) else ''
                pieces.append('<div class="notebook-cell notebook-text'+cls+'" id="'+ident+'">'+rendered+'</div>'+paired)
        return mo.Html('<div class="author-flow">'+''.join(pieces)+'</div>')

    def author_code(study,start,end):
        sources=[]
        aliases=[]
        for i in range(start,end):
            item=REPORTS[study][i]
            if item['kind']=='code' and item['source'].strip():
                sources.append('# Ячейка '+str(i)+'\n'+item['source'])
                aliases.append('<span class="source-anchor" id="'+study+'-cell-'+str(i)+'"></span>')
        if not sources:return mo.Html('')
        return mo.Html(''.join(aliases)+code_panel('Код этого раздела · раскрыть / свернуть','\n\n'.join(sources)).text)
    return (author_code, author_flow, browser_ui, control_bar, controls_window, result_grid,)


