@app.cell(hide_code=True)
def _(html, mo, navigation_chapters, project_tabs):
    _titles={'Спринт 1':'Белое вино · Спринт 1','Спринт 2':'Генераторы · Спринт 2','Доп. КТиД':'Анализ интерфейсов приложений — UICrit'}
