@app.cell(hide_code=True)
def _(X, mo, np, project_tabs):
    mo.stop(project_tabs.value != 'Спринт 1')
    def _density(x, width=1000, height=90):
        # Плотность спирта (ядерная оценка) — верхний край зелёной полосы под бокалом
        x = np.asarray(x, dtype=float)
        bw = 1.06 * x.std() * len(x) ** (-1 / 5)
        grid = np.linspace(x.min(), x.max(), 160)
        dens = np.exp(-0.5 * ((grid[:, None] - x[None, :]) / bw) ** 2).sum(axis=1)
        dens = dens / dens.max()
        pts = " ".join(f"{i / (len(grid) - 1) * width:.1f},{height - d * (height - 6):.1f}" for i, d in enumerate(dens))
        return (f'<svg class="hero-density" viewBox="0 0 {width} {height}" preserveAspectRatio="none" aria-hidden="true">'
                f'<defs><linearGradient id="pour" x1="0" y1="0" x2="0" y2="1">'
                f'<stop offset="0" stop-color="var(--data)" /><stop offset="1" class="pour-end" /></linearGradient></defs>'
                f'<polygon fill="url(#pour)" points="0,{height} {pts} {width},{height}" /></svg>'
                f'<div class="hero-density-cap">Край волны — плотность распределения спирта в {len(x)} винах, '
                f'от {x.min():.1f} до {x.max():.1f} % об.</div>')

    mo.Html(f"""
    <section class="hero hero-wine" id="top">
      <div class="hero-intro">
      <img class="wine-hero-art" src="./public/wine-glass.png" alt="" aria-hidden="true" fetchpriority="high" />
      <div class="hero-kicker">Прикладная статистика · Lab01 — sprint 1</div>
      <h1 class="hero-title">Три случайные величины <em>белого вина</em></h1>
      <p class="hero-sub">pH, остаточный сахар и спирт в 4898 образцах Vinho Verde: почему они случайны,
      как распределены, насколько независимы и что можно сказать о генеральной совокупности по выборке.</p>
      </div>
      <div class="hero-vars">
        {_density(X["alc"])}
        <a href="#rv1-desc" class="hero-var"><span>01</span>pH<small>почти колокол, правый хвост</small></a>
        <a href="#rv2-desc" class="hero-var"><span>02</span>Остаточный сахар<small>длинный правый хвост</small></a>
        <a href="#rv3-desc" class="hero-var"><span>03</span>Спирт<small>плоский, с «зубцами»</small></a>
      </div>
      <p class="hero-sub" style="margin-top:18px">Генераторы случайных величин — на вкладке «Спринт 2», дополнительное исследование оценок мобильных интерфейсов (UICrit) — на вкладке «Доп. КТиД».</p>
    </section>
    """)
    return ()


@app.cell(hide_code=True)
def _(C, MODEL_STYLE, mo, project_tabs, section):
    mo.stop(project_tabs.value != 'Спринт 1')
    _legend = ''.join((f"""<div class="lg-item"><span class="lg-line" style="border-top:3px {('dashed' if s['ls'] == '--' else 'dotted' if s['ls'] == ':' else 'solid')} {s['color']}"></span>{n}</div>""" for n, s in MODEL_STYLE.items()))
    mo.vstack([section('', 'Как читать отчёт', 'guide', level=2, kicker='Навигация', lead='Оглавление открывается кнопкой ☰ в левом верхнем углу. Оно меняется вместе с вкладкой. Выберите раздел; закрыть меню можно крестиком, клавишей Esc или нажатием вне панели. Ссылки в таблицах критериев также ведут прямо к нужному месту. Элементы управления (слайдеры, переключатели) пересчитывают графики прямо в браузере.'), mo.Html(f"""\n    <div class="guide-grid">\n      <div class="card">\n        <div class="card-t">Цвет = роль на графике</div>\n        <div class="lg-item"><span class="lg-box" style="background:{C['data']}"></span>Эмпирические данные</div>\n        <div class="lg-item"><span class="lg-box" style="background:{C['data_alt']}"></span>Вторая группа данных</div>\n        <div class="lg-item"><span class="lg-line" style="border-top:3px solid {C['ref']}"></span>Значение по всей таблице, H₀</div>\n        <div class="card-t" style="margin-top:14px">Модели распределений</div>\n        {_legend}\n      </div>\n      <div class="card">\n        <div class="card-t">Обозначения</div>\n        <dl class="gloss">\n          <dt>N, n</dt><dd>объём таблицы (4898) и объём выборки</dd>\n          <dt>x̄, s</dt><dd>выборочные среднее и стандартное отклонение</dd>\n          <dt>μ, σ</dt><dd>среднее и std «генеральной» совокупности (здесь — всей таблицы)</dd>\n          <dt>H₀, H₁, α</dt><dd>нулевая и альтернативная гипотезы, уровень значимости 0.05</dd>\n          <dt>W, D</dt><dd>статистики Шапиро-Уилка и Колмогорова-Смирнова</dd>\n          <dt>AIC</dt><dd>2k − 2 ln L, меньше — лучше</dd>\n          <dt>r, ρ</dt><dd>корреляции Пирсона и Спирмена</dd>\n          <dt>χ², V</dt><dd>хи-квадрат и V Крамера</dd>\n          <dt>r<sub>rb</sub></dt><dd>ранговая бисериальная корреляция (размер эффекта)</dd>\n          <dt>SE</dt><dd>стандартная ошибка среднего</dd>\n        </dl>\n      </div>\n    </div>""")])
    return ()


