@app.cell(hide_code=True)
def _(C, VARS, X, author_code, author_flow, control_bar, controls_window, figure, histogram_panel, intro_bandwidth, intro_hist_mode, intro_metric, kpis, mo, num, overview_bins, overview_var, pd, plt, project_tabs, section):
    mo.stop(project_tabs.value != 'Спринт 1')
    _k = overview_var.value
    _fig, _ax = plt.subplots(figsize=(8.4, 3.4))
    _ax.hist(X[_k], bins=overview_bins.value, color=C['data'])
    _ax.set(xlabel=VARS[_k]['axis'], ylabel='Количество вин', title=f"{VARS[_k]['name']}: гистограмма, {overview_bins.value} столбиков")
    mo.vstack([section('0.3', 'Три величины: общий EDA', 'data-eda', level=3), control_bar([overview_var, overview_bins]), figure(_fig), kpis([('Уникальных значений', f'{pd.Series(X[_k]).nunique()}', f'на {len(X[_k])} наблюдений'), ('Асимметрия', num(pd.Series(X[_k]).skew(), 2), '0 у симметричного'), ('Эксцесс', num(pd.Series(X[_k]).kurt(), 2), '0 у нормального')]), controls_window('Одна величина — один график',[intro_metric,intro_hist_mode,intro_bandwidth]), figure(histogram_panel(intro_metric.value,intro_hist_mode.value,intro_bandwidth.value)), author_flow('sprint1', 10, 19, outputs=False, headers=False), author_code('sprint1', 10, 19)])
    return ()


@app.cell(hide_code=True)
def _(VARS, X, author_code, author_flow, chip, describe, fit_models, kpis, mo, num, project_tabs, section):
    mo.stop(project_tabs.value != 'Спринт 1')
    _v = VARS['ph']
    _d = describe(X['ph'])
    _tbl, _ = fit_models('ph')
    mo.vstack([section('1', f"Random Variable 01 · {_v['name']}", 'rv1', level=2, kicker=f'Случайная величина 1 из 3'), kpis([('Среднее', num(_d['среднее'], 3), _v['unit']), ('Медиана', num(_d['медиана'], 3), _v['unit']), ('Std', num(_d['std'], 3), _v['unit_std']), ('Асимметрия', num(_d['асимметрия'], 2), 'правый хвост' if _d['асимметрия'] > 0 else 'левый хвост')]), mo.Html('<div class="chips">' + chip('Лучшая модель по AIC: ' + _tbl.index[0], 'model') + chip('Генератор (спринт 2): ' + _v['generator'], 'neutral') + '</div>'), section('1.1', 'Description · Природа величины', 'rv1-desc', level=3, kicker='Природа события'), author_flow('sprint1', 19, 22, outputs=False, headers=False), author_code('sprint1', 19, 22)])
    return ()


@app.cell(hide_code=True)
def _(VARS, X, author_code, author_flow, describe, figure, kpis, mo, num, pd, plot_box, project_tabs, section):
    mo.stop(project_tabs.value != 'Спринт 1')
    _v = VARS['ph']
    _d = describe(X['ph'])
    _q1, _q3 = (_d['Q1'], _d['Q3'])
    _lo, _hi = (_q1 - 1.5 * (_q3 - _q1), _q3 + 1.5 * (_q3 - _q1))
    _out = int(((X['ph'] < _lo) | (X['ph'] > _hi)).sum())
    _stats = pd.DataFrame({'значение': [num(v, 4) if k != 'n' else f'{v}' for k, v in _d.items()]}, index=pd.Index(list(_d.keys()), name='статистика'))
    mo.vstack([section('1.2', 'EDA & Distribution · От наблюдений к модели', 'rv1-eda', level=3, kicker='Распределение'), section('1.2.1', 'Описательные статистики и выбросы', 'rv1-stats', level=4), mo.Html('<div class="stat-grid">' + ''.join((f'<div class="stat-item"><span>{label}</span><b>{value}</b></div>' for label, value in _stats['значение'].items())) + '</div>'), kpis([('Границы 1.5·IQR', f'{num(_lo, 2)} … {num(_hi, 2)}', _v['unit']), ('Формальных выбросов', f'{_out}', f"из {len(X['ph'])}")]), figure(plot_box(X['ph'], _v['axis'])), author_flow('sprint1', 22, 26, outputs=False, headers=False), author_code('sprint1', 22, 26)])
    return ()


@app.cell(hide_code=True)
def _(X, author_code, author_flow, control_bar, figure, histogram_panel, mo, num, ph_hist_mode, project_tabs, section, stats, verdict):
    mo.stop(project_tabs.value != 'Спринт 1')
