@app.cell(hide_code=True)
def _(author_code, author_flow, control_bar, corr_method, df, figure, html_table, mo, np, num, pd, plot_corr, project_tabs, section, stats, verdict):
    mo.stop(project_tabs.value != 'Спринт 1')
    _alc_q = pd.qcut(df['alcohol'], 4, duplicates='drop')
    _sug_q = pd.qcut(df['residual sugar'], 4, duplicates='drop')
    _tab = pd.crosstab(_alc_q, _sug_q)
    _chi2, _p, _dof, _exp = stats.chi2_contingency(_tab)
    _V = np.sqrt(_chi2 / (_tab.values.sum() * (min(_tab.shape) - 1)))
    _tab.index = [f'спирт {i.left:.1f}–{i.right:.1f}' for i in _tab.index]
    _tab.index.name = 'спирт \\ сахар'
    _tab.columns = [f'сахар {c.left:.1f}–{c.right:.1f}' for c in _tab.columns]
    mo.vstack([section('4', 'Независимость трёх величин', 'joint', level=2, kicker='Все три вместе'), control_bar([corr_method]), mo.hstack([figure(plot_corr(corr_method.value))], justify='center'), section('4.1', 'Критерий χ²: спирт и остаточный сахар', 'joint-chi2', level=3), html_table(_tab), verdict('Независимы ли спирт и сахар?', 'спирт и сахар независимы', 'зависимы', 'χ² Пирсона, 4×4 квантильные группы', [('χ²', num(_chi2, 1)), ('степеней свободы', f'{_dof}'), ('V Крамера', num(_V, 3)), ('мин. ожидаемая частота', num(_exp.min(), 1))], _p), author_flow('sprint1', 138, 143, outputs=False, headers=False), author_code('sprint1', 138, 143)])
    return ()


